export function getOldRankRoleIds(newRankId: number): string[] {
  return Object.entries(DISCORD_RANK_ROLES)
    .filter(([id]) => Number(id) !== newRankId)
    .map(([, roleId]) => roleId);
}

/**
 * Get ALL Discord prestige role IDs except the current one.
