  const tierNum = MEDAL_TIER[medal];
  if (!tierNum) return `${BADGE_BASE_URL}/SeasonalRank0-0.png`;
  const clampedStars = Math.max(1, Math.min(5, stars || 1));
  return `${BADGE_BASE_URL}/SeasonalRank${tierNum}-${clampedStars}.png`;
}

/**
 * Check if a user's rank is eligible for Kernel Kup player registration.
 *
 * Rules:
 *   {minRank} through {maxRank} = eligible to play
 *   Below {minRank} or above {maxRank} = blocked from playing, can coach
 *   Unknown rank = blocked until they self-report or connect Steam
 *
 * @param dbUser - User record from the database
 * @param selfReportedRank - Optional medal name the user self-reported (e.g. 'Archon')
 * @param maxNumericRank - Maximum numeric rank allowed (1â€“36 scale). Defaults to DEFAULT_MAX_PLAYER_RANK.
 * @param minNumericRank - Minimum numeric rank allowed (1â€“36 scale). Defaults to DEFAULT_MIN_PLAYER_RANK.
 */
export function checkKernelKupEligibility(
  dbUser: any,
  selfReportedRank?: string | null,
  maxNumericRank: number = DEFAULT_MAX_PLAYER_RANK,
  minNumericRank: number = DEFAULT_MIN_PLAYER_RANK,
): {
  eligible: boolean;
  rankMedal: string | null;
  rankStars: number;
  selfReported: boolean;
  rankUnknown: boolean;
  reason: string;
} {
  const resolved = resolveUserRank(dbUser);

  // No rank data and no self-report
  if (!resolved && !selfReportedRank) {
    return {
      eligible: false,
      rankMedal: null,
      rankStars: 0,
      selfReported: false,
      rankUnknown: true,
      reason: 'We couldn\'t determine your Dota 2 rank. Please tell us your approximate skill level so we can check eligibility.',
    };
  }

  const effectiveMedal = resolved?.medal || selfReportedRank || null;
  const effectiveStars = resolved
    ? resolved.stars
    : (selfReportedRank === 'Divine' ? 1 : (selfReportedRank === 'Immortal' ? 0 : 0));
  const isSelfReported = !resolved && !!selfReportedRank;

  // Convert to numeric for comparison
  const playerNumeric = effectiveMedal
    ? rankToNumeric(effectiveMedal, effectiveStars || 1)
    : 0;

  // Build display strings for the rank thresholds
  const maxRankDisplay = numericToRank(maxNumericRank);
  const maxRankStr = maxRankDisplay.medal === 'Immortal'
    ? 'Immortal'
    : `${maxRankDisplay.medal} ${maxRankDisplay.stars}`;

  const minRankDisplay = numericToRank(minNumericRank);
  const minRankStr = minRankDisplay.medal === 'Immortal'
    ? 'Immortal'
    : `${minRankDisplay.medal} ${minRankDisplay.stars}`;

  const playerRankStr = `${effectiveMedal}${effectiveStars ? ' ' + effectiveStars : ''}`;

  if (playerNumeric > maxNumericRank) {
    return {
      eligible: false,
      rankMedal: effectiveMedal,
      rankStars: effectiveStars,
      selfReported: isSelfReported,
      rankUnknown: false,
      reason: `This tournament is for ${minRankStr} through ${maxRankStr}. Your rank (${playerRankStr}) is above the eligibility threshold. You can still participate as a Coach!`,
    };
  }

  if (playerNumeric < minNumericRank) {
    return {
      eligible: false,
      rankMedal: effectiveMedal,
      rankStars: effectiveStars,
      selfReported: isSelfReported,
      rankUnknown: false,
      reason: `This tournament is for ${minRankStr} through ${maxRankStr}. Your rank (${playerRankStr}) is below the minimum eligibility threshold.`,
    };
  }

  // Eligible
  return {
    eligible: true,
    rankMedal: effectiveMedal,
    rankStars: effectiveStars,
    selfReported: isSelfReported,
    rankUnknown: false,
    reason: '',
  };
}

/**
 * Role Configuration â€” Server-side built-in role helpers.
 *
 * These hardcoded arrays provide fast, synchronous permission checks for
 * the built-in roles. Custom roles are managed via the `roles` database
 * table and validated dynamically in routes-admin-roles.ts.
 *
 * Keep in sync with /src/lib/roles.ts on the frontend.
 *
 * Permission tiers: owner > officer > member > guest
 * ALL authenticated users (including guests) have full app access.
 * Guests are simply users without guild affiliation.
 *
 * IMPORTANT: As of Guild Wars migration, `role` is PURELY a permission tier.
 * Guild affiliation is stored in `users.guild_id` â†’ `guild_wars_guilds`.
 *   owner         â†’ Colonel Kernel   â†’ owner tier
 *   admin         â†’ Cob Officer      â†’ officer tier
 *   queen_of_hog  â†’ Queen Of Hog     â†’ officer tier
 *   member        â†’ Member           â†’ member tier (generic onboarded user)
 *   guest         â†’ Guest            â†’ guest tier (not yet onboarded)
 */

/** Alias roles that grant officer-level access */
export const OFFICER_ROLES = ['admin', 'queen_of_hog'] as const;

/** The standard member permission role (onboarded user) */
export const MEMBER_ROLE = 'member' as const;

/** Every valid role value that can exist in the database */
export const ALL_ROLES = ['owner', ...OFFICER_ROLES, MEMBER_ROLE, 'guest'] as const;

/** Is this the site owner? */
export function isOwner(role: string | undefined | null): boolean {
  return role === 'owner';
}

/** Has officer powers? (officer + owner tier) */
export function isOfficer(role: string | undefined | null): boolean {
  if (!role) return false;
  return role === 'owner' || (OFFICER_ROLES as readonly string[]).includes(role);
}

/** Is an onboarded member? (not guest, not officer, not owner â€” the generic member tier) */
export function isMember(role: string | undefined | null): boolean {
  return role === 'member';
}

/** Is a guest? (identification only â€” NOT an access gate) */
export function isGuest(role: string): boolean {
  return role === 'guest';
}

/** Is authenticated? (any user with a valid role â€” ALL roles including guest) */
export function isAuthenticated(role: string): boolean {
  return (ALL_ROLES as readonly string[]).includes(role);
}

/** Is this a valid role value for the database? */
export function isValidRole(role: string): boolean {
  return (ALL_ROLES as readonly string[]).includes(role);
}

