export function registerAdminImportRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ Shared auth check (owner via users table) â”€â”€
  async function requireAdmin(c: any) {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return null;
    const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
    if (authError || !authUser) return null;
    const { data: dbUser } = await supabase.from('users').select('role').eq('supabase_id', authUser.id).single();
    const allowedRoles = ['owner', 'queen_of_hog'];
    if (!dbUser || !allowedRoles.includes(dbUser.role)) return null;
    return authUser;
  }

  /**
   * POST /admin/import-tournament
   * Full pipeline: 5-ID verification â†’ fetch all matches â†’ create tournament + teams + matches + player stats
   */
  app.post(`${PREFIX}/admin/import-tournament`, async (c) => {
    try {
      const authUser = await requireAdmin(c);
      if (!authUser) return c.json({ error: 'Admin access required' }, 403);

      const { league_id, series_id, match_id, team_id, player_id } = await c.req.json();
      const STEAM_API_KEY = Deno.env.get('STEAM_WEB_API_KEY') ?? '';

      // â”€â”€ Step 1: Verify 5 IDs â”€â”€
      const errors: string[] = [];

      const leagueResponse = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetLeagueListing/v1/?key=${STEAM_API_KEY}`);
      const leagueData = await leagueResponse.json();
      const leagueInfo = leagueData.result?.leagues?.find((l: any) => l.leagueid === league_id);
      if (!leagueInfo) errors.push(`League ID ${league_id} not found in Steam API`);
      const tournamentName = leagueInfo?.name || `Tournament ${league_id}`;

      const matchDetailResponse = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchDetails/v1/?key=${STEAM_API_KEY}&match_id=${match_id}`);
      const matchDetailData = await matchDetailResponse.json();
      if (!matchDetailData.result || matchDetailData.result.error) errors.push(`Match ID ${match_id} not found`);
      else if (matchDetailData.result.leagueid !== league_id) errors.push(`Match ID ${match_id} does not belong to League ID ${league_id}`);

      const radiantTeamId = matchDetailData.result?.radiant_team_id;
      const direTeamId = matchDetailData.result?.dire_team_id;
      if (radiantTeamId !== team_id && direTeamId !== team_id) errors.push(`Team ID ${team_id} not found in Match ID ${match_id}`);

      if (!matchDetailData.result?.players?.some((p: any) => p.account_id === player_id)) errors.push(`Player ID ${player_id} not found in Match ID ${match_id}`);

      if (matchDetailData.result?.series_id && matchDetailData.result.series_id !== series_id) errors.push(`Series ID ${series_id} does not match match data`);

      if (errors.length > 0) {
        return c.json({ error: 'Verification failed', details: errors, field_errors: {
          league_id: errors.find(e => e.includes('League')), match_id: errors.find(e => e.includes('Match')),
          team_id: errors.find(e => e.includes('Team')), player_id: errors.find(e => e.includes('Player')),
          series_id: errors.find(e => e.includes('Series'))
        }}, 400);
      }

      // â”€â”€ Step 2: Fetch all matches â”€â”€
      const historyRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchHistory/v1/?key=${STEAM_API_KEY}&league_id=${league_id}&matches_requested=100`);
      const allMatches = (await historyRes.json()).result?.matches || [];

      let earliestMatchTime = Infinity, latestMatchTime = 0;
      for (const m of allMatches) {
        if (m.start_time) { if (m.start_time < earliestMatchTime) earliestMatchTime = m.start_time; if (m.start_time > latestMatchTime) latestMatchTime = m.start_time; }
      }
      const tournamentStartDate = earliestMatchTime !== Infinity ? new Date(earliestMatchTime * 1000).toISOString().split('T')[0] : new Date().toISOString().split('T')[0];
      const tournamentEndDate = latestMatchTime > 0 ? new Date(latestMatchTime * 1000).toISOString().split('T')[0] : new Date().toISOString().split('T')[0];

      // â”€â”€ Step 3: Create tournament â”€â”€
      const { data: tournament, error: tournamentError } = await supabase.from('kkup_tournaments').insert({
        name: tournamentName, league_id, series_id, verified_match_id: match_id, verified_team_id: team_id, verified_player_id: player_id,
        tournament_start_date: tournamentStartDate, tournament_end_date: tournamentEndDate,
        import_status: 'in_progress', created_at: new Date().toISOString(), updated_at: new Date().toISOString()
      }).select().single();
      if (tournamentError || !tournament) return c.json({ error: 'Failed to create tournament', details: tournamentError }, 500);
      const kkupId = tournament.id;

      // â”€â”€ Step 4: Process teams & matches â”€â”€
      const teamMap = new Map();
      let teamsCreated = 0, matchesCreated = 0;

      for (const match of allMatches) {
        try {
          const detailRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchDetails/v1/?key=${STEAM_API_KEY}&match_id=${match.match_id}`);
          const result = (await detailRes.json()).result;
          if (!result || result.error) continue;

          // Process radiant team
          let radiantDbTeam = teamMap.get(result.radiant_team_id) || null;
          if (result.radiant_team_id && !radiantDbTeam) {
            const teamInfoRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetTeamInfoByTeamID/v1/?key=${STEAM_API_KEY}&start_at_team_id=${result.radiant_team_id}&teams_requested=1`);
            const td = (await teamInfoRes.json()).result?.teams?.[0];
            const { data: nt } = await supabase.from('kkup_teams').insert({
              tournament_id: kkupId, team_name: td?.name || result.radiant_name || 'Radiant Team', team_tag: td?.tag || 'RAD',
              valve_team_id: result.radiant_team_id, logo_url: td?.logo_url || td?.logo, imported_at: new Date().toISOString()
            }).select().single();
            if (nt) { teamMap.set(result.radiant_team_id, nt); radiantDbTeam = nt; teamsCreated++; }
          }

          // Process dire team
          let direDbTeam = teamMap.get(result.dire_team_id) || null;
          if (result.dire_team_id && !direDbTeam) {
            const teamInfoRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetTeamInfoByTeamID/v1/?key=${STEAM_API_KEY}&start_at_team_id=${result.dire_team_id}&teams_requested=1`);
            const td = (await teamInfoRes.json()).result?.teams?.[0];
            const { data: nt } = await supabase.from('kkup_teams').insert({
              tournament_id: kkupId, team_name: td?.name || result.dire_name || 'Dire Team', team_tag: td?.tag || 'DIR',
              valve_team_id: result.dire_team_id, logo_url: td?.logo_url || td?.logo, imported_at: new Date().toISOString()
            }).select().single();
            if (nt) { teamMap.set(result.dire_team_id, nt); direDbTeam = nt; teamsCreated++; }
          }

          // Create match
          const { data: dbMatch } = await supabase.from('kkup_matches').insert({
            tournament_id: kkupId, match_id: match.match_id, series_id: result.series_id || null, series_type: result.series_type || null,
            team1_id: radiantDbTeam?.id, team2_id: direDbTeam?.id, radiant_team_id: result.radiant_team_id, dire_team_id: result.dire_team_id,
            winning_team_id: result.radiant_win ? radiantDbTeam?.id : direDbTeam?.id,
            team1_score: result.radiant_win ? 1 : 0, team2_score: result.radiant_win ? 0 : 1,
            duration: result.duration, status: 'completed', stage: 'playoffs',
            dotabuff_url: `https://www.dotabuff.com/matches/${match.match_id}`,
            scheduled_time: new Date(match.start_time * 1000).toISOString(), opendota_fetched: false
          }).select().single();

          if (dbMatch) {
            matchesCreated++;
            if (result.players && Array.isArray(result.players)) {
              for (const player of result.players) {
                if (!player.account_id) continue;
                const { data: existing } = await supabase.from('kkup_persons').select('*').eq('steam_id', String(player.account_id)).maybeSingle();
                let profile = existing;
                if (!profile) {
                  const { data: np } = await supabase.from('kkup_persons').insert({
                    display_name: player.personaname || `Player ${player.account_id}`, steam_id: String(player.account_id),
                  }).select().single();
                  profile = np;
                }
                if (!profile) continue;
                const isRadiant = player.player_slot < 128;
                 const playerTeamId = isRadiant ? radiantDbTeam?.id : direDbTeam?.id;
                 const isWinner = isRadiant ? (result.radiant_win === true) : (result.radiant_win === false);
                 await supabase.from('kkup_player_match_stats').insert({
                   match_id: dbMatch.id, person_id: profile.id, team_id: playerTeamId,
                   hero: getHeroName(player.hero_id || 0),
                   kills: player.kills || 0, deaths: player.deaths || 0, assists: player.assists || 0,
                   last_hits: player.last_hits || 0, denies: player.denies || 0,
                   gpm: player.gold_per_min || 0, xpm: player.xp_per_min || 0,
                   net_worth: player.total_gold || 0,
                   is_winner: isWinner,
                   hero_damage: player.hero_damage || 0,
                   tower_damage: player.tower_damage || 0,
                   hero_healing: player.hero_healing || 0,
                   level: player.level || 0,
                   item_0: player.item_0 || 0,
                   item_1: player.item_1 || 0,
                   item_2: player.item_2 || 0,
                   item_3: player.item_3 || 0,
                   item_4: player.item_4 || 0,
                   item_5: player.item_5 || 0,
                   item_neutral: player.item_neutral || 0,
                 });
              }
            }
          }
        } catch (e) { console.error(`Error processing match ${match.match_id}:`, e); }
      }

      // â”€â”€ Step 5: Complete â”€â”€
      await supabase.from('kkup_tournaments').update({ import_status: 'completed', imported_at: new Date().toISOString() }).eq('id', kkupId);

      try { await createAdminLog({ type: 'tournament_imported', action: `Imported tournament "${tournamentName}" via 5-ID pipeline (${teamsCreated} teams, ${matchesCreated} matches)`, actor_name: 'Owner' }); } catch (_) {}

      return c.json({ success: true, message: 'Tournament imported successfully', tournament_id: kkupId,
        stats: { teams_created: teamsCreated, matches_created: matchesCreated, next_step: 'Run OpenDota enrichment to fetch detailed player stats' } });
    } catch (error: any) {
      console.error('Tournament import error:', error);
      return c.json({ error: 'Internal server error', details: error?.message || String(error) }, 500);
    }
  });

  /**
   * POST /admin/test-tournament-import
   * Test/preview mode: fetches data but doesn't save anything
   */
  app.post(`${PREFIX}/admin/test-tournament-import`, async (c) => {
    try {
      const authUser = await requireAdmin(c);
      if (!authUser) return c.json({ error: 'Admin access required' }, 403);

      const { league_id, series_id, match_id, team_id, player_id } = await c.req.json();
      const STEAM_API_KEY = Deno.env.get('STEAM_WEB_API_KEY') ?? '';

      // Verify IDs
      const errors: string[] = [];
      const leagueRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetLeagueListing/v1/?key=${STEAM_API_KEY}`);
      const leagueInfo = (await leagueRes.json()).result?.leagues?.find((l: any) => l.leagueid === league_id);
      if (!leagueInfo) errors.push(`League ID ${league_id} not found`);
      const tournamentName = leagueInfo?.name || `Tournament ${league_id}`;

      const matchRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchDetails/v1/?key=${STEAM_API_KEY}&match_id=${match_id}`);
      const matchData = (await matchRes.json()).result;
      if (!matchData || matchData.error) errors.push(`Match ID ${match_id} not found`);
      else if (matchData.leagueid !== league_id) errors.push(`Match does not belong to league`);
      if (matchData?.radiant_team_id !== team_id && matchData?.dire_team_id !== team_id) errors.push(`Team ID ${team_id} not found in match`);
      if (!matchData?.players?.some((p: any) => p.account_id === player_id)) errors.push(`Player ID ${player_id} not found in match`);
      if (matchData?.series_id && matchData.series_id !== series_id) errors.push(`Series ID mismatch`);

      if (errors.length > 0) {
        return c.json({ verified: false, errors, field_errors: {
          league_id: errors.find(e => e.includes('League')), match_id: errors.find(e => e.includes('Match')),
          team_id: errors.find(e => e.includes('Team')), player_id: errors.find(e => e.includes('Player')),
          series_id: errors.find(e => e.includes('Series'))
        }}, 400);
      }

      // Fetch all matches
      const historyRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchHistory/v1/?key=${STEAM_API_KEY}&league_id=${league_id}&matches_requested=100`);
      const allMatches = (await historyRes.json()).result?.matches || [];

      let earliestMatchTime = Infinity, latestMatchTime = 0;
      for (const m of allMatches) { if (m.start_time) { if (m.start_time < earliestMatchTime) earliestMatchTime = m.start_time; if (m.start_time > latestMatchTime) latestMatchTime = m.start_time; } }

      const teamsMap = new Map();
      const playersMap = new Map();
      const teamWL = new Map();

      // Process all matches for teams/players/W-L
      for (const match of allMatches) {
        try {
          const result = (await (await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchDetails/v1/?key=${STEAM_API_KEY}&match_id=${match.match_id}`)).json()).result;
          if (!result || result.error) continue;

          for (const valveTeamId of [result.radiant_team_id, result.dire_team_id]) {
            if (valveTeamId && !teamsMap.has(valveTeamId)) {
              const td = (await (await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetTeamInfoByTeamID/v1/?key=${STEAM_API_KEY}&start_at_team_id=${valveTeamId}&teams_requested=1`)).json()).result?.teams?.[0];
              const isRadiant = valveTeamId === result.radiant_team_id;
              teamsMap.set(valveTeamId, {
                team_id: valveTeamId, team_name: td?.name || (isRadiant ? result.radiant_name : result.dire_name) || 'Team',
                tag: td?.tag || 'TEAM', logo_url: getSteamLogoUrl(td?.logo_url || td?.logo), wins: 0, losses: 0
              });
              teamWL.set(valveTeamId, { wins: 0, losses: 0 });
            }
          }

          if (result.radiant_win) {
            const r = teamWL.get(result.radiant_team_id); if (r) r.wins++;
            const d = teamWL.get(result.dire_team_id); if (d) d.losses++;
          } else {
            const d = teamWL.get(result.dire_team_id); if (d) d.wins++;
            const r = teamWL.get(result.radiant_team_id); if (r) r.losses++;
          }

          if (result.players) {
            for (const p of result.players) {
              if (p.account_id && !playersMap.has(p.account_id)) {
                playersMap.set(p.account_id, { account_id: p.account_id, steam_id: steam32ToSteam64(p.account_id),
                  name: p.personaname || `Player ${p.account_id}`, dotabuff_url: `https://www.dotabuff.com/players/${p.account_id}`, opendota_url: `https://www.opendota.com/players/${p.account_id}` });
              }
            }
          }
        } catch (_) { /* skip */ }
      }

      // Update W/L
      for (const [tid, team] of teamsMap.entries()) { const r = teamWL.get(tid); if (r) { team.wins = r.wins; team.losses = r.losses; } }

      // Enrich first 8 matches for preview
      const enrichedMatches: any[] = [];
      for (const match of allMatches.slice(0, 8)) {
        try {
          const result = (await (await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchDetails/v1/?key=${STEAM_API_KEY}&match_id=${match.match_id}`)).json()).result;
          if (!result || result.error) continue;
          const rt = teamsMap.get(result.radiant_team_id);
          const dt = teamsMap.get(result.dire_team_id);
          const winner = result.radiant_win ? rt : dt;
          enrichedMatches.push({
            match_id: match.match_id, series_id: result.series_id || null, match_date: new Date(result.start_time * 1000).toISOString(),
            duration_seconds: result.duration, duration_formatted: `${Math.floor(result.duration / 60)}:${String(result.duration % 60).padStart(2, '0')}`,
            radiant_team: { team_id: result.radiant_team_id, name: rt?.team_name || 'Radiant', tag: rt?.tag, logo_url: rt?.logo_url },
            dire_team: { team_id: result.dire_team_id, name: dt?.team_name || 'Dire', tag: dt?.tag, logo_url: dt?.logo_url },
            winner: { team_id: winner?.team_id, name: winner?.team_name || 'Unknown', tag: winner?.tag },
            radiant_win: result.radiant_win, radiant_score: result.radiant_score || 0, dire_score: result.dire_score || 0,
            radiant_players: (result.players || []).filter((p: any) => p.player_slot < 128).map((p: any) => ({ account_id: p.account_id, name: playersMap.get(p.account_id)?.name || `Player ${p.account_id}`, hero_id: p.hero_id })),
            dire_players: (result.players || []).filter((p: any) => p.player_slot >= 128).map((p: any) => ({ account_id: p.account_id, name: playersMap.get(p.account_id)?.name || `Player ${p.account_id}`, hero_id: p.hero_id })),
          });
        } catch (_) { /* skip */ }
      }

      return c.json({
        verified: true, message: `Found tournament data for "${tournamentName}"`,
        data: { verified: true, tournament: {
          name: tournamentName, league_id, series_id, verified_match_id: match_id, verified_team_id: team_id, verified_player_id: player_id,
          tournament_start_date: earliestMatchTime !== Infinity ? new Date(earliestMatchTime * 1000).toISOString().split('T')[0] : null,
          tournament_end_date: latestMatchTime > 0 ? new Date(latestMatchTime * 1000).toISOString().split('T')[0] : null
        }, teams: Array.from(teamsMap.values()), matches: enrichedMatches, players: Array.from(playersMap.values()) },
        league: { leagueid: league_id, name: tournamentName, tier: leagueInfo?.tier || 'unknown' },
        stats: { total_matches: allMatches.length, total_teams: teamsMap.size, total_players: playersMap.size, matches_preview: enrichedMatches.length }
      });
    } catch (error: any) {
      console.error('Test error:', error);
      return c.json({ error: 'Internal server error', details: error?.message || String(error) }, 500);
    }
  });

  /**
   * POST /admin/import-tournament-from-test
   * Import pre-verified data from the test endpoint
   */
  app.post(`${PREFIX}/admin/import-tournament-from-test`, async (c) => {
    try {
      const authUser = await requireAdmin(c);
      if (!authUser) return c.json({ error: 'Admin access required' }, 403);

      const { tournament, teams, league_id } = await c.req.json();
      if (!tournament || !teams) return c.json({ error: 'Invalid data format' }, 400);

      // Create tournament
      const { data: dbTournament, error: tournamentError } = await supabase.from('kkup_tournaments').insert({
        name: tournament.name, league_id: tournament.league_id, series_id: tournament.series_id,
        verified_match_id: tournament.verified_match_id, verified_team_id: tournament.verified_team_id, verified_player_id: tournament.verified_player_id,
        tournament_start_date: tournament.tournament_start_date, tournament_end_date: tournament.tournament_end_date,
        import_status: 'in_progress', created_at: new Date().toISOString(), updated_at: new Date().toISOString()
      }).select().single();
      if (tournamentError || !dbTournament) return c.json({ error: 'Failed to create tournament', details: tournamentError }, 500);
      const kkupId = dbTournament.id;

      // Create teams
      const teamMap = new Map();
      for (const team of teams) {
        const { data: dbTeam } = await supabase.from('kkup_teams').insert({
          tournament_id: kkupId, team_name: team.name, team_tag: team.tag, valve_team_id: team.valve_team_id,
          logo_url: team.logo_url, imported_at: new Date().toISOString()
        }).select().single();
        if (dbTeam) teamMap.set(team.valve_team_id, dbTeam);
      }

      // Fetch and create matches
      const STEAM_API_KEY = Deno.env.get('STEAM_WEB_API_KEY') ?? '';
      const historyRes = await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchHistory/v1/?key=${STEAM_API_KEY}&league_id=${league_id}&matches_requested=100`);
      const allMatches = (await historyRes.json()).result?.matches || [];
      let matchesCreated = 0;

      for (const match of allMatches) {
        try {
          const result = (await (await fetch(`${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchDetails/v1/?key=${STEAM_API_KEY}&match_id=${match.match_id}`)).json()).result;
          if (!result || result.error) continue;

          const radiantDbTeam = teamMap.get(result.radiant_team_id);
          const direDbTeam = teamMap.get(result.dire_team_id);

          const { data: dbMatch } = await supabase.from('kkup_matches').insert({
            tournament_id: kkupId, valve_match_id: match.match_id, match_date: new Date(result.start_time * 1000).toISOString(),
            duration_seconds: result.duration || 0, scheduled_time: new Date(result.start_time * 1000).toISOString(),
            radiant_team_id: radiantDbTeam?.id, dire_team_id: direDbTeam?.id,
            team1_id: radiantDbTeam?.id, team2_id: direDbTeam?.id,
            winning_team_id: result.radiant_win ? radiantDbTeam?.id : direDbTeam?.id,
            radiant_score: result.radiant_score || 0, dire_score: result.dire_score || 0,
            team1_score: result.radiant_score || 0, team2_score: result.dire_score || 0,
            stage: 'tournament', status: 'completed', imported_at: new Date().toISOString()
          }).select().single();

          if (dbMatch) {
            matchesCreated++;
            if (result.players) {
              for (const player of result.players) {
                if (!player.account_id) continue;
                const { data: existing } = await supabase.from('kkup_persons').select('*').eq('steam_id', String(player.account_id)).maybeSingle();
                let profile = existing;
                if (!profile) {
                  const { data: np } = await supabase.from('kkup_persons').insert({
                    steam_id: String(player.account_id), display_name: player.personaname || `Player ${player.account_id}`,
                    dotabuff_url: `https://www.dotabuff.com/players/${player.account_id}`, opendota_url: `https://www.opendota.com/players/${player.account_id}`,
                  }).select().single();
                  profile = np;
                }
                if (!profile) continue;
                const isRadiant = player.player_slot < 128;
                 const playerTeamId = isRadiant ? radiantDbTeam?.id : direDbTeam?.id;
                 const isWinner = isRadiant ? (result.radiant_win === true) : (result.radiant_win === false);
                 await supabase.from('kkup_player_match_stats').insert({
                   match_id: dbMatch.id, person_id: profile.id, team_id: playerTeamId,
                   hero: getHeroName(player.hero_id || 0),
                   kills: player.kills || 0, deaths: player.deaths || 0, assists: player.assists || 0,
                   last_hits: player.last_hits || 0, denies: player.denies || 0,
                   gpm: player.gold_per_min || 0, xpm: player.xp_per_min || 0,
                   net_worth: player.total_gold || 0,
                   is_winner: isWinner,
                   hero_damage: player.hero_damage || 0,
                   tower_damage: player.tower_damage || 0,
                   hero_healing: player.hero_healing || 0,
                   level: player.level || 0,
                   item_0: player.item_0 || 0,
                   item_1: player.item_1 || 0,
                   item_2: player.item_2 || 0,
                   item_3: player.item_3 || 0,
                   item_4: player.item_4 || 0,
                   item_5: player.item_5 || 0,
                   item_neutral: player.item_neutral || 0,
                 });
              }
            }
          }
        } catch (e) { console.error('Error processing match:', e); }
      }

      // Calculate W/L and update teams
      const { data: allTournamentMatches } = await supabase.from('kkup_matches').select('*').eq('tournament_id', kkupId);
      const teamRecords = new Map<string, { wins: number; losses: number }>();
      for (const [_, dbTeam] of teamMap.entries()) teamRecords.set(dbTeam.id, { wins: 0, losses: 0 });
      for (const m of (allTournamentMatches || [])) {
        if (m.winning_team_id) {
          const winner = teamRecords.get(m.winning_team_id);
          if (winner) winner.wins++;
          // Find the loser (the other team in the match)
          const loserId = m.radiant_team_id === m.winning_team_id ? m.dire_team_id : m.radiant_team_id;
          const loser = loserId ? teamRecords.get(loserId) : null;
          if (loser) loser.losses++;
        }
      }
      for (const [teamId, record] of teamRecords.entries()) await supabase.from('kkup_teams').update({ wins: record.wins, losses: record.losses }).eq('id', teamId);

      await supabase.from('kkup_tournaments').update({ import_status: 'completed', imported_at: new Date().toISOString() }).eq('id', kkupId);

      try { await createAdminLog({ type: 'tournament_imported', action: `Imported tournament "${tournament.name || 'Unknown'}" from test data (${teamMap.size} teams, ${matchesCreated} matches)`, actor_name: 'Owner' }); } catch (_) {}

      return c.json({ success: true, message: 'Tournament imported successfully', tournament_id: kkupId,
        stats: { teams_created: teamMap.size, matches_created: matchesCreated } });
    } catch (error: any) {
      console.error('Import error:', error);
      return c.json({ error: 'Internal server error', details: error?.message || String(error) }, 500);
    }
  });

}

/**
 * Guild Role Management Routes â€” backed by the `roles` table.
 *
 * The `roles` table is the single source of truth for every role in the system.
 * Built-in roles have `is_builtin = true` and cannot be deleted via the API.
 * Custom roles have `is_builtin = false` and are fully CRUD-able by the owner.
 *
 * 5 routes:
 *   GET    /roles                  â€” list ALL roles (public, any authenticated user)
 *   POST   /roles                  â€” create a new custom role (owner only)
 *   PUT    /roles/:value           â€” update any role's display properties (owner only)
 *   GET    /roles/:value/users     â€” count users with this role (owner only)
 *   DELETE /roles/:value           â€” delete a custom role + reassign users to guest (owner only)
 */
import type { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import { createAdminLog, createUserActivity, createNotification } from "./routes-notifications.ts";

/** Shape returned by the API (camelCase for frontend) */
export interface RoleRow {
  value: string;
  displayName: string;
  badgeTag: string;
  hex: string;
  tier: "owner" | "officer" | "member" | "guest";
  isBuiltin: boolean;
  sortOrder: number;
}

/** Convert a DB row (snake_case) to the API shape (camelCase) */
function toApiRole(row: any): RoleRow {
  return {
    value: row.value,
    displayName: row.display_name,
    badgeTag: row.badge_tag,
    hex: row.hex,
    tier: row.tier,
    isBuiltin: row.is_builtin,
    sortOrder: row.sort_order,
  };
}

/** Check if a role value exists in the `roles` table */
export async function isValidRoleDynamic(role: string, supabase: any): Promise<boolean> {
  const { data, error } = await supabase
    .from("roles")
    .select("value")
    .eq("value", role)
    .maybeSingle();
  if (error) {
    console.error("isValidRoleDynamic error:", error);
    return false;
  }
  return !!data;
}

export function registerAdminRolesRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ GET /roles â€” All roles (any authenticated user) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/roles`, async (c) => {
    try {
      const accessToken = c.req.header("Authorization")?.split(" ")[1];
      if (!accessToken) return c.json({ error: "No access token" }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: "Unauthorized" }, 401);

      const { data: rows, error: dbError } = await supabase
        .from("roles")
        .select("*")
        .order("sort_order", { ascending: true });

      if (dbError) {
        console.error("Error fetching roles from DB:", dbError);
        return c.json({ error: "Failed to fetch roles" }, 500);
      }

      const roles = (rows || []).map(toApiRole);
      return c.json({ roles });
    } catch (error) {
      console.error("Get roles error:", error);
      return c.json({ error: "Internal server error" }, 500);
    }
  });

  // â”€â”€ POST /roles â€” Create a custom role (owner only) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/roles`, async (c) => {
    try {
      const accessToken = c.req.header("Authorization")?.split(" ")[1];
      if (!accessToken) return c.json({ error: "No access token" }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: "Unauthorized" }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from("users").select("role").eq("supabase_id", authUser.id).single();
      if (userError || !dbUser) return c.json({ error: "User not found" }, 404);
      if (dbUser.role !== "owner") return c.json({ error: "Only the owner can create roles" }, 403);

      const body = await c.req.json();
      const { value, displayName, badgeTag, hex, tier } = body;

      // Validate required fields
      if (!value || !displayName || !badgeTag || !hex) {
        return c.json({ error: "Missing required fields: value, displayName, badgeTag, hex" }, 400);
      }

      // Sanitize value: lowercase, alphanumeric + underscores only
      const sanitized = value.toLowerCase().replace(/[^a-z0-9_]/g, "_");
      if (sanitized.length < 2 || sanitized.length > 30) {
        return c.json({ error: "Role value must be 2-30 characters (a-z, 0-9, _)" }, 400);
      }

      // Check collision â€” just try to select by PK
      const { data: existing } = await supabase
        .from("roles").select("value").eq("value", sanitized).maybeSingle();
      if (existing) {
        return c.json({ error: `Role "${sanitized}" already exists` }, 409);
      }

      // Determine sort_order: max existing + 10
      const { data: maxRow } = await supabase
        .from("roles")
        .select("sort_order")
        .order("sort_order", { ascending: false })
        .limit(1)
        .maybeSingle();
      const nextSort = (maxRow?.sort_order ?? 60) + 10;

      const safeTier = ["member", "officer"].includes(tier) ? tier : "member";

      const { data: inserted, error: insertError } = await supabase
        .from("roles")
        .insert({
          value: sanitized,
          display_name: displayName.trim(),
          badge_tag: badgeTag.trim().toUpperCase().slice(0, 5),
          hex: hex.startsWith("#") ? hex : `#${hex}`,
          tier: safeTier,
          is_builtin: false,
          sort_order: nextSort,
        })
        .select()
        .single();

      if (insertError) {
        console.error("Error inserting role:", insertError);
        return c.json({ error: `Failed to create role: ${insertError.message}` }, 500);
      }

      const role = toApiRole(inserted);
      console.log(`Created role: ${role.value} (${role.displayName})`);

      // Admin log (non-critical)
      try {
        await createAdminLog({
          type: 'role_created',
          action: `Created guild role "${role.displayName}" (${role.value}, tier: ${role.tier})`,
          actor_name: 'Owner',
          details: { role_value: role.value, display_name: role.displayName, tier: role.tier },
        });
      } catch (logErr) {
        console.error('Non-critical: admin log for role creation failed:', logErr);
      }

      return c.json({ role }, 201);
    } catch (error) {
      console.error("Create role error:", error);
      return c.json({ error: "Internal server error" }, 500);
    }
  });

  // â”€â”€ PUT /roles/:value â€” Update any role's display properties (owner only) â”€â”€â”€â”€â”€â”€â”€â”€
  app.put(`${PREFIX}/roles/:value`, async (c) => {
    try {
      const accessToken = c.req.header("Authorization")?.split(" ")[1];
      if (!accessToken) return c.json({ error: "No access token" }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: "Unauthorized" }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from("users").select("role").eq("supabase_id", authUser.id).single();
      if (userError || !dbUser) return c.json({ error: "User not found" }, 404);
      if (dbUser.role !== "owner") return c.json({ error: "Only the owner can update roles" }, 403);

      const roleValue = c.req.param("value");

      // Check it exists
      const { data: target } = await supabase
        .from("roles").select("value, is_builtin, tier").eq("value", roleValue).maybeSingle();

      if (!target) {
        return c.json({ error: `Role "${roleValue}" not found` }, 404);
      }

      const body = await c.req.json();
      const { displayName, badgeTag, hex, tier } = body;

      // Validate required fields
      if (!displayName || !badgeTag || !hex) {
        return c.json({ error: "Missing required fields: displayName, badgeTag, hex" }, 400);
      }

      // Built-in roles: only allow display property changes, keep original tier
      // Custom roles: allow tier changes too
      const updatePayload: Record<string, any> = {
        display_name: displayName.trim(),
        badge_tag: badgeTag.trim().toUpperCase().slice(0, 5),
        hex: hex.startsWith("#") ? hex : `#${hex}`,
      };

      if (!target.is_builtin) {
        updatePayload.tier = ["member", "officer"].includes(tier) ? tier : "member";
      }

      const { data: updated, error: updateError } = await supabase
        .from("roles")
        .update(updatePayload)
        .eq("value", roleValue)
        .select()
        .single();

      if (updateError) {
        console.error("Error updating role:", updateError);
        return c.json({ error: `Failed to update role: ${updateError.message}` }, 500);
      }

      const role = toApiRole(updated);
      console.log(`Updated role: ${role.value} (${role.displayName})`);

      // Admin log (non-critical)
      try {
        await createAdminLog({
          type: 'role_updated',
          action: `Updated guild role "${role.displayName}" (${role.value})`,
          actor_name: 'Owner',
          details: { role_value: role.value, display_name: role.displayName },
        });
      } catch (logErr) {
        console.error('Non-critical: admin log for role update failed:', logErr);
      }

      return c.json({ role });
    } catch (error) {
      console.error("Update role error:", error);
      return c.json({ error: "Internal server error" }, 500);
    }
  });

  // â”€â”€ GET /roles/:value/users â€” Count users with this role (owner only) â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/roles/:value/users`, async (c) => {
    try {
      const accessToken = c.req.header("Authorization")?.split(" ")[1];
      if (!accessToken) return c.json({ error: "No access token" }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: "Unauthorized" }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from("users").select("role").eq("supabase_id", authUser.id).single();
      if (userError || !dbUser) return c.json({ error: "User not found" }, 404);
      if (dbUser.role !== "owner") return c.json({ error: "Only the owner can count users with roles" }, 403);

      const roleValue = c.req.param("value");

      // Check it exists and is not built-in
      const { data: target } = await supabase
        .from("roles").select("value, is_builtin").eq("value", roleValue).maybeSingle();

      if (!target) {
        return c.json({ error: `Role "${roleValue}" not found` }, 404);
      }
      if (target.is_builtin) {
        return c.json({ error: `Cannot count users with built-in role "${roleValue}"` }, 403);
      }

      const { data: userCount, error: countError } = await supabase
        .from("users")
        .select("role", { count: "exact" })
        .eq("role", roleValue);

      if (countError) {
        console.error("Error counting users with role:", countError);
        return c.json({ error: `Failed to count users with role: ${countError.message}` }, 500);
      }

      const count = userCount?.length || 0;
      console.log(`Counted users with role: ${roleValue} (${count})`);
      return c.json({ count });
    } catch (error) {
      console.error("Count users with role error:", error);
      return c.json({ error: "Internal server error" }, 500);
    }
  });

  // â”€â”€ DELETE /roles/:value â€” Delete a custom role + reassign users to guest (owner only) â”€â”€â”€â”€â”€â”€
  app.delete(`${PREFIX}/roles/:value`, async (c) => {
    try {
      const accessToken = c.req.header("Authorization")?.split(" ")[1];
      if (!accessToken) return c.json({ error: "No access token" }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: "Unauthorized" }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from("users").select("role").eq("supabase_id", authUser.id).single();
      if (userError || !dbUser) return c.json({ error: "User not found" }, 404);
      if (dbUser.role !== "owner") return c.json({ error: "Only the owner can delete roles" }, 403);

      const roleValue = c.req.param("value");

      // Check it exists and is not built-in
      const { data: target } = await supabase
        .from("roles").select("value, is_builtin").eq("value", roleValue).maybeSingle();

      if (!target) {
        return c.json({ error: `Role "${roleValue}" not found` }, 404);
      }
      if (target.is_builtin) {
        return c.json({ error: `Cannot delete built-in role "${roleValue}"` }, 403);
      }

      // Reassign users with this role to "guest"
      const { data: affectedUsers } = await supabase
        .from("users")
        .select("id, discord_username")
        .eq("role", roleValue);
      const affectedCount = affectedUsers?.length || 0;

      const { error: reassignError } = await supabase
        .from("users")
        .update({ role: "guest" })
        .eq("role", roleValue);

      if (reassignError) {
        console.error("Error reassigning users to guest:", reassignError);
        return c.json({ error: `Failed to reassign users to guest: ${reassignError.message}` }, 500);
      }

      const { error: deleteError } = await supabase
        .from("roles").delete().eq("value", roleValue);

      if (deleteError) {
        console.error("Error deleting role:", deleteError);
        return c.json({ error: `Failed to delete role: ${deleteError.message}` }, 500);
      }

      console.log(`Deleted role: ${roleValue} (${affectedCount} users reassigned to guest)`);

      // Admin log + notify affected users (non-critical)
      try {
        await createAdminLog({
          type: 'role_deleted',
          action: `Deleted guild role "${roleValue}" â€” ${affectedCount} user(s) reassigned to Guest`,
          actor_name: 'Owner',
          details: { role_value: roleValue, affected_users: affectedCount },
        });

        // Notify each affected user
        if (affectedUsers && affectedUsers.length > 0) {
          for (const user of affectedUsers) {
            try {
              await createUserActivity({
                user_id: user.id,
                type: 'admin_role_removed',
                title: 'Guild Role Removed',
                description: `Your guild role "${roleValue}" was deleted by the owner. You have been moved to Guest.`,
                actor_name: 'Owner',
              });
              await createNotification({
                user_id: user.id,
                type: 'role_removed',
                title: 'Guild Role Removed',
                body: `Your guild "${roleValue}" was deleted. You've been moved to Guest â€” you can join a new guild anytime.`,
                actor_name: 'Owner',
              });
            } catch (_) { /* non-critical per-user */ }
          }
        }
      } catch (logErr) {
        console.error('Non-critical: admin log for role deletion failed:', logErr);
      }

      return c.json({ deleted: roleValue });
    } catch (error) {
      console.error("Delete role error:", error);
      return c.json({ error: "Internal server error" }, 500);
    }
  });
}

/**
 * Admin User Management Routes -- list users + change roles
 * 2 routes: GET /admin/users, PATCH /admin/users/:userId/role
 */
import type { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import { isOfficer } from './roles.ts';
import { isValidRoleDynamic } from "./routes-admin-roles.ts";
import { createAdminLog, createUserActivity } from "./routes-notifications.ts";
import { syncDiscordUserRoles, syncAllDiscordRoles } from "./discord-api.ts";

export function registerAdminUsersRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // Get all users (Officers + Owner)
  app.get(`${PREFIX}/admin/users`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('role').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (!isOfficer(dbUser.role)) return c.json({ error: 'Only officers can access this endpoint' }, 403);

      const { data: users, error: usersError } = await supabase
        .from('users')
        .select(`
          *,
          ranks (
            id, name, display_order
          )
        `)
        .order('created_at', { ascending: false });

      if (usersError) {
        console.error('Error fetching users:', usersError);
        return c.json({ error: 'Failed to fetch users' }, 500);
      }

      return c.json({ users });
    } catch (error) {
      console.error('Get users error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Update user role (Owner only)
  app.patch(`${PREFIX}/admin/users/:userId/role`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('role').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (dbUser.role !== 'owner') return c.json({ error: 'Only owners can update user roles' }, 403);

      const userId = c.req.param('userId');
      const { role, rank_id, prestige_level } = await c.req.json();

      const updatePayload: any = { updated_at: new Date().toISOString() };
      
      if (role !== undefined) {
        if (!isValidRoleDynamic(role, supabase)) {
          return c.json({ error: 'Invalid role' }, 400);
        }
        updatePayload.role = role;
      }
      
      if (rank_id !== undefined) updatePayload.rank_id = rank_id;
      if (prestige_level !== undefined) updatePayload.prestige_level = prestige_level;

      const { data: updatedUser, error: updateError } = await supabase
        .from('users')
        .update(updatePayload)
        .eq('id', userId).select().single();

      if (updateError) {
        console.error('Error updating user role:', updateError);
        return c.json({ error: 'Failed to update user role' }, 500);
      }

      // Fetch the actor's full info for logging
      const { data: actorUser } = await supabase
        .from('users').select('id, discord_username').eq('supabase_id', authUser.id).single();
      const actorName = actorUser?.discord_username || 'owner';
      const targetName = updatedUser.discord_username || userId;
      const oldRole = updatedUser.role; // this is already the new role after update, so we need to track it before

      // Admin log + dual-log to target user (non-critical)
      try {
        await createAdminLog({
          type: 'role_change',
          action: `Changed ${targetName}'s role to "${role}"`,
          actor_id: actorUser?.id,
          actor_name: actorName,
          details: { target_user_id: userId, new_role: role, target_name: targetName },
        });
        await createUserActivity({
          user_id: userId,
          type: 'admin_role_change',
          title: 'Role Changed',
          description: `Your role was changed to "${role}" by ${actorName}.`,
          actor_name: actorName,
        });
      } catch (logErr) { console.error('Non-critical: role change logging failed:', logErr); }

      // Sync Discord roles (background/best-effort)
      // @ts-ignore: EdgeRuntime is available in Supabase
      if (updatePayload.role || updatePayload.rank_id !== undefined || updatePayload.prestige_level !== undefined) {
        EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, userId));
      }

      return c.json({ user: updatedUser });
    } catch (error) {
      console.error('Update user role error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Reset Home Announcement Message for all users (Owner only)
  app.post(`${PREFIX}/admin/users/reset-home-message`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('role, discord_username').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (dbUser.role !== 'owner') return c.json({ error: 'Only owners can reset global announcements' }, 403);

      const { error: updateError } = await supabase
        .from('users')
        .update({ seen_home_message: false })
        .neq('id', '00000000-0000-0000-0000-000000000000'); // dummy neq

      // Alternative to update all rows is to omit filters, but some clients require at least one filter
      // Actually simply `.not('id', 'is', null)` is safer:
      const { error: trueUpdateError } = await supabase
        .from('users')
        .update({ seen_home_message: false })
        .not('id', 'is', null);

      if (trueUpdateError) {
        console.error('Error resetting home messages:', trueUpdateError);
        return c.json({ error: 'Failed to reset global announcements' }, 500);
      }

      // Log the admin action
      try {
        await createAdminLog({
          type: 'announcement_reset',
          action: 'Reset seen_home_message to false for all users',
          actor_name: dbUser.discord_username || 'owner',
        });
      } catch (logErr) { console.error('Non-critical: announcement reset logging failed:', logErr); }

      return c.json({ success: true, message: 'Global announcement has been reset for all users.' });
    } catch (error) {
      console.error('Reset home announcements error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Sync All Discord Roles (Owner only - Heavy operation)
  app.post(`${PREFIX}/admin/sync-all-discord-roles`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('role').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (dbUser.role !== 'owner') return c.json({ error: 'Only owners can trigger a global sync' }, 403);

      // Trigger the heavy sync in the background
      // @ts-ignore: EdgeRuntime is available in Supabase
      EdgeRuntime.waitUntil(syncAllDiscordRoles(supabase));

      return c.json({ 
        message: 'Server-wide Discord role synchronization started in the background. Check logs for progress.',
        status: 'processing'
      });
    } catch (error) {
      console.error('Sync all discord roles error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Public/Service-Role endpoint for individual user sync (used by Bot)
  app.post(`${PREFIX}/sync-discord-user`, async (c) => {
    try {
      const { discord_id } = await c.req.json();
      if (!discord_id) return c.json({ error: 'Missing discord_id' }, 400);

      // Find user by discord_id
      const { data: user, error: userError } = await supabase
        .from('users')
        .select('id')
        .eq('discord_id', discord_id)
        .maybeSingle();

      if (userError || !user) {
        console.error(`sync-discord-user: User not found for ${discord_id}`, userError);
        return c.json({ error: 'User not found on kernelkup.com. Please link your account first!' }, 404);
      }

      // Trigger sync in background
      // @ts-ignore: EdgeRuntime is available
      EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, user.id));

      return c.json({ success: true, message: 'Synchronization started.' });
    } catch (error) {
      console.error('Individual sync error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

}

/**
 * Auth Routes â€” Discord OAuth callback + current user info + onboarding
 * 4 routes:
 *   POST /auth/discord-callback  â€” create or update user after Discord OAuth
 *   GET  /auth/me                â€” current user (with guild + onboarding metadata)
 *   POST /auth/join-guild        â€” DEPRECATED (use POST /guilds/:id/join)
 *   POST /auth/claim-onboarding-reward â€” free rank-up for completing setup
 */
import type { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import * as kv from "./kv_store.tsx";
import { createUserActivity } from "./routes-notifications.ts";
import { syncDiscordUserRoles } from "./discord-api.ts";

export function registerAuthRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ POST /auth/discord-callback â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/auth/discord-callback`, async (c) => {
    try {
      const body = await c.req.json();
      const { user } = body;

      if (!user) {
        console.error('No user object provided in callback');
        return c.json({ error: "User object required" }, 400);
      }

      // Extract the actual Discord user ID from identities array
      const discordIdentity = user.identities?.find((i: any) => i.provider === 'discord');
      const discordUserId = discordIdentity?.id || discordIdentity?.provider_id;

      if (!discordUserId) {
        console.error('No Discord identity found for user:', user.id);
        return c.json({ error: 'Discord identity not found. Please sign in with Discord.' }, 400);
      }

      const supabaseUserId = user.id; // UUID from auth.users
      const discord_username = user.user_metadata?.custom_claims?.global_name 
        || user.user_metadata?.full_name 
        || user.user_metadata?.name 
        || user.email?.split('@')[0] 
        || 'Unknown';
      const discord_avatar = user.user_metadata?.avatar_url || user.user_metadata?.picture || null;
      const discord_email = user.email || null;

      console.log('Discord callback - Discord ID:', discordUserId, 'Supabase ID:', supabaseUserId, 'Username:', discord_username, 'Email:', discord_email);

      // Check if user exists by discord_id (the actual Discord user ID)
      const { data: existingUser, error: fetchError } = await supabase
        .from('users')
        .select('*')
        .eq('discord_id', discordUserId)
        .single();

      if (fetchError && fetchError.code !== 'PGRST116') {
        console.error('Error fetching user:', fetchError);
        return c.json({ error: 'Failed to fetch user' }, 500);
      }

      if (existingUser) {
        // Check if this user should be owner
        let updateData: any = {
          supabase_id: supabaseUserId, // Update in case it changed
          discord_username,
          discord_avatar,
          email: discord_email,
          updated_at: new Date().toISOString(),
        };

        // If email matches owner email and user is not already owner, upgrade them
        if (discord_email === Deno.env.get('OWNER_EMAIL') && existingUser.role !== 'owner') {
          updateData.role = 'owner';
          console.log('EXISTING USER UPGRADED TO OWNER');
        }

        // Detect Twitch identity from linkIdentity OAuth flow
        const twitchIdentity = user.identities?.find((i: any) => i.provider === 'twitch');
        if (twitchIdentity) {
          const twitchData = twitchIdentity.identity_data || {};
          updateData.twitch_username = twitchData.preferred_username || twitchData.name || twitchData.full_name || null;
          updateData.twitch_avatar = twitchData.avatar_url || twitchData.picture || null;
          updateData.twitch_id = twitchIdentity.id || twitchData.provider_id || twitchData.sub || null;
          console.log('Twitch identity found:', updateData.twitch_username, 'ID:', updateData.twitch_id);
        } else if (existingUser.twitch_id) {
          // Twitch identity was removed (unlinkIdentity) â€” clear Twitch fields
          updateData.twitch_username = null;
          updateData.twitch_avatar = null;
          updateData.twitch_id = null;
          console.log('Twitch identity removed (unlinked)');
        }

        // Update existing user info
        const { data: updatedUser, error: updateError } = await supabase
          .from('users')
          .update(updateData)
          .eq('discord_id', discordUserId)
          .select()
          .single();

        if (updateError) {
          console.error('Error updating user:', updateError);
          return c.json({ error: 'Failed to update user' }, 500);
        }

        console.log('Updated existing user');
        return c.json({ user: updatedUser });
      }

      // Determine role based on email - check if this is the owner
      let role = 'guest';
      if (discord_email === Deno.env.get('OWNER_EMAIL')) {
        role = 'owner';
        console.log('OWNER ACCOUNT DETECTED - Setting role to owner');
      }

      // Look up Unaffiliated guild for new users
      const { data: unaffiliatedGuild } = await supabase
        .from('guild_wars_guilds')
        .select('id')
        .eq('name', 'Unaffiliated')
        .single();

      // Create new user with guest role (or owner if matched) and rank 1 (Earwig)
      const { data: newUser, error: createError } = await supabase
        .from('users')
        .insert({
          supabase_id: supabaseUserId,  // UUID from auth.users for JWT verification
          discord_id: discordUserId,     // Actual Discord user ID string
          discord_username,
          discord_avatar,
          email: discord_email,
          rank_id: 1, // Earwig
          prestige_level: 0,
          role: role,
          guild_id: unaffiliatedGuild?.id || null,
        })
        .select()
        .single();

      if (createError) {
        console.error('Error creating user:', createError);
        return c.json({ error: 'Failed to create user' }, 500);
      }

      console.log('Created new user with role:', role);

      // Sync Discord roles for new user (Earwig + Unaffiliated)
      syncDiscordUserRoles(supabase, newUser.id, 1, 0);

      // Log first-time registration (non-critical)
      try {
        await createUserActivity({
          user_id: newUser.id,
          type: 'account_created',
          title: 'Joined The Corn Field',
          description: `Welcome! You created your account as ${discord_username}.`,
        });
      } catch (_) { /* non-critical */ }

      return c.json({ user: newUser });
    } catch (error) {
      console.error('Discord callback error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ GET /auth/me â€” Current user with guild + onboarding metadata â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/auth/me`, async (c) => {
    try {
      const authHeader = c.req.header('Authorization');
      
      if (!authHeader) {
        return c.json({ error: 'No access token provided' }, 401);
      }

      const accessToken = authHeader.replace('Bearer ', '');

      // Use anon client to verify the token
      const { data, error } = await anonSupabase.auth.getUser(accessToken);
      
      if (error) {
        console.error('Token verification failed:', error.message);
        return c.json({ error: 'Unauthorized - Invalid token: ' + error.message }, 401);
      }
      
      if (!data.user) {
        return c.json({ error: 'Unauthorized - No user found' }, 401);
      }
      
      // Get user from database - query by supabase_id (UUID from auth.users)
      // Include guild info via guild_id FK
      const { data: dbUser, error: dbError } = await supabase
        .from('users')
        .select(`
          *,
          ranks (
            id,
            name,
            display_order
          ),
          guild:guild_wars_guilds!users_guild_id_fkey (
            id,
            name,
            tag,
            color,
            logo_url,
            is_default,
            discord_role_id
          )
        `)
        .eq('supabase_id', data.user.id)
        .single();

      if (dbError) {
        console.error('Database query error:', dbError.message, dbError.code);
        return c.json({ error: 'User not found in database: ' + dbError.message }, 404);
      }

      if (!dbUser) {
        return c.json({ error: 'User not found in database' }, 404);
      }

      // Auto-refresh OpenDota data if needed (non-blocking background sync)
      if (dbUser.steam_id) {
        const lastSynced = dbUser.opendota_last_synced ? new Date(dbUser.opendota_last_synced) : null;
        const now = new Date();
        const twoHoursAgo = new Date(now.getTime() - 2 * 60 * 60 * 1000);

        if (!lastSynced || lastSynced < twoHoursAgo) {
          // Trigger background sync (non-blocking - don't await)
          fetch(`${Deno.env.get('SUPABASE_URL')}/functions/v1/make-server-4789f4af/users/me/opendota/sync`, {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${accessToken}`,
            },
          }).catch(err => {
            console.error('Background OpenDota sync failed:', err);
          });
        }
      }

      // â”€â”€ Onboarding metadata (lightweight, parallel queries) â”€â”€
      const [mvpCountResult, rewardClaimed] = await Promise.all([
        // Count of MVP requests this user has submitted
        supabase
          .from('rank_up_requests')
          .select('id', { count: 'exact', head: true })
          .eq('user_id', dbUser.id),
        // Check if onboarding reward was already claimed (KV)
        kv.get(`onboarding_reward:${dbUser.id}`),
      ]);

      const onboarding = {
        mvp_request_count: mvpCountResult.count ?? 0,
        reward_claimed: rewardClaimed === 'true',
      };
      
      return c.json({ user: dbUser, onboarding });
    } catch (error) {
      console.error('Unexpected error in /auth/me:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // â”€â”€ POST /auth/join-guild â€” DEPRECATED â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // Guild joining now uses POST /guilds/:id/join (routes-guilds.ts).
  // This endpoint is kept for backward compatibility but returns 410 Gone.
  app.post(`${PREFIX}/auth/join-guild`, async (c) => {
    return c.json({
      error: 'This endpoint is deprecated. Use POST /guilds/:id/join instead.',
      migration: 'Guild affiliation is now managed via guild_wars_guilds table, not users.role.',
    }, 410);
  });

  // â”€â”€ POST /auth/claim-onboarding-reward â€” Free rank-up â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/auth/claim-onboarding-reward`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('id, role, rank_id, prestige_level, steam_id').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);

      // Check if already claimed
      const alreadyClaimed = await kv.get(`onboarding_reward:${dbUser.id}`);
      if (alreadyClaimed === 'true') {
        return c.json({ error: 'Onboarding reward already claimed' }, 400);
      }

      // Verify all required steps are complete
      const isDiscord = true; // always true if they're authenticated
      const isSteam = !!dbUser.steam_id;
      const isGuild = dbUser.role !== 'guest';

      if (!isDiscord || !isSteam || !isGuild) {
        return c.json({ error: 'Not all onboarding steps are complete (need: Steam linked and Guild joined)' }, 400);
      }

      // Grant free rank-up (cap at max rank for prestige level)
      const maxRank = dbUser.prestige_level === 5 ? 11 : 10;
      const newRankId = Math.min(dbUser.rank_id + 1, maxRank);

      const { data: updatedUser, error: updateError } = await supabase
        .from('users')
        .update({ rank_id: newRankId, updated_at: new Date().toISOString() })
        .eq('id', dbUser.id)
        .select(`*, ranks ( id, name, display_order )`)
        .single();

      if (updateError) {
        console.error('Error granting onboarding rank-up:', updateError);
        return c.json({ error: 'Failed to grant rank-up' }, 500);
      }

      // Sync Discord roles (background/best-effort)
      syncDiscordUserRoles(supabase, dbUser.id, newRankId, dbUser.prestige_level);

      // Mark as claimed
      await kv.set(`onboarding_reward:${dbUser.id}`, 'true');

      // Log onboarding reward (non-critical)
      try {
        const { data: rankData } = await supabase.from('ranks').select('name').eq('id', newRankId).single();
        const rankName = rankData?.name || `Rank ${newRankId}`;
        await createUserActivity({
          user_id: dbUser.id,
          type: 'onboarding_reward',
          title: 'Onboarding Rank-Up Claimed',
          description: `You completed onboarding and received a free rank-up to ${rankName}!`,
        });
      } catch (_) { /* non-critical */ }

      console.log(`Onboarding reward claimed: user ${dbUser.id} ranked up to ${newRankId}`);
      return c.json({ user: updatedUser, ranked_up: true, new_rank_id: newRankId });
    } catch (error) {
      console.error('Claim onboarding reward error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

}

/**
 * Bracket Builder Routes
 * Officer-only routes for building tournament bracket structure
 * (phases, match groups, match assignments) using kkup_matches columns.
 *
 * The bracket "structure" is stored two places:
 *   1. kkup_tournaments.bracket_config JSONB â€” phase + group metadata (name, type, team counts, etc.)
 *   2. kkup_matches columns â€” phase, match_group, match_group_type, matchup_type,
 *      is_final_node_group, phase_order, match_group_order, game_number
 *
 * Routes:
 *   GET  /kkup/tournaments/:id/bracket-builder          â€” full structure + matches
 *   PUT  /kkup/tournaments/:id/bracket-builder/config   â€” save bracket_config (phases + groups)
 *   PUT  /kkup/tournaments/:id/bracket-builder/assign   â€” assign match IDs to a group
 *   PUT  /kkup/tournaments/:id/bracket-builder/unassign â€” remove match IDs from their group
 */

import { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import { isOfficer } from "./roles.ts";

async function requireOfficer(c: any, supabase: any, anonSupabase: any) {
  const token = c.req.header('Authorization')?.split(' ')[1];
  if (!token) return { ok: false, response: c.json({ error: 'No access token' }, 401) };
  const { data: { user: authUser }, error } = await anonSupabase.auth.getUser(token);
  if (error || !authUser) return { ok: false, response: c.json({ error: 'Unauthorized' }, 401) };
  const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', authUser.id).single();
  if (!dbUser || !isOfficer(dbUser.role)) return { ok: false, response: c.json({ error: 'Officer access required' }, 403) };
  return { ok: true, dbUser };
}

export function registerBracketBuilderRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // GET â€” Full bracket structure + all matches
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/kkup/tournaments/:id/bracket-builder`, async (c) => {
    try {
      const tournamentId = c.req.param('id');

      const { data: tournament, error: tErr } = await supabase
        .from('kkup_tournaments')
        .select('id, name, bracket_config')
        .eq('id', tournamentId)
        .single();

      if (tErr || !tournament) {
        return c.json({ error: `Tournament not found: ${tErr?.message}` }, 404);
      }

      const { data: matches, error: mErr } = await supabase
        .from('kkup_matches')
        .select(`
          id, external_match_id, series_id, match_status,
          radiant_team_id, dire_team_id, winning_team_id,
          radiant_team_score, dire_team_score,
          phase, match_group, match_group_type, matchup_type,
          is_final_node_group, phase_order, match_group_order, game_number,
          scheduled_time,
          team1:kkup_teams!radiant_team_id(id, team_name, team_tag, logo_url),
          team2:kkup_teams!dire_team_id(id, team_name, team_tag, logo_url)
        `)
        .eq('tournament_id', tournamentId)
        .order('phase_order', { ascending: true, nullsFirst: false })
        .order('match_group_order', { ascending: true, nullsFirst: false })
        .order('game_number', { ascending: true });

      if (mErr) {
        return c.json({ error: `Failed to fetch matches: ${mErr.message}` }, 500);
      }

      const bracketConfig = tournament.bracket_config || { phases: [] };
      const allMatches = (matches || []).map(m => ({
        ...m,
        team1_id: m.radiant_team_id,
        team2_id: m.dire_team_id,
        winner_team_id: m.winning_team_id,
        team1_score: m.radiant_team_score,
        team2_score: m.dire_team_score,
      }));

      // Organize matches by phase â†’ match_group
      const assigned: Record<string, Record<string, any[]>> = {};
      const unassigned: any[] = [];

      for (const match of allMatches) {
        if (match.phase && match.match_group) {
          if (!assigned[match.phase]) assigned[match.phase] = {};
          if (!assigned[match.phase][match.match_group]) assigned[match.phase][match.match_group] = [];
          assigned[match.phase][match.match_group].push(match);
        } else {
          unassigned.push(match);
        }
      }

      return c.json({ bracketConfig, assigned, unassigned, matches: allMatches });

    } catch (err: any) {
      console.error('Bracket builder GET error:', err);
      return c.json({ error: `Internal error: ${err.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // PUT /config â€” Save bracket_config (phase/group metadata)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.put(`${PREFIX}/kkup/tournaments/:id/bracket-builder/config`, async (c) => {
    try {
      const auth = await requireOfficer(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');
      const body = await c.req.json();
      const { bracket_config } = body;

      if (!bracket_config) return c.json({ error: 'bracket_config is required' }, 400);

      const { error: updateErr } = await supabase
        .from('kkup_tournaments')
        .update({ bracket_config })
        .eq('id', tournamentId);

      if (updateErr) {
        return c.json({ error: `Failed to update bracket config: ${updateErr.message}` }, 500);
      }

      return c.json({ success: true });

    } catch (err: any) {
      console.error('Bracket builder config PUT error:', err);
      return c.json({ error: `Internal error: ${err.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // PUT /assign â€” Assign matches to a phase/group
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.put(`${PREFIX}/kkup/tournaments/:id/bracket-builder/assign`, async (c) => {
    try {
      const auth = await requireOfficer(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');
      const body = await c.req.json();
      const {
        match_ids,
        phase,
        match_group,
        match_group_type,
        matchup_type,
        is_final_node_group,
        phase_order,
        match_group_order,
      } = body;

      if (!match_ids?.length) return c.json({ error: 'match_ids array is required' }, 400);
      if (!phase || !match_group) return c.json({ error: 'phase and match_group are required' }, 400);

      // Update all matches, assigning game_number by their order in the array
      const errors: string[] = [];
      for (let i = 0; i < match_ids.length; i++) {
        const { error } = await supabase
          .from('kkup_matches')
          .update({
            phase,
            match_group,
            match_group_type: match_group_type || null,
            matchup_type: matchup_type || null,
            is_final_node_group: is_final_node_group || false,
            phase_order: phase_order ?? 1,
            match_group_order: match_group_order ?? 1,
            game_number: i + 1,
          })
          .eq('id', match_ids[i])
          .eq('tournament_id', tournamentId);

        if (error) {
          console.error(`Failed to assign match ${match_ids[i]}:`, error);
          errors.push(`Match ${match_ids[i]}: ${error.message}`);
        }
      }

      if (errors.length === match_ids.length) {
        return c.json({ error: `All assignments failed: ${errors.join('; ')}` }, 500);
      }

      return c.json({
        success: true,
        updated: match_ids.length - errors.length,
        errors: errors.length ? errors : undefined,
      });

    } catch (err: any) {
      console.error('Bracket builder assign error:', err);
      return c.json({ error: `Internal error: ${err.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // PUT /unassign â€” Remove matches from their group
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.put(`${PREFIX}/kkup/tournaments/:id/bracket-builder/unassign`, async (c) => {
    try {
      const auth = await requireOfficer(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');
      const { match_ids } = await c.req.json();

      if (!match_ids?.length) return c.json({ error: 'match_ids array is required' }, 400);

      const { error } = await supabase
        .from('kkup_matches')
        .update({
          phase: null,
          match_group: null,
          match_group_type: null,
          matchup_type: null,
          is_final_node_group: false,
          phase_order: null,
          match_group_order: null,
          game_number: 1,
        })
        .in('id', match_ids)
        .eq('tournament_id', tournamentId);

      if (error) {
        return c.json({ error: `Failed to unassign matches: ${error.message}` }, 500);
      }

      return c.json({ success: true });

    } catch (err: any) {
      console.error('Bracket builder unassign error:', err);
      return c.json({ error: `Internal error: ${err.message}` }, 500);
    }
  });
}

/**
 * Bracket Routes â€” Generation, reading, and management of tournament brackets.
 *
 * Routes:
 *   POST   /kkup/tournaments/:id/bracket/generate  â€” Generate bracket at roster lock (owner only)
 *   GET    /kkup/tournaments/:id/bracket            â€” Get full bracket (series + matches) (public)
 *   DELETE /kkup/tournaments/:id/bracket            â€” Delete bracket (owner only, for re-generation)
 *   POST   /kkup/tournaments/:id/bracket/series/:seriesId/result â€” Record series winner (officer+)
 *   POST   /kkup/voice-channels/reset               â€” Reset Discord voice channels to defaults (owner only)
 *
 * Tables used: kkup_bracket_series, kkup_bracket_matches, kkup_teams, kkup_team_rosters, users
 *
 * The bracket generation logic:
 *   1. Validates all rostered players have Dota ranks
 *   2. Calculates average team rank for seeding
 *   3. Creates 7 series rows (4 QF + 2 SF + 1 GF) with proper seeding & advancement links
 *   4. Handles byes (6-7 teams) â€” top seeds auto-advance
 *   5. Pre-creates match rows for QF series (game 1 of each)
 *
 * The series advancement logic:
 *   1. Owner/officer records a series winner
 *   2. Series is marked completed, winner_team_id set
 *   3. Winner advances to next_series_id in next_series_slot
 *   4. Loser's voice channel renamed to "Xth Seed: Eliminated"
 *   5. If GF winner, champion channel renamed to "ðŸŒ½ CHAMPION: TAG"
 *   6. If next series now has both teams, pre-create game 1 match
 *   7. Discord webhook + admin log
 */

import { Hono } from "npm:hono";
import { PREFIX, requireAuth as sharedRequireAuth, requireOwner as sharedRequireOwner } from "./helpers.ts";
import { resolveUserRank, rankToNumeric } from "./rank-utils.ts";
import { createAdminLog } from "./routes-notifications.ts";
import { isOfficer } from "./roles.ts";
import { renameTeamVoiceChannels, resetTeamVoiceChannels, renameDiscordChannel, ordinal, DISCORD_TEAM_VOICE_CHANNELS, DISCORD_WEBHOOKS } from "./discord-config.ts";
import { sendWebhookEmbed } from "./discord-embeds.tsx";

// â”€â”€ Seeding map: Tate's official bracket â”€â”€
// QF1: Seed 1 vs Seed 8 â†’ SF1 radiant
// QF2: Seed 3 vs Seed 6 â†’ SF1 dire
// QF3: Seed 2 vs Seed 7 â†’ SF2 radiant
// QF4: Seed 4 vs Seed 5 â†’ SF2 dire
const BRACKET_TEMPLATE = {
  QF: [
    { position: 1, seedRadiant: 1, seedDire: 8, nextRound: 'SF', nextPosition: 1, nextSlot: 'radiant' },
    { position: 2, seedRadiant: 3, seedDire: 6, nextRound: 'SF', nextPosition: 1, nextSlot: 'dire' },
    { position: 3, seedRadiant: 2, seedDire: 7, nextRound: 'SF', nextPosition: 2, nextSlot: 'radiant' },
    { position: 4, seedRadiant: 4, seedDire: 5, nextRound: 'SF', nextPosition: 2, nextSlot: 'dire' },
  ],
  SF: [
    { position: 1, nextRound: 'GF', nextPosition: 1, nextSlot: 'radiant' },
    { position: 2, nextRound: 'GF', nextPosition: 1, nextSlot: 'dire' },
  ],
  GF: [
    { position: 1 },
  ],
} as const;

/**
 * Calculate the average numeric rank for a team's roster.
 * Returns { avgRank, playerCount, unrankedPlayers[] }.
 */
async function calculateTeamSeedRank(
  supabase: any,
  teamId: string,
  tournamentType: string,
): Promise<{
  avgRank: number;
  playerCount: number;
  unrankedPlayers: { name: string; userId: string | null }[];
}> {
  // Get roster members with their linked user data
  const { data: roster, error } = await supabase
    .from('kkup_team_rosters')
    .select(`
      id,
      person:kkup_persons!person_id (
        id, display_name, user_id
      )
    `)
    .eq('team_id', teamId);

  if (error || !roster?.length) {
    return { avgRank: 0, playerCount: 0, unrankedPlayers: [] };
  }

  const unrankedPlayers: { name: string; userId: string | null }[] = [];
  let totalRank = 0;
  let rankedCount = 0;

  for (const member of roster) {
    const person = member.person;
    if (!person?.user_id) {
      unrankedPlayers.push({ name: person?.display_name || 'Unknown', userId: null });
      continue;
    }

    // Fetch the user's rank data
    const { data: user } = await supabase
      .from('users')
      .select('id, discord_username, opendota_data')
      .eq('id', person.user_id)
      .single();

    const rank = resolveUserRank(user);
    if (!rank) {
      unrankedPlayers.push({ name: person.display_name || user?.discord_username || 'Unknown', userId: person.user_id });
      continue;
    }

    totalRank += rankToNumeric(rank.medal, rank.stars);
    rankedCount++;
  }

  return {
    avgRank: rankedCount > 0 ? totalRank / rankedCount : 0,
    playerCount: roster.length,
    unrankedPlayers,
  };
}


export function registerBracketRoutes(app: Hono, supabase: any, anonSupabase: any) {

  const requireOwner = (c: any) => sharedRequireOwner(c, supabase, anonSupabase);
  const requireAuth = (c: any) => sharedRequireAuth(c, supabase, anonSupabase);


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 1. GENERATE BRACKET (Owner only)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/kkup/tournaments/:id/bracket/generate`, async (c) => {
    try {
      const auth = await requireOwner(c);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');

      // Fetch tournament
      const { data: tournament, error: tErr } = await supabase
        .from('kkup_tournaments')
        .select('*')
        .eq('id', tournamentId)
        .single();

      if (tErr || !tournament) {
        return c.json({ error: `Tournament not found: ${tErr?.message || 'no data'}` }, 404);
      }

      // Must be in roster_lock or registration_closed to generate bracket
      if (!['roster_lock', 'registration_closed'].includes(tournament.status)) {
        const msg = `Cannot generate bracket in "${tournament.status}" phase. Tournament must be in "registration_closed" or "roster_lock".`;
        console.log(`Bracket generation blocked: ${msg}`);
        return c.json({
          error: msg,
        }, 400);
      }

      // Check if bracket already exists
      const { data: existingSeries } = await supabase
        .from('kkup_bracket_series')
        .select('id')
        .eq('tournament_id', tournamentId)
        .limit(1);

      if (existingSeries?.length > 0) {
        return c.json({
          error: 'Bracket already exists for this tournament. Delete it first if you need to re-generate.',
        }, 409);
      }

      // Get approved teams
      const { data: teams, error: teamsErr } = await supabase
        .from('kkup_teams')
        .select('id, team_name, team_tag, logo_url, approval_status')
        .eq('tournament_id', tournamentId)
        .eq('approval_status', 'approved');

      if (teamsErr) {
        return c.json({ error: `Failed to fetch teams: ${teamsErr.message}` }, 500);
      }

      const teamCount = teams?.length || 0;

      // Use tournament's configured min_teams, or default to 2 (absolute minimum for any bracket)
      const minTeamsRequired = tournament.min_teams || 2;

      if (teamCount < minTeamsRequired) {
        const msg = `Need at least ${minTeamsRequired} approved teams to generate a bracket. Currently have ${teamCount}.`;
        console.log(`Bracket generation blocked: ${msg}`);
        return c.json({
          error: msg,
        }, 400);
      }

      if (teamCount > 8) {
        const msg = `Maximum 8 teams for single elimination bracket. Currently have ${teamCount} approved teams. Deny some before generating.`;
        console.log(`Bracket generation blocked: ${msg}`);
        return c.json({
          error: msg,
        }, 400);
      }

      // â”€â”€ Calculate seeding for all teams â”€â”€
      const allUnrankedPlayers: { teamName: string; name: string; userId: string | null }[] = [];
      const teamSeeds: { teamId: string; teamName: string; avgRank: number; playerCount: number }[] = [];

      for (const team of teams) {
        const seedData = await calculateTeamSeedRank(supabase, team.id, tournament.tournament_type);

        if (seedData.unrankedPlayers.length > 0) {
          for (const p of seedData.unrankedPlayers) {
            allUnrankedPlayers.push({ teamName: team.team_name, ...p });
          }
        }

        teamSeeds.push({
          teamId: team.id,
          teamName: team.team_name,
          avgRank: seedData.avgRank,
          playerCount: seedData.playerCount,
        });
      }

      // Block if any players are unranked
      if (allUnrankedPlayers.length > 0) {
        const msg = `Cannot generate bracket â€” ${allUnrankedPlayers.length} player(s) have no rank set.`;
        console.log(`Bracket generation blocked: ${msg}`, allUnrankedPlayers.map(p => `${p.teamName}: ${p.name}`));
        return c.json({
          error: 'Cannot generate bracket â€” some players have no rank set.',
          unrankedPlayers: allUnrankedPlayers,
          message: `${allUnrankedPlayers.length} player(s) need ranks before roster lock. Use the officer rank override tool to set them.`,
        }, 400);
      }

      // Sort by avgRank descending (highest rank = seed 1)
      teamSeeds.sort((a, b) => b.avgRank - a.avgRank);

      // Assign seed numbers 1-N
      const seededTeams: Map<number, { teamId: string; teamName: string; avgRank: number }> = new Map();
      teamSeeds.forEach((t, i) => {
        seededTeams.set(i + 1, t);
      });

      console.log(`Bracket seeding for "${tournament.name}":`, teamSeeds.map((t, i) => `Seed ${i + 1}: ${t.teamName} (avg ${t.avgRank.toFixed(1)})`));

      // Determine best-of for each round from tournament config or defaults
      const bestOfQF = tournament.bracket_config?.best_of_qf || 1;
      const bestOfSF = tournament.bracket_config?.best_of_sf || 3;
      const bestOfGF = tournament.bracket_config?.best_of_gf || 5;

      const bestOfByRound: Record<string, number> = {
        QF: bestOfQF,
        SF: bestOfSF,
        GF: bestOfGF,
      };

      // â”€â”€ Create series rows (bottom-up: GF first, then SF, then QF) â”€â”€
      // We need GF/SF IDs first so QF rows can reference them via next_series_id

      // Step 1: Create GF series
      const gfTemplate = BRACKET_TEMPLATE.GF[0];
      const { data: gfSeries, error: gfErr } = await supabase
        .from('kkup_bracket_series')
        .insert({
          tournament_id: tournamentId,
          round: 'GF',
          position: gfTemplate.position,
          best_of: bestOfByRound.GF,
          status: 'pending',
        })
        .select()
        .single();

      if (gfErr) {
        return c.json({ error: `Failed to create GF series: ${gfErr.message}` }, 500);
      }

      // Step 2: Create SF series (linking to GF)
      const sfSeriesMap: Record<number, string> = {}; // position -> series ID

      for (const sfTemplate of BRACKET_TEMPLATE.SF) {
        const { data: sfSeries, error: sfErr } = await supabase
          .from('kkup_bracket_series')
          .insert({
            tournament_id: tournamentId,
            round: 'SF',
            position: sfTemplate.position,
            best_of: bestOfByRound.SF,
            status: 'pending',
            next_series_id: gfSeries.id,
            next_series_slot: sfTemplate.nextSlot,
          })
          .select()
          .single();

        if (sfErr) {
          // Cleanup GF on failure
          await supabase.from('kkup_bracket_series').delete().eq('tournament_id', tournamentId);
          return c.json({ error: `Failed to create SF series: ${sfErr.message}` }, 500);
        }

        sfSeriesMap[sfTemplate.position] = sfSeries.id;
      }

      // Step 3: Create QF series (linking to SF, with teams assigned)
      const qfResults: any[] = [];

      for (const qfTemplate of BRACKET_TEMPLATE.QF) {
        const radiantTeam = seededTeams.get(qfTemplate.seedRadiant);
        const direTeam = seededTeams.get(qfTemplate.seedDire);

        // Determine the target SF series
        const nextSeriesId = sfSeriesMap[qfTemplate.nextPosition];

        // Determine if this is a bye (dire seed doesn't exist because < 8 teams)
        const isBye = !direTeam;

        const { data: qfSeries, error: qfErr } = await supabase
          .from('kkup_bracket_series')
          .insert({
            tournament_id: tournamentId,
            round: 'QF',
            position: qfTemplate.position,
            seed_radiant: qfTemplate.seedRadiant,
            seed_dire: isBye ? null : qfTemplate.seedDire,
            radiant_team_id: radiantTeam?.teamId || null,
            dire_team_id: isBye ? null : (direTeam?.teamId || null),
            best_of: bestOfByRound.QF,
            status: isBye ? 'bye' : 'pending',
            winner_team_id: isBye ? (radiantTeam?.teamId || null) : null,
            next_series_id: nextSeriesId,
            next_series_slot: qfTemplate.nextSlot,
            completed_at: isBye ? new Date().toISOString() : null,
          })
          .select()
          .single();

        if (qfErr) {
          await supabase.from('kkup_bracket_series').delete().eq('tournament_id', tournamentId);
          return c.json({ error: `Failed to create QF${qfTemplate.position} series: ${qfErr.message}` }, 500);
        }

        qfResults.push({ ...qfSeries, isBye });

        // If bye, auto-advance the winner to the SF
        if (isBye && radiantTeam) {
          const slotColumn = qfTemplate.nextSlot === 'radiant' ? 'radiant_team_id' : 'dire_team_id';
          const seedColumn = qfTemplate.nextSlot === 'radiant' ? 'seed_radiant' : 'seed_dire';

          await supabase
            .from('kkup_bracket_series')
            .update({
              [slotColumn]: radiantTeam.teamId,
              [seedColumn]: qfTemplate.seedRadiant,
            })
            .eq('id', nextSeriesId);
        }
      }

      // Step 4: Pre-create game 1 match rows for non-bye QF series
      for (const qf of qfResults) {
        if (qf.isBye) continue;

        const { error: matchErr } = await supabase
          .from('kkup_bracket_matches')
          .insert({
            series_id: qf.id,
            game_number: 1,
            radiant_team_id: qf.radiant_team_id,
            dire_team_id: qf.dire_team_id,
            status: 'pending',
          });

        if (matchErr) {
          console.error(`Non-critical: Failed to pre-create match for QF${qf.position}: ${matchErr.message}`);
        }
      }

      // Log admin action (non-critical)
      try {
        const byeCount = qfResults.filter(q => q.isBye).length;
        const seedingSummary = teamSeeds.map((t, i) => `${i + 1}. ${t.teamName}`).join(', ');
        await createAdminLog({
          type: 'bracket_generated',
          action: `Generated ${teamCount}-team bracket for "${tournament.name}"${byeCount > 0 ? ` (${byeCount} bye${byeCount > 1 ? 's' : ''})` : ''}. Seeding: ${seedingSummary}`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          details: {
            tournament_id: tournamentId,
            team_count: teamCount,
            bye_count: byeCount,
            seeding: teamSeeds.map((t, i) => ({ seed: i + 1, team: t.teamName, avgRank: t.avgRank })),
          },
        });
      } catch (_) { /* non-critical */ }

      // Rename Discord team voice channels to show seeding (non-critical)
      // Maps seed 1 â†’ channel[0] "1st Seed: CDGS", seed 2 â†’ channel[1] "2nd Seed: FTHOG", etc.
      try {
        const teamLookup = new Map(teams.map((t: any) => [t.id, t]));
        const seededTeamsForDiscord = teamSeeds.map((t, i) => ({
          seed: i + 1,
          teamTag: teamLookup.get(t.teamId)?.team_tag || t.teamName.substring(0, 4),
        }));
        const result = await renameTeamVoiceChannels(seededTeamsForDiscord);
        console.log(`Discord voice channel rename: ${result.renamed} renamed, ${result.failed} failed`);
      } catch (vcErr) {
        console.error('Non-critical: Discord voice channel rename failed:', vcErr);
      }

      // Send bracket generated webhook to #kkup-updates (non-critical)
      try {
        const byeCount = qfResults.filter(q => q.isBye).length;
        const seedingLines = teamSeeds.map((t, i) => `**${i + 1}.** ${t.teamName}`).join('\n');
        await sendWebhookEmbed(DISCORD_WEBHOOKS.BRACKET_UPDATE, {
          title: `ðŸŒ½ Bracket Generated â€” ${tournament.name}`,
          description: `${teamCount}-team single elimination bracket is live!${byeCount > 0 ? ` (${byeCount} bye${byeCount > 1 ? 's' : ''})` : ''}\n\n**Seeding:**\n${seedingLines}`,
          color: 0xD6A615, // harvest gold
          footer: { text: 'Voice channels have been renamed to match seedings.' },
        });
      } catch (_) { /* non-critical */ }

      return c.json({
        success: true,
        message: `Bracket generated for "${tournament.name}" with ${teamCount} teams.`,
        teamCount,
        byeCount: qfResults.filter(q => q.isBye).length,
        seeding: teamSeeds.map((t, i) => ({
          seed: i + 1,
          teamId: t.teamId,
          teamName: t.teamName,
          avgRank: Math.round(t.avgRank * 10) / 10,
        })),
      });

    } catch (error: any) {
      console.error('Bracket generation error:', error);
      return c.json({ error: `Internal server error during bracket generation: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 2. GET BRACKET (Public)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/kkup/tournaments/:id/bracket`, async (c) => {
    try {
      const tournamentId = c.req.param('id');

      // Fetch all series for this tournament
      const { data: series, error: sErr } = await supabase
        .from('kkup_bracket_series')
        .select(`
          *,
          radiant_team:kkup_teams!radiant_team_id ( id, team_name, team_tag, logo_url ),
          dire_team:kkup_teams!dire_team_id ( id, team_name, team_tag, logo_url ),
          winner_team:kkup_teams!winner_team_id ( id, team_name, team_tag, logo_url )
        `)
        .eq('tournament_id', tournamentId)
        .order('round')
        .order('position');

      if (sErr) {
        return c.json({ error: `Failed to fetch bracket: ${sErr.message}` }, 500);
      }

      if (!series || series.length === 0) {
        return c.json({ bracket: null, message: 'No bracket generated yet.' });
      }

      // Fetch all matches for these series
      const seriesIds = series.map((s: any) => s.id);
      const { data: matches, error: mErr } = await supabase
        .from('kkup_bracket_matches')
        .select(`
          *,
          radiant_team:kkup_teams!radiant_team_id ( id, team_name, team_tag, logo_url ),
          dire_team:kkup_teams!dire_team_id ( id, team_name, team_tag, logo_url ),
          winner_team:kkup_teams!winner_team_id ( id, team_name, team_tag, logo_url )
        `)
        .in('series_id', seriesIds)
        .order('game_number');

      if (mErr) {
        console.error('Failed to fetch bracket matches:', mErr);
      }

      // Group matches by series
      const matchesBySeries: Record<string, any[]> = {};
      for (const match of (matches || [])) {
        if (!matchesBySeries[match.series_id]) {
          matchesBySeries[match.series_id] = [];
        }
        matchesBySeries[match.series_id].push(match);
      }

      // Attach matches to series
      const enrichedSeries = series.map((s: any) => ({
        ...s,
        matches: matchesBySeries[s.id] || [],
      }));

      // Organize by round for easy frontend consumption
      const bracket = {
        QF: enrichedSeries.filter((s: any) => s.round === 'QF').sort((a: any, b: any) => a.position - b.position),
        SF: enrichedSeries.filter((s: any) => s.round === 'SF').sort((a: any, b: any) => a.position - b.position),
        GF: enrichedSeries.filter((s: any) => s.round === 'GF'),
      };

      return c.json({ bracket });

    } catch (error: any) {
      console.error('Fetch bracket error:', error);
      return c.json({ error: `Internal server error fetching bracket: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 3. DELETE BRACKET (Owner only â€” for re-generation)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.delete(`${PREFIX}/kkup/tournaments/:id/bracket`, async (c) => {
    try {
      const auth = await requireOwner(c);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');

      // Fetch tournament to validate
      const { data: tournament } = await supabase
        .from('kkup_tournaments')
        .select('id, name, status')
        .eq('id', tournamentId)
        .single();

      if (!tournament) {
        return c.json({ error: 'Tournament not found' }, 404);
      }

      // Don't allow deletion if tournament is live or completed (safety valve)
      if (['live', 'completed'].includes(tournament.status)) {
        return c.json({
          error: `Cannot delete bracket while tournament is "${tournament.status}". Change status first.`,
        }, 400);
      }

      // Delete all matches first (FK cascade should handle this, but be explicit)
      const { data: series } = await supabase
        .from('kkup_bracket_series')
        .select('id')
        .eq('tournament_id', tournamentId);

      if (series?.length > 0) {
        const seriesIds = series.map((s: any) => s.id);
        await supabase
          .from('kkup_bracket_matches')
          .delete()
          .in('series_id', seriesIds);
      }

      // Delete all series
      const { error: delErr } = await supabase
        .from('kkup_bracket_series')
        .delete()
        .eq('tournament_id', tournamentId);

      if (delErr) {
        return c.json({ error: `Failed to delete bracket: ${delErr.message}` }, 500);
      }

      // Admin log (non-critical)
      try {
        await createAdminLog({
          type: 'bracket_deleted',
          action: `Deleted bracket for "${tournament.name}"`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          details: { tournament_id: tournamentId },
        });
      } catch (_) { /* non-critical */ }

      // Reset Discord team voice channels back to "Team 1", "Team 2", etc. (non-critical)
      try {
        await resetTeamVoiceChannels();
        console.log('Discord voice channels reset to defaults');
      } catch (vcErr) {
        console.error('Non-critical: Discord voice channel reset failed:', vcErr);
      }

      return c.json({
        success: true,
        message: `Bracket deleted for "${tournament.name}". You can now re-generate.`,
      });

    } catch (error: any) {
      console.error('Delete bracket error:', error);
      return c.json({ error: `Internal server error deleting bracket: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 4. RECORD SERIES WINNER (Officer+)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/kkup/tournaments/:id/bracket/series/:seriesId/result`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');
      const seriesId = c.req.param('seriesId');
      const { winner_team_id: winnerTeamId } = await c.req.json();

      if (!winnerTeamId) {
        return c.json({ error: 'Missing winner_team_id in request body' }, 400);
      }

      // Fetch tournament
      const { data: tournament } = await supabase
        .from('kkup_tournaments')
        .select('id, name, status')
        .eq('id', tournamentId)
        .single();

      if (!tournament) {
        return c.json({ error: 'Tournament not found' }, 404);
      }

      if (tournament.status !== 'live') {
        return c.json({
          error: `Cannot record series results while tournament is "${tournament.status}". Tournament must be "live".`,
        }, 400);
      }

      // Fetch series with joined team data (we need team_tag for Discord channels)
      const { data: series } = await supabase
        .from('kkup_bracket_series')
        .select(`
          *,
          radiant_team:kkup_teams!radiant_team_id ( id, team_name, team_tag ),
          dire_team:kkup_teams!dire_team_id ( id, team_name, team_tag )
        `)
        .eq('id', seriesId)
        .single();

      if (!series) {
        return c.json({ error: 'Series not found' }, 404);
      }

      if (series.tournament_id !== tournamentId) {
        return c.json({ error: 'Series does not belong to this tournament' }, 400);
      }

      if (series.status === 'completed') {
        return c.json({ error: 'Series already has a recorded result' }, 409);
      }

      // Validate winner is one of the two teams
      const winnerIsRadiant = winnerTeamId === series.radiant_team_id;
      const winnerIsDire = winnerTeamId === series.dire_team_id;
      if (!winnerIsRadiant && !winnerIsDire) {
        return c.json({ error: `Team ${winnerTeamId} is not part of this series.` }, 400);
      }

      // Determine winner/loser data
      const winnerTeam = winnerIsRadiant ? series.radiant_team : series.dire_team;
      const loserTeam = winnerIsRadiant ? series.dire_team : series.radiant_team;
      const winnerSeed = winnerIsRadiant ? series.seed_radiant : series.seed_dire;
      const loserSeed = winnerIsRadiant ? series.seed_dire : series.seed_radiant;

      // â”€â”€ Mark series completed â”€â”€
      const { error: updateErr } = await supabase
        .from('kkup_bracket_series')
        .update({
          winner_team_id: winnerTeamId,
          status: 'completed',
          completed_at: new Date().toISOString(),
        })
        .eq('id', seriesId);

      if (updateErr) {
        return c.json({ error: `Failed to update series: ${updateErr.message}` }, 500);
      }

      // â”€â”€ Advance winner to next series â”€â”€
      const isGrandFinal = series.round === 'GF';

      if (series.next_series_id && !isGrandFinal) {
        const slotColumn = series.next_series_slot === 'radiant' ? 'radiant_team_id' : 'dire_team_id';
        const seedColumn = series.next_series_slot === 'radiant' ? 'seed_radiant' : 'seed_dire';

        const { data: nextSeries, error: advErr } = await supabase
          .from('kkup_bracket_series')
          .update({
            [slotColumn]: winnerTeamId,
            [seedColumn]: winnerSeed,
          })
          .eq('id', series.next_series_id)
          .select()
          .single();

        if (advErr) {
          console.error(`Failed to advance winner to next series: ${advErr.message}`);
          // Don't fail the whole request â€” series is already marked completed
        }

        // If next series now has both teams, pre-create game 1 match
        if (nextSeries?.radiant_team_id && nextSeries?.dire_team_id) {
          try {
            await supabase
              .from('kkup_bracket_matches')
              .insert({
                series_id: nextSeries.id,
                game_number: 1,
                radiant_team_id: nextSeries.radiant_team_id,
                dire_team_id: nextSeries.dire_team_id,
                status: 'pending',
              });
          } catch (matchErr) {
            console.error('Non-critical: Failed to pre-create match for next series:', matchErr);
          }
        }
      }

      // â”€â”€ Discord voice channel updates (non-critical) â”€â”€

      // Rename loser's channel to "Xth Seed: Eliminated"
      try {
        if (loserSeed && loserSeed >= 1 && loserSeed <= DISCORD_TEAM_VOICE_CHANNELS.length) {
          const channelId = DISCORD_TEAM_VOICE_CHANNELS[loserSeed - 1];
          await renameDiscordChannel(channelId, `${ordinal(loserSeed)} Seed: Eliminated`);
        }
      } catch (vcErr) {
        console.error('Non-critical: loser channel rename failed:', vcErr);
      }

      // If GF, also rename champion's channel and loser's (runner-up)
      if (isGrandFinal) {
        try {
          if (winnerSeed && winnerSeed >= 1 && winnerSeed <= DISCORD_TEAM_VOICE_CHANNELS.length) {
            const channelId = DISCORD_TEAM_VOICE_CHANNELS[winnerSeed - 1];
            const tag = winnerTeam?.team_tag?.toUpperCase() || winnerTeam?.team_name?.substring(0, 4).toUpperCase() || 'CHAMP';
            await renameDiscordChannel(channelId, `ðŸŒ½ CHAMPION: ${tag}`);
          }
        } catch (vcErr) {
          console.error('Non-critical: champion channel rename failed:', vcErr);
        }
      }

      // â”€â”€ Webhook to #kkup-updates (non-critical) â”€â”€
      try {
        const ROUND_LABELS: Record<string, string> = { QF: 'Quarterfinal', SF: 'Semifinal', GF: 'Grand Final' };
        const roundLabel = ROUND_LABELS[series.round] || series.round;
        const winnerName = winnerTeam?.team_name || 'Unknown';
        const loserName = loserTeam?.team_name || 'Unknown';

        if (isGrandFinal) {
          // Special champion embed
          await sendWebhookEmbed(DISCORD_WEBHOOKS.BRACKET_UPDATE, {
            title: `ðŸŒ½ðŸ‘‘ CHAMPION â€” ${tournament.name}`,
            description: `**${winnerName}** has won the ${tournament.name}!\n\nDefeated **${loserName}** in the Grand Final.`,
            color: 0xF1C60F, // kernel gold
          });
        } else {
          await sendWebhookEmbed(DISCORD_WEBHOOKS.BRACKET_UPDATE, {
            title: `âš”ï¸ ${roundLabel} Result â€” ${tournament.name}`,
            description: `**${winnerName}** defeated **${loserName}** and advances!`,
            color: 0xD6A615,
          });
        }
      } catch (_) { /* non-critical */ }

      // â”€â”€ Admin log (non-critical) â”€â”€
      try {
        await createAdminLog({
          type: 'series_result_recorded',
          action: `Recorded ${series.round}${series.position} result for "${tournament.name}": ${winnerTeam?.team_name || 'Unknown'} defeats ${loserTeam?.team_name || 'Unknown'}${isGrandFinal ? ' â€” TOURNAMENT CHAMPION!' : ''}`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          details: {
            tournament_id: tournamentId,
            series_id: seriesId,
            round: series.round,
            position: series.position,
            winner_team_id: winnerTeamId,
            winner_name: winnerTeam?.team_name,
            loser_name: loserTeam?.team_name,
            is_grand_final: isGrandFinal,
          },
        });
      } catch (_) { /* non-critical */ }

      return c.json({
        success: true,
        message: isGrandFinal
          ? `ðŸŒ½ ${winnerTeam?.team_name} wins ${tournament.name}!`
          : `${winnerTeam?.team_name} advances from ${series.round}${series.position}.`,
        is_grand_final: isGrandFinal,
        winner: { id: winnerTeamId, name: winnerTeam?.team_name, seed: winnerSeed },
        loser: { id: loserTeam?.id, name: loserTeam?.team_name, seed: loserSeed },
      });

    } catch (error: any) {
      console.error('Record series result error:', error);
      return c.json({ error: `Internal server error recording series result: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 5. RESET DISCORD VOICE CHANNELS (Owner only)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/kkup/voice-channels/reset`, async (c) => {
    try {
      const auth = await requireOwner(c);
      if (!auth.ok) return auth.response;

      // Reset Discord team voice channels back to "Team 1", "Team 2", etc. (non-critical)
      try {
        await resetTeamVoiceChannels();
        console.log('Discord voice channels reset to defaults');
      } catch (vcErr) {
        console.error('Non-critical: Discord voice channel reset failed:', vcErr);
      }

      return c.json({
        success: true,
        message: 'Discord voice channels reset to defaults.',
      });

    } catch (error: any) {
      console.error('Reset voice channels error:', error);
      return c.json({ error: `Internal server error resetting voice channels: ${error.message}` }, 500);
    }
  });

}

/**
 * Routes: App Configuration
 *
 * KV-backed config values that officers can tweak at runtime.
 * Currently supports: max player rank for tournament eligibility.
 */
import type { Hono } from "npm:hono";
import type { SupabaseClient } from "npm:@supabase/supabase-js@2";
import { PREFIX } from "./helpers.ts";
import { isOfficer } from "./roles.ts";
import * as kv from "./kv_store.tsx";

// â”€â”€ Defaults â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Numeric rank scale: Herald 1 = 1, Divine 1 = 31, Immortal = 36
export const DEFAULT_MAX_PLAYER_RANK = 31; // Divine 1
export const DEFAULT_MIN_PLAYER_RANK = 1;  // Herald 1

const CONFIG_KEY_MAX = "config:max_player_rank";
const CONFIG_KEY_MIN = "config:min_player_rank";

// â”€â”€ Shared getters (used by other route modules) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
/**
 * Read the current max player rank from KV, falling back to the default.
 * Returns a numeric value on the 1â€“36 scale.
 */
export async function getMaxPlayerRank(): Promise<number> {
  try {
    const stored = await kv.get(CONFIG_KEY_MAX);
    if (stored !== null && stored !== undefined) {
      const parsed = typeof stored === "number" ? stored : Number(stored);
      if (!isNaN(parsed) && parsed >= 1 && parsed <= 36) return parsed;
    }
  } catch (err) {
    console.error("Non-critical: failed to read max_player_rank from KV:", err);
  }
  return DEFAULT_MAX_PLAYER_RANK;
}

/**
 * Read the current min player rank from KV, falling back to the default.
 * Returns a numeric value on the 1â€“36 scale.
 */
export async function getMinPlayerRank(): Promise<number> {
  try {
    const stored = await kv.get(CONFIG_KEY_MIN);
    if (stored !== null && stored !== undefined) {
      const parsed = typeof stored === "number" ? stored : Number(stored);
      if (!isNaN(parsed) && parsed >= 1 && parsed <= 36) return parsed;
    }
  } catch (err) {
    console.error("Non-critical: failed to read min_player_rank from KV:", err);
  }
  return DEFAULT_MIN_PLAYER_RANK;
}

// â”€â”€ Medal helpers (server-side, mirrors frontend rank-utils) â”€
const MEDAL_ORDER = [
  "Herald",
  "Guardian",
  "Crusader",
  "Archon",
  "Legend",
  "Ancient",
  "Divine",
  "Immortal",
] as const;

function numericToRank(value: number): { medal: string; stars: number } {
  if (value <= 0) return { medal: "Unranked", stars: 0 };
  if (value >= 36) return { medal: "Immortal", stars: 0 };
  const clamped = Math.max(1, Math.min(35, Math.round(value)));
  const tierIndex = Math.floor((clamped - 1) / 5);
  const stars = ((clamped - 1) % 5) + 1;
  return { medal: MEDAL_ORDER[tierIndex], stars };
}

function rankToNumeric(medal: string, stars: number): number {
  const tierIndex = MEDAL_ORDER.indexOf(medal as any);
  if (tierIndex === -1) return 0;
  if (medal === "Immortal") return 36;
  return tierIndex * 5 + Math.max(1, Math.min(5, stars));
}

// â”€â”€ Route Registration â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
export function registerConfigRoutes(
  app: Hono,
  supabase: SupabaseClient,
  _anonSupabase: SupabaseClient,
) {
  // GET /config/max-player-rank â€” public, no auth required
  app.get(`${PREFIX}/config/max-player-rank`, async (c) => {
    try {
      const numeric = await getMaxPlayerRank();
      const { medal, stars } = numericToRank(numeric);
      return c.json({
        numeric,
        medal,
        stars,
        display: medal === "Immortal" ? "Immortal" : `${medal} ${stars}`,
      });
    } catch (err) {
      console.error("Error reading max-player-rank config:", err);
      return c.json({ error: `Failed to read max player rank config: ${err}` }, 500);
    }
  });

  // PUT /config/max-player-rank â€” officer-protected
  app.put(`${PREFIX}/config/max-player-rank`, async (c) => {
    try {
      // Auth check
      const accessToken = c.req.header("Authorization")?.split(" ")[1];
      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id || authError) {
        return c.json({ error: "Unauthorized" }, 401);
      }

      // Role check
      const { data: dbUser } = await supabase
        .from("users")
        .select("role, discord_username")
        .eq("id", user.id)
        .single();
      if (!dbUser || !isOfficer(dbUser.role)) {
        return c.json({ error: "Forbidden: officer role required" }, 403);
      }

      const body = await c.req.json();

      // Accept either { numeric } or { medal, stars }
      let numeric: number;
      if (typeof body.numeric === "number") {
        numeric = body.numeric;
      } else if (body.medal && typeof body.stars === "number") {
        numeric = rankToNumeric(body.medal, body.stars);
      } else {
        return c.json(
          { error: "Provide either { numeric } (1-36) or { medal, stars }" },
          400,
        );
      }

      if (numeric < 1 || numeric > 36) {
        return c.json({ error: "Numeric rank must be between 1 (Herald 1) and 36 (Immortal)" }, 400);
      }

      await kv.set(CONFIG_KEY_MAX, numeric);

      const { medal, stars } = numericToRank(numeric);
      const display = medal === "Immortal" ? "Immortal" : `${medal} ${stars}`;

      console.log(
        `Config updated: max_player_rank set to ${display} (${numeric}) by ${dbUser.discord_username}`,
      );

      return c.json({
        numeric,
        medal,
        stars,
        display,
        updated_by: dbUser.discord_username,
      });
    } catch (err) {
      console.error("Error updating max-player-rank config:", err);
      return c.json({ error: `Failed to update max player rank config: ${err}` }, 500);
    }
  });

  // â”€â”€ Combined rank eligibility endpoints (min + max) â”€â”€

  // GET /config/rank-eligibility â€” public, returns both min and max
  app.get(`${PREFIX}/config/rank-eligibility`, async (c) => {
    try {
      const [minNumeric, maxNumeric] = await Promise.all([
        getMinPlayerRank(),
        getMaxPlayerRank(),
      ]);
      const minRank = numericToRank(minNumeric);
      const maxRank = numericToRank(maxNumeric);
      return c.json({
        min: {
          numeric: minNumeric,
          medal: minRank.medal,
          stars: minRank.stars,
          display: minRank.medal === "Immortal" ? "Immortal" : `${minRank.medal} ${minRank.stars}`,
        },
        max: {
          numeric: maxNumeric,
          medal: maxRank.medal,
          stars: maxRank.stars,
          display: maxRank.medal === "Immortal" ? "Immortal" : `${maxRank.medal} ${maxRank.stars}`,
        },
      });
    } catch (err) {
      console.error("Error reading rank-eligibility config:", err);
      return c.json({ error: `Failed to read rank eligibility config: ${err}` }, 500);
    }
  });

  // PUT /config/rank-eligibility â€” officer-protected, updates both min and max
  app.put(`${PREFIX}/config/rank-eligibility`, async (c) => {
    try {
      const accessToken = c.req.header("Authorization")?.split(" ")[1];
      const {
        data: { user },
        error: authError,
      } = await supabase.auth.getUser(accessToken);
      if (!user?.id || authError) {
        return c.json({ error: "Unauthorized" }, 401);
      }

      const { data: dbUser } = await supabase
        .from("users")
        .select("role, discord_username")
        .eq("id", user.id)
        .single();
      if (!dbUser || !isOfficer(dbUser.role)) {
        return c.json({ error: "Forbidden: officer role required" }, 403);
      }

      const body = await c.req.json();
      const { min_numeric, max_numeric } = body;

      if (typeof min_numeric !== "number" || typeof max_numeric !== "number") {
        return c.json({ error: "Provide { min_numeric, max_numeric } (1-36)" }, 400);
      }
      if (min_numeric < 1 || min_numeric > 36 || max_numeric < 1 || max_numeric > 36) {
        return c.json({ error: "Numeric rank must be between 1 (Herald 1) and 36 (Immortal)" }, 400);
      }
      if (min_numeric > max_numeric) {
        return c.json({ error: "Minimum rank cannot be higher than maximum rank" }, 400);
      }

      await kv.set(CONFIG_KEY_MIN, min_numeric);
      await kv.set(CONFIG_KEY_MAX, max_numeric);

      const minRank = numericToRank(min_numeric);
      const maxRank = numericToRank(max_numeric);
      const minDisplay = minRank.medal === "Immortal" ? "Immortal" : `${minRank.medal} ${minRank.stars}`;
      const maxDisplay = maxRank.medal === "Immortal" ? "Immortal" : `${maxRank.medal} ${maxRank.stars}`;

      console.log(
        `Config updated: rank eligibility set to ${minDisplay} â€“ ${maxDisplay} by ${dbUser.discord_username}`,
      );

      return c.json({
        min: { numeric: min_numeric, medal: minRank.medal, stars: minRank.stars, display: minDisplay },
        max: { numeric: max_numeric, medal: maxRank.medal, stars: maxRank.stars, display: maxDisplay },
        updated_by: dbUser.discord_username,
      });
    } catch (err) {
      console.error("Error updating rank-eligibility config:", err);
      return c.json({ error: `Failed to update rank eligibility config: ${err}` }, 500);
    }
  });
}

/**
 * Stripe Connect Routes â€” Money OUT Pipeline
 *
 * Handles:
 *   POST /connect/onboard            â€” Create Express account + return onboarding URL
 *   GET  /connect/status             â€” Check current user's Connect status
 *   POST /connect/dashboard          â€” Generate Express Dashboard login link
 *   POST /connect/award              â€” Owner: create a prize award
 *   POST /connect/award-batch        â€” Owner: batch create prize awards (multi-recipient)
 *   PUT  /connect/award/:id/accept   â€” Recipient: accept a prize
 *   PUT  /connect/award/:id/decline  â€” Recipient: decline a prize
 *   POST /connect/award/:id/disburse â€” Owner: execute Stripe transfer + update aggregates
 *   PUT  /connect/award/:id/revoke   â€” Owner: revoke a pending/accepted award
 *   GET  /connect/awards/tournament/:id â€” Officer: list awards for a tournament
 *   GET  /connect/awards/mine        â€” Any user: list their own awards
 *   GET  /connect/awards/all         â€” Owner: list ALL awards (admin overview)
 *
 * The flow:
 *   Owner awards prize â†’ Recipient notified â†’ Recipient accepts (must have Connect) â†’ Owner disburses
 *
 * Stripe is authoritative for money movement.
 * Supabase is authoritative for meaning.
 */

import { PREFIX, requireAuth, requireOwner } from './helpers.ts';
import { createNotification, createUserActivity, createAdminLog } from './routes-notifications.ts';
import { isOfficer } from './roles.ts';
import Stripe from 'npm:stripe@17';

// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
// STRIPE CONFIG
// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

function getStripe(): Stripe {
  const key = Deno.env.get('STRIPE_LIVE_SECRET_KEY');
  if (!key) throw new Error('STRIPE_LIVE_SECRET_KEY is not configured');
  return new Stripe(key, { apiVersion: '2024-12-18.acacia' });
}

// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
// HELPERS
// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

/** Format cents â†’ "$12.50" */
function formatCents(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/** Resolve kkup_teams â†’ kkup_master_teams link for a team row */
async function resolveMasterTeamId(supabase: any, teamId: string): Promise<string | null> {
  const { data } = await supabase
    .from('kkup_teams')
    .select('master_team_id')
    .eq('id', teamId)
    .single();
  return data?.master_team_id || null;
}

// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
// ROUTE REGISTRATION
// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

export function registerConnectRoutes(
  app: any,
  supabase: any,
  anonSupabase: any,
) {

  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // POST /connect/onboard â€” Create Stripe Express account + return onboarding URL
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/connect/onboard`, async (c: any) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      const stripe = getStripe();
      const body = await c.req.json().catch(() => ({}));
      const returnUrl = body.return_url || 'https://make.figma.com';
      const refreshUrl = body.refresh_url || returnUrl;

      // Check if user already has a Connect account
      let accountId = dbUser.stripe_connect_account_id;

      if (accountId) {
        // Account exists â€” check if onboarding is complete
        const account = await stripe.accounts.retrieve(accountId);

        if (account.details_submitted && account.charges_enabled) {
          // Already fully onboarded
          await supabase.from('users').update({
            stripe_connect_status: 'active',
          }).eq('id', dbUser.id);

          return c.json({
            status: 'active',
            message: 'Your Stripe account is already connected and active.',
          });
        }

        // Onboarding incomplete â€” generate new link
        const link = await stripe.accountLinks.create({
          account: accountId,
          type: 'account_onboarding',
          return_url: returnUrl,
          refresh_url: refreshUrl,
        });

        return c.json({
          status: 'pending',
          onboarding_url: link.url,
          message: 'Continue your Stripe onboarding.',
        });
      }

      // No account yet â€” create Express account
      const account = await stripe.accounts.create({
        type: 'express',
        email: dbUser.email || undefined,
        metadata: {
          tcf_user_id: dbUser.id,
          discord_username: dbUser.discord_username || '',
        },
        capabilities: {
          card_payments: { requested: true },
          transfers: { requested: true },
        },
      });

      // Save to DB immediately
      await supabase.from('users').update({
        stripe_connect_account_id: account.id,
        stripe_connect_status: 'pending',
      }).eq('id', dbUser.id);

      // Generate onboarding link
      const link = await stripe.accountLinks.create({
        account: account.id,
        type: 'account_onboarding',
        return_url: returnUrl,
        refresh_url: refreshUrl,
      });

      // Activity log
      try {
        await createUserActivity({
          user_id: dbUser.id,
          type: 'stripe_connect_started',
          title: 'Stripe Connect Started',
          description: 'You started connecting your Stripe account for prize payouts.',
          related_url: '#profile',
        });
      } catch (err) {
        console.error('Non-critical: activity log for Connect onboard failed:', err);
      }

      return c.json({
        status: 'pending',
        onboarding_url: link.url,
        message: 'Complete your Stripe onboarding to receive prize payouts.',
      });
    } catch (err: any) {
      console.error('Connect onboard error:', err);
      return c.json({ error: `Failed to start Stripe Connect onboarding: ${err.message}` }, 500);
    }
  });


  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // GET /connect/status â€” Check current user's Connect status
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/connect/status`, async (c: any) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      if (!dbUser.stripe_connect_account_id) {
        return c.json({ status: 'not_connected', account_id: null });
      }

      // Refresh status from Stripe (source of truth)
      const stripe = getStripe();
      try {
        const account = await stripe.accounts.retrieve(dbUser.stripe_connect_account_id);

        let status: string;
        if (account.details_submitted && account.charges_enabled) {
          status = 'active';
        } else if (account.details_submitted) {
          status = 'pending_verification';
        } else {
          status = 'pending';
        }

        // Sync status to DB if changed
        if (status !== dbUser.stripe_connect_status) {
          await supabase.from('users').update({
            stripe_connect_status: status,
          }).eq('id', dbUser.id);

          // If just became active, log it
          if (status === 'active' && dbUser.stripe_connect_status !== 'active') {
            try {
              await createUserActivity({
                user_id: dbUser.id,
                type: 'stripe_connected',
                title: 'Stripe Account Connected',
                description: 'Your Stripe account is now active. You can receive prize payouts!',
                related_url: '#profile',
              });
            } catch (err) {
              console.error('Non-critical: activity log for Connect active failed:', err);
            }
          }
        }

        return c.json({
          status,
          account_id: dbUser.stripe_connect_account_id,
          details_submitted: account.details_submitted,
          charges_enabled: account.charges_enabled,
          payouts_enabled: account.payouts_enabled,
        });
      } catch (stripeErr: any) {
        // If Stripe can't find the account, it was probably deleted
        if (stripeErr.code === 'account_invalid') {
          await supabase.from('users').update({
            stripe_connect_account_id: null,
            stripe_connect_status: null,
          }).eq('id', dbUser.id);
          return c.json({ status: 'not_connected', account_id: null });
        }
        throw stripeErr;
      }
    } catch (err: any) {
      console.error('Connect status error:', err);
      return c.json({ error: `Failed to check Connect status: ${err.message}` }, 500);
    }
  });


  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // POST /connect/dashboard â€” Generate Express Dashboard login link
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/connect/dashboard`, async (c: any) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      if (!dbUser.stripe_connect_account_id) {
        return c.json({ error: 'No Stripe Connect account found. Complete onboarding first.' }, 400);
      }

      const stripe = getStripe();
      const loginLink = await stripe.accounts.createLoginLink(dbUser.stripe_connect_account_id);

      return c.json({ url: loginLink.url });
    } catch (err: any) {
      console.error('Connect dashboard error:', err);
      return c.json({ error: `Failed to generate dashboard link: ${err.message}` }, 500);
    }
  });


  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // POST /connect/award â€” Owner: create a prize award for a user
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/connect/award`, async (c: any) => {
    try {
      const auth = await requireOwner(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser: ownerUser } = auth;

      const body = await c.req.json();
      const {
        recipient_user_id,
        amount_cents,
        reason,
        tournament_id,
        team_id,
        place,
        role: awardRole,
      } = body;

      // Validation
      if (!recipient_user_id) return c.json({ error: 'recipient_user_id is required' }, 400);
      if (!amount_cents || amount_cents <= 0) return c.json({ error: 'amount_cents must be positive' }, 400);

      // Look up the recipient user
      const { data: recipientUser, error: recipientError } = await supabase
        .from('users')
        .select('id, discord_username, discord_avatar, steam_id')
        .eq('id', recipient_user_id)
        .single();

      if (recipientError || !recipientUser) {
        return c.json({ error: `Recipient user not found: ${recipient_user_id}` }, 404);
      }

      // Resolve person_id for the recipient
      let personId: string | null = null;
      if (recipientUser.steam_id) {
        const { data: person } = await supabase
          .from('kkup_persons')
          .select('id')
          .eq('steam_id', recipientUser.steam_id)
          .maybeSingle();
        personId = person?.id || null;
      }

      // Resolve master_team_id if team_id is provided
      let masterTeamId: string | null = null;
      if (team_id) {
        masterTeamId = await resolveMasterTeamId(supabase, team_id);
      }

      // Insert the award
      const { data: award, error: insertError } = await supabase
        .from('prize_awards')
        .insert({
          recipient_user_id,
          awarded_by_user_id: ownerUser.id,
          amount_cents,
          reason: reason || null,
          tournament_id: tournament_id || null,
          team_id: team_id || null,
          master_team_id: masterTeamId,
          person_id: personId,
          place: place || null,
          role: awardRole || 'player',
          status: 'pending',
        })
        .select()
        .single();

      if (insertError) {
        return c.json({ error: `Failed to create prize award: ${insertError.message}` }, 500);
      }

      // Resolve tournament name for notifications
      let tournamentName = '';
      if (tournament_id) {
        const { data: t } = await supabase
          .from('kkup_tournaments')
          .select('name')
          .eq('id', tournament_id)
          .single();
        tournamentName = t?.name || '';
      }

      const amountStr = formatCents(amount_cents);
      const placeStr = place ? `${place}${getOrdinalSuffix(place)} place` : '';
      const reasonStr = reason || (placeStr ? `${placeStr}${tournamentName ? ` in ${tournamentName}` : ''}` : 'prize winnings');

      // Notify the recipient
      try {
        await createNotification({
          user_id: recipient_user_id,
          type: 'prize_awarded',
          title: `Prize Awarded: ${amountStr}`,
          body: `You've been awarded ${amountStr} for ${reasonStr}. Accept it to receive your payout!`,
          related_id: award.id,
          action_url: '#inbox',
          actor_name: ownerUser.discord_username || 'The Corn Field',
          actor_avatar: ownerUser.discord_avatar || undefined,
          metadata: {
            award_id: award.id,
            amount_cents,
            tournament_id,
            tournament_name: tournamentName,
          },
        });
      } catch (err) {
        console.error('Non-critical: notification for prize award failed:', err);
      }

      // Admin log
      try {
        await createAdminLog({
          type: 'prize_awarded',
          action: `Awarded ${amountStr} to ${recipientUser.discord_username || recipient_user_id} for ${reasonStr}`,
          actor_id: ownerUser.id,
          actor_name: ownerUser.discord_username,
          actor_avatar: ownerUser.discord_avatar,
          details: { award_id: award.id, amount_cents, tournament_id, recipient_user_id },
        });
      } catch (err) {
        console.error('Non-critical: admin log for prize award failed:', err);
      }

      // User activity for recipient
      try {
        await createUserActivity({
          user_id: recipient_user_id,
          type: 'prize_awarded',
          title: `Prize Awarded: ${amountStr}`,
          description: `You were awarded ${amountStr} for ${reasonStr}. Check your inbox to accept!`,
          related_id: award.id,
          related_url: '#inbox',
          actor_name: ownerUser.discord_username || 'The Corn Field',
          actor_avatar: ownerUser.discord_avatar || undefined,
        });
      } catch (err) {
        console.error('Non-critical: activity log for prize award failed:', err);
      }

      return c.json({ award, message: `Awarded ${amountStr} to ${recipientUser.discord_username || recipient_user_id}` });
    } catch (err: any) {
      console.error('Award create error:', err);
      return c.json({ error: `Failed to create prize award: ${err.message}` }, 500);
    }
  });


  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // POST /connect/award-batch â€” Owner: create prize awards for multiple recipients
  //
  // Body: {
  //   tournament_id: string,
  //   role: 'champion' | 'popd_kernel' | 'match_of_the_night' | 'staff' | 'rampage_bonus' | 'custom',
  //   team_id?: string,        // for champion awards â€” the winning team
  //   recipients: [{ user_id: string, person_id?: string, amount_cents: number }],
  //   reason?: string,
  //   place?: number,
  // }
  //
  // Creates one prize_awards row per recipient.
  // Side-effects: updates kkup_tournaments columns for champion/popd_kernel.
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/connect/award-batch`, async (c: any) => {
    try {
      const auth = await requireOwner(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser: ownerUser } = auth;

      const body = await c.req.json();
      const {
        tournament_id,
        role: awardRole,
        team_id,
        recipients,
        reason,
        place,
      } = body;

      // â”€â”€ Validation â”€â”€
      if (!tournament_id) return c.json({ error: 'tournament_id is required' }, 400);
      if (!awardRole) return c.json({ error: 'role is required' }, 400);
      if (!recipients || !Array.isArray(recipients) || recipients.length === 0) {
        return c.json({ error: 'recipients array is required and must not be empty' }, 400);
      }

      // Validate recipients: each must have at least a user_id OR person_id, and non-negative amount
      for (const r of recipients) {
        if (!r.user_id && !r.person_id) {
          return c.json({ error: 'Each recipient must have a user_id or person_id (or both)' }, 400);
        }
        if (r.amount_cents === undefined || r.amount_cents === null || r.amount_cents < 0) {
          return c.json({ error: 'Each recipient must have a non-negative amount_cents' }, 400);
        }
      }

      // Fetch tournament
      const { data: tournament, error: tErr } = await supabase
        .from('kkup_tournaments')
        .select('id, name, tournament_start_date')
        .eq('id', tournament_id)
        .single();
      if (tErr || !tournament) return c.json({ error: `Tournament not found: ${tournament_id}` }, 404);

      // Resolve master_team_id if team_id provided
      let masterTeamId: string | null = null;
      let teamName: string | null = null;
      if (team_id) {
        masterTeamId = await resolveMasterTeamId(supabase, team_id);
        const { data: teamRow } = await supabase
          .from('kkup_teams')
          .select('team_name')
          .eq('id', team_id)
          .single();
        teamName = teamRow?.team_name || null;
      }

      // â”€â”€ Create prize_awards rows â”€â”€
      const createdAwards: any[] = [];
      const errors: string[] = [];

      for (const r of recipients) {
        // Resolve person_id if not provided â€” look up by user's steam_id
        let personId = r.person_id || null;
        if (!personId && r.user_id) {
          const { data: usr } = await supabase
            .from('users')
            .select('steam_id')
            .eq('id', r.user_id)
            .single();
          if (usr?.steam_id) {
            const { data: person } = await supabase
              .from('kkup_persons')
              .select('id')
              .eq('steam_id', usr.steam_id)
              .maybeSingle();
            personId = person?.id || null;
          }
        }

        const isHonorary = r.amount_cents === 0;
        const hasAccount = !!r.user_id;

        // Determine status:
        // - $0 â†’ 'honorary' (bragging rights, tracked for history)
        // - has account + $$ â†’ 'pending' (can accept/decline/get paid)
        // - no account + $$ â†’ 'unclaimed' (recorded, claimable if they ever create an account)
        const awardStatus = isHonorary ? 'honorary' : hasAccount ? 'pending' : 'unclaimed';

        const { data: award, error: insertErr } = await supabase
          .from('prize_awards')
          .insert({
            recipient_user_id: r.user_id || null,
            awarded_by_user_id: ownerUser.id,
            amount_cents: r.amount_cents,
            reason: reason || null,
            tournament_id,
            team_id: team_id || null,
            master_team_id: masterTeamId,
            person_id: personId,
            place: place || null,
            role: awardRole,
            status: awardStatus,
          })
          .select()
          .single();

        if (insertErr) {
          const recipientLabel = r.user_id || r.person_id || 'unknown';
          errors.push(`Failed to create award for ${recipientLabel}: ${insertErr.message}`);
          continue;
        }

        createdAwards.push(award);

        // â”€â”€ Notifications (non-critical, only for users with accounts) â”€â”€
        if (hasAccount) {
          // Look up recipient for notifications
          const { data: recipientUser } = await supabase
            .from('users')
            .select('id, discord_username, discord_avatar')
            .eq('id', r.user_id)
            .single();

          if (!isHonorary) {
            const amountStr = formatCents(r.amount_cents);
            const roleLabel = ROLE_LABELS[awardRole] || awardRole;
            const reasonStr = reason || `${roleLabel} â€” ${tournament.name}`;

            try {
              await createNotification({
                user_id: r.user_id,
                type: 'prize_awarded',
                title: `Prize Awarded: ${amountStr}`,
                body: `You've been awarded ${amountStr} for ${reasonStr}. Accept it to receive your payout!`,
                related_id: award.id,
                action_url: '#inbox',
                actor_name: ownerUser.discord_username || 'The Corn Field',
                actor_avatar: ownerUser.discord_avatar || undefined,
                metadata: { award_id: award.id, amount_cents: r.amount_cents, tournament_id, tournament_name: tournament.name },
              });
            } catch (err) { console.error('Non-critical: notification for batch award failed:', err); }

            try {
              await createUserActivity({
                user_id: r.user_id,
                type: 'prize_awarded',
                title: `Prize Awarded: ${amountStr}`,
                description: `You were awarded ${amountStr} for ${reasonStr}. Check your inbox to accept!`,
                related_id: award.id,
                related_url: '#inbox',
                actor_name: ownerUser.discord_username || 'The Corn Field',
                actor_avatar: ownerUser.discord_avatar || undefined,
              });
            } catch (err) { console.error('Non-critical: activity log for batch award failed:', err); }
          } else {
            // Honorary award â€” still log activity if they have an account
            const roleLabel = ROLE_LABELS[awardRole] || awardRole;
            try {
              await createUserActivity({
                user_id: r.user_id,
                type: 'prize_awarded',
                title: `${roleLabel} â€” ${tournament.name}`,
                description: `You received the ${roleLabel} award for ${tournament.name}. No monetary prize attached.`,
                related_id: award.id,
                related_url: `#tournament-hub/${tournament_id}`,
                actor_name: ownerUser.discord_username || 'The Corn Field',
                actor_avatar: ownerUser.discord_avatar || undefined,
              });
            } catch (err) { console.error('Non-critical: honorary activity log failed:', err); }
          }
        }
        // Note: recipients without accounts get the prize_awards row created
        // but no notifications/activity. They'll see it if they ever sign up.
      }

      // â”€â”€ Side-effects: update kkup_tournaments columns â”€â”€
      if (awardRole === 'champion' && team_id) {
        try {
          await supabase
            .from('kkup_tournaments')
            .update({
              winning_team_id: team_id,
              winning_team_name: teamName,
            })
            .eq('id', tournament_id);
          console.log(`Updated kkup_tournaments.winning_team_id for ${tournament.name} â†’ ${teamName}`);
        } catch (err) {
          console.error('Non-critical: failed to update kkup_tournaments winning team:', err);
        }
      }

      if (awardRole === 'popd_kernel') {
        try {
          const personIds = createdAwards.map(a => a.person_id).filter(Boolean);
          await supabase
            .from('kkup_tournaments')
            .update({
              popd_kernel_1_person_id: personIds[0] || null,
              popd_kernel_2_person_id: personIds[1] || null,
            })
            .eq('id', tournament_id);
          console.log(`Updated kkup_tournaments popd_kernel person IDs for ${tournament.name}`);
        } catch (err) {
          console.error('Non-critical: failed to update kkup_tournaments popd_kernel:', err);
        }
      }

      // â”€â”€ Admin log â”€â”€
      const totalCents = createdAwards.reduce((s: number, a: any) => s + a.amount_cents, 0);
      const roleLabel = ROLE_LABELS[awardRole] || awardRole;
      const summaryMsg = totalCents > 0
        ? `Awarded ${formatCents(totalCents)} (${createdAwards.length} recipient${createdAwards.length > 1 ? 's' : ''}) for ${roleLabel} â€” ${tournament.name}`
        : `Awarded ${roleLabel} (honorary) to ${createdAwards.length} recipient${createdAwards.length > 1 ? 's' : ''} â€” ${tournament.name}`;

      try {
        await createAdminLog({
          type: 'prize_awarded',
          action: summaryMsg,
          actor_id: ownerUser.id,
          actor_name: ownerUser.discord_username,
          actor_avatar: ownerUser.discord_avatar,
          details: {
            tournament_id,
            role: awardRole,
            team_id,
            recipient_count: createdAwards.length,
            total_cents: totalCents,
            award_ids: createdAwards.map((a: any) => a.id),
          },
        });
      } catch (err) { console.error('Non-critical: admin log for batch award failed:', err); }

      return c.json({
        success: true,
        awards: createdAwards,
        errors: errors.length > 0 ? errors : undefined,
        message: summaryMsg,
      });
    } catch (err: any) {
      console.error('Award batch error:', err);
      return c.json({ error: `Failed to create batch awards: ${err.message}` }, 500);
    }
  });


  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // PUT /connect/award/:id/accept â€” Recipient: accept a prize
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.put(`${PREFIX}/connect/award/:id/accept`, async (c: any) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      const awardId = c.req.param('id');

      // Fetch the award
      const { data: award, error } = await supabase
        .from('prize_awards')
        .select('*')
        .eq('id', awardId)
        .single();

      if (error || !award) return c.json({ error: 'Prize award not found' }, 404);
      if (award.recipient_user_id !== dbUser.id) return c.json({ error: 'This award is not yours' }, 403);
      if (award.status !== 'pending') return c.json({ error: `Award is already ${award.status}` }, 400);

      // Update status
      const { error: updateError } = await supabase
        .from('prize_awards')
        .update({
          status: 'accepted',
          accepted_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq('id', awardId);

      if (updateError) return c.json({ error: `Failed to accept award: ${updateError.message}` }, 500);

      const amountStr = formatCents(award.amount_cents);

      // Admin log
      try {
        await createAdminLog({
          type: 'prize_accepted',
          action: `${dbUser.discord_username || dbUser.id} accepted ${amountStr} prize award`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
        });
      } catch (err) {
        console.error('Non-critical: admin log for prize accept failed:', err);
      }

      // User activity
      try {
        await createUserActivity({
          user_id: dbUser.id,
          type: 'prize_accepted',
          title: `Accepted ${amountStr} Prize`,
          description: `You accepted your ${amountStr} prize award. It will be disbursed to your Stripe account.`,
          related_id: awardId,
          related_url: '#profile',
        });
      } catch (err) {
        console.error('Non-critical: activity log for prize accept failed:', err);
      }

      // Check if they have Stripe Connect â€” include in response so frontend can prompt
      const hasConnect = !!dbUser.stripe_connect_account_id && dbUser.stripe_connect_status === 'active';

      return c.json({
        success: true,
        message: `Accepted ${amountStr} prize.${hasConnect ? '' : ' Connect your Stripe account to receive the payout.'}`,
        has_connect: hasConnect,
      });
    } catch (err: any) {
      console.error('Award accept error:', err);
      return c.json({ error: `Failed to accept prize award: ${err.message}` }, 500);
    }
  });


  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
