// â”€â”€ Route registration â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export function registerDiscordCommandsRoute(app: Hono) {
  const handler = async (c: any) => {
    try {
      const applicationId = Deno.env.get('DISCORD_APPLICATION_ID');
      const botToken = Deno.env.get('DISCORD_BOT_TOKEN');

      if (!applicationId || !botToken) {
        return c.json({ error: 'Missing DISCORD_APPLICATION_ID or DISCORD_BOT_TOKEN env vars' }, 500);
      }

      console.log('Registering Discord slash commands via API...');

      const response = await fetch(
        `https://discord.com/api/v10/applications/${applicationId}/commands`,
        {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bot ${botToken}`,
          },
          body: JSON.stringify(DISCORD_COMMANDS),
        }
      );

      if (!response.ok) {
        const errorText = await response.text();
        console.error('Discord command registration failed:', errorText);
        return c.json({ error: 'Discord API error', details: errorText, status: response.status }, 500);
      }

      const data = await response.json();
      const commandNames = data.map((cmd: any) => `/${cmd.name}`);
      console.log('Discord commands registered successfully:', commandNames.join(', '));

      return c.json({
        success: true,
        message: 'Discord commands registered successfully!',
        commands: commandNames,
        count: data.length,
      });
    } catch (error) {
      console.error('Error registering Discord commands:', error);
      return c.json({ error: 'Failed to register Discord commands', details: String(error) }, 500);
    }
  };

  // Support both POST and GET for convenience (browser = GET, API = POST)
  app.post(`${PREFIX}/admin/discord/register-commands`, handler);
  app.get(`${PREFIX}/admin/discord/register-commands`, handler);
}

/**
 * Dota Lookup Routes -- fetch team/player data from Steam + OpenDota
 * 2 routes: GET /dota/team/:teamId, GET /dota/player/:steamId
 */
import type { Hono } from "npm:hono";
import { normalizePlayerId, PREFIX } from "./helpers.ts";

export function registerDotaLookupRoutes(app: Hono) {

  // Fetch team data (Steam API with OpenDota fallback)
  app.get(`${PREFIX}/dota/team/:teamId`, async (c) => {
    try {
      const teamId = c.req.param('teamId');
      const steamKey = Deno.env.get('STEAM_WEB_API_KEY');
      
      // Try Steam API first
      if (steamKey) {
        try {
          const url = `https://api.steampowered.com/IDOTA2Match_570/GetTeamInfoByTeamID/v1/?key=${steamKey}&start_at_team_id=${teamId}&teams_requested=1`;
          const response = await fetch(url);
          
          if (response.ok) {
            const data = await response.json();
            if (data.result?.teams && data.result.teams.length > 0) {
              const teamData = data.result.teams[0];
              return c.json({
                name: teamData.name || 'Unknown Team',
                tag: teamData.tag || null,
                logo_url: teamData.logo || teamData.url_logo || null,
                team_id: teamData.team_id || parseInt(teamId),
                source: 'steam'
              });
            }
          }
        } catch (steamError) {
          console.log('Steam API error, falling back to OpenDota:', steamError);
        }
      }
      
      // Fallback to OpenDota
      const odResponse = await fetch(`https://api.opendota.com/api/teams/${teamId}`);
      if (!odResponse.ok) {
        return c.json({ error: 'Team not found in Steam or OpenDota' }, 404);
      }

      const text = await odResponse.text();
      if (!text) return c.json({ error: 'Empty response from OpenDota' }, 404);

      const teamData = JSON.parse(text);
      return c.json({
        name: teamData.name || 'Unknown Team',
        tag: teamData.tag || null,
        logo_url: teamData.logo_url || null,
        team_id: parseInt(teamId),
        source: 'opendota'
      });
    } catch (error) {
      console.error('Failed to fetch team:', error);
      return c.json({ error: `Failed to fetch team data: ${error.message}` }, 500);
    }
  });

  // Fetch player data by Steam ID (Steam API with OpenDota fallback)
  app.get(`${PREFIX}/dota/player/:steamId`, async (c) => {
    try {
      const steamId = c.req.param('steamId');
      const steamKey = Deno.env.get('STEAM_WEB_API_KEY');
      
      const normalized = normalizePlayerId(steamId);
      const steam64 = normalized.steam64;
      const accountId = normalized.steam32;
      
      // Try Steam API first
      if (steamKey) {
        try {
          const url = `https://api.steampowered.com/ISteamUser/GetPlayerSummaries/v2/?key=${steamKey}&steamids=${steam64}`;
          const response = await fetch(url);
          
          if (response.ok) {
            const data = await response.json();
            if (data.response?.players && data.response.players.length > 0) {
              const playerData = data.response.players[0];
              return c.json({
                accountId: accountId,
                name: playerData.personaname || 'Unknown Player',
                avatar: playerData.avatarfull || playerData.avatarmedium || playerData.avatar || null,
                source: 'steam'
              });
            }
          }
        } catch (steamError) {
          console.log('Steam API error, falling back to OpenDota:', steamError);
        }
      }
      
      // Fallback to OpenDota
      const odResponse = await fetch(`https://api.opendota.com/api/players/${accountId}`);
      if (!odResponse.ok) {
        return c.json({ error: 'Player not found in Steam or OpenDota' }, 404);
      }

      const text = await odResponse.text();
      if (!text) return c.json({ error: 'Empty response from OpenDota' }, 404);

      const playerData = JSON.parse(text);
      return c.json({
        accountId: accountId,
        name: playerData.profile?.personaname || 'Unknown Player',
        avatar: playerData.profile?.avatarfull || playerData.profile?.avatar || null,
        source: 'opendota'
      });
    } catch (error) {
      console.error('Failed to fetch player:', error);
      return c.json({ error: `Failed to fetch player data: ${error.message}` }, 500);
    }
  });

}

/**
 * Giveaway Config Routes â€” Prize type CRUD via KV store
 *
 * 4 routes:
 *   GET    /giveaway-config/prize-types           â€” List all prize types (built-in + custom)
 *   POST   /giveaway-config/prize-types           â€” Create a custom prize type (officer+)
 *   PATCH  /giveaway-config/prize-types/:key      â€” Update a custom prize type (officer+)
 *   DELETE /giveaway-config/prize-types/:key      â€” Delete a custom prize type (officer+)
 *
 * Built-in types (cash, dota_plus, discount_code, physical, other) cannot be deleted
 * but CAN be edited (label, icon, color changes).
 *
 * Storage: KV store with prefix "giveaway_prize_type:"
 */
import type { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import { isOfficer } from "./roles.ts";
import * as kv from "./kv_store.tsx";
import { createAdminLog } from "./routes-notifications.ts";

// â”€â”€ Built-in prize type defaults â”€â”€
const BUILTIN_PRIZE_TYPES = [
  { key: 'cash',          label: 'Cash',          icon: 'ðŸ’µ', color: '#10b981', sort_order: 0, builtin: true },
  { key: 'dota_plus',     label: 'Dota Plus',     icon: 'â­', color: '#d6a615', sort_order: 1, builtin: true },
  { key: 'discount_code', label: 'Discount Code', icon: 'ðŸ·ï¸', color: '#3b82f6', sort_order: 2, builtin: true },
  { key: 'physical',      label: 'Physical Item', icon: 'ðŸ“¦', color: '#8b5cf6', sort_order: 3, builtin: true },
  { key: 'other',         label: 'Other',         icon: 'ðŸŽ', color: '#f59e0b', sort_order: 4, builtin: true },
];

const KV_PREFIX = 'giveaway_prize_type:';

export function registerGiveawayConfigRoutes(app: Hono, supabase: any, anonSupabase: any) {

  /** Verify token + require officer-level role */
  async function requireOfficer(c: any): Promise<{ ok: true; dbUser: any } | { ok: false; response: any }> {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return { ok: false, response: c.json({ error: 'No access token provided' }, 401) };
    const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
    if (authError || !authUser) return { ok: false, response: c.json({ error: 'Unauthorized' }, 401) };
    const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', authUser.id).single();
    if (!dbUser) return { ok: false, response: c.json({ error: 'User not found' }, 404) };
    if (!isOfficer(dbUser.role)) return { ok: false, response: c.json({ error: 'Forbidden â€” officers only' }, 403) };
    return { ok: true, dbUser };
  }

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // LIST ALL PRIZE TYPES
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/giveaway-config/prize-types`, async (c) => {
    try {
      // Fetch custom prize types from KV
      const customTypes = await kv.getByPrefix(KV_PREFIX);

      // Build a map of custom overrides (key -> data)
      const customMap = new Map<string, any>();
      for (const ct of customTypes) {
        // getByPrefix returns { key: "giveaway_prize_type:xyz", ...value }
        const typeKey = ct.key.replace(KV_PREFIX, '');
        customMap.set(typeKey, { ...ct, key: typeKey });
      }

      // Merge: built-in types with any custom overrides, then append purely custom types
      const builtinKeys = new Set(BUILTIN_PRIZE_TYPES.map(b => b.key));
      const merged: any[] = [];

      // First, add built-in types (with custom overrides if any)
      for (const bt of BUILTIN_PRIZE_TYPES) {
        if (customMap.has(bt.key)) {
          // Custom override of a built-in type
          const override = customMap.get(bt.key);
          merged.push({ ...bt, ...override, key: bt.key, builtin: true });
          customMap.delete(bt.key);
        } else {
          merged.push({ ...bt });
        }
      }

      // Then, add purely custom types (not overriding built-ins)
      for (const [typeKey, ct] of customMap) {
        merged.push({
          key: typeKey,
          label: ct.label || typeKey,
          icon: ct.icon || 'ðŸŽ',
          color: ct.color || '#f59e0b',
          sort_order: ct.sort_order ?? 99,
          builtin: false,
        });
      }

      // Sort by sort_order
      merged.sort((a, b) => (a.sort_order ?? 99) - (b.sort_order ?? 99));

      return c.json({ prize_types: merged });
    } catch (error: any) {
      console.error('List prize types error:', error);
      return c.json({ error: `Failed to list prize types: ${error.message}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // CREATE CUSTOM PRIZE TYPE
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/giveaway-config/prize-types`, async (c) => {
    try {
      const auth = await requireOfficer(c);
      if (!auth.ok) return auth.response;

      const body = await c.req.json();
      const { key, label, icon, color, sort_order } = body;

      if (!key || !key.trim()) return c.json({ error: 'Key is required (e.g. "steam_gift_card")' }, 400);
      if (!label || !label.trim()) return c.json({ error: 'Label is required' }, 400);

      // Sanitize key: lowercase, underscores
      const sanitizedKey = key.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');

      // Check if key already exists
      const existing = await kv.get(`${KV_PREFIX}${sanitizedKey}`);
      if (existing) return c.json({ error: `Prize type "${sanitizedKey}" already exists` }, 409);

      const prizeType = {
        label: label.trim(),
        icon: icon || 'ðŸŽ',
        color: color || '#f59e0b',
        sort_order: sort_order ?? 99,
        builtin: false,
        created_at: new Date().toISOString(),
      };

      await kv.set(`${KV_PREFIX}${sanitizedKey}`, prizeType);

      console.log(`Prize type created: "${sanitizedKey}" by ${auth.dbUser.discord_username}`);

      try { await createAdminLog({ type: 'giveaway_config_created', action: `Created prize type "${prizeType.label}" (${sanitizedKey})`, actor_name: auth.dbUser.discord_username }); } catch (_) {}

      return c.json({ success: true, prize_type: { key: sanitizedKey, ...prizeType } });
    } catch (error: any) {
      console.error('Create prize type error:', error);
      return c.json({ error: `Failed to create prize type: ${error.message}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // UPDATE PRIZE TYPE (built-in or custom)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/giveaway-config/prize-types/:key`, async (c) => {
    try {
      const auth = await requireOfficer(c);
      if (!auth.ok) return auth.response;

      const typeKey = c.req.param('key');
      const body = await c.req.json();

      // Get existing (from KV or built-in defaults)
      const builtinKeys = new Set(BUILTIN_PRIZE_TYPES.map(b => b.key));
      const isBuiltin = builtinKeys.has(typeKey);
      const existingKV = await kv.get(`${KV_PREFIX}${typeKey}`);
      const existingBuiltin = BUILTIN_PRIZE_TYPES.find(b => b.key === typeKey);

      if (!existingKV && !existingBuiltin) {
        return c.json({ error: `Prize type "${typeKey}" not found` }, 404);
      }

      // Merge updates
      const base = existingKV || existingBuiltin || {};
      const updated = {
        label: body.label?.trim() ?? base.label,
        icon: body.icon ?? base.icon,
        color: body.color ?? base.color,
        sort_order: body.sort_order ?? base.sort_order,
        builtin: isBuiltin,
        updated_at: new Date().toISOString(),
      };

      await kv.set(`${KV_PREFIX}${typeKey}`, updated);

      console.log(`Prize type updated: "${typeKey}" by ${auth.dbUser.discord_username}`);

      try { await createAdminLog({ type: 'giveaway_config_updated', action: `Updated prize type "${updated.label}" (${typeKey})`, actor_name: auth.dbUser.discord_username }); } catch (_) {}

      return c.json({ success: true, prize_type: { key: typeKey, ...updated } });
    } catch (error: any) {
      console.error('Update prize type error:', error);
      return c.json({ error: `Failed to update prize type: ${error.message}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // DELETE CUSTOM PRIZE TYPE
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.delete(`${PREFIX}/giveaway-config/prize-types/:key`, async (c) => {
    try {
      const auth = await requireOfficer(c);
      if (!auth.ok) return auth.response;

      const typeKey = c.req.param('key');

      // Cannot delete built-in types
      const builtinKeys = new Set(BUILTIN_PRIZE_TYPES.map(b => b.key));
      if (builtinKeys.has(typeKey)) {
        // Check if it's a custom override of a built-in â€” delete the override to reset to default
        const existingKV = await kv.get(`${KV_PREFIX}${typeKey}`);
        if (existingKV) {
          await kv.del(`${KV_PREFIX}${typeKey}`);
          console.log(`Prize type reset to default: "${typeKey}" by ${auth.dbUser.discord_username}`);

          try { await createAdminLog({ type: 'giveaway_config_updated', action: `Reset built-in prize type "${typeKey}" to default`, actor_name: auth.dbUser.discord_username }); } catch (_) {}

          return c.json({ success: true, message: `Built-in type "${typeKey}" reset to default` });
        }
        return c.json({ error: `Cannot delete built-in prize type "${typeKey}"` }, 400);
      }

      // Delete custom type
      await kv.del(`${KV_PREFIX}${typeKey}`);
      console.log(`Prize type deleted: "${typeKey}" by ${auth.dbUser.discord_username}`);

      try { await createAdminLog({ type: 'giveaway_config_deleted', action: `Deleted prize type "${typeKey}"`, actor_name: auth.dbUser.discord_username }); } catch (_) {}

      return c.json({ success: true, message: `Prize type "${typeKey}" deleted` });
    } catch (error: any) {
      console.error('Delete prize type error:', error);
      return c.json({ error: `Failed to delete prize type: ${error.message}` }, 500);
    }
  });
}

/**
 * Giveaway Routes â€” CRUD, entry, draw, lifecycle
 *
 * 10 routes:
 *   GET    /giveaways                      â€” List all giveaways (public; drafts visible to officers only)
 *   GET    /giveaways/:id                  â€” Get giveaway detail with prizes, entries, user status
 *   POST   /giveaways                      â€” Create giveaway (officer+)
 *   PATCH  /giveaways/:id                  â€” Update giveaway + prizes (officer+)
 *   DELETE /giveaways/:id                  â€” Delete giveaway (officer+, draft only)
 *   PATCH  /giveaways/:id/status           â€” Advance phase (officer+)
 *   POST   /giveaways/:id/enter            â€” Enter giveaway (any authenticated user)
 *   DELETE /giveaways/:id/enter            â€” Leave giveaway (any authenticated user)
 *   POST   /giveaways/:id/draw             â€” Draw winners (officer+, closed only)
 *   PATCH  /giveaways/:id/prizes/:prize_id â€” Mark prize fulfilled (officer+)
 *
 * Tables: giveaways, giveaway_prizes, giveaway_entries, users
 */
import type { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import { createNotification, createAdminLog, createUserActivity } from "./routes-notifications.ts";
import { isOfficer } from "./roles.ts";

// â”€â”€ Valid phase transitions (mirrors giveaway-state-config.ts) â”€â”€
const PHASE_TRANSITIONS: Record<string, string[]> = {
  draft:     ['open'],
  open:      ['closed'],
  closed:    ['drawn'],
  drawn:     ['completed'],
  completed: [],
};

export function registerGiveawayRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // AUTH HELPERS
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  /** Verify token + return user (any authenticated role) */
  async function requireAuth(c: any): Promise<{ ok: true; authUser: any; dbUser: any } | { ok: false; response: any }> {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return { ok: false, response: c.json({ error: 'No access token provided' }, 401) };
    const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
    if (authError || !authUser) return { ok: false, response: c.json({ error: 'Unauthorized â€” invalid or expired token' }, 401) };
    const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', authUser.id).single();
    if (!dbUser) return { ok: false, response: c.json({ error: 'User not found in database' }, 404) };
    return { ok: true, authUser, dbUser };
  }

  /** Verify token + require officer-level role */
  async function requireOfficer(c: any): Promise<{ ok: true; authUser: any; dbUser: any } | { ok: false; response: any }> {
    const result = await requireAuth(c);
    if (!result.ok) return result;
    if (!isOfficer(result.dbUser.role)) {
      return { ok: false, response: c.json({ error: 'Forbidden â€” only officers and owner can manage giveaways' }, 403) };
    }
    return result;
  }

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // LIST GIVEAWAYS
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/giveaways`, async (c) => {
    try {
      // Check if requester is officer (optional â€” no auth required for public)
      let isAdmin = false;
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (accessToken) {
        const { data: { user: authUser } } = await anonSupabase.auth.getUser(accessToken);
        if (authUser) {
          const { data: dbUser } = await supabase.from('users').select('role').eq('supabase_id', authUser.id).single();
          if (dbUser && isOfficer(dbUser.role)) isAdmin = true;
        }
      }

      // Fetch giveaways â€” hide drafts from non-officers
      let query = supabase.from('giveaways').select('*').order('created_at', { ascending: false });
      if (!isAdmin) {
        query = query.neq('status', 'draft');
      }
      const { data: giveaways, error } = await query;
      if (error) {
        console.error('Failed to fetch giveaways:', error);
        return c.json({ error: `Failed to fetch giveaways: ${error.message}` }, 500);
      }

      if (!giveaways || giveaways.length === 0) {
        return c.json({ giveaways: [] });
      }

      // Batch-fetch entry counts and prizes for all giveaways
      const giveawayIds = giveaways.map((g: any) => g.id);

      const [
        { data: allPrizes },
        { data: allEntries },
        { data: allWinners },
      ] = await Promise.all([
        supabase.from('giveaway_prizes').select('id, giveaway_id, type, title, cash_amount, cash_currency, dota_plus_months, discount_percent, sort_order').in('giveaway_id', giveawayIds).order('sort_order'),
        supabase.from('giveaway_entries').select('giveaway_id').in('giveaway_id', giveawayIds),
        supabase.from('giveaway_entries').select('id, giveaway_id, user_id, discord_username, discord_avatar, winner_rank').in('giveaway_id', giveawayIds).not('winner_rank', 'is', null),
      ]);

      // Build lookup maps
      const entryCountMap = new Map<string, number>();
      (allEntries || []).forEach((e: any) => {
        entryCountMap.set(e.giveaway_id, (entryCountMap.get(e.giveaway_id) || 0) + 1);
      });

      const prizesMap = new Map<string, any[]>();
      (allPrizes || []).forEach((p: any) => {
        if (!prizesMap.has(p.giveaway_id)) prizesMap.set(p.giveaway_id, []);
        prizesMap.get(p.giveaway_id)!.push(p);
      });

      const winnersMap = new Map<string, any[]>();
      (allWinners || []).forEach((w: any) => {
        if (!winnersMap.has(w.giveaway_id)) winnersMap.set(w.giveaway_id, []);
        winnersMap.get(w.giveaway_id)!.push(w);
      });

      // Build response with prize_summary and entry_count
      const enriched = giveaways.map((g: any) => {
        const prizes = prizesMap.get(g.id) || [];
        const prizeSummary = prizes.map((p: any) => {
          if (p.type === 'cash' && p.cash_amount) return `$${Number(p.cash_amount).toFixed(0)} ${p.cash_currency || 'USD'}`;
          if (p.type === 'dota_plus' && p.dota_plus_months) return `${p.dota_plus_months}mo Dota Plus`;
          if (p.type === 'discount_code' && p.discount_percent) return `${Number(p.discount_percent).toFixed(0)}% Off`;
          return p.title;
        });

        return {
          ...g,
          entry_count: entryCountMap.get(g.id) || 0,
          prize_summary: prizeSummary,
          winners: winnersMap.get(g.id) || [],
        };
      });

      return c.json({ giveaways: enriched });
    } catch (error: any) {
      console.error('List giveaways error:', error);
      return c.json({ error: `Internal server error listing giveaways: ${error.message}` }, 500);
    }
  });

