  // ADVANCE PHASE (STATUS TRANSITION)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/giveaways/:id/status`, async (c) => {
    try {
      const auth = await requireOfficer(c);
      if (!auth.ok) return auth.response;

      const id = c.req.param('id');
      const { status: newStatus } = await c.req.json();

      if (!newStatus) return c.json({ error: 'New status is required' }, 400);

      // Fetch current status
      const { data: existing } = await supabase.from('giveaways').select('status, title').eq('id', id).single();
      if (!existing) return c.json({ error: `Giveaway not found: ${id}` }, 404);

      // Validate transition
      const allowed = PHASE_TRANSITIONS[existing.status] || [];
      if (!allowed.includes(newStatus)) {
        return c.json({
          error: `Invalid transition: "${existing.status}" â†’ "${newStatus}". Allowed: [${allowed.join(', ')}]`,
        }, 400);
      }

      // Build update
      const updateData: any = { status: newStatus };
      if (newStatus === 'drawn') {
        updateData.drawn_at = new Date().toISOString();
      }

      const { error: updateError } = await supabase.from('giveaways').update(updateData).eq('id', id);
      if (updateError) {
        return c.json({ error: `Failed to update status: ${updateError.message}` }, 500);
      }

      console.log(`Giveaway "${existing.title}" phase: ${existing.status} â†’ ${newStatus} (by ${auth.dbUser.discord_username})`);

      // Admin log (non-critical)
      try {
        await createAdminLog({
          type: 'giveaway_phase_changed',
          action: `Advanced giveaway "${existing.title}" phase: ${existing.status} â†’ ${newStatus}`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          actor_avatar: auth.dbUser.discord_avatar,
          details: { giveaway_id: id, title: existing.title, previous_status: existing.status, new_status: newStatus },
        });
      } catch (logErr) {
        console.error('Non-critical: admin log for giveaway phase change failed:', logErr);
      }

      return c.json({ success: true, previous_status: existing.status, new_status: newStatus });
    } catch (error: any) {
      console.error('Advance giveaway phase error:', error);
      return c.json({ error: `Internal server error advancing giveaway phase: ${error.message}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // ENTER GIVEAWAY
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/giveaways/:id/enter`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const id = c.req.param('id');

      // Check giveaway is open
      const { data: giveaway } = await supabase.from('giveaways').select('status, title, closes_at').eq('id', id).single();
      if (!giveaway) return c.json({ error: `Giveaway not found: ${id}` }, 404);
      if (giveaway.status !== 'open') {
        return c.json({ error: `Giveaway is not open for entries (current status: ${giveaway.status})` }, 400);
      }

      // Check if closes_at has passed
      if (giveaway.closes_at && new Date(giveaway.closes_at) < new Date()) {
        return c.json({ error: 'Entry period has ended' }, 400);
      }

      // Insert entry (UNIQUE constraint handles duplicates)
      const { data: entry, error: insertError } = await supabase
        .from('giveaway_entries')
        .insert({
          giveaway_id: id,
          user_id: auth.dbUser.id,
          discord_username: auth.dbUser.discord_username || 'Unknown',
          discord_avatar: auth.dbUser.discord_avatar || null,
          source: 'web',
        })
        .select()
        .single();

      if (insertError) {
        // Check for unique constraint violation (already entered)
        if (insertError.code === '23505') {
          return c.json({ error: 'You have already entered this giveaway' }, 409);
        }
        return c.json({ error: `Failed to enter giveaway: ${insertError.message}` }, 500);
      }

      console.log(`${auth.dbUser.discord_username} entered giveaway "${giveaway.title}" (${id})`);

      // Log activity
      try {
        await createUserActivity({
          user_id: auth.dbUser.id,
          type: 'giveaway_entered',
          title: `Entered: ${giveaway.title}`,
          description: `You entered the giveaway "${giveaway.title}".`,
          related_id: id,
          related_url: `#giveaways/${id}`,
        });
      } catch (actErr) { console.error('Non-critical: activity log for giveaway entry failed:', actErr); }

      return c.json({ success: true, entry });
    } catch (error: any) {
      console.error('Enter giveaway error:', error);
      return c.json({ error: `Internal server error entering giveaway: ${error.message}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // LEAVE GIVEAWAY
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.delete(`${PREFIX}/giveaways/:id/enter`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const id = c.req.param('id');

      // Check giveaway is still open (can't leave after closed)
      const { data: giveaway } = await supabase.from('giveaways').select('status, title').eq('id', id).single();
      if (!giveaway) return c.json({ error: `Giveaway not found: ${id}` }, 404);
      if (giveaway.status !== 'open') {
        return c.json({ error: `Cannot leave giveaway in "${giveaway.status}" phase` }, 400);
      }

      const { error: deleteError } = await supabase
        .from('giveaway_entries')
        .delete()
        .eq('giveaway_id', id)
        .eq('user_id', auth.dbUser.id);

      if (deleteError) {
        return c.json({ error: `Failed to leave giveaway: ${deleteError.message}` }, 500);
      }

      console.log(`${auth.dbUser.discord_username} left giveaway "${giveaway.title}" (${id})`);

      // Log activity
      try {
        await createUserActivity({
          user_id: auth.dbUser.id,
          type: 'giveaway_withdrawn',
          title: `Left: ${giveaway.title}`,
          description: `You withdrew from the giveaway "${giveaway.title}".`,
          related_id: id,
          related_url: `#giveaways/${id}`,
        });
      } catch (actErr) { console.error('Non-critical: activity log for giveaway leave failed:', actErr); }

      return c.json({ success: true, message: 'Entry removed' });
    } catch (error: any) {
      console.error('Leave giveaway error:', error);
      return c.json({ error: `Internal server error leaving giveaway: ${error.message}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // DRAW WINNERS
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/giveaways/:id/draw`, async (c) => {
    try {
      const auth = await requireOfficer(c);
      if (!auth.ok) return auth.response;

      const id = c.req.param('id');

      // Fetch giveaway
      const { data: giveaway } = await supabase
        .from('giveaways').select('status, title, winner_count').eq('id', id).single();
      if (!giveaway) return c.json({ error: `Giveaway not found: ${id}` }, 404);

      if (giveaway.status !== 'closed') {
        return c.json({ error: `Cannot draw winners â€” giveaway must be in "closed" phase (current: ${giveaway.status})` }, 400);
      }

      // Fetch all entries
      const { data: entries, error: entriesError } = await supabase
        .from('giveaway_entries').select('*').eq('giveaway_id', id);
      if (entriesError) {
        return c.json({ error: `Failed to fetch entries for draw: ${entriesError.message}` }, 500);
      }

      if (!entries || entries.length === 0) {
        return c.json({ error: 'Cannot draw â€” no entries in this giveaway' }, 400);
      }

      // Shuffle using Fisher-Yates
      const shuffled = [...entries];
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
      }

      // Pick winners (min of winner_count and total entries)
      const winnerCount = Math.min(giveaway.winner_count || 1, shuffled.length);
      const winners = shuffled.slice(0, winnerCount);

      // Update winner_rank on winning entries
      for (let i = 0; i < winners.length; i++) {
        await supabase
          .from('giveaway_entries')
          .update({ winner_rank: i + 1 })
          .eq('id', winners[i].id);
      }

      // Assign winners to prizes (by rank order)
      const { data: prizes } = await supabase
        .from('giveaway_prizes').select('*').eq('giveaway_id', id).order('sort_order');

      if (prizes && prizes.length > 0) {
        for (let i = 0; i < Math.min(winners.length, prizes.length); i++) {
          await supabase
            .from('giveaway_prizes')
            .update({ winner_user_id: winners[i].user_id })
            .eq('id', prizes[i].id);
        }
      }

      // Advance to drawn status
      await supabase.from('giveaways').update({
        status: 'drawn',
        drawn_at: new Date().toISOString(),
      }).eq('id', id);

      const winnerNames = winners.map((w: any) => w.discord_username).join(', ');
      console.log(`Giveaway "${giveaway.title}" drawn! Winners: ${winnerNames} (drawn by ${auth.dbUser.discord_username})`);

      // Notify each winner and log admin action (non-critical)
      try {
        for (let i = 0; i < winners.length; i++) {
          const w = winners[i];
          const prizeName = prizes && prizes[i] ? prizes[i].title : `Prize #${i + 1}`;
          await createNotification({
            user_id: w.user_id,
            type: 'giveaway_prize',
            title: `You won: ${giveaway.title}!`,
            body: `Congratulations! You won "${prizeName}" in the ${giveaway.title} giveaway.`,
            related_id: id,
            action_url: `#giveaway/${id}`,
            actor_name: auth.dbUser.discord_username,
          });
        }
        await createAdminLog({
          type: 'giveaway_drawn',
          action: `Drew ${winners.length} winner(s) for "${giveaway.title}"`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          details: { giveaway_id: id, winner_count: winners.length, winners: winnerNames },
        });
      } catch (_) { /* non-critical */ }

      return c.json({
        success: true,
        winners: winners.map((w: any, i: number) => ({
          rank: i + 1,
          user_id: w.user_id,
          discord_username: w.discord_username,
          discord_avatar: w.discord_avatar,
          entry_id: w.id,
        })),
      });
    } catch (error: any) {
      console.error('Draw giveaway error:', error);
      return c.json({ error: `Internal server error drawing giveaway winners: ${error.message}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // MARK PRIZE FULFILLED
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/giveaways/:id/prizes/:prize_id`, async (c) => {
    try {
      const auth = await requireOfficer(c);
      if (!auth.ok) return auth.response;

      const prizeId = c.req.param('prize_id');
      const body = await c.req.json();

      const updateData: any = {};
      if (body.fulfilled !== undefined) {
        updateData.fulfilled = body.fulfilled;
        updateData.fulfilled_at = body.fulfilled ? new Date().toISOString() : null;
      }
      if (body.stripe_transfer_id !== undefined) {
        updateData.stripe_transfer_id = body.stripe_transfer_id;
      }

      const { data: prize, error: updateError } = await supabase
        .from('giveaway_prizes')
        .update(updateData)
        .eq('id', prizeId)
        .select()
        .single();

      if (updateError) {
        return c.json({ error: `Failed to update prize: ${updateError.message}` }, 500);
      }

      console.log(`Prize ${prizeId} updated (fulfilled=${prize?.fulfilled}) by ${auth.dbUser.discord_username}`);

      // Admin log + notify winner (non-critical)
      try {
        const giveawayId = c.req.param('id');
        const { data: giveaway } = await supabase.from('giveaways').select('title').eq('id', giveawayId).single();

        await createAdminLog({
          type: 'prize_fulfilled',
          action: `${body.fulfilled ? 'Fulfilled' : 'Unfulfilled'} prize "${prize?.title || prizeId}" for "${giveaway?.title || giveawayId}"`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          actor_avatar: auth.dbUser.discord_avatar,
          details: { giveaway_id: giveawayId, prize_id: prizeId, fulfilled: prize?.fulfilled, prize_title: prize?.title },
        });

        // Notify the winner when their prize is fulfilled
        if (body.fulfilled && prize?.winner_user_id) {
          await createNotification({
            user_id: prize.winner_user_id,
            type: 'prize_fulfilled',
            title: `Prize Fulfilled: ${prize.title || 'Your Prize'}`,
            body: `Your prize "${prize.title}" from "${giveaway?.title || 'a giveaway'}" has been fulfilled!`,
            related_id: giveawayId,
            actor_name: auth.dbUser.discord_username,
          });
        }
      } catch (logErr) {
        console.error('Non-critical: admin log for prize fulfillment failed:', logErr);
      }

      return c.json({ success: true, prize });
    } catch (error: any) {
      console.error('Update prize error:', error);
      return c.json({ error: `Internal server error updating prize: ${error.message}` }, 500);
    }
  });

}

/**
 * Guild Wars â€” Guild Routes
 * CRUD for guilds, join/leave, Discord role sync.
 *
 * 7 routes:
 *   GET    /guilds              â€” list all guilds (with member counts)
 *   GET    /guilds/:id          â€” single guild detail
 *   POST   /guilds              â€” create a guild (any authenticated user)
 *   PATCH  /guilds/:id          â€” update guild (creator or officer)
 *   DELETE /guilds/:id          â€” delete guild (creator or officer, not defaults)
 *   POST   /guilds/:id/join     â€” join a guild (handles rank reset on switch)
 *   POST   /guilds/:id/leave    â€” leave guild â†’ Unaffiliated
 */
import type { Hono } from "npm:hono";
import { PREFIX, requireAuth } from "./helpers.ts";
import { isOfficer } from "./roles.ts";
import { DISCORD_SERVER_ID } from "./discord-config.ts";
import { createNotification, createAdminLog, createUserActivity } from "./routes-notifications.ts";
import { 
  createDiscordRole, 
  updateDiscordRole, 
  deleteDiscordRole, 
  addDiscordRoleToUser, 
  removeDiscordRoleFromUser,
  syncDiscordUserRoles
} from "./discord-api.ts";

export function registerGuildRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ GET /guilds â€” List all guilds with member counts â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/guilds`, async (c) => {
    try {
      // Fetch all guilds
      const { data: guilds, error } = await supabase
        .from('guild_wars_guilds')
        .select('*')
        .order('is_default', { ascending: false })
        .order('name', { ascending: true });

      if (error) return c.json({ error: `Failed to fetch guilds: ${error.message}` }, 500);

      // Get member counts per guild from users table
      const { data: counts } = await supabase
        .from('users')
        .select('guild_id')
        .not('guild_id', 'is', null);

      const countMap: Record<string, number> = {};
      for (const u of (counts || [])) {
        countMap[u.guild_id] = (countMap[u.guild_id] || 0) + 1;
      }

      const guildsWithCounts = (guilds || []).map((g: any) => ({
        ...g,
        member_count: countMap[g.id] || 0,
      }));

      return c.json({ guilds: guildsWithCounts });
    } catch (error: any) {
      console.error('List guilds error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ GET /guilds/:id â€” Single guild detail â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/guilds/:id`, async (c) => {
    try {
      const guildId = c.req.param('id');
      const { data: guild, error } = await supabase
        .from('guild_wars_guilds')
        .select('*')
        .eq('id', guildId)
        .single();

      if (error || !guild) return c.json({ error: 'Guild not found' }, 404);

      // Get members
      const { data: members } = await supabase
        .from('users')
        .select('id, discord_username, discord_avatar, rank_id, prestige_level, role')
        .eq('guild_id', guildId)
        .order('rank_id', { ascending: false });

      // Get active season MVP count for this guild
      const { data: activeSeason } = await supabase
        .from('guild_wars_seasons')
        .select('id')
        .eq('status', 'active')
        .single();

      let mvpCount = 0;
      if (activeSeason) {
        const { count } = await supabase
          .from('rank_up_requests')
          .select('id', { count: 'exact', head: true })
          .eq('guild_id', guildId)
          .eq('season_id', activeSeason.id)
          .eq('status', 'approved');
        mvpCount = count || 0;
      }

      return c.json({
        guild: { ...guild, member_count: (members || []).length, mvp_count: mvpCount },
        members: members || [],
      });
    } catch (error: any) {
      console.error('Get guild detail error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ POST /guilds â€” Create a new guild â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/guilds`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      const { name, tag, color, logo_url, description, from_master_team_id } = await c.req.json();

      // Validation
      if (!name || name.trim().length < 2) return c.json({ error: 'Guild name must be at least 2 characters' }, 400);
      if (name.trim().length > 30) return c.json({ error: 'Guild name cannot exceed 30 characters' }, 400);
      if (!color) return c.json({ error: 'Guild color is required' }, 400);
      if (!logo_url) return c.json({ error: 'Guild logo is required' }, 400);
      if (tag && tag.trim().length > 5) return c.json({ error: 'Guild tag cannot exceed 5 characters' }, 400);

      // Check for duplicate name
      const { data: existing } = await supabase
        .from('guild_wars_guilds')
        .select('id')
        .ilike('name', name.trim())
        .maybeSingle();
      if (existing) return c.json({ error: 'A guild with this name already exists' }, 409);

      // Check if user already created a guild (one guild per creator)
      const { data: ownedGuild } = await supabase
        .from('guild_wars_guilds')
        .select('id, name')
        .eq('created_by', dbUser.id)
        .maybeSingle();
      if (ownedGuild) return c.json({ error: `You already own a guild: "${ownedGuild.name}". Each user can create one guild.` }, 409);

      // Create Discord role
      const discordRoleId = await createDiscordRole(name.trim(), color);

      // Insert guild
      const { data: guild, error: insertError } = await supabase
        .from('guild_wars_guilds')
        .insert({
          name: name.trim(),
          tag: tag?.trim().toUpperCase() || null,
          color,
          logo_url,
          description: description?.trim() || null,
          created_by: dbUser.id,
          from_master_team_id: from_master_team_id || null,
          is_default: false,
          is_open: true,
          discord_role_id: discordRoleId,
        })
        .select()
        .single();

      if (insertError) {
        console.error('Guild creation failed:', insertError);
        // Clean up Discord role if guild insert failed
        if (discordRoleId) deleteDiscordRole(discordRoleId);
        return c.json({ error: `Failed to create guild: ${insertError.message}` }, 500);
      }

      // Close old membership if any
      await supabase
        .from('guild_wars_memberships')
        .update({ left_at: new Date().toISOString(), rank_on_leave: dbUser.rank_id, prestige_on_leave: dbUser.prestige_level })
        .eq('user_id', dbUser.id)
        .is('left_at', null);

      // Auto-join the creator to their guild
      await supabase
        .from('users')
        .update({ guild_id: guild.id, updated_at: new Date().toISOString() })
        .eq('id', dbUser.id);

      // Set role to member if guest
      if (dbUser.role === 'guest') {
        await supabase
          .from('users')
          .update({ role: 'member' })
          .eq('id', dbUser.id);
      }

      // Create new membership record
      await supabase
        .from('guild_wars_memberships')
        .insert({ user_id: dbUser.id, guild_id: guild.id });

      // Sync Discord roles (Rank 1 + New Guild Role)
      // @ts-ignore: EdgeRuntime is available in Supabase
      EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, dbUser.id));

      // Log
      try {
        await createUserActivity({
          user_id: dbUser.id,
          type: 'guild_created',
          title: `Created Guild: ${guild.name}`,
          description: `You created the guild "${guild.name}" and were auto-joined.`,
          related_id: guild.id,
        });
        await createAdminLog({
          type: 'guild_created',
          action: `${dbUser.discord_username} created guild "${guild.name}"`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
          details: { guild_id: guild.id, guild_name: guild.name },
        });
      } catch (_) { /* non-critical */ }

      console.log(`Guild created: "${guild.name}" by ${dbUser.discord_username} (discord role: ${discordRoleId})`);
      return c.json({ guild });
    } catch (error: any) {
      console.error('Create guild error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ PATCH /guilds/:id â€” Update guild â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.patch(`${PREFIX}/guilds/:id`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      const guildId = c.req.param('id');
      const { data: guild, error: fetchError } = await supabase
        .from('guild_wars_guilds')
        .select('*')
        .eq('id', guildId)
        .single();

      if (fetchError || !guild) return c.json({ error: 'Guild not found' }, 404);

      // Only creator or officers can edit
      if (guild.created_by !== dbUser.id && !isOfficer(dbUser.role)) {
        return c.json({ error: 'Only the guild creator or officers can update this guild' }, 403);
      }

      const body = await c.req.json();
      const updates: any = { updated_at: new Date().toISOString() };

      if (body.name !== undefined) updates.name = body.name.trim();
      if (body.tag !== undefined) updates.tag = body.tag?.trim().toUpperCase() || null;
      if (body.color !== undefined) updates.color = body.color;
      if (body.logo_url !== undefined) updates.logo_url = body.logo_url;
      if (body.description !== undefined) updates.description = body.description?.trim() || null;
      if (body.is_open !== undefined) updates.is_open = body.is_open;

      const { data: updatedGuild, error: updateError } = await supabase
        .from('guild_wars_guilds')
        .update(updates)
        .eq('id', guildId)
        .select()
        .single();

      if (updateError) return c.json({ error: `Failed to update guild: ${updateError.message}` }, 500);

      // Sync Discord role if name or color changed
      if (guild.discord_role_id && (body.name || body.color)) {
        updateDiscordRole(guild.discord_role_id, {
          name: body.name?.trim(),
          color: body.color,
        });
      }

      return c.json({ guild: updatedGuild });
    } catch (error: any) {
      console.error('Update guild error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ DELETE /guilds/:id â€” Delete guild â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.delete(`${PREFIX}/guilds/:id`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      const guildId = c.req.param('id');
      const { data: guild, error: fetchError } = await supabase
        .from('guild_wars_guilds')
        .select('*')
        .eq('id', guildId)
        .single();

      if (fetchError || !guild) return c.json({ error: 'Guild not found' }, 404);
      if (guild.is_default) return c.json({ error: 'Default guilds cannot be deleted' }, 403);
      if (guild.created_by !== dbUser.id && !isOfficer(dbUser.role)) {
        return c.json({ error: 'Only the guild creator or officers can delete this guild' }, 403);
      }

      // Move all members to Unaffiliated
      const { data: unaffiliated } = await supabase
        .from('guild_wars_guilds')
        .select('id')
        .eq('name', 'Unaffiliated')
        .single();

      if (unaffiliated) {
        // Close all active memberships
        await supabase
          .from('guild_wars_memberships')
          .update({ left_at: new Date().toISOString() })
          .eq('guild_id', guildId)
          .is('left_at', null);

        // Move users to Unaffiliated
        const { data: affectedUsers } = await supabase
          .from('users')
          .select('id, discord_id')
          .eq('guild_id', guildId);

        await supabase
          .from('users')
          .update({ guild_id: unaffiliated.id })
          .eq('guild_id', guildId);

        // Create Unaffiliated membership records
        for (const user of (affectedUsers || [])) {
          await supabase.from('guild_wars_memberships').insert({ user_id: user.id, guild_id: unaffiliated.id });
          // Sync Discord roles for displaced users
          // @ts-ignore: EdgeRuntime is available in Supabase
          EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, user.id));
        }
      }

      // Delete the Discord role
      if (guild.discord_role_id) {
        deleteDiscordRole(guild.discord_role_id);
      }

      // Delete the guild
      const { error: deleteError } = await supabase
        .from('guild_wars_guilds')
        .delete()
        .eq('id', guildId);

      if (deleteError) return c.json({ error: `Failed to delete guild: ${deleteError.message}` }, 500);

      // Log
      try {
        await createAdminLog({
          type: 'guild_deleted',
          action: `${dbUser.discord_username} deleted guild "${guild.name}"`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
          details: { guild_id: guildId, guild_name: guild.name },
        });
      } catch (_) { /* non-critical */ }

      console.log(`Guild deleted: "${guild.name}" by ${dbUser.discord_username}`);
      return c.json({ success: true });
    } catch (error: any) {
      console.error('Delete guild error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ POST /guilds/:id/join â€” Join a guild â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // Handles: Discord role swap, membership records, rank reset on switch
  app.post(`${PREFIX}/guilds/:id/join`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      const guildId = c.req.param('id');

      // Can't join the guild you're already in
      if (dbUser.guild_id === guildId) {
        return c.json({ error: 'You are already in this guild' }, 400);
      }

      // Fetch target guild
      const { data: guild, error: guildError } = await supabase
        .from('guild_wars_guilds')
        .select('*')
        .eq('id', guildId)
        .single();

      if (guildError || !guild) return c.json({ error: 'Guild not found' }, 404);
      if (!guild.is_open) return c.json({ error: 'This guild is not accepting new members' }, 403);

      // Determine if this is a guild SWITCH (has existing non-Unaffiliated guild)
      let isSwitch = false;
      let oldGuild: any = null;
      const { data: unaffiliated } = await supabase
        .from('guild_wars_guilds')
        .select('id')
        .eq('name', 'Unaffiliated')
        .single();

      if (dbUser.guild_id && dbUser.guild_id !== unaffiliated?.id) {
        isSwitch = true;
        const { data: og } = await supabase
          .from('guild_wars_guilds')
          .select('id, name, discord_role_id')
          .eq('id', dbUser.guild_id)
          .maybeSingle();
        oldGuild = og;
      }

      // â”€â”€ Guild switch: rank + prestige reset â”€â”€
      const updateData: any = {
        guild_id: guildId,
        updated_at: new Date().toISOString(),
      };

      if (isSwitch) {
        updateData.rank_id = 1; // Reset to Earwig
        updateData.prestige_level = 0; // Reset prestige
      }

      // If guest, also set role to member (onboard them)
      if (dbUser.role === 'guest') {
        updateData.role = 'member';
      }

      // Update user
      const { data: updatedUser, error: updateError } = await supabase
        .from('users')
        .update(updateData)
        .eq('id', dbUser.id)
        .select(`*, ranks ( id, name, display_order )`)
        .single();

      if (updateError) return c.json({ error: `Failed to join guild: ${updateError.message}` }, 500);

      // Close old membership record
      if (dbUser.guild_id) {
        await supabase
          .from('guild_wars_memberships')
          .update({ left_at: new Date().toISOString(), rank_on_leave: dbUser.rank_id, prestige_on_leave: dbUser.prestige_level })
          .eq('user_id', dbUser.id)
          .is('left_at', null);
      }

      // Create new membership record
      await supabase
        .from('guild_wars_memberships')
        .insert({ user_id: dbUser.id, guild_id: guildId });

      // Discord role swap (Rank, Prestige, and Guild)
      // @ts-ignore: EdgeRuntime is available in Supabase
      EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, dbUser.id));

      // Log
      try {
        const description = isSwitch
          ? `You switched from ${oldGuild?.name || 'your old guild'} to ${guild.name}. Your rank was reset to Earwig and prestige to 0.`
          : `You joined the ${guild.name} guild!`;

        await createUserActivity({
          user_id: dbUser.id,
          type: isSwitch ? 'guild_switched' : 'guild_joined',
          title: isSwitch ? `Switched to ${guild.name}` : `Joined ${guild.name}`,
          description,
          related_id: guild.id,
        });

        if (isSwitch) {
          await createAdminLog({
            type: 'guild_switched',
            action: `${dbUser.discord_username} switched from ${oldGuild?.name || '?'} to ${guild.name} (rank/prestige reset)`,
            actor_id: dbUser.id,
            actor_name: dbUser.discord_username,
            details: { old_guild: oldGuild?.name, new_guild: guild.name, old_rank: dbUser.rank_id, old_prestige: dbUser.prestige_level },
          });
        }
      } catch (_) { /* non-critical */ }

      console.log(`User ${dbUser.discord_username} joined guild "${guild.name}"${isSwitch ? ' (switch â€” rank/prestige reset)' : ''}`);
      return c.json({ user: updatedUser, guild, was_switch: isSwitch });
    } catch (error: any) {
      console.error('Join guild error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ POST /guilds/:id/leave â€” Leave guild â†’ Unaffiliated â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/guilds/:id/leave`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      const guildId = c.req.param('id');

      if (dbUser.guild_id !== guildId) {
        return c.json({ error: 'You are not in this guild' }, 400);
      }

      // Get Unaffiliated guild
      const { data: unaffiliated } = await supabase
        .from('guild_wars_guilds')
        .select('id')
        .eq('name', 'Unaffiliated')
        .single();

      if (!unaffiliated) return c.json({ error: 'Unaffiliated guild not found â€” contact admin' }, 500);

      // Can't leave Unaffiliated
      if (guildId === unaffiliated.id) {
        return c.json({ error: 'You cannot leave the Unaffiliated guild (you must join another guild instead)' }, 400);
      }

      // Get current guild info for logging
      const { data: currentGuild } = await supabase
        .from('guild_wars_guilds')
        .select('name, discord_role_id')
        .eq('id', guildId)
        .maybeSingle();

      // Move to Unaffiliated (no rank/prestige reset for leaving to Unaffiliated)
      await supabase
        .from('users')
        .update({ guild_id: unaffiliated.id, updated_at: new Date().toISOString() })
        .eq('id', dbUser.id);

      // Close old membership, create Unaffiliated membership
      await supabase
        .from('guild_wars_memberships')
        .update({ left_at: new Date().toISOString(), rank_on_leave: dbUser.rank_id, prestige_on_leave: dbUser.prestige_level })
        .eq('user_id', dbUser.id)
        .is('left_at', null);

      await supabase
        .from('guild_wars_memberships')
        .insert({ user_id: dbUser.id, guild_id: unaffiliated.id });

      // Sync Discord roles (Guild Role removed, Unaffiliated role added if any)
      // @ts-ignore: EdgeRuntime is available in Supabase
      EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, dbUser.id));

      // Log
      try {
        await createUserActivity({
          user_id: dbUser.id,
          type: 'guild_left',
          title: `Left ${currentGuild?.name || 'guild'}`,
          description: `You left ${currentGuild?.name || 'your guild'} and are now Unaffiliated.`,
        });
      } catch (_) { /* non-critical */ }

      console.log(`User ${dbUser.discord_username} left guild "${currentGuild?.name}" â†’ Unaffiliated`);
      return c.json({ success: true });
    } catch (error: any) {
      console.error('Leave guild error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

}

/**
 * KKUP Read Routes -- all GET endpoints for Kernel Kup tournament data
 * Routes: list, detail, hall-of-fame (players/teams/combined), players, awards, achievements
 */
import type { Hono } from "npm:hono";
import * as kv from "./kv_store.tsx";
import { PREFIX, getHeroName, getHeroIdFromName, getSteamLogoUrl } from "./helpers.ts";

// Cache key and TTL for total Dota hero count from OpenDota
const DOTA_HERO_COUNT_KEY = 'dota_total_hero_count';
const HERO_COUNT_TTL_DAYS = 30;

async function getTotalDotaHeroCount(): Promise<number> {
  try {
    // Check KV cache first
    const cached = await kv.get(DOTA_HERO_COUNT_KEY);
    if (cached && cached.count && cached.fetched_at) {
      const age = Date.now() - new Date(cached.fetched_at).getTime();
      if (age < HERO_COUNT_TTL_DAYS * 24 * 60 * 60 * 1000) {
        return cached.count;
      }
    }

    // Fetch from OpenDota API (free, no auth required)
    const res = await fetch('https://api.opendota.com/api/heroes');
    if (res.ok) {
      const heroes = await res.json();
      const count = Array.isArray(heroes) ? heroes.length : 0;
      if (count > 0) {
        await kv.set(DOTA_HERO_COUNT_KEY, { count, fetched_at: new Date().toISOString() });
        console.log(`Cached total Dota hero count: ${count}`);
        return count;
      }
    }

    // Fallback if API fails â€” return cached value if we have one, otherwise 126
    return cached?.count || 126;
  } catch (err) {
    console.error('Failed to fetch Dota hero count:', err);
    return 126; // safe fallback
  }
}

export function registerKkupReadRoutes(app: Hono, supabase: any, _anonSupabase: any) {

  // ============================================================
  // HALL OF FAME â€” must be registered BEFORE /:kkup_id routes
  // ============================================================

  // Hall of Fame â€” players (aggregated across all tournaments)
  app.get(`${PREFIX}/kkup/hall-of-fame/players`, async (c) => {
    try {
      const startTime = Date.now();

      // Parallel fetch: stats, tournaments, users, and prize awards all at once
      const [statsResult, tournamentsResult, usersResult, prizeAwardsResult] = await Promise.all([
        supabase
          .from('kkup_player_match_stats')
          .select(`
            id, match_id, person_id, team_id, hero, kills, deaths, assists,
            last_hits, denies, gpm, xpm, net_worth,
            person:kkup_persons!person_id(id, steam_id, display_name, tournaments_won, prize_money_won),
            match:kkup_matches!match_id(id, tournament_id, winning_team_id)
          `),
        supabase
          .from('kkup_tournaments')
          .select('id, winning_team_id, tournament_type, popd_kernel_1_person_id, popd_kernel_2_person_id'),
        supabase
          .from('users')
          .select('id, discord_username, discord_avatar, rank_id, prestige_level, role, steam_id')
          .not('steam_id', 'is', null),
        supabase
          .from('prize_awards')
          .select('person_id, amount_cents, status, tournament_id')
          .not('status', 'in', '("revoked")'),
      ]);

      const { data: allStats, error: statsError } = statsResult;
      if (statsError) {
        console.error('Hall of Fame stats error:', statsError);
        return c.json({ error: 'Failed to fetch stats', details: statsError.message }, 500);
      }

      const { data: tournaments } = tournamentsResult;
      const { data: usersWithSteam } = usersResult;

      // Aggregate prize winnings per person_id (overall + by tournament type)
      const { data: prizeAwards } = prizeAwardsResult;
      const prizeByPerson = new Map<string, { overall: number; kernel_kup: number; heaps_n_hooks: number }>();
      const tournamentTypeMap = new Map<string, string>(); // built below after tournaments

      const winningTeamIds = new Set((tournaments || []).map((t: any) => t.winning_team_id).filter(Boolean));

      // Build tournament lookup: id â†’ { type, winning_team_id }
      const tournamentMap = new Map<string, any>();
      (tournaments || []).forEach((t: any) => { tournamentMap.set(t.id, t); });

      // Aggregate prize winnings by person (now that tournamentMap is available)
      (prizeAwards || []).forEach((a: any) => {
        if (!a.person_id) return;
        const tType = a.tournament_id ? (tournamentMap.get(a.tournament_id)?.tournament_type || 'kernel_kup') : 'kernel_kup';
        if (!prizeByPerson.has(a.person_id)) prizeByPerson.set(a.person_id, { overall: 0, kernel_kup: 0, heaps_n_hooks: 0 });
        const entry = prizeByPerson.get(a.person_id)!;
        entry.overall += a.amount_cents || 0;
        if (tType === 'heaps_n_hooks') entry.heaps_n_hooks += a.amount_cents || 0;
        else entry.kernel_kup += a.amount_cents || 0;
      });

      // Count Pop'd Kernel (MVP) awards per person â€” split by tournament type
      const popdKernelCount = new Map<string, number>(); // overall
      const popdKernelByType = new Map<string, { kernel_kup: number; heaps_n_hooks: number }>(); // by type

      (tournaments || []).forEach((t: any) => {
        const tType = t.tournament_type || 'kernel_kup';
        for (const pid of [t.popd_kernel_1_person_id, t.popd_kernel_2_person_id]) {
          if (!pid) continue;
          popdKernelCount.set(pid, (popdKernelCount.get(pid) || 0) + 1);
          if (!popdKernelByType.has(pid)) popdKernelByType.set(pid, { kernel_kup: 0, heaps_n_hooks: 0 });
          const entry = popdKernelByType.get(pid)!;
          if (tType === 'heaps_n_hooks') entry.heaps_n_hooks++;
          else entry.kernel_kup++;
        }
      });

      // Get winning team rosters to determine champions â€” also track per tournament_type
      const { data: winningRosters } = await supabase
        .from('kkup_team_rosters')
        .select('team_id, person_id')
        .in('team_id', Array.from(winningTeamIds));

      // Build reverse map: winning_team_id â†’ tournament (so we can look up tournament_type from a team_id)
      const winningTeamToTournament = new Map<string, any>();
      (tournaments || []).forEach((t: any) => {
        if (t.winning_team_id) winningTeamToTournament.set(t.winning_team_id, t);
      });

      const championsByType = new Map<string, { kernel_kup: number; heaps_n_hooks: number }>(); // by type

      (winningRosters || []).forEach((r: any) => {
        const tInfo = winningTeamToTournament.get(r.team_id);
        const tType = tInfo?.tournament_type || 'kernel_kup';
        if (!championsByType.has(r.person_id)) championsByType.set(r.person_id, { kernel_kup: 0, heaps_n_hooks: 0 });
        const entry = championsByType.get(r.person_id)!;
        if (tType === 'heaps_n_hooks') entry.heaps_n_hooks++;
        else entry.kernel_kup++;
      });

      const championPersonIds = new Set(championsByType.keys());

      // Try to link kkup_persons to discord users via steam_id
      const userBySteamId = new Map();
      (usersWithSteam || []).forEach((u: any) => {
        if (u.steam_id) userBySteamId.set(u.steam_id, u);
      });

      // Helper to create empty stat bucket
      const emptyBucket = () => ({
        totalMatches: 0, totalWins: 0, totalLosses: 0,
        totalKills: 0, totalDeaths: 0, totalAssists: 0,
        totalLastHits: 0, totalDenies: 0, totalGPM: 0, totalXPM: 0,
        totalNetWorth: 0, bestKills: 0, bestGPM: 0, bestXPM: 0,
        heroes: new Map<string, { games: number; wins: number }>(),
        tournaments: new Set<string>(),
      });

      // Aggregate stats by person, split by overall / kernel_kup / heaps_n_hooks
      const playerAgg = new Map<string, any>();
      const uniqueHeroes = new Set<string>();
      const uniqueMatches = new Set<string>();

      (allStats || []).forEach((s: any) => {
        if (!s.person) return;
        const pid = s.person_id;
        uniqueMatches.add(s.match_id);
        if (s.hero) uniqueHeroes.add(s.hero.toLowerCase());

        const tournamentId = s.match?.tournament_id;
        const tInfo = tournamentId ? tournamentMap.get(tournamentId) : null;
        const tType = tInfo?.tournament_type || 'kernel_kup';

        if (!playerAgg.has(pid)) {
          playerAgg.set(pid, {
            person_id: pid,
            steam_id: s.person.steam_id,
            display_name: s.person.display_name,
            tournaments_won: s.person.tournaments_won || 0,
            prize_money_won_dollars: parseFloat(s.person.prize_money_won || '0'),
            overall: emptyBucket(),
            kernel_kup: emptyBucket(),
            heaps_n_hooks: emptyBucket(),
          });
        }

        const p = playerAgg.get(pid)!;
        const isWin = s.match && s.team_id === s.match.winning_team_id;

        // Accumulate into both overall and type-specific buckets
        const buckets = [p.overall, tType === 'heaps_n_hooks' ? p.heaps_n_hooks : p.kernel_kup];
        for (const b of buckets) {
          b.totalMatches++;
          if (isWin) b.totalWins++;
          else b.totalLosses++;
          b.totalKills += s.kills || 0;
          b.totalDeaths += s.deaths || 0;
          b.totalAssists += s.assists || 0;
          b.totalLastHits += s.last_hits || 0;
          b.totalDenies += s.denies || 0;
          b.totalGPM += s.gpm || 0;
          b.totalXPM += s.xpm || 0;
          b.totalNetWorth += s.net_worth || 0;
          if ((s.kills || 0) > b.bestKills) b.bestKills = s.kills;
          if ((s.gpm || 0) > b.bestGPM) b.bestGPM = s.gpm;
          if ((s.xpm || 0) > b.bestXPM) b.bestXPM = s.xpm;
          if (tournamentId) b.tournaments.add(tournamentId);
          if (s.hero) {
            if (!b.heroes.has(s.hero)) b.heroes.set(s.hero, { games: 0, wins: 0 });
            const h = b.heroes.get(s.hero)!;
            h.games++;
            if (isWin) h.wins++;
          }
        }
      });

      // Batch-load all avatars from KV in a single query
      const allAvatarEntries = await kv.getByPrefix('kkup_avatar:');
      const hofAvatarMap = new Map<string, string>();
      allAvatarEntries.forEach((entry: any) => {
        const steamId = entry.key?.replace('kkup_avatar:', '');
        if (steamId && entry.avatar_url) hofAvatarMap.set(steamId, entry.avatar_url);
      });

      // Helper to build a stats object from a bucket
      const buildStats = (bucket: any, personId: string, champCount: number, mvpCount: number, prizeCents: number) => {
        if (bucket.totalMatches === 0) return null;
        const winrate = bucket.totalMatches > 0 ? ((bucket.totalWins / bucket.totalMatches) * 100).toFixed(1) : '0.0';
        const avgKDA = bucket.totalDeaths > 0 ? ((bucket.totalKills + bucket.totalAssists) / bucket.totalDeaths).toFixed(2) : (bucket.totalKills + bucket.totalAssists).toFixed(2);
        const avgGPM = bucket.totalMatches > 0 ? (bucket.totalGPM / bucket.totalMatches).toFixed(0) : '0';
        const avgXPM = bucket.totalMatches > 0 ? (bucket.totalXPM / bucket.totalMatches).toFixed(0) : '0';

        // Signature hero
        let signatureHero: any = null;
        let maxGames = 0;
        bucket.heroes.forEach((h: any, heroName: string) => {
          if (h.games > maxGames) {
            maxGames = h.games;
            const heroId = getHeroIdFromName(heroName);
            signatureHero = {
              hero_id: heroId,
              hero_name: heroName,
              games: h.games,
              wins: h.wins,
              winrate: h.games > 0 ? ((h.wins / h.games) * 100).toFixed(1) : '0.0',
            };
          }
        });

        return {
          totalTournaments: bucket.tournaments.size,
          totalMatches: bucket.totalMatches,
          totalWins: bucket.totalWins,
          totalLosses: bucket.totalLosses,
          winrate,
          totalKills: bucket.totalKills,
          totalDeaths: bucket.totalDeaths,
          totalAssists: bucket.totalAssists,
          totalLastHits: bucket.totalLastHits,
          totalDenies: bucket.totalDenies,
          avgKDA,
          avgGPM,
          avgXPM,
          totalNetWorth: bucket.totalNetWorth,
          avgNetWorth: bucket.totalMatches > 0 ? Math.round(bucket.totalNetWorth / bucket.totalMatches) : 0,
          championships: champCount,
          mvps: mvpCount,
          prizeWinnings: prizeCents,
          signatureHero,
          records: {
            bestKills: bucket.bestKills,
            bestGPM: bucket.bestGPM,
            bestXPM: bucket.bestXPM,
          },
        };
      };

      // Build response
      const players = Array.from(playerAgg.values()).map((p: any) => {
        const linkedUser = userBySteamId.get(p.steam_id);
        const avatarUrl = hofAvatarMap.get(p.steam_id) || null;
        const mvpCount = popdKernelCount.get(p.person_id) || 0;
        const kkMvps = popdKernelByType.get(p.person_id)?.kernel_kup || 0;
        const hnhMvps = popdKernelByType.get(p.person_id)?.heaps_n_hooks || 0;
        const overallChamps = championsByType.has(p.person_id)
          ? (championsByType.get(p.person_id)!.kernel_kup + championsByType.get(p.person_id)!.heaps_n_hooks)
          : (p.tournaments_won || 0);
        const kkChamps = championsByType.get(p.person_id)?.kernel_kup || 0;
        const hnhChamps = championsByType.get(p.person_id)?.heaps_n_hooks || 0;

        return {
          id: p.person_id,
          name: p.display_name,
          avatar_url: avatarUrl,
          steam_id: p.steam_id,
          user: linkedUser ? {
            id: linkedUser.id,
            discord_username: linkedUser.discord_username,
            discord_avatar: linkedUser.discord_avatar,
            rank_id: linkedUser.rank_id,
            prestige_level: linkedUser.prestige_level || 0,
            role: linkedUser.role,
          } : null,
          // For overall: use the greater of kkup_persons.prize_money_won (denormalized) vs prize_awards aggregate
          // This catches both historical manual entries and new award-system entries
          stats: buildStats(p.overall, p.person_id, overallChamps, mvpCount,
            Math.max(Math.round(p.prize_money_won_dollars * 100), prizeByPerson.get(p.person_id)?.overall || 0)),
          // For per-type: use prize_awards aggregate (has tournament_id â†’ type mapping)
          kernelKupStats: buildStats(p.kernel_kup, p.person_id, kkChamps, kkMvps, prizeByPerson.get(p.person_id)?.kernel_kup || 0),
          heapsNHooksStats: buildStats(p.heaps_n_hooks, p.person_id, hnhChamps, hnhMvps, prizeByPerson.get(p.person_id)?.heaps_n_hooks || 0),
        };
      }).filter((p: any) => p.stats !== null)
