        const pid = s.person_id;
        const tInfo = s.tournament_id ? tournamentMap.get(s.tournament_id) : null;
        const tType = tInfo?.tournament_type || 'kernel_kup';

        if (!staffAgg.has(pid)) {
          staffAgg.set(pid, {
