  // ============================================================
  // LIST ALL TOURNAMENTS (Simple endpoint for Kernel Kup page)
  // ============================================================

  app.get(`${PREFIX}/kkup/tournaments`, async (c) => {
    try {
      // Fetch all tournaments with winner info and POPD Kernel person IDs
      const { data: tournaments, error } = await supabase
        .from('kkup_tournaments')
        .select(`
          id,
          name,
          description,
          status,
          tournament_start_date,
          tournament_end_date,
          tournament_type,
          prize_pool,
          prize_pool_donations,
          max_teams,
          team_count,
          player_count,
          winning_team_id,
          winning_team_name,
          popd_kernel_1_person_id,
          popd_kernel_2_person_id,
          league_id,
          kkup_season
        `)
        .order('tournament_start_date', { ascending: false });

      if (error) {
        console.error('Failed to fetch tournaments list:', error);
        return c.json({ error: 'Failed to fetch tournaments', details: error.message }, 500);
      }

      // For tournaments with winning_team_id, fetch team details
      const winningTeamIds = (tournaments || [])
        .map(t => t.winning_team_id)
        .filter(Boolean);

      let winnerMap = new Map<string, any>();
      if (winningTeamIds.length > 0) {
        const { data: winningTeams } = await supabase
          .from('kkup_teams')
          .select('id, team_name, team_tag, logo_url')
          .in('id', winningTeamIds);

        (winningTeams || []).forEach(team => {
          winnerMap.set(team.id, {
            team_name: team.team_name,
            team_tag: team.team_tag,
            logo_url: team.logo_url,
          });
        });
      }

      // For tournaments with POPD Kernel winners, fetch person names
      const popdPersonIds = (tournaments || [])
        .flatMap(t => [t.popd_kernel_1_person_id, t.popd_kernel_2_person_id])
        .filter(Boolean);

      let popdPersonMap = new Map<string, string>();
      if (popdPersonIds.length > 0) {
        const { data: persons } = await supabase
          .from('kkup_persons')
          .select('id, display_name')
          .in('id', popdPersonIds);

        (persons || []).forEach(person => {
          popdPersonMap.set(person.id, person.display_name);
        });
      }

      // For active tournaments, fetch registration data with player previews
      const activeTournamentIds = (tournaments || [])
        .filter(t => ['upcoming', 'registration_open', 'registration_closed', 'roster_lock', 'live', 'paused', 'in_progress'].includes(t.status))
        .map(t => t.id);

      let registrationMap = new Map<string, { count: number; previews: any[] }>();
      if (activeTournamentIds.length > 0) {
        const { data: registrations } = await supabase
          .from('kkup_registrations')
          .select(`
            tournament_id,
            user_id,
            users!inner(
              discord_avatar,
              discord_username,
              tcf_plus_active
            )
          `)
          .in('tournament_id', activeTournamentIds)
          .neq('status', 'withdrawn')
          .order('created_at', { ascending: false });

        // Group by tournament
        const regsByTournament = (registrations || []).reduce<Record<string, any[]>>((acc, reg) => {
          if (!acc[reg.tournament_id]) acc[reg.tournament_id] = [];
          acc[reg.tournament_id].push(reg);
          return acc;
        }, {});

        // Build preview data for each tournament
        Object.entries(regsByTournament).forEach(([tournamentId, regs]) => {
          registrationMap.set(tournamentId, {
            count: regs.length,
            previews: regs.slice(0, 15).map(r => ({
              avatar: r.users?.discord_avatar || null,
              name: r.users?.discord_username || 'Unknown',
              tcf_plus_active: r.users?.tcf_plus_active || false,
            })),
          });
        });
      }

      // Enrich tournaments with winner data, POPD Kernel names, and registration info
      const enrichedTournaments = (tournaments || []).map(t => {
        const regData = registrationMap.get(t.id);
        return {
          ...t,
          winner: t.winning_team_id ? winnerMap.get(t.winning_team_id) : null,
          popd_kernel_1_name: t.popd_kernel_1_person_id ? popdPersonMap.get(t.popd_kernel_1_person_id) : null,
          popd_kernel_2_name: t.popd_kernel_2_person_id ? popdPersonMap.get(t.popd_kernel_2_person_id) : null,
          registration_count: regData?.count || 0,
          player_previews: regData?.previews || [],
        };
      });

      return c.json({ tournaments: enrichedTournaments });
    } catch (error: any) {
      console.error('Get tournaments list error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // ============================================================
  // TOURNAMENT DETAIL â€” the big endpoint
  // ============================================================

  app.get(`${PREFIX}/kkup/:kkup_id`, async (c, next) => {
    const kkupId = c.req.param('kkup_id');
    if (kkupId === 'hall-of-fame' || kkupId === 'tournaments') return await next();

    try {
      const startTime = Date.now();

      // 1. Fetch tournament
      const { data: rawTournament, error: tournamentError } = await supabase
        .from('kkup_tournaments').select('*').eq('id', kkupId).single();
      if (tournamentError || !rawTournament) {
        console.error('Tournament not found:', kkupId, tournamentError?.message);
        return c.json({ error: 'Tournament not found' }, 404);
      }

      // Resolve Pop'd Kernel names from person IDs
      let popdKernel1Name: string | null = null;
      let popdKernel2Name: string | null = null;
      const popdIds = [rawTournament.popd_kernel_1_person_id, rawTournament.popd_kernel_2_person_id].filter(Boolean);
      if (popdIds.length > 0) {
        const { data: popdPersons } = await supabase
          .from('kkup_persons')
          .select('id, display_name')
          .in('id', popdIds);
        if (popdPersons) {
          for (const p of popdPersons) {
            if (p.id === rawTournament.popd_kernel_1_person_id) popdKernel1Name = p.display_name;
            if (p.id === rawTournament.popd_kernel_2_person_id) popdKernel2Name = p.display_name;
          }
        }
      }

      const tournament = {
        id: rawTournament.id,
        name: rawTournament.name,
        league_id: rawTournament.league_id,
        tournament_start_date: rawTournament.tournament_start_date,
        tournament_end_date: rawTournament.tournament_end_date,
        prize_pool: rawTournament.prize_pool ? String(rawTournament.prize_pool) : '0',
        prize_pool_donations: rawTournament.prize_pool_donations ?? 0,
        status: rawTournament.status,
        description: rawTournament.description,
        tournament_type: rawTournament.tournament_type,
        twitch_channel: rawTournament.twitch_url_1 || null,
        twitch_url_1: rawTournament.twitch_url_1,
        twitch_url_2: rawTournament.twitch_url_2,
        youtube_url: rawTournament.youtube_url,
        youtube_playlist_url: rawTournament.youtube_url,
        cover_photo_url: null,
        winning_team_id: rawTournament.winning_team_id,
        winning_team_name: rawTournament.winning_team_name,
        popd_kernel_1_person_id: rawTournament.popd_kernel_1_person_id,
        popd_kernel_2_person_id: rawTournament.popd_kernel_2_person_id,
        popd_kernel_1_name: popdKernel1Name,
        popd_kernel_2_name: popdKernel2Name,
        staff_count: rawTournament.staff_count,
        team_count: rawTournament.team_count,
        player_count: rawTournament.player_count,
        match_count: rawTournament.match_count,
        player_match_stats_count: rawTournament.player_match_stats_count,
        created_at: rawTournament.created_at,
      };

      // 2. Fetch teams
      const { data: rawTeams } = await supabase
        .from('kkup_teams').select('*').eq('tournament_id', kkupId);

      const teamLookup = new Map();
      (rawTeams || []).forEach((t: any) => {
        teamLookup.set(t.id, {
          id: t.id, name: t.team_name, tag: t.team_tag || t.team_name,
          logo_url: t.logo_url || (t.valve_team_id ? getSteamLogoUrl(t.valve_team_id) : null),
          valve_team_id: t.valve_team_id,
          captain_person_id: t.captain_person_id, coach_person_id: t.coach_person_id,
        });
      });

      // 3. Fetch matches
      const { data: rawMatches } = await supabase
        .from('kkup_matches').select('*').eq('tournament_id', kkupId)
        .order('match_date', { ascending: true });

      const matches = (rawMatches || []).map((m: any) => {
        const radiantTeam = teamLookup.get(m.radiant_team_id);
        const direTeam = teamLookup.get(m.dire_team_id);
        const winnerTeam = m.winning_team_id ? teamLookup.get(m.winning_team_id) : null;
        return {
          id: m.id,
          team1_id: m.radiant_team_id,
          team2_id: m.dire_team_id,
          team1: radiantTeam ? { id: radiantTeam.id, name: radiantTeam.name, tag: radiantTeam.tag, logo_url: radiantTeam.logo_url } : null,
          team2: direTeam ? { id: direTeam.id, name: direTeam.name, tag: direTeam.tag, logo_url: direTeam.logo_url } : null,
          winner: winnerTeam ? { id: winnerTeam.id, name: winnerTeam.name, tag: winnerTeam.tag, logo_url: winnerTeam.logo_url } : null,
          winner_team_id: m.winning_team_id,
          team1_score: m.radiant_team_score || 0,
          team2_score: m.dire_team_score || 0,
          stage: m.game_mode || 'captains_mode',
          status: m.winning_team_id ? 'completed' : 'scheduled',
          scheduled_time: m.match_date || m.match_time || rawTournament.tournament_start_date,
          match_id: m.external_match_id,
          series_id: m.series_id,
          match_length: m.match_length,
          match_time: m.match_time,
          match_date: m.match_date,
          game_mode: m.game_mode,
          radiant_person_id: m.radiant_person_id,
          dire_person_id: m.dire_person_id,
        };
      });

      // 4. Infer series_id
      let inferredSeriesCounter = 1000000;
      const seriesMap = new Map();
      for (const match of matches) {
        if (!match.series_id && match.team1_id && match.team2_id) {
          const teamPair = [match.team1_id, match.team2_id].sort();
          const seriesKey = `${teamPair[0]}-${teamPair[1]}`;
          if (!seriesMap.has(seriesKey)) seriesMap.set(seriesKey, String(inferredSeriesCounter++));
          match.series_id = seriesMap.get(seriesKey);
        }
      }

      // 5. Calculate records
      const teamRecords = new Map();
      teamLookup.forEach((_: any, teamId: string) => {
        teamRecords.set(teamId, { series_wins: 0, series_losses: 0, game_wins: 0, game_losses: 0, total_kills: 0 });
      });

      matches.forEach((match: any) => {
        if (match.winner_team_id) {
          if (match.team1_id === match.winner_team_id) {
            const r = teamRecords.get(match.team1_id); if (r) r.game_wins++;
            const o = teamRecords.get(match.team2_id); if (o) o.game_losses++;
          } else if (match.team2_id === match.winner_team_id) {
            const r = teamRecords.get(match.team2_id); if (r) r.game_wins++;
            const o = teamRecords.get(match.team1_id); if (o) o.game_losses++;
          }
        }
      });

      const seriesAgg = new Map();
      matches.forEach((match: any) => {
        if (!match.series_id) return;
        if (!seriesAgg.has(match.series_id)) {
          seriesAgg.set(match.series_id, { team1_id: match.team1_id, team2_id: match.team2_id, team1_wins: 0, team2_wins: 0 });
        }
        const s = seriesAgg.get(match.series_id);
        if (match.winner_team_id === s.team1_id) s.team1_wins++;
        else if (match.winner_team_id === s.team2_id) s.team2_wins++;
      });
      seriesAgg.forEach((series: any) => {
        if (series.team1_wins > series.team2_wins) {
          const r = teamRecords.get(series.team1_id); if (r) r.series_wins++;
          const o = teamRecords.get(series.team2_id); if (o) o.series_losses++;
        } else if (series.team2_wins > series.team1_wins) {
          const r = teamRecords.get(series.team2_id); if (r) r.series_wins++;
          const o = teamRecords.get(series.team1_id); if (o) o.series_losses++;
        }
      });

      // 6. Player match stats â€” resolve hero names to IDs
      const matchIds = matches.map((m: any) => m.id);
      let playerStats: any[] = [];
      if (matchIds.length > 0) {
        const { data: rawStats } = await supabase
          .from('kkup_player_match_stats')
          .select(`*, person:kkup_persons!person_id(steam_id, display_name)`)
          .in('match_id', matchIds)
          .order('match_id', { ascending: false })
          .order('team_id', { ascending: true });

        const matchWinnerMap = new Map();
        matches.forEach((m: any) => { matchWinnerMap.set(m.id, m.winner_team_id); });

        // Batch-load avatars from KV for all unique steam_ids
        const allSteamIds = new Set<string>();
        (rawStats || []).forEach((s: any) => {
          if (s.person?.steam_id) allSteamIds.add(s.person.steam_id);
        });
        const avatarMap = new Map<string, string>();
        for (const sid of allSteamIds) {
          const cached = await kv.get(`kkup_avatar:${sid}`);
          if (cached?.avatar_url) avatarMap.set(sid, cached.avatar_url);
        }

        playerStats = (rawStats || []).map((s: any) => {
          const team = s.team_id ? teamLookup.get(s.team_id) : null;
          const matchWinner = matchWinnerMap.get(s.match_id);
          const heroId = getHeroIdFromName(s.hero);
          const steamId = s.person?.steam_id || '';
          const avatarUrl = avatarMap.get(steamId) || null;
          return {
            id: s.id,
            match_id: s.match_id,
            team_id: s.team_id,
            player_name: s.person?.display_name || 'Unknown',
            steam_id: steamId,
            hero_id: heroId,
            hero_name: s.hero || 'Unknown',
            kills: s.kills || 0,
            deaths: s.deaths || 0,
            assists: s.assists || 0,
            last_hits: s.last_hits || 0,
            denies: s.denies || 0,
            gpm: s.gpm || 0,
            xpm: s.xpm || 0,
            net_worth: s.net_worth || 0,
            is_winner: s.team_id === matchWinner,
            account_id: parseInt(s.person?.steam_id || '0', 10),
            person_id: s.person_id,
            player: s.person ? {
              steam_id: s.person.steam_id,
              name: s.person.display_name,
              avatar_url: avatarUrl,
              dotabuff_url: s.person.steam_id ? `https://www.dotabuff.com/players/${s.person.steam_id}` : null,
              opendota_url: s.person.steam_id ? `https://www.opendota.com/players/${s.person.steam_id}` : null,
            } : null,
            team: team ? { id: team.id, name: team.name, tag: team.tag, logo_url: team.logo_url } : null,
          };
        });
      }

      // Update total kills per team
      playerStats.forEach((stat: any) => {
        if (stat.team_id) {
          const record = teamRecords.get(stat.team_id);
          if (record) record.total_kills += stat.kills || 0;
        }
      });

      // Build final teams array
      const teams = Array.from(teamLookup.values()).map((team: any) => {
        const record = teamRecords.get(team.id) || {};
        return {
          ...team,
          wins: record.game_wins || 0, losses: record.game_losses || 0,
          series_wins: record.series_wins || 0, series_losses: record.series_losses || 0,
          game_wins: record.game_wins || 0, game_losses: record.game_losses || 0,
          total_kills: record.total_kills || 0,
        };
      }).sort((a: any, b: any) => {
        if (b.series_wins !== a.series_wins) return b.series_wins - a.series_wins;
        return b.game_wins - a.game_wins;
      });

      // 7. Fetch rosters
      const teamIds = teams.map((t: any) => t.id);
      let rosters: any[] = [];
      if (teamIds.length > 0) {
        const { data: rawRosters } = await supabase
          .from('kkup_team_rosters')
          .select(`*, person:kkup_persons!person_id(steam_id, display_name)`)
          .in('team_id', teamIds);
        
        // Detect stand-ins: a person on multiple teams' rosters is a stand-in on teams
        // where they DON'T have the most match stats
        const rosterEntries = rawRosters || [];
        
        // Count match stats per person per team to determine "home" team
        const personTeamStats = new Map<string, Map<string, number>>(); // person_id â†’ { team_id â†’ match_count }
        playerStats.forEach((stat: any) => {
          if (!stat.team_id || !stat.person_id) return;
          if (!personTeamStats.has(stat.person_id)) personTeamStats.set(stat.person_id, new Map());
          const teamMap = personTeamStats.get(stat.person_id)!;
          teamMap.set(stat.team_id, (teamMap.get(stat.team_id) || 0) + 1);
        });

        // For each person on multiple teams, find their "home" team (most matches)
        const personHomeTeam = new Map<string, string>(); // person_id â†’ home team_id
        const multiTeamPersons = new Set<string>();
        const personTeams = new Map<string, string[]>();
        rosterEntries.forEach((r: any) => {
          if (!personTeams.has(r.person_id)) personTeams.set(r.person_id, []);
          personTeams.get(r.person_id)!.push(r.team_id);
        });
        personTeams.forEach((teamList, personId) => {
          if (teamList.length > 1) {
            multiTeamPersons.add(personId);
            // Home team = team with most match stats
            const statsMap = personTeamStats.get(personId);
            if (statsMap) {
              let maxCount = 0;
              let homeTeamId = teamList[0];
              statsMap.forEach((count, tid) => {
                if (count > maxCount) { maxCount = count; homeTeamId = tid; }
              });
              personHomeTeam.set(personId, homeTeamId);
            } else {
              personHomeTeam.set(personId, teamList[0]);
            }
          }
        });

        rosters = rosterEntries.map((r: any) => ({
          ...r,
          is_standin: multiTeamPersons.has(r.person_id) && personHomeTeam.get(r.person_id) !== r.team_id,
        }));
      }

      // 8. Fetch staff â€” include avatars from KV cache
      const { data: rawStaff } = await supabase
        .from('kkup_tournament_staff')
        .select(`*, person:kkup_persons!person_id(steam_id, display_name)`)
        .eq('tournament_id', kkupId);

      // Collect staff steam_ids for avatar lookup (reuse existing avatarMap if possible)
      const staffSteamIds = (rawStaff || []).map((s: any) => s.person?.steam_id).filter(Boolean);
      const staffAvatarMap = new Map<string, string>();
      for (const sid of staffSteamIds) {
        // Check if already loaded from player stats avatarMap
        if (playerStats.length > 0) {
          const existing = playerStats.find((ps: any) => ps.steam_id === sid);
          if (existing?.player?.avatar_url) {
            staffAvatarMap.set(sid, existing.player.avatar_url);
            continue;
          }
        }
        const cached = await kv.get(`kkup_avatar:${sid}`);
        if (cached?.avatar_url) staffAvatarMap.set(sid, cached.avatar_url);
      }

      const staff = (rawStaff || []).map((s: any) => ({
        person_id: s.person_id,
        role: s.role,
        display_name: s.person?.display_name || 'Unknown',
        steam_id: s.person?.steam_id || '',
        avatar_url: staffAvatarMap.get(s.person?.steam_id) || null,
      }));

      // 8b. Build coaches list from team data
      const coaches: any[] = [];
      for (const team of Array.from(teamLookup.values())) {
        if (team.coach_person_id) {
          const { data: coachPerson } = await supabase
            .from('kkup_persons').select('steam_id, display_name')
            .eq('id', team.coach_person_id).single();
          if (coachPerson) {
            const coachAvatar = staffAvatarMap.get(coachPerson.steam_id) || null;
            coaches.push({
              person_id: team.coach_person_id,
              display_name: coachPerson.display_name,
              steam_id: coachPerson.steam_id,
              avatar_url: coachAvatar,
              team_name: team.name,
              team_id: team.id,
            });
          }
        }
      }

      // 9. Popd kernel person names â€” already resolved above into tournament object
      // (removed duplicate resolution block)

      // Group stats by match
      const statsByMatch = playerStats.reduce((acc: any, stat: any) => {
        if (!acc[stat.match_id]) acc[stat.match_id] = [];
        acc[stat.match_id].push(stat);
        return acc;
      }, {});

      const responseTime = Date.now() - startTime;
      console.log(`Tournament ${kkupId} loaded in ${responseTime}ms (${teams.length} teams, ${matches.length} matches, ${playerStats.length} stats)`);

      return c.json({
        tournament,
        teams, matches, player_stats: playerStats, stats_by_match: statsByMatch,
        hero_bans: {}, staff, coaches, rosters,
      });
    } catch (error: any) {
      console.error('Get tournament details error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // NOTE: GET /kkup/tournaments/:id/staff is handled by routes-staff-applications.ts
  // Duplicate removed to avoid route conflicts.

}

/**
 * KKUP Tools Routes -- enrich matches, sync names/logos, OpenDota import, fix hero names,
 * all-teams, storage listing, bulk logo update, link/unlink profiles, user stats, search, find-duplicates
 * 13 routes
 */
import type { Hono } from "npm:hono";
import * as kv from "./kv_store.tsx";
import { PREFIX, getHeroName, getHeroIdFromName } from "./helpers.ts";
import { createAdminLog } from "./routes-notifications.ts";
import { normalizeToAccountId, steam32ToSteam64, getDotabuffUrl, getOpendotaUrl, getSteamProfileUrl } from "./steam-id-helpers.ts";

export function registerKkupToolsRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ Helper: require owner â”€â”€
  async function requireOwner(c: any) {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return null;
    const { data: { user: authUser }, error } = await anonSupabase.auth.getUser(accessToken);
    if (error || !authUser) return null;
    const { data: dbUser } = await supabase.from('users').select('role').eq('supabase_id', authUser.id).single();
    if (!dbUser || dbUser.role !== 'owner') return null;
    return authUser;
  }

  // Enrich matches with OpenDota data (Owner only)
  app.post(`${PREFIX}/kkup/:kkup_id/enrich-matches`, async (c) => {
    try {
      if (!await requireOwner(c)) return c.json({ error: 'Owner access required' }, 403);

      const kkupId = c.req.param('kkup_id');
      const { data: matches, error: matchesError } = await supabase
        .from('kkup_matches').select('*').eq('tournament_id', kkupId).order('scheduled_time', { ascending: true });
      if (matchesError) return c.json({ error: 'Failed to fetch matches' }, 500);
      if (!matches || matches.length === 0) return c.json({ error: 'No matches found' }, 404);

      const apiKey = Deno.env.get('OPENDOTA_API_KEY');
      let enrichedCount = 0, skippedCount = 0, errorCount = 0;
      const errors: any[] = [];

      for (const match of matches) {
        try {
          if (!match.match_id) { skippedCount++; continue; }

          const res = await fetch(`https://api.opendota.com/api/matches/${match.match_id}?api_key=${apiKey}`);
          if (!res.ok) { errorCount++; errors.push({ match_id: match.match_id, error: `HTTP ${res.status}` }); continue; }
          const detail = await res.json();
          if (!detail || detail.error) { errorCount++; errors.push({ match_id: match.match_id, error: 'Not found on OpenDota' }); continue; }

          // Find or create teams
          let radiantTeam: any = null, direTeam: any = null;
          for (const [teamKey, teamData] of [['radiant_team', detail.radiant_team], ['dire_team', detail.dire_team]] as const) {
            if (!teamData) continue;
            const { data: existing } = await supabase.from('kkup_teams').select('*').eq('tournament_id', kkupId).eq('valve_team_id', teamData.team_id).maybeSingle();
            if (existing) { if (teamKey === 'radiant_team') radiantTeam = existing; else direTeam = existing; }
            else {
              const { data: newTeam } = await supabase.from('kkup_teams').insert({
                tournament_id: kkupId, team_name: teamData.name || 'Unknown', team_tag: teamData.tag,
                valve_team_id: teamData.team_id, logo_url: teamData.logo_url
              }).select().single();
              if (teamKey === 'radiant_team') radiantTeam = newTeam; else direTeam = newTeam;
            }
          }

          const winnerTeam = detail.radiant_win ? radiantTeam : direTeam;
          const team1Score = match.team1_id === radiantTeam?.id ? (detail.radiant_score || 0) : (detail.dire_score || 0);
          const team2Score = match.team2_id === radiantTeam?.id ? (detail.radiant_score || 0) : (detail.dire_score || 0);

          await supabase.from('kkup_matches').update({
            team1_score: team1Score, team2_score: team2Score, winner_team_id: winnerTeam?.id,
            radiant_win: detail.radiant_win, duration: detail.duration || 0,
            pick_bans_data: detail.picks_bans || null, opendota_fetched: true, opendota_fetched_at: new Date().toISOString(),
          }).eq('id', match.id);

          // Player stats
          for (const player of detail.players) {
            let profile: any = null;
            if (player.account_id) {
              const { data: existing } = await supabase.from('kkup_persons').select('*').eq('steam_id', String(player.account_id)).maybeSingle();
              if (existing) profile = existing;
              else {
                const { data: np } = await supabase.from('kkup_persons').insert({
                  steam_id: String(player.account_id), display_name: player.personaname || `Player ${player.account_id}`,
                  avatar_url: player.avatarfull,
                }).select().single();
                profile = np;
              }
            }

            const isRadiant = player.player_slot < 128;
            const teamId = isRadiant ? radiantTeam?.id : direTeam?.id;
            if (!teamId) continue;

            const statData = {
              match_id: match.id, team_id: teamId, person_id: profile?.id || null,
              hero_id: player.hero_id || 0,
              hero: getHeroName(player.hero_id || 0),
              kills: player.kills || 0, deaths: player.deaths || 0, assists: player.assists || 0,
              last_hits: player.last_hits || 0, denies: player.denies || 0,
              gpm: player.gold_per_min || 0, xpm: player.xp_per_min || 0,
              net_worth: player.net_worth || player.total_gold || 0,
            };

            const { data: existingStats } = await supabase.from('kkup_player_match_stats').select('*').eq('match_id', match.id).eq('person_id', profile?.id || null).maybeSingle();
            if (existingStats) await supabase.from('kkup_player_match_stats').update(statData).eq('id', existingStats.id);
            else await supabase.from('kkup_player_match_stats').insert(statData);
          }

          enrichedCount++;
          await new Promise(r => setTimeout(r, 200));
        } catch (e: any) { errorCount++; errors.push({ match_id: match.match_id, error: e.message }); }
      }

      const { data: t } = await supabase.from('kkup_tournaments').select('name').eq('id', kkupId).maybeSingle();
      try { await createAdminLog({ type: 'data_enrich', action: `Enriched ${enrichedCount}/${matches.length} matches for ${t?.name || kkupId} (${errorCount} errors)`, actor_name: 'Owner' }); } catch (_) {}

      return c.json({ success: true, enriched: enrichedCount, skipped: skippedCount, errors: errorCount, error_details: errors, message: `Enriched ${enrichedCount} out of ${matches.length} matches` });
    } catch (error: any) {
      console.error('Enrich matches error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // Sync player names & team logos (Owner only)
  app.post(`${PREFIX}/kkup/sync-names-logos`, async (c) => {
    try {
      if (!await requireOwner(c)) return c.json({ error: 'Owner access required' }, 403);

      let playersUpdated = 0, teamsUpdated = 0, usersUpdated = 0, masterTeamsUpdated = 0;
      const errors: string[] = [];

      // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
      // PHASE 1: Sync Player Names & Avatars from Steam Web API
      // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
      const { data: players } = await supabase.from('kkup_persons').select('id, steam_id, display_name').not('steam_id', 'is', null);
      if (players && players.length > 0) {
        console.log(`ðŸ”„ Syncing ${players.length} players from Steam Web API...`);
        
        // Batch Steam IDs into groups of 100 (Steam API limit)
        const BATCH_SIZE = 100;
        for (let i = 0; i < players.length; i += BATCH_SIZE) {
          const batch = players.slice(i, i + BATCH_SIZE);
          const steamIds = batch.map((p: any) => p.steam_id).join(',');
          
          try {
            const steamApiKey = Deno.env.get('STEAM_WEB_API_KEY');
            if (!steamApiKey) {
              errors.push('STEAM_WEB_API_KEY not configured');
              break;
            }

            // Call Steam Web API GetPlayerSummaries (source of truth!)
            const res = await fetch(
              `https://api.steampowered.com/ISteamUser/GetPlayerSummaries/v0002/?key=${steamApiKey}&steamids=${steamIds}`
            );
            
            if (res.ok) {
              const data = await res.json();
              const steamPlayers = data.response?.players || [];
              
              for (const steamPlayer of steamPlayers) {
                const person = batch.find((p: any) => p.steam_id === steamPlayer.steamid);
                if (!person) continue;
                
                const updates: any = {};
                
                // Update display name from Steam (current, real-time data!)
                if (steamPlayer.personaname && steamPlayer.personaname !== person.display_name) {
                  updates.display_name = steamPlayer.personaname;
                }
                
                // Update avatar from Steam
                if (steamPlayer.avatarfull) {
                  updates.avatar_url = steamPlayer.avatarfull;
                }
                
                if (Object.keys(updates).length > 0) {
                  await supabase.from('kkup_persons').update(updates).eq('id', person.id);
                  playersUpdated++;
                  
                  // Also sync to users table if they have a linked Discord account
                  const { data: linkedUser } = await supabase
                    .from('users')
                    .select('id')
                    .eq('steam_id', person.steam_id)
                    .single();
                  
                  if (linkedUser) {
                    await supabase.from('users').update({
                      steam_name: updates.display_name || undefined,
                      steam_avatar: updates.avatar_url || undefined
                    }).eq('id', linkedUser.id);
                    usersUpdated++;
                  }
                }
              }
            } else {
              errors.push(`Steam API returned ${res.status} for batch ${i / BATCH_SIZE + 1}`);
            }
            
            // Delay between batches to avoid rate limiting
            await new Promise(r => setTimeout(r, 200));
          } catch (batchError) {
            console.error(`Error processing player batch ${i / BATCH_SIZE + 1}:`, batchError);
            errors.push(`Batch ${i / BATCH_SIZE + 1} failed: ${batchError instanceof Error ? batchError.message : String(batchError)}`);
          }
        }
      }

      // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
      // PHASE 2: Sync Master Team Logos (Source of Truth)
      // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
      const { data: masterTeams } = await supabase.from('kkup_master_teams').select('id, team_tag, team_name, logo_url');
      if (masterTeams && masterTeams.length > 0) {
        console.log(`ðŸ”„ Syncing ${masterTeams.length} master team logos from team_logos/ folder...`);
        
        for (const team of masterTeams) {
          try {
            const sanitizedTag = (team.team_tag || team.team_name || '')
              .toLowerCase()
              .replace(/[^a-z0-9]/g, '');
            
            if (!sanitizedTag || sanitizedTag.length < 2) continue;
            
            // Search in master team_logos/ folder for .png or .jpg
            const { data: pngFiles } = await supabase.storage
              .from('make-4789f4af-kkup-assets')
              .list('team_logos', { search: sanitizedTag });
            
            let foundFile = pngFiles?.find((f: any) => f.name.toLowerCase().includes(sanitizedTag));
            
            if (foundFile) {
              const { data: urlData } = supabase.storage
                .from('make-4789f4af-kkup-assets')
                .getPublicUrl(`team_logos/${foundFile.name}`);
              
              if (urlData?.publicUrl && urlData.publicUrl !== team.logo_url) {
                await supabase.from('kkup_master_teams').update({ logo_url: urlData.publicUrl }).eq('id', team.id);
                masterTeamsUpdated++;
              }
            }
          } catch (teamError) {
            console.error(`Error syncing master team ${team.team_tag}:`, teamError);
          }
        }
      }

      // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
      // PHASE 3: Sync Tournament Team Logos (per-tournament snapshots)
      // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
      const { data: teams } = await supabase.from('kkup_teams').select('id, team_tag, team_name, tournament_id, master_team_id, logo_url');
      if (teams && teams.length > 0) {
        console.log(`ðŸ”„ Syncing ${teams.length} tournament team logos...`);
        
        const { data: tournaments } = await supabase.from('kkup_tournaments').select('id, name');
        const tournamentMap = new Map(tournaments?.map((t: any) => [t.id, t.name]) || []);
        
        for (const team of teams) {
          try {
            const tournamentName = tournamentMap.get(team.tournament_id);
            if (!tournamentName) continue;
            
            const isHeapsNHooks = tournamentName.toLowerCase().includes('heaps') && tournamentName.toLowerCase().includes('hooks');
            const folderName = tournamentName.toLowerCase().trim()
              .replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
            
            if (folderName.length < 3) continue;
            
            let foundLogoUrl: string | null = null;
            
            if (isHeapsNHooks) {
              // Heaps n Hooks: Pull from tournament-specific folder
              const sanitizedName = (team.team_tag || team.team_name || '')
                .toLowerCase()
                .replace(/[^a-z0-9]/g, '');
              
              const { data: fileData } = await supabase.storage
                .from('make-4789f4af-kkup-assets')
                .list(folderName, { search: sanitizedName });
              
              if (fileData && fileData.length > 0) {
                const { data: urlData } = supabase.storage
                  .from('make-4789f4af-kkup-assets')
                  .getPublicUrl(`${folderName}/${fileData[0].name}`);
                foundLogoUrl = urlData?.publicUrl || null;
              }
            } else {
              // Kernel Kup: Pull from master team_logos/ folder
              if (team.master_team_id) {
                // Use master team logo if linked
                const { data: masterTeam } = await supabase
                  .from('kkup_master_teams')
                  .select('logo_url')
                  .eq('id', team.master_team_id)
                  .single();
                foundLogoUrl = masterTeam?.logo_url || null;
              } else {
                // Fallback: search team_logos/ by tag
                const sanitizedTag = (team.team_tag || team.team_name || '')
                  .toLowerCase()
                  .replace(/[^a-z0-9]/g, '');
                
                const { data: fileData } = await supabase.storage
                  .from('make-4789f4af-kkup-assets')
                  .list('team_logos', { search: sanitizedTag });
                
                if (fileData && fileData.length > 0) {
                  const { data: urlData } = supabase.storage
                    .from('make-4789f4af-kkup-assets')
                    .getPublicUrl(`team_logos/${fileData[0].name}`);
                  foundLogoUrl = urlData?.publicUrl || null;
                }
              }
            }
            
            if (foundLogoUrl && foundLogoUrl !== team.logo_url) {
              await supabase.from('kkup_teams').update({ logo_url: foundLogoUrl }).eq('id', team.id);
              teamsUpdated++;
            }
          } catch (teamError) {
            console.error(`Error syncing team ${team.team_tag}:`, teamError);
          }
        }
      }

      try { 
        await createAdminLog({ 
          type: 'data_sync', 
          action: `Synced names & logos: ${playersUpdated} players, ${teamsUpdated} teams, ${masterTeamsUpdated} master teams, ${usersUpdated} users updated`, 
          actor_name: 'Owner' 
        }); 
      } catch (_) {}

      return c.json({ 
        success: true, 
        playersUpdated, 
        teamsUpdated,
        masterTeamsUpdated,
        usersUpdated,
        errors: errors.length > 0 ? errors : undefined
      });
    } catch (error) {
      console.error('Sync error:', error);
      return c.json({ success: false, error: String(error) }, 500);
    }
  });

  // Import single match from OpenDota data
  app.post(`${PREFIX}/kkup/import-opendota-match`, async (c) => {
    try {
      const body = await c.req.json();
      const matchData = body.opendota?.data || body;
      if (!matchData || !matchData.match_id) return c.json({ error: 'Invalid OpenDota match data' }, 400);

      const leagueId = matchData.leagueid || matchData.league?.leagueid;
      if (!leagueId) return c.json({ error: 'No league_id found in match data' }, 400);
      const tournamentName = matchData.league?.name || `League ${leagueId}`;

      const { data: existing } = await supabase.from('kkup_tournaments').select('*').eq('league_id', leagueId).single();
      let kkupId: string, isNew = false;

      if (existing) { kkupId = existing.id; }
      else {
        const matchDate = new Date(matchData.start_time * 1000);
        const { data: nt, error } = await supabase.from('kkup_tournaments').insert({
          name: tournamentName, league_id: leagueId, series_id: 0,
          verified_match_id: matchData.match_id, verified_team_id: matchData.radiant_team_id || 0, verified_player_id: matchData.players?.[0]?.account_id || 0,
          tournament_start_date: matchDate.toISOString().split('T')[0], tournament_end_date: matchDate.toISOString().split('T')[0],
          import_status: 'in_progress', created_at: new Date().toISOString(), updated_at: new Date().toISOString()
        }).select().single();
        if (error || !nt) return c.json({ error: 'Failed to create tournament', details: error }, 500);
        kkupId = nt.id; isNew = true;
      }

      // Create/find teams
      const teamMap = new Map();
      for (const [valveId, name, logo] of [
        [matchData.radiant_team_id, matchData.radiant_name, matchData.radiant_logo],
        [matchData.dire_team_id, matchData.dire_name, matchData.dire_logo]
      ] as any[]) {
        if (!valveId) continue;
        const { data: et } = await supabase.from('kkup_teams').select('*').eq('tournament_id', kkupId).eq('valve_team_id', valveId).single();
        if (et) { teamMap.set(valveId, et); }
        else {
          const { data: nt } = await supabase.from('kkup_teams').insert({
            tournament_id: kkupId, team_name: name || `Team ${valveId}`, team_tag: (name || '').substring(0, 5).toUpperCase() || 'TEAM',
            valve_team_id: valveId, logo_url: logo ? `https://steamcdn-a.akamaihd.net/apps/dota2/images/team_logos/${logo}.png` : null,
            imported_at: new Date().toISOString()
          }).select().single();
          if (nt) teamMap.set(valveId, nt);
        }
      }

      // Create match if not exists
      const { data: existingMatch } = await supabase.from('kkup_matches').select('*').eq('valve_match_id', matchData.match_id).single();
      let matchCreated = false;
      if (!existingMatch) {
        const rt = teamMap.get(matchData.radiant_team_id);
        const dt = teamMap.get(matchData.dire_team_id);
        await supabase.from('kkup_matches').insert({
          tournament_id: kkupId, valve_match_id: matchData.match_id,
          match_date: new Date(matchData.start_time * 1000).toISOString(), duration_seconds: matchData.duration,
          radiant_team_id: rt?.id, dire_team_id: dt?.id,
          radiant_win: matchData.radiant_win, radiant_score: matchData.radiant_score || 0, dire_score: matchData.dire_score || 0,
          imported_at: new Date().toISOString()
        });
        matchCreated = true;
      }

      await supabase.from('kkup_tournaments').update({ import_status: 'completed', imported_at: new Date().toISOString() }).eq('id', kkupId);

      try { await createAdminLog({ type: 'match_imported', action: `Imported match ${matchData.match_id} into ${tournamentName}${isNew ? ' (new tournament)' : ''}`, actor_name: 'Owner' }); } catch (_) {}

      return c.json({ success: true, message: matchCreated ? 'Match imported' : 'Match already exists',
        tournament_id: kkupId, tournament_name: tournamentName, tournament_created: isNew,
        stats: { teams_processed: teamMap.size, match_created: matchCreated } });
    } catch (error: any) {
      console.error('OpenDota import error:', error);
      return c.json({ error: 'Import failed', details: error?.message || String(error) }, 500);
    }
  });

  // Fix hero names in player stats
  app.post(`${PREFIX}/kkup/fix-hero-names`, async (c) => {
    try {
      const { data: stats, error } = await supabase.from('kkup_player_match_stats').select('id, hero_id, hero').like('hero', 'Hero %');
      if (error) return c.json({ error: 'Failed to fetch player stats' }, 500);
      if (!stats || stats.length === 0) return c.json({ message: 'No hero names to fix!', updated: 0 });

      let updated = 0, failed = 0;
      for (const stat of stats) {
        const { error: ue } = await supabase.from('kkup_player_match_stats').update({ hero: getHeroName(stat.hero_id) }).eq('id', stat.id);
        if (ue) failed++; else updated++;
      }

      try { await createAdminLog({ type: 'data_fix', action: `Fixed ${updated} hero names (${failed} failed, ${stats.length} total)`, actor_name: 'Owner' }); } catch (_) {}

      return c.json({ message: `Updated ${updated} hero names!`, updated, failed, total: stats.length });
    } catch (error) {
      console.error('Fix hero names error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Backfill hero_id from hero names (Owner only)
  app.post(`${PREFIX}/kkup/backfill-hero-ids`, async (c) => {
    try {
      if (!await requireOwner(c)) return c.json({ error: 'Owner access required' }, 403);

      // Get all stats that have a hero name but missing hero_id
      const { data: stats, error } = await supabase
        .from('kkup_player_match_stats')
        .select('id, hero, hero_id')
        .not('hero', 'is', null);

      if (error) return c.json({ error: 'Failed to fetch player stats: ' + error.message }, 500);
      if (!stats || stats.length === 0) return c.json({ message: 'No records to backfill!', updated: 0 });

      let updated = 0, skipped = 0, failed = 0;
      const errors: string[] = [];

      for (const stat of stats) {
        try {
          // Skip if hero_id already exists
          if (stat.hero_id && stat.hero_id > 0) {
            skipped++;
            continue;
          }

          // Convert hero name to ID
          const heroId = getHeroIdFromName(stat.hero);
          
          if (!heroId || heroId === 0) {
            failed++;
            errors.push(`Unknown hero name: "${stat.hero}" (stat ID: ${stat.id})`);
            continue;
          }

          // Update the record
          const { error: updateError } = await supabase
            .from('kkup_player_match_stats')
            .update({ hero_id: heroId })
            .eq('id', stat.id);

          if (updateError) {
            failed++;
            errors.push(`Failed to update stat ${stat.id}: ${updateError.message}`);
          } else {
            updated++;
          }
        } catch (rowError: any) {
          failed++;
          errors.push(`Error processing stat ${stat.id}: ${rowError.message}`);
        }
      }

      try {
        await createAdminLog({
          type: 'data_fix',
          action: `Backfilled hero IDs: ${updated} updated, ${skipped} skipped, ${failed} failed (${stats.length} total)`,
          actor_name: 'Owner',
        });
      } catch (_) {}

      return c.json({
        success: true,
        message: `Backfill complete: ${updated} hero IDs added!`,
        updated,
        skipped,
        failed,
        total: stats.length,
        errors: errors.length > 0 ? errors.slice(0, 20) : undefined, // Show first 20 errors
      });
    } catch (error: any) {
      console.error('Backfill hero IDs error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // Get all teams with tournament info
  app.get(`${PREFIX}/kkup/all-teams`, async (c) => {
    try {
      const { data: teams, error } = await supabase.from('kkup_teams').select('*').order('team_name', { ascending: true });
      if (error) return c.json({ error: 'Failed to fetch teams' }, 500);
      const { data: tournaments } = await supabase.from('kkup_tournaments').select('id, name');
      const tMap = new Map(tournaments?.map((t: any) => [t.id, t]) || []);
      const teamsWithTournaments = (teams || []).map((team: any) => ({ ...team, tournament: tMap.get(team.tournament_id) || null }));
      return c.json({ teams: teamsWithTournaments });
    } catch (error) {
      console.error('Get all teams error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // List files in KKup Assets storage
  app.get(`${PREFIX}/kkup/storage/list`, async (c) => {
    try {
      const path = c.req.query('path') || '';
      const { data: files, error } = await supabase.storage.from('make-4789f4af-kkup-assets').list(path, { limit: 1000, sortBy: { column: 'name', order: 'asc' } });
      if (error) return c.json({ error: 'Failed to list files' }, 500);

      const filesWithUrls = files.map((file: any) => {
        const fullPath = path ? `${path}/${file.name}` : file.name;
        const { data: urlData } = supabase.storage.from('make-4789f4af-kkup-assets').getPublicUrl(fullPath);
        return { name: file.name, path: fullPath, url: urlData.publicUrl, isFolder: !file.id || !file.name.includes('.'), metadata: file.metadata };
      });
      return c.json({ files: filesWithUrls, path: path || '/' });
    } catch (error) {
      console.error('List storage error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Bulk update team logos
  app.post(`${PREFIX}/kkup/teams/update-logos`, async (c) => {
    try {
      const { mappings = [] } = await c.req.json();
      let updated = 0, failed = 0;
      for (const mapping of mappings) {
        const { data: urlData } = supabase.storage.from('make-4789f4af-kkup-assets').getPublicUrl(mapping.logo_path);
        const { error } = await supabase.from('kkup_teams').update({ logo_url: urlData.publicUrl }).eq('id', mapping.team_id);
        if (error) failed++; else updated++;
      }

      try { await createAdminLog({ type: 'logo_update', action: `Bulk updated ${updated} team logos (${failed} failed)`, actor_name: 'Owner' }); } catch (_) {}

      return c.json({ message: `Updated ${updated} team logos!`, updated, failed, total: mappings.length });
    } catch (error) {
      console.error('Update logos error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Link user to KKUP player profile (DEPRECATED â€” linking now uses steam_id automatically)
  app.post(`${PREFIX}/admin/link-user-kkup-profile`, async (c) => {
    return c.json({ error: 'This endpoint is deprecated. KKUP profiles are now automatically linked via steam_id. Connect your OpenDota/Steam account to link.' }, 410);
  });

  // Unlink user from KKUP player profile (DEPRECATED â€” linking now uses steam_id automatically)
  app.post(`${PREFIX}/admin/unlink-user-kkup-profile`, async (c) => {
    return c.json({ error: 'This endpoint is deprecated. KKUP profiles are now automatically linked via steam_id.' }, 410);
  });

  // Get user's KKUP stats
  app.get(`${PREFIX}/users/:user_id/kkup-stats`, async (c) => {
    try {
      const userId = c.req.param('user_id');
      const { data: user, error: ue } = await supabase.from('users').select('id, discord_username, steam_id').eq('id', userId).single();
      if (ue || !user) return c.json({ error: 'User not found' }, 404);
      if (!user.steam_id) return c.json({ linked: false, championships: { kernel_kup: 0, heaps_n_hooks: 0, total: 0 }, popd_kernels: 0, tournaments_played: 0, total_games: 0, wins: 0, losses: 0 });

      // Find the kkup_persons record by steam_id
      const { data: person, error: pe } = await supabase.from('kkup_persons').select('id, display_name, steam_id').eq('steam_id', user.steam_id).maybeSingle();
      if (pe || !person) return c.json({ linked: false, championships: { kernel_kup: 0, heaps_n_hooks: 0, total: 0 }, popd_kernels: 0, tournaments_played: 0, total_games: 0, wins: 0, losses: 0 });

      const personId = person.id;

      // Get team memberships
      const { data: teamMemberships } = await supabase.from('kkup_team_rosters').select('team_id').eq('person_id', personId);
      const teamIds = teamMemberships?.map((tm: any) => tm.team_id) || [];

      // Get all tournaments for championship & MVP lookups
      const { data: tournaments } = await supabase.from('kkup_tournaments').select('id, winning_team_id, tournament_type, popd_kernel_1_person_id, popd_kernel_2_person_id, name, status');

      // Count championships by type
      let kernelKupChampionships = 0, heapsNHooksChampionships = 0;
      if (teamIds.length > 0) {
        // Get winning team rosters for teams we're on
        const winningTournaments = (tournaments || []).filter((t: any) => t.winning_team_id && teamIds.includes(t.winning_team_id));
        for (const t of winningTournaments) {
          const tType = t.tournament_type || 'kernel_kup';
          if (tType === 'heaps_n_hooks') heapsNHooksChampionships++;
          else kernelKupChampionships++;
        }
      }

      // Count Pop'd Kernel awards
      let popdKernels = 0;
      (tournaments || []).forEach((t: any) => {
        if (t.popd_kernel_1_person_id === personId) popdKernels++;
        if (t.popd_kernel_2_person_id === personId) popdKernels++;
      });

      // Count unique tournaments played
      const { data: teamsPlayed } = await supabase.from('kkup_teams').select('tournament_id').in('id', teamIds.length > 0 ? teamIds : ['__none__']);
      const uniqueTournaments = new Set(teamsPlayed?.map((t: any) => t.tournament_id));

      // Get player match stats â€” is_winner is pre-computed on the row (backfilled for KK1-9, set at import for future)
      // Fall back to the join-based check for any rows where is_winner is null (edge case: pre-backfill imports)
      const { data: playerGames } = await supabase
        .from('kkup_player_match_stats')
        .select('id, team_id, kills, deaths, assists, hero, is_winner, match:kkup_matches!match_id(winning_team_id)')
        .eq('person_id', personId);

      const totalGames = playerGames?.length || 0;
      const wins = playerGames?.filter((g: any) => {
        // Prefer the pre-computed is_winner column; fall back to join-based check for null rows
        if (g.is_winner !== null && g.is_winner !== undefined) return g.is_winner === true;
        return g.match && g.team_id === g.match.winning_team_id;
      }).length || 0;
      const totalKills = playerGames?.reduce((s: number, g: any) => s + (g.kills || 0), 0) || 0;
      const totalDeaths = playerGames?.reduce((s: number, g: any) => s + (g.deaths || 0), 0) || 0;
      const totalAssists = playerGames?.reduce((s: number, g: any) => s + (g.assists || 0), 0) || 0;

      // Find most played hero across all KKup matches
      let mostPlayedHero: { name: string; games: number } | null = null;
      try {
        if (playerGames && playerGames.length > 0) {
          const heroCounts: Record<string, number> = {};
          for (const g of playerGames) {
            if (g.hero) {
              heroCounts[g.hero] = (heroCounts[g.hero] || 0) + 1;
            }
          }
          const sorted = Object.entries(heroCounts).sort((a, b) => b[1] - a[1]);
          if (sorted.length > 0) {
            mostPlayedHero = { name: sorted[0][0], games: sorted[0][1] };
          }
        }
      } catch (heroErr) {
        console.error('Non-critical: most played hero lookup failed:', heroErr);
      }

      // Check for current/active tournament registration
      let currentRegistration: { tournament_id: string; tournament_name: string; status: string } | null = null;
      try {
        // Find non-archived/completed tournaments where this person is on a roster
        const activeTournaments = (tournaments || []).filter((t: any) =>
          t.status && !['completed', 'archived'].includes(t.status)
        );
        if (activeTournaments.length > 0) {
          const activeTournamentIds = activeTournaments.map((t: any) => t.id);
          // Check if on any team in an active tournament
          const { data: activeTeams } = await supabase
            .from('kkup_teams')
            .select('id, tournament_id')
            .in('tournament_id', activeTournamentIds);
          const activeTeamIds = activeTeams?.map((t: any) => t.id) || [];
          const matchingTeamIds = teamIds.filter((tid: string) => activeTeamIds.includes(tid));
          if (matchingTeamIds.length > 0) {
            const matchedTeam = activeTeams?.find((t: any) => matchingTeamIds.includes(t.id));
            if (matchedTeam) {
              const matchedTournament = activeTournaments.find((t: any) => t.id === matchedTeam.tournament_id);
              if (matchedTournament) {
                currentRegistration = {
                  tournament_id: matchedTournament.id,
                  tournament_name: matchedTournament.name || 'Active Tournament',
                  status: matchedTournament.status,
                };
              }
            }
          }
        }
      } catch (regErr) {
        console.error('Non-critical: current registration lookup failed:', regErr);
      }

      return c.json({
        linked: true,
        profile: { name: person.display_name, steam_id: person.steam_id },
        championships: { kernel_kup: kernelKupChampionships, heaps_n_hooks: heapsNHooksChampionships, total: kernelKupChampionships + heapsNHooksChampionships },
        popd_kernels: popdKernels,
        tournaments_played: uniqueTournaments.size,
        total_games: totalGames,
        wins,
        losses: totalGames - wins,
        total_kills: totalKills,
        total_deaths: totalDeaths,
        total_assists: totalAssists,
        most_played_hero: mostPlayedHero,
        current_registration: currentRegistration,
      });
    } catch (error) {
      console.error('Get user KKUP stats error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Search KKUP player profiles
  app.get(`${PREFIX}/kkup-player-profiles/search`, async (c) => {
    try {
      const query = c.req.query('q') || '';
      if (query.length < 2) return c.json({ profiles: [] });
      const { data: profiles, error } = await supabase.from('kkup_persons').select('id, display_name, steam_id').ilike('display_name', `%${query}%`).order('display_name').limit(20);
      if (error) return c.json({ error: 'Failed to search profiles' }, 500);
      return c.json({ profiles: (profiles || []).map((p: any) => ({ id: p.id, name: p.display_name, steam_id: p.steam_id })) });
    } catch (error) {
      console.error('Search KKUP profiles error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Find duplicate player profiles
  app.get(`${PREFIX}/kkup/admin/find-duplicates`, async (c) => {
    try {
      const { data: allPlayers, error } = await supabase.from('kkup_persons').select('id, display_name, steam_id, created_at').order('display_name');
      if (error) return c.json({ error: 'Failed to fetch player profiles: ' + error.message }, 500);
      const players = allPlayers || [];

      const steamIdGroups: Record<string, any[]> = {};
      const nullSteamIdPlayers: any[] = [];
      for (const p of players) {
        if (!p.steam_id) nullSteamIdPlayers.push(p);
        else { const k = String(p.steam_id); if (!steamIdGroups[k]) steamIdGroups[k] = []; steamIdGroups[k].push(p); }
      }
      const steamIdDuplicates = Object.entries(steamIdGroups).filter(([_, g]) => g.length > 1).map(([sid, g]) => ({ steam_id: sid, count: g.length, profiles: g }));

      const nameGroups: Record<string, any[]> = {};
      for (const p of players) { const n = (p.display_name || '').toLowerCase().trim(); if (!n) continue; if (!nameGroups[n]) nameGroups[n] = []; nameGroups[n].push(p); }
      const nameDuplicates = Object.entries(nameGroups).filter(([_, g]) => g.length > 1).map(([name, g]) => ({ normalized_name: name, count: g.length, profiles: g }));

      const { data: teamPlayers } = await supabase.from('kkup_team_rosters').select('person_id, team_id');
      const profileIds = new Set(players.map((p: any) => p.id));
      const orphanedTeamAssignments = (teamPlayers || []).filter((tp: any) => !profileIds.has(tp.person_id));

      return c.json({
        total_profiles: players.length,
        steam_id_duplicates: { count: steamIdDuplicates.length, groups: steamIdDuplicates },
        name_duplicates: { count: nameDuplicates.length, groups: nameDuplicates },
        null_steam_id_players: { count: nullSteamIdPlayers.length, players: nullSteamIdPlayers },
        orphaned_team_assignments: { count: orphanedTeamAssignments.length, assignments: orphanedTeamAssignments },
      });
    } catch (error) {
      console.error('Find duplicates error:', error);
      return c.json({ error: 'Internal server error: ' + String(error) }, 500);
    }
  });

  // Sync player profile by ANY Steam ID format (Account ID, Steam64, or vanity URL)
  // Normalizes input to Account ID, fetches from Steam API, updates kkup_persons
  app.post(`${PREFIX}/kkup/sync-player-by-steam-id`, async (c) => {
    try {
      if (!await requireOwner(c)) return c.json({ error: 'Owner access required' }, 403);

      const { steam_id_input } = await c.req.json();
      if (!steam_id_input) {
        return c.json({ error: 'steam_id_input is required (can be Account ID, Steam64, or vanity URL)' }, 400);
      }

      console.log(`ðŸ” Normalizing Steam ID input: "${steam_id_input}"...`);

      // Normalize ANY format to Account ID
      const accountId = await normalizeToAccountId(steam_id_input);
      if (!accountId) {
        return c.json({ 
          error: `Could not resolve Steam ID: "${steam_id_input}". Please provide a valid Account ID, Steam64, or vanity URL.`,
          examples: {
            account_id: '51579950',
            steam64: '76561198011845678',
            vanity_url: 'permasnooze'
          }
        }, 400);
      }

      console.log(`âœ… Normalized to Account ID: ${accountId}`);

      // Convert to Steam64 for API lookup
      const steam64 = steam32ToSteam64(accountId);

      // Fetch from Steam API
      const steamApiKey = Deno.env.get('STEAM_WEB_API_KEY');
      if (!steamApiKey) {
        return c.json({ error: 'STEAM_WEB_API_KEY not configured' }, 500);
      }

      const res = await fetch(
        `https://api.steampowered.com/ISteamUser/GetPlayerSummaries/v0002/?key=${steamApiKey}&steamids=${steam64}`
      );

      if (!res.ok) {
        return c.json({ error: `Steam API returned ${res.status}` }, 500);
      }

      const data = await res.json();
      const steamPlayer = data.response?.players?.[0];

      if (!steamPlayer) {
        return c.json({ 
          error: `No Steam profile found for Account ID ${accountId} (Steam64: ${steam64})`,
          account_id: accountId,
          steam64: steam64
        }, 404);
      }

      // Check if player already exists
      const { data: existing } = await supabase
        .from('kkup_persons')
        .select('*')
        .eq('steam_id', String(accountId))
        .maybeSingle();

      let personRecord;
      const playerData = {
        steam_id: String(accountId),
        display_name: steamPlayer.personaname || `Player ${accountId}`,
        avatar_url: steamPlayer.avatarfull || steamPlayer.avatarmedium || steamPlayer.avatar || null,
        steam_name: steamPlayer.personaname,
        steam_avatar: steamPlayer.avatarfull || steamPlayer.avatarmedium || steamPlayer.avatar || null,
        dotabuff_url: getDotabuffUrl(accountId),
        opendota_url: getOpendotaUrl(accountId),
        updated_at: new Date().toISOString(),
      };

      if (existing) {
        // Update existing record
        const { data: updated, error: updateError } = await supabase
          .from('kkup_persons')
          .update(playerData)
          .eq('id', existing.id)
          .select()
          .single();

        if (updateError) {
          return c.json({ error: `Failed to update player: ${updateError.message}` }, 500);
        }

        personRecord = updated;
        console.log(`âœ… Updated existing player: ${personRecord.display_name} (${accountId})`);

        try {
          await createAdminLog({
            type: 'player_sync',
            action: `Synced player "${personRecord.display_name}" (${accountId}) from Steam`,
            actor_name: 'Owner',
          });
        } catch (_) {}

        return c.json({
          success: true,
          action: 'updated',
          player: {
            id: personRecord.id,
            steam_id: personRecord.steam_id,
            display_name: personRecord.display_name,
            avatar_url: personRecord.avatar_url,
            dotabuff_url: personRecord.dotabuff_url,
            opendota_url: personRecord.opendota_url,
            steam_profile_url: getSteamProfileUrl(accountId),
          },
          steam_data: {
            account_id: accountId,
            steam64: steam64,
            personaname: steamPlayer.personaname,
            profileurl: steamPlayer.profileurl,
          },
        });
      } else {
        // Create new record
        const { data: created, error: createError } = await supabase
          .from('kkup_persons')
          .insert(playerData)
          .select()
          .single();

        if (createError) {
          return c.json({ error: `Failed to create player: ${createError.message}` }, 500);
        }

        personRecord = created;
        console.log(`âœ… Created new player: ${personRecord.display_name} (${accountId})`);

        try {
          await createAdminLog({
            type: 'player_sync',
            action: `Created new player "${personRecord.display_name}" (${accountId}) from Steam`,
            actor_name: 'Owner',
          });
        } catch (_) {}

        return c.json({
          success: true,
          action: 'created',
          player: {
            id: personRecord.id,
            steam_id: personRecord.steam_id,
            display_name: personRecord.display_name,
            avatar_url: personRecord.avatar_url,
            dotabuff_url: personRecord.dotabuff_url,
            opendota_url: personRecord.opendota_url,
            steam_profile_url: getSteamProfileUrl(accountId),
          },
          steam_data: {
            account_id: accountId,
            steam64: steam64,
            personaname: steamPlayer.personaname,
            profileurl: steamPlayer.profileurl,
          },
        });
      }
    } catch (error: any) {
      console.error('Sync player by Steam ID error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

}

/**
 * KKUP Write Routes -- mutations for tournaments
 * 
 * Legacy award routes (award-championship, award-popd-kernel) are deprecated.
 * All prize/award operations now go through POST /connect/award-batch in routes-connect.ts.
 */
import type { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import { isOfficer } from "./roles.ts";
import * as kv from "./kv_store.tsx";

export function registerKkupWriteRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // Update tournament details (Owner only)
  app.patch(`${PREFIX}/kkup/:kkup_id/update`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('role').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (dbUser.role !== 'owner') return c.json({ error: 'Only owners can update tournaments' }, 403);

      const kkupId = c.req.param('kkup_id');
      const body = await c.req.json();

      const { data: tournament, error: updateError } = await supabase
        .from('kkup_tournaments')
        .update({
          cover_photo_url: body.cover_photo_url,
          prize_pool: body.prize_pool,
          description: body.description,
          updated_at: new Date().toISOString(),
        })
        .eq('id', kkupId).select().single();

      if (updateError) {
        console.error('Update error:', updateError);
        return c.json({ error: 'Failed to update tournament' }, 500);
      }

      return c.json({ success: true, tournament, message: 'Tournament updated successfully' });
    } catch (error: any) {
      console.error('Update tournament error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // DEPRECATED â€” use POST /connect/award-batch with role='champion' instead
  app.post(`${PREFIX}/kkup/award-championship`, async (c) => {
    return c.json({ error: 'Deprecated: Use POST /connect/award-batch with role="champion" instead.' }, 410);
  });

  // DEPRECATED â€” use POST /connect/award-batch with role='popd_kernel' instead
  app.post(`${PREFIX}/kkup/award-popd-kernel`, async (c) => {
    return c.json({ error: 'Deprecated: Use POST /connect/award-batch with role="popd_kernel" instead.' }, 410);
  });

  // DEPRECATED â€” achievements system removed
  app.post(`${PREFIX}/kkup/achievements/award`, async (c) => {
    return c.json({ error: 'Achievements are deprecated. Use POST /connect/award-batch instead.' }, 410);
  });

  // DEPRECATED â€” achievements system removed
  app.delete(`${PREFIX}/kkup/achievements/:achievement_id`, async (c) => {
    return c.json({ error: 'Achievements are deprecated. Use POST /connect/award-batch instead.' }, 410);
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // PRIZE CONFIG â€” per-tournament prize pool structure
  // Stored in KV: tournament_prize_config:{tournament_id}
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  // GET prize config for a tournament (public)
  app.get(`${PREFIX}/kkup/:kkup_id/prize-config`, async (c) => {
    try {
      const kkupId = c.req.param('kkup_id');
      const kvKey = `tournament_prize_config:${kkupId}`;
      const stored = await kv.get(kvKey);
      if (!stored) return c.json({ config: null });
      const config = typeof stored === 'string' ? JSON.parse(stored) : stored;
      return c.json({ config });
    } catch (error: any) {
      console.error('Get prize config error:', error);
      return c.json({ error: 'Failed to fetch prize config: ' + error.message }, 500);
    }
  });

  // PUT prize config for a tournament (officer-only)
  app.put(`${PREFIX}/kkup/:kkup_id/prize-config`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser } = await supabase
        .from('users').select('role').eq('supabase_id', authUser.id).single();
      if (!dbUser || !isOfficer(dbUser.role)) return c.json({ error: 'Officer access required' }, 403);

      const kkupId = c.req.param('kkup_id');
      const body = await c.req.json();

      if (!body.categories || !Array.isArray(body.categories)) {
        return c.json({ error: 'Invalid config: categories array required' }, 400);
      }

      // Validate each category
      for (const cat of body.categories) {
        if (!cat.key || !cat.label || typeof cat.amount_cents !== 'number') {
          return c.json({ error: `Invalid category: key, label, and amount_cents required. Got: ${JSON.stringify(cat)}` }, 400);
        }
      }

      const kvKey = `tournament_prize_config:${kkupId}`;
      await kv.set(kvKey, JSON.stringify(body));

      // Also update the tournament's prize_pool total (in dollars) for display
      const totalCents = body.categories.reduce((sum: number, c: any) => sum + (c.amount_cents || 0), 0);
      await supabase
        .from('kkup_tournaments')
        .update({ prize_pool: (totalCents / 100).toFixed(2) })
        .eq('id', kkupId);

      console.log(`Prize config saved for tournament ${kkupId}: ${body.categories.length} categories, total $${(totalCents / 100).toFixed(2)}`);
      return c.json({ success: true, message: 'Prize config saved' });
    } catch (error: any) {
      console.error('Save prize config error:', error);
      return c.json({ error: 'Failed to save prize config: ' + error.message }, 500);
    }
  });

}

/**
 * Leaderboard Route -- ranked member listing with KKUP stats
 * 1 route: GET /leaderboard
 */
import type { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";

export function registerLeaderboardRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // Get leaderboard (all authenticated users)
  app.get(`${PREFIX}/leaderboard`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('role').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);

      // Get all users (all authenticated roles)
      const { data: users, error: usersError } = await supabase
        .from('users')
        .select(`
          id, discord_username, discord_avatar, discord_id, rank_id, prestige_level,
          role, created_at, steam_id, opendota_data, tcf_plus_active, twitch_username, twitch_avatar,
          guild_id,
          ranks ( id, name, display_order ),
          guild:guild_wars_guilds!users_guild_id_fkey ( id, name, tag, color, logo_url )
        `);

      if (usersError) {
        console.error('Error fetching leaderboard:', usersError);
        return c.json({ error: 'Failed to fetch leaderboard' }, 500);
      }

      // Compute KKUP stats for each user via steam_id â†’ kkup_persons join
      const steamIds = (users || []).map((u: any) => u.steam_id).filter(Boolean);
      const userStatsMap: Record<string, { linked: boolean; championships: number; popdKernels: number }> = {};

      if (steamIds.length > 0) {
        // Find all kkup_persons matched by steam_id
        const { data: persons } = await supabase
          .from('kkup_persons')
          .select('id, steam_id')
          .in('steam_id', steamIds);

        if (persons && persons.length > 0) {
          const personBySteamId = new Map<string, string>();
          const personIds: string[] = [];
          for (const p of persons) {
            personBySteamId.set(p.steam_id, p.id);
            personIds.push(p.id);
          }

          // Get all team rosters for matched persons
          const { data: rosters } = await supabase
            .from('kkup_team_rosters')
            .select('person_id, team_id')
            .in('person_id', personIds);

          // Build person_id â†’ team_ids map
          const personTeams = new Map<string, string[]>();
          (rosters || []).forEach((r: any) => {
            if (!personTeams.has(r.person_id)) personTeams.set(r.person_id, []);
            personTeams.get(r.person_id)!.push(r.team_id);
          });

          // Get all tournaments for championship & MVP lookups
          const { data: tournaments } = await supabase
            .from('kkup_tournaments')
            .select('id, winning_team_id, tournament_type, popd_kernel_1_person_id, popd_kernel_2_person_id');

          // For each user, compute stats
          for (const u of (users || [])) {
            if (!u.steam_id || !personBySteamId.has(u.steam_id)) {
              userStatsMap[u.id] = { linked: false, championships: 0, popdKernels: 0 };
              continue;
            }

            const personId = personBySteamId.get(u.steam_id)!;
            const teamIds = personTeams.get(personId) || [];

            let champs = 0;
            let popdK = 0;

            (tournaments || []).forEach((t: any) => {
              if (t.winning_team_id && teamIds.includes(t.winning_team_id)) champs++;
              if (t.popd_kernel_1_person_id === personId) popdK++;
              if (t.popd_kernel_2_person_id === personId) popdK++;
            });

            userStatsMap[u.id] = { linked: true, championships: champs, popdKernels: popdK };
          }
        }
      }

      // Fill in any users not yet in the map
      for (const u of (users || [])) {
        if (!userStatsMap[u.id]) {
          userStatsMap[u.id] = { linked: false, championships: 0, popdKernels: 0 };
        }
      }

      // Sort: prestige DESC > rank DESC > championships DESC > pop'd kernels DESC > badge DESC > created ASC
      const sortedUsers = [...(users || [])].sort((a: any, b: any) => {
        const prestigeDiff = (b.prestige_level || 0) - (a.prestige_level || 0);
        if (prestigeDiff !== 0) return prestigeDiff;

        const rankDiff = (b.rank_id || 0) - (a.rank_id || 0);
        if (rankDiff !== 0) return rankDiff;

        const champDiff = (userStatsMap[b.id]?.championships || 0) - (userStatsMap[a.id]?.championships || 0);
        if (champDiff !== 0) return champDiff;

        const popdDiff = (userStatsMap[b.id]?.popdKernels || 0) - (userStatsMap[a.id]?.popdKernels || 0);
        if (popdDiff !== 0) return popdDiff;

        const badgeDiff = (b.opendota_data?.badge_rank?.rank_tier || 0) - (a.opendota_data?.badge_rank?.rank_tier || 0);
        if (badgeDiff !== 0) return badgeDiff;

        return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
      });

      // Attach KKUP stats to each user
      const usersWithStats = sortedUsers.map((u: any) => ({
        ...u,
        kkup_stats: {
          linked: userStatsMap[u.id]?.linked || false,
          championships: userStatsMap[u.id]?.championships || 0,
          popd_kernels: userStatsMap[u.id]?.popdKernels || 0,
        }
      }));

      return c.json({ users: usersWithStats });
    } catch (error) {
      console.error('Get leaderboard error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

}

/**
 * Master Teams Routes â€” Canonical team identity registry
 *
 * 8 routes:
 *   GET    /kkup/persons/by-steam/:steam_id â€” Resolve steam_id to kkup_persons (officer)
 *   GET    /master-teams                  â€” List all master teams (public)
 *   GET    /master-teams/mine             â€” My teams (by authenticated user's person_id)
 *   GET    /master-teams/:id              â€” Single team with tournament history
 *   POST   /master-teams                  â€” Create new master team (authenticated)
 *   PATCH  /master-teams/:id              â€” Edit team identity (captain or officer)
 *   POST   /master-teams/:id/transfer     â€” Transfer captaincy (captain or officer)
 *   DELETE /master-teams/:id              â€” Delete team (only if zero tournament appearances)
 *
 * Table: kkup_master_teams (canonical identity)
 * Linked: kkup_teams.master_team_id (per-tournament snapshots)
 */
import type { Hono } from "npm:hono";
import { PREFIX } from './helpers.ts';
import { createAdminLog, createUserActivity } from './routes-notifications.ts';
import { isOfficer } from './roles.ts';

export function registerMasterTeamsRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // AUTH HELPER
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  async function requireAuth(c: any): Promise<{ ok: true; authUser: any; dbUser: any } | { ok: false; response: any }> {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return { ok: false, response: c.json({ error: 'No access token provided' }, 401) };
    const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
    if (authError || !authUser) return { ok: false, response: c.json({ error: 'Unauthorized â€” invalid or expired token' }, 401) };
    const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', authUser.id).single();
    if (!dbUser) return { ok: false, response: c.json({ error: 'User not found in database' }, 404) };
    return { ok: true, authUser, dbUser };
  }

  /** Resolve a users row â†’ kkup_persons row via steam_id */
  async function resolvePersonForUser(dbUser: any): Promise<{ person: any } | { error: string }> {
    if (dbUser.steam_id) {
      const { data: person } = await supabase
        .from('kkup_persons').select('*').eq('steam_id', dbUser.steam_id).maybeSingle();
      if (person) return { person };
    }
    return { error: 'No linked Steam identity found. Link your Steam account first.' };
  }

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // GET /kkup/persons/by-steam/:steam_id â€” Resolve steam_id to kkup_persons record
  // Used by officer transfer captaincy flow
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/kkup/persons/by-steam/:steam_id`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      if (!isOfficer(auth.dbUser.role)) {
        return c.json({ error: 'Officers only' }, 403);
      }

      const steamId = c.req.param('steam_id');
      if (!steamId) return c.json({ error: 'steam_id is required' }, 400);

      const { data: person, error } = await supabase
        .from('kkup_persons')
        .select('id, display_name, steam_id, avatar_url')
        .eq('steam_id', steamId)
        .maybeSingle();

      if (error) return c.json({ error: `Lookup failed: ${error.message}` }, 500);
      if (!person) return c.json({ error: `No Kernel Kup person found with Steam ID ${steamId}` }, 404);

      return c.json({ person });
    } catch (err) {
      console.error('Error looking up person by steam_id:', err);
      return c.json({ error: `Unexpected error: ${err}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // GET /master-teams â€” List all (public, with tournament count)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/master-teams`, async (c) => {
    try {
      const { data: masterTeams, error } = await supabase
        .from('kkup_master_teams')
        .select(`
          *,
          captain:kkup_persons!current_captain_person_id (
            id,
            display_name
          )
        `)
        .order('current_name', { ascending: true });

      if (error) return c.json({ error: `Failed to fetch master teams: ${error.message}` }, 500);

      // Count tournament appearances per master team
      const { data: teamLinks } = await supabase
        .from('kkup_teams')
        .select('master_team_id, tournament_id');

      const countsMap = new Map<string, number>();
      (teamLinks || []).forEach((t: any) => {
        if (t.master_team_id) {
          countsMap.set(t.master_team_id, (countsMap.get(t.master_team_id) || 0) + 1);
        }
      });

      const enriched = (masterTeams || []).map((mt: any) => ({
        ...mt,
        tournament_count: countsMap.get(mt.id) || 0,
        // captain is already populated via join
      }));

      return c.json({ master_teams: enriched });
    } catch (err) {
      console.error('Error listing master teams:', err);
      return c.json({ error: `Unexpected error listing master teams: ${err}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // GET /master-teams/mine â€” My teams (authenticated)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/master-teams/mine`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const personResult = await resolvePersonForUser(auth.dbUser);
      if ('error' in personResult) return c.json({ error: personResult.error }, 400);

      const personId = personResult.person.id;

      // Teams where user is captain
      const { data: myTeams, error } = await supabase
        .from('kkup_master_teams')
        .select('*')
        .eq('current_captain_person_id', personId)
        .order('current_name', { ascending: true });

      if (error) return c.json({ error: `Failed to fetch your teams: ${error.message}` }, 500);

      // Enrich with tournament counts
      const masterIds = (myTeams || []).map((t: any) => t.id);
      let countsMap = new Map<string, number>();

      if (masterIds.length > 0) {
        const { data: teamLinks } = await supabase
          .from('kkup_teams')
          .select('master_team_id, tournament_id')
          .in('master_team_id', masterIds);

        (teamLinks || []).forEach((t: any) => {
          if (t.master_team_id) {
            countsMap.set(t.master_team_id, (countsMap.get(t.master_team_id) || 0) + 1);
          }
        });
      }

      const enriched = (myTeams || []).map((mt: any) => ({
        ...mt,
        tournament_count: countsMap.get(mt.id) || 0,
      }));

      return c.json({ master_teams: enriched, person_id: personId });
    } catch (err) {
      console.error('Error fetching my teams:', err);
      return c.json({ error: `Unexpected error fetching your teams: ${err}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // GET /master-teams/:id â€” Single team with full history
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/master-teams/:id`, async (c) => {
    try {
      const id = c.req.param('id');
      if (!id) return c.json({ error: 'Master team ID is required' }, 400);

      // Don't match the /mine route
      if (id === 'mine') return;

      const { data: masterTeam, error } = await supabase
        .from('kkup_master_teams')
        .select('*')
        .eq('id', id)
        .single();

      if (error || !masterTeam) return c.json({ error: `Master team not found: ${id}` }, 404);

      // Get all tournament appearances
      const { data: tournamentTeams } = await supabase
        .from('kkup_teams')
        .select('id, tournament_id, team_name, team_tag, logo_url, valve_team_id, approval_status, captain_person_id, coach_person_id, created_at')
        .eq('master_team_id', id)
        .order('created_at', { ascending: false });

      // Get tournament details for those appearances
      const tournamentIds = [...new Set((tournamentTeams || []).map((t: any) => t.tournament_id).filter(Boolean))];
      let tournaments: any[] = [];
      if (tournamentIds.length > 0) {
        const { data } = await supabase
          .from('kkup_tournaments')
          .select('id, name, status, tournament_type, winning_team_id, start_date, end_date')
          .in('id', tournamentIds);
        tournaments = data || [];
      }

      const tournamentMap = new Map(tournaments.map((t: any) => [t.id, t]));

      // Enrich tournament appearances
      const appearances = (tournamentTeams || []).map((tt: any) => {
        const tournament = tournamentMap.get(tt.tournament_id);
        return {
          ...tt,
          tournament_name: tournament?.name || 'Unknown',
          tournament_status: tournament?.status || 'unknown',
          tournament_type: tournament?.tournament_type || 'kernel_kup',
          is_champion: tournament?.winning_team_id === tt.id,
          start_date: tournament?.start_date,
          end_date: tournament?.end_date,
        };
      });

      // Get captain person info
      let captain = null;
      if (masterTeam.current_captain_person_id) {
        const { data: captainPerson } = await supabase
          .from('kkup_persons')
          .select('id, display_name, steam_id, avatar_url')
          .eq('id', masterTeam.current_captain_person_id)
          .single();
        captain = captainPerson;
      }

      return c.json({
        master_team: masterTeam,
        captain,
        appearances,
        tournament_count: appearances.length,
        championships: appearances.filter((a: any) => a.is_champion).length,
      });
    } catch (err) {
      console.error('Error fetching master team detail:', err);
      return c.json({ error: `Unexpected error fetching master team: ${err}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // POST /master-teams â€” Create new master team
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/master-teams`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const personResult = await resolvePersonForUser(auth.dbUser);
      if ('error' in personResult) return c.json({ error: personResult.error }, 400);

      const body = await c.req.json();
      const { name, tag, description, logo_url, valve_team_id } = body;

      if (!name || !name.trim()) return c.json({ error: 'Team name is required' }, 400);
      if (!tag || !tag.trim()) return c.json({ error: 'Team tag is required' }, 400);

      const personId = personResult.person.id;

      // â”€â”€ Team limit: Free = 1, TCF+ = 20 â”€â”€
      const isTcfPlus = !!auth.dbUser.tcf_plus_active;
      const TEAM_LIMIT = isTcfPlus ? 20 : 1;
      const { data: existingTeams, error: countErr } = await supabase
        .from('kkup_master_teams')
        .select('id')
        .eq('current_captain_person_id', personId);

      if (countErr) return c.json({ error: `Failed to check team count: ${countErr.message}` }, 500);

      if ((existingTeams || []).length >= TEAM_LIMIT) {
        return c.json({
          error: isTcfPlus
            ? `You've reached the TCF+ limit of ${TEAM_LIMIT} teams.`
            : `Free accounts can only create ${TEAM_LIMIT} team. Upgrade to TCF+ for up to 20 teams.`,
          code: 'TEAM_LIMIT_REACHED',
          limit: TEAM_LIMIT,
          is_tcf_plus: isTcfPlus,
        }, 403);
      }

      // Check for duplicate (case-insensitive) â€” the DB constraint will catch this too,
      // but we give a friendlier error message
      const { data: existing } = await supabase
        .from('kkup_master_teams')
        .select('id, current_name, current_tag')
        .ilike('current_name', name.trim())
        .ilike('current_tag', tag.trim())
        .maybeSingle();

      if (existing) {
        return c.json({
          error: `A team with name "${existing.current_name}" and tag "${existing.current_tag}" already exists.`,
        }, 409);
      }

      const { data: newTeam, error } = await supabase
        .from('kkup_master_teams')
        .insert({
          current_name: name.trim(),
          current_tag: tag.trim(),
          description: description?.trim() || null,
          current_logo_url: logo_url || null,
          valve_team_id: valve_team_id || null,
          current_captain_person_id: personId,
          created_by_person_id: personId,
          status: 'active',
          name_history: [],
          captain_history: [],
        })
        .select()
        .single();

      if (error) {
        // Handle unique constraint violation
        if (error.code === '23505') {
          return c.json({ error: `A team with that name and tag already exists (case-insensitive).` }, 409);
        }
        return c.json({ error: `Failed to create master team: ${error.message}` }, 500);
      }

      // Log activity
      try {
        await createUserActivity({
          user_id: auth.dbUser.supabase_id,
          type: 'master_team_created',
          title: `Created team "${name.trim()}"`,
          description: `Registered new team identity: ${name.trim()} [${tag.trim()}]`,
          actor_name: auth.dbUser.discord_username || auth.dbUser.email,
        });
      } catch (actErr) {
        console.error('Non-critical: activity log for master team creation failed:', actErr);
      }

      return c.json({ master_team: newTeam }, 201);
    } catch (err) {
      console.error('Error creating master team:', err);
      return c.json({ error: `Unexpected error creating master team: ${err}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // PATCH /master-teams/:id â€” Edit team identity
  // Allowed: captain of the team, or officers/owner
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/master-teams/:id`, async (c) => {
    try {
      const id = c.req.param('id');
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      // Fetch current master team
      const { data: masterTeam, error: fetchErr } = await supabase
        .from('kkup_master_teams')
        .select('*')
        .eq('id', id)
        .single();

      if (fetchErr || !masterTeam) return c.json({ error: `Master team not found: ${id}` }, 404);

      // Permission check: captain or officer
      const personResult = await resolvePersonForUser(auth.dbUser);
      const personId = 'error' in personResult ? null : personResult.person.id;
      const isCaptain = personId && masterTeam.current_captain_person_id === personId;
      const isOfficerUser = isOfficer(auth.dbUser.role);

      if (!isCaptain && !isOfficerUser) {
        return c.json({ error: 'Only the team captain or officers can edit team identity' }, 403);
      }

      const body = await c.req.json();
      const updates: Record<string, any> = {};
      const changes: string[] = [];

      // Name change â€” log to history
      if (body.name !== undefined && body.name.trim() && body.name.trim() !== masterTeam.current_name) {
        // Check duplicate
        const { data: dupe } = await supabase
          .from('kkup_master_teams')
          .select('id')
          .ilike('current_name', body.name.trim())
          .ilike('current_tag', body.tag?.trim() || masterTeam.current_tag)
          .neq('id', id)
          .maybeSingle();

        if (dupe) return c.json({ error: 'A team with that name and tag already exists.' }, 409);

        const nameHistory = [...(masterTeam.name_history || []), {
          from_name: masterTeam.current_name,
          from_tag: masterTeam.current_tag,
          to_name: body.name.trim(),
          to_tag: body.tag?.trim() || masterTeam.current_tag,
          changed_at: new Date().toISOString(),
          changed_by: auth.dbUser.discord_username || auth.dbUser.email,
        }];

        updates.current_name = body.name.trim();
        updates.name_history = nameHistory;
        changes.push(`name: "${masterTeam.current_name}" â†’ "${body.name.trim()}"`);
      }

      // Tag change
      if (body.tag !== undefined && body.tag.trim() && body.tag.trim() !== masterTeam.current_tag) {
        if (!updates.name_history) {
          // Tag-only change, still log it
          const nameHistory = [...(masterTeam.name_history || []), {
            from_name: masterTeam.current_name,
            from_tag: masterTeam.current_tag,
            to_name: updates.current_name || masterTeam.current_name,
            to_tag: body.tag.trim(),
            changed_at: new Date().toISOString(),
            changed_by: auth.dbUser.discord_username || auth.dbUser.email,
          }];
          updates.name_history = nameHistory;
        }
        updates.current_tag = body.tag.trim();
        changes.push(`tag: "${masterTeam.current_tag}" â†’ "${body.tag.trim()}"`);
      }

      // Logo
      if (body.logo_url !== undefined) {
        updates.current_logo_url = body.logo_url || null;
        if (body.logo_url !== masterTeam.current_logo_url) changes.push('logo updated');
      }

      // Description
      if (body.description !== undefined) {
        updates.description = body.description?.trim() || null;
        if (body.description?.trim() !== masterTeam.description) changes.push('description updated');
      }

      // Valve team ID
      if (body.valve_team_id !== undefined) {
        updates.valve_team_id = body.valve_team_id || null;
        changes.push('valve_team_id updated');
      }

      if (Object.keys(updates).length === 0) {
        return c.json({ message: 'No changes to apply' });
      }

      updates.updated_at = new Date().toISOString();

      const { data: updated, error: updateErr } = await supabase
        .from('kkup_master_teams')
        .update(updates)
        .eq('id', id)
        .select()
        .single();

      if (updateErr) return c.json({ error: `Failed to update master team: ${updateErr.message}` }, 500);

      // Log activity
      const changeStr = changes.join(', ');
      try {
        await createUserActivity({
          user_id: auth.dbUser.supabase_id,
          type: 'master_team_edited',
          title: `Edited team "${updated.current_name}"`,
          description: `Changes: ${changeStr}`,
          actor_name: auth.dbUser.discord_username || auth.dbUser.email,
        });
      } catch (actErr) {
        console.error('Non-critical: activity log for master team edit failed:', actErr);
      }

      // If officer edited someone else's team, also log to admin log
      if (isOfficerUser && !isCaptain) {
        try {
          await createAdminLog({
            type: 'master_team_edited',
            action: `Edited master team "${updated.current_name}" [${updated.current_tag}]: ${changeStr}`,
            actor_id: auth.dbUser.supabase_id,
            actor_name: auth.dbUser.discord_username || auth.dbUser.email,
          });
        } catch (logErr) {
          console.error('Non-critical: admin log for master team edit failed:', logErr);
        }
      }

      return c.json({ master_team: updated });
    } catch (err) {
      console.error('Error editing master team:', err);
      return c.json({ error: `Unexpected error editing master team: ${err}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // POST /master-teams/:id/transfer â€” Transfer captaincy
  // Allowed: current captain or officers/owner
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/master-teams/:id/transfer`, async (c) => {
    try {
      const id = c.req.param('id');
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const { data: masterTeam, error: fetchErr } = await supabase
        .from('kkup_master_teams')
        .select('*')
        .eq('id', id)
        .single();

      if (fetchErr || !masterTeam) return c.json({ error: `Master team not found: ${id}` }, 404);

      // Permission: captain or officer
      const personResult = await resolvePersonForUser(auth.dbUser);
      const personId = 'error' in personResult ? null : personResult.person.id;
      const isCaptain = personId && masterTeam.current_captain_person_id === personId;
      const isOfficerUser = isOfficer(auth.dbUser.role);

      if (!isCaptain && !isOfficerUser) {
        return c.json({ error: 'Only the team captain or officers can transfer captaincy' }, 403);
      }

      const body = await c.req.json();
      const { new_captain_person_id } = body;

      if (!new_captain_person_id) return c.json({ error: 'new_captain_person_id is required' }, 400);

      // Verify new captain exists
      const { data: newCaptain } = await supabase
        .from('kkup_persons')
        .select('id, display_name')
        .eq('id', new_captain_person_id)
        .single();

      if (!newCaptain) return c.json({ error: 'New captain person not found' }, 404);

      // Get old captain name for history
      let oldCaptainName = 'Unknown';
      if (masterTeam.current_captain_person_id) {
        const { data: oldCaptain } = await supabase
          .from('kkup_persons')
          .select('display_name')
          .eq('id', masterTeam.current_captain_person_id)
          .single();
        if (oldCaptain) oldCaptainName = oldCaptain.display_name;
      }

      // Update captain history
      const captainHistory = [...(masterTeam.captain_history || []), {
        from_person_id: masterTeam.current_captain_person_id,
        from_name: oldCaptainName,
        to_person_id: new_captain_person_id,
        to_name: newCaptain.display_name,
        transferred_at: new Date().toISOString(),
        transferred_by: auth.dbUser.discord_username || auth.dbUser.email,
      }];

      const { data: updated, error: updateErr } = await supabase
        .from('kkup_master_teams')
        .update({
          current_captain_person_id: new_captain_person_id,
          captain_history: captainHistory,
          updated_at: new Date().toISOString(),
        })
        .eq('id', id)
        .select()
        .single();

      if (updateErr) return c.json({ error: `Failed to transfer captaincy: ${updateErr.message}` }, 500);

      // Propagate change to active tournament teams
      // Mutable statuses from team-formation: upcoming, registration_open, registration_closed
      try {
        const { data: activeTournaments } = await supabase
          .from('kkup_tournaments')
          .select('id')
          .in('status', ['upcoming', 'registration_open', 'registration_closed']);
        
        const activeTourneyIds = (activeTournaments || []).map((t: any) => t.id);
        
        if (activeTourneyIds.length > 0) {
          const { error: teamUpdateErr } = await supabase
            .from('kkup_teams')
            .update({ captain_person_id: new_captain_person_id })
            .eq('master_team_id', id)
            .in('tournament_id', activeTourneyIds);
          
          if (teamUpdateErr) {
            console.error('Failed to propagate captaincy change to tournament teams:', teamUpdateErr);
          }
        }
      } catch (propErr) {
        console.error('Non-critical: Propagation of captaincy failed:', propErr);
      }

      // Log: activity on actor
      try {
        await createUserActivity({
          user_id: auth.dbUser.supabase_id,
          type: 'master_team_captain_transferred',
          title: `Transferred captaincy of "${masterTeam.current_name}"`,
          description: `Captain transferred from ${oldCaptainName} to ${newCaptain.display_name}.`,
          actor_name: auth.dbUser.discord_username || auth.dbUser.email,
        });

        await createAdminLog({
          type: 'captain_transferred',
          action: `Transferred captaincy of "${masterTeam.current_name}" from ${oldCaptainName} to ${newCaptain.display_name}`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username || auth.dbUser.email,
          details: {
            master_team_id: id,
            from_person_id: masterTeam.current_captain_person_id,
            to_person_id: new_captain_person_id,
          },
        });
      } catch (actErr) {
        console.error('Non-critical: activity log for captain transfer failed:', actErr);
      }

      // Notify the new captain (find their supabase user)
      try {
        // Resolve person â†’ user via steam_id
        const { data: newCaptainPerson } = await supabase
          .from('kkup_persons')
          .select('steam_id')
          .eq('id', new_captain_person_id)
          .single();

        if (newCaptainPerson?.steam_id) {
          const { data: newCaptainUser } = await supabase
            .from('users')
            .select('supabase_id')
            .eq('steam_id', newCaptainPerson.steam_id)
            .maybeSingle();

          if (newCaptainUser) {
            const { createNotification } = await import('./routes-notifications.ts');
            await createNotification({
              user_id: newCaptainUser.supabase_id,
              type: 'master_team_captain_received',
              title: `You are now captain of "${masterTeam.current_name}"`,
              body: `${auth.dbUser.discord_username || 'Someone'} transferred captaincy of ${masterTeam.current_name} [${masterTeam.current_tag}] to you.`,
              actor_name: auth.dbUser.discord_username || auth.dbUser.email,
            });
          }
        }
      } catch (notifErr) {
        console.error('Non-critical: notification for captain transfer failed:', notifErr);
      }

      // Admin log if officer did it
      if (isOfficerUser && !isCaptain) {
        try {
          await createAdminLog({
            type: 'master_team_captain_transferred',
            action: `Transferred captaincy of "${masterTeam.current_name}" from ${oldCaptainName} to ${newCaptain.display_name}`,
            actor_id: auth.dbUser.supabase_id,
            actor_name: auth.dbUser.discord_username || auth.dbUser.email,
          });
        } catch (logErr) {
          console.error('Non-critical: admin log for captain transfer failed:', logErr);
        }
      }

      return c.json({ master_team: updated, new_captain: newCaptain });
    } catch (err) {
      console.error('Error transferring captaincy:', err);
      return c.json({ error: `Unexpected error transferring captaincy: ${err}` }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // DELETE /master-teams/:id â€” Delete team
  // Only allowed if ZERO tournament appearances
  // Captain or officer can delete
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.delete(`${PREFIX}/master-teams/:id`, async (c) => {
    try {
      const id = c.req.param('id');
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const { data: masterTeam, error: fetchErr } = await supabase
        .from('kkup_master_teams')
        .select('*')
        .eq('id', id)
        .single();

      if (fetchErr || !masterTeam) return c.json({ error: `Master team not found: ${id}` }, 404);

      // Permission: captain or officer
      const personResult = await resolvePersonForUser(auth.dbUser);
      const personId = 'error' in personResult ? null : personResult.person.id;
      const isCaptain = personId && masterTeam.current_captain_person_id === personId;
      const isOfficerUser = isOfficer(auth.dbUser.role);

      if (!isCaptain && !isOfficerUser) {
        return c.json({ error: 'Only the team captain or officers can delete a team' }, 403);
      }

      // Check for tournament appearances â€” block deletion if any exist
      const { data: appearances, error: appErr } = await supabase
        .from('kkup_teams')
        .select('id')
        .eq('master_team_id', id)
        .limit(1);

      if (appErr) return c.json({ error: `Failed to check tournament history: ${appErr.message}` }, 500);

      if (appearances && appearances.length > 0) {
        return c.json({
          error: `Cannot delete "${masterTeam.current_name}" â€” it has tournament history. Teams with history are preserved for the record books. You can edit the team identity instead.`,
        }, 409);
      }

      // Safe to delete â€” no tournament appearances
      const { error: deleteErr } = await supabase
        .from('kkup_master_teams')
        .delete()
        .eq('id', id);

      if (deleteErr) return c.json({ error: `Failed to delete master team: ${deleteErr.message}` }, 500);

      // Log activity
      try {
        await createUserActivity({
          user_id: auth.dbUser.supabase_id,
          type: 'master_team_deleted',
          title: `Deleted team "${masterTeam.current_name}"`,
          description: `Removed team identity: ${masterTeam.current_name} [${masterTeam.current_tag}]`,
          actor_name: auth.dbUser.discord_username || auth.dbUser.email,
        });
      } catch (actErr) {
        console.error('Non-critical: activity log for master team deletion failed:', actErr);
      }

      return c.json({ success: true, message: `Team "${masterTeam.current_name}" deleted.` });
    } catch (err) {
      console.error('Error deleting master team:', err);
      return c.json({ error: `Unexpected error deleting master team: ${err}` }, 500);
    }
  });
}

/**
 * MVP / Rank Routes -- submit screenshots, admin approve/deny, rank up/down, prestige
 * 7 routes + 3 Discord helper functions
 */
import type { Hono } from "npm:hono";
import * as kv from "./kv_store.tsx";
import { buildPendingMVPEmbed, buildResolvedMVPEmbed } from "./discord-embeds.tsx";
import { PREFIX } from "./helpers.ts";
import { isOfficer } from "./roles.ts";
import { createNotification, createAdminLog, createUserActivity } from "./routes-notifications.ts";
import { DISCORD_WEBHOOKS } from "./discord-config.ts";
import { syncDiscordUserRoles } from "./discord-api.ts";

export function registerMVPRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ Discord helper: update bot-submitted message on approve/deny â”€â”€
  async function updateDiscordMVPMessage(requestId: string, status: 'approved' | 'denied', reviewerUsername: string) {
    try {
      const { data: request, error: requestError } = await supabase
        .from('rank_up_requests')
        .select(`discord_message_id, discord_channel_id, action, match_id, screenshot_url,
          users!rank_up_requests_user_id_fkey(discord_id, discord_username, rank_id, prestige_level),
          target_user:users!rank_up_requests_target_user_id_fkey(discord_id, discord_username, rank_id, prestige_level, ranks(name))`)
        .eq('id', requestId).single();

      if (requestError || !request || !request.discord_message_id || !request.discord_channel_id) return;

      const botToken = Deno.env.get('DISCORD_BOT_TOKEN');
      if (!botToken) return;

      const submitter = request.users;
      const targetUser = request.target_user || request.users;

      let imageUrl = '';
      if (request.screenshot_url) {
        const { data: signedUrlData } = await supabase.storage
          .from('make-4789f4af-mvp-screenshots').createSignedUrl(request.screenshot_url, 60 * 60 * 24 * 7);
        imageUrl = signedUrlData?.signedUrl || '';
      }

      const { embed: updatedEmbed } = buildResolvedMVPEmbed(
        submitter?.discord_id || null, submitter?.discord_username || 'Unknown User',
        targetUser?.discord_id || null, targetUser?.discord_username || 'Unknown User',
        request.action || 'rank_up', request.match_id || null, imageUrl, status, reviewerUsername,
        (targetUser as any)?.ranks?.name,
      );

      const response = await fetch(
        `https://discord.com/api/v10/channels/${request.discord_channel_id}/messages/${request.discord_message_id}`,
        { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'Authorization': `Bot ${botToken}` },
          body: JSON.stringify({ embeds: [updatedEmbed] }) }
      );
      if (!response.ok) console.error('Failed to update Discord message:', await response.text());
    } catch (error) {
      console.error('Error updating Discord message:', error);
    }
  }

  // â”€â”€ Discord helper: update webhook-submitted message on approve/deny â”€â”€
  async function updateWebhookMVPMessage(requestId: string, status: 'approved' | 'denied', reviewerUsername: string) {
    try {
      const { data: request, error: requestError } = await supabase
        .from('rank_up_requests')
        .select(`discord_message_id, action, match_id, screenshot_url,
          users!rank_up_requests_user_id_fkey(discord_id, discord_username, discord_avatar, ranks(name), rank_id, prestige_level),
          target_user:users!rank_up_requests_target_user_id_fkey(discord_id, discord_username, discord_avatar, ranks(name), rank_id, prestige_level)`)
        .eq('id', requestId).single();

      if (requestError || !request) return;

      const webhookUrl = DISCORD_WEBHOOKS.MVP_SUBMISSION;
      if (!webhookUrl || !request.discord_message_id) return;

      const submittingUser = request.users;
      const targetUser = request.target_user;

      const { data: signedUrlData } = await supabase.storage
        .from('make-4789f4af-mvp-screenshots').createSignedUrl(request.screenshot_url, 60 * 60 * 24 * 7);
      const fullScreenshotUrl = signedUrlData?.signedUrl || request.screenshot_url;

      const { embed: updatedEmbed } = buildResolvedMVPEmbed(
        submittingUser?.discord_id || null, submittingUser?.discord_username || 'Unknown User',
        targetUser?.discord_id || null, targetUser?.discord_username || 'Unknown User',
        request.action || 'rank_up', request.match_id || null, fullScreenshotUrl, status, reviewerUsername,
        (targetUser as any)?.ranks?.name,
      );

      const response = await fetch(`${webhookUrl}/messages/${request.discord_message_id}`,
        { method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ embeds: [updatedEmbed] }) });
      if (!response.ok) console.error('Failed to update webhook message:', await response.text());
    } catch (error) {
      console.error('Error updating webhook message:', error);
    }
  }

  // â”€â”€ Discord helper: warn when target not in guild â”€â”€
  async function updateDiscordMVPMessageBlocked(
    messageId: string, channelId: string, targetDiscordId: string, targetUsername: string, reviewerUsername: string
  ) {
    try {
      const botToken = Deno.env.get('DISCORD_BOT_TOKEN');
      if (!botToken) return;

      const warningEmbed = {
        title: `âš ï¸ MVP Request - Awaiting Guild Join`,
        color: 0xF97316,
        description: `<@${targetDiscordId}> is not in The Corn Field guild yet!\n\n **Action Required:** Please use the \`/joinguild\` command to join The Corn Field before this request can be approved.`,
        fields: [
          { name: 'ðŸ“Š Status', value: `â³ Pending - Waiting for <@${targetDiscordId}> to join the guild`, inline: false },
          { name: 'ðŸ‘¤ Attempted Reviewer', value: reviewerUsername, inline: true },
        ],
        timestamp: new Date().toISOString(),
      };

      await fetch(`https://discord.com/api/v10/channels/${channelId}/messages/${messageId}`,
        { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'Authorization': `Bot ${botToken}` },
          body: JSON.stringify({ embeds: [warningEmbed], content: `<@${targetDiscordId}> Please use \`/joinguild\` to join the guild!` }) });
    } catch (error) {
      console.error('Error sending Discord guild join warning:', error);
    }
  }

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // ROUTES
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  // Submit MVP screenshot for rank-up (Members only)
  app.post(`${PREFIX}/requests/mvp`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: submittingUser, error: userError } = await supabase
        .from('users').select('id, role, rank_id, prestige_level').eq('supabase_id', authUser.id).single();
      if (userError || !submittingUser) return c.json({ error: 'User not found' }, 404);

      const { screenshot_url, match_id, user_id, action, notify_discord } = await c.req.json();
      if (!screenshot_url) return c.json({ error: 'Screenshot URL is required' }, 400);
      if (!user_id) return c.json({ error: 'User ID is required' }, 400);
      if (!action || !['rank_up', 'rank_down', 'prestige'].includes(action)) {
        return c.json({ error: 'Valid action is required (rank_up, rank_down, or prestige)' }, 400);
      }

      const { data: targetUser, error: targetError } = await supabase
        .from('users').select('id, rank_id, prestige_level, role').eq('id', user_id).single();
      if (targetError || !targetUser) return c.json({ error: 'Target user not found' }, 404);

      // Validate action permissions
      const isSelf = submittingUser.id === targetUser.id;
      const targetMaxRank = targetUser.prestige_level === 5 ? 11 : 10;
      const targetIsAtMaxRank = targetUser.rank_id >= targetMaxRank;
      const targetCanPrestige = targetUser.prestige_level < 5 && targetIsAtMaxRank;

      // â”€â”€ Smart action resolution â”€â”€
      // If the user sends rank_up but the target is at max rank and eligible to prestige,
      // auto-upgrade the action to prestige. This powers the "2-button" UI where the
      // frontend only shows Rank Up / Rank Down and the system figures out prestige.
      let resolvedAction = action;
      if (action === 'rank_up' && targetCanPrestige) {
        resolvedAction = 'prestige';
        console.log(`Smart action: auto-upgraded rank_up â†’ prestige for target rank ${targetUser.rank_id}, prestige ${targetUser.prestige_level}`);
      }

      if (resolvedAction === 'rank_up') {
        if (targetIsAtMaxRank) return c.json({ error: 'User is already at maximum rank and prestige level' }, 400);
      }
      if (resolvedAction === 'rank_down') {
        if (isSelf) return c.json({ error: 'You cannot rank yourself down' }, 403);
        // Only Corn Star (rank 10) can rank down others â€” Pop'd Kernel (rank 11) is protected
        // and per guild rules may no longer de-rank anyone else
        if (submittingUser.rank_id !== 10) return c.json({ error: 'Only Corn Star (Rank 10) members can rank down others' }, 403);
        if (targetUser.rank_id <= 1) return c.json({ error: 'User is already at minimum rank' }, 400);
        // Pop'd Kernel (rank 11, prestige 5) cannot be ranked down â€” they are protected
        if (targetUser.rank_id === 11 && targetUser.prestige_level === 5) {
          return c.json({ error: "Pop'd Kernel members are protected and cannot be ranked down" }, 400);
        }
      }
      if (resolvedAction === 'prestige') {
        // No submitter rank check â€” anyone can submit an MVP request; officers control the approval gate.
        // This enables the smart rank_upâ†’prestige upgrade path for all members.
        if (targetUser.prestige_level >= 5) return c.json({ error: 'User is already at maximum prestige level' }, 400);
        if (!targetIsAtMaxRank) return c.json({ error: 'User must be at maximum rank to prestige' }, 400);
      }

      // Check for duplicates
      const { data: duplicates } = await supabase
        .from('rank_up_requests').select('*').eq('user_id', submittingUser.id)
        .or(`screenshot_url.eq.${screenshot_url}${match_id ? `,match_id.eq.${match_id}` : ''}`);
      if (duplicates && duplicates.length > 0) return c.json({ error: 'You have already submitted this screenshot or match' }, 400);

      // Insert request
      const { data: request, error: insertError } = await supabase
        .from('rank_up_requests')
        .insert({
          user_id: submittingUser.id, target_user_id: user_id, action: resolvedAction, type: 'mvp',
          screenshot_url, match_id: match_id || null,
          current_rank_id: targetUser.rank_id, current_prestige_level: targetUser.prestige_level,
          status: 'pending',
        }).select().single();
      if (insertError) { console.error('Error creating MVP request:', insertError); return c.json({ error: 'Failed to create MVP request' }, 500); }

      // Log activity for the submitter (non-critical)
      try {
        const isSelfSubmission = submittingUser.id === user_id;
        const actionLabel = resolvedAction === 'prestige' ? 'Prestige' : resolvedAction === 'rank_down' ? 'Rank Down' : 'Rank Up';
        await createUserActivity({
          user_id: submittingUser.id,
          type: 'mvp_submitted',
          title: `Submitted MVP Request: ${actionLabel}`,
          description: isSelfSubmission
            ? `You submitted a ${actionLabel.toLowerCase()} request for yourself${match_id ? ` (Match ${match_id})` : ''}`
            : `You submitted a ${actionLabel.toLowerCase()} request for another player${match_id ? ` (Match ${match_id})` : ''}`,
          related_id: request.id,
          metadata: { action: resolvedAction, match_id, target_user_id: user_id, is_self: isSelfSubmission },
        });
      } catch (_) { /* activity logging is non-critical */ }

      // Send Discord webhook notification
      if (notify_discord !== false) {
        try {
          const webhookUrl = DISCORD_WEBHOOKS.MVP_SUBMISSION;
          if (webhookUrl) {
            const { data: submitterDetails } = await supabase
              .from('users').select('discord_username, discord_avatar, discord_id, ranks!inner(name), rank_id, prestige_level')
              .eq('id', submittingUser.id).single();
            const { data: targetDetails } = await supabase
              .from('users').select('discord_username, discord_id, ranks!inner(name), rank_id, prestige_level')
              .eq('id', user_id).single();

            const { data: signedUrlData } = await supabase.storage
              .from('make-4789f4af-mvp-screenshots').createSignedUrl(screenshot_url, 60 * 60 * 24 * 7);
            const fullScreenshotUrl = signedUrlData?.signedUrl || screenshot_url;

            const { embed } = buildPendingMVPEmbed(
              submitterDetails?.discord_id || null, submitterDetails?.discord_username || 'Unknown User',
              targetDetails?.discord_id || null, targetDetails?.discord_username || 'Unknown User',
              resolvedAction, match_id || null, fullScreenshotUrl,
            );

            const webhookResponse = await fetch(webhookUrl + '?wait=true', {
              method: 'POST', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ embeds: [embed] }),
            });

            if (webhookResponse.ok) {
              const responseText = await webhookResponse.text();
              if (responseText && responseText.trim().length > 0) {
                try {
                  const discordMessage = JSON.parse(responseText);
                  if (discordMessage.id) {
                    await supabase.from('rank_up_requests').update({ discord_message_id: discordMessage.id }).eq('id', request.id);
                  }
                } catch (_) { /* ignore parse errors */ }
              }
            } else {
              console.error('Discord webhook failed:', webhookResponse.status);
            }
          }
        } catch (webhookError) {
          console.error('Failed to send Discord notification:', webhookError);
        }
      }

      return c.json({ request });
    } catch (error) {
      console.error('Submit MVP request error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Update user rank directly (Owner only)
  app.patch(`${PREFIX}/admin/users/:userId/rank`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('id, role').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (dbUser.role !== 'owner') return c.json({ error: 'Only owners can update user ranks' }, 403);

      const userId = c.req.param('userId');
      const { action } = await c.req.json();
      if (!['rank_up', 'rank_down', 'prestige', 'rank_to_max', 'rank_to_min', 'reset_prestige'].includes(action)) {
        return c.json({ error: 'Invalid action' }, 400);
      }

      const { data: targetUser, error: targetError } = await supabase
        .from('users').select('rank_id, prestige_level').eq('id', userId).single();
      if (targetError || !targetUser) return c.json({ error: 'Target user not found' }, 404);

      let newRankId = targetUser.rank_id;
      let newPrestigeLevel = targetUser.prestige_level;
      const oldRankId = targetUser.rank_id;
      const oldPrestigeLevel = targetUser.prestige_level;

      if (action === 'rank_up') {
        const maxRank = newPrestigeLevel === 5 ? 11 : 10;
        if (newRankId >= maxRank) return c.json({ error: `User is already at max rank for prestige level ${newPrestigeLevel}` }, 400);
        newRankId++;
      } else if (action === 'rank_down') {
        if (newRankId <= 1) return c.json({ error: 'User is already at minimum rank' }, 400);
        newRankId--;
      } else if (action === 'prestige') {
        if (newPrestigeLevel >= 5) return c.json({ error: 'User is already at max prestige level' }, 400);
        const maxRank = 10;
        if (newRankId < maxRank) return c.json({ error: 'User must be at max rank to prestige' }, 400);
        newPrestigeLevel++;
        newRankId = 1;
      } else if (action === 'rank_to_max') {
        newRankId = newPrestigeLevel === 5 ? 11 : 10;
      } else if (action === 'rank_to_min') {
        newRankId = 1;
      } else if (action === 'reset_prestige') {
        newPrestigeLevel = 0;
        newRankId = 1;
      }

      const { data: updatedUser, error: updateError } = await supabase
        .from('users').update({ rank_id: newRankId, prestige_level: newPrestigeLevel, updated_at: new Date().toISOString() })
        .eq('id', userId).select().single();
      if (updateError) { console.error('Error updating user rank:', updateError); return c.json({ error: 'Failed to update user rank' }, 500); }

      // Sync Discord roles (background/best-effort)
      // @ts-ignore: EdgeRuntime is available in Supabase
      EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, userId, newRankId, newPrestigeLevel));

      // â”€â”€ Activity logging (non-critical) â”€â”€
      try {
        const { data: targetUsername } = await supabase
          .from('users').select('discord_username').eq('id', userId).single();
        const { data: actorUser } = await supabase
          .from('users').select('discord_username, discord_avatar').eq('id', dbUser.id).single();
        const targetName = targetUsername?.discord_username || 'Unknown';
        const actorName = actorUser?.discord_username || 'Owner';
        const actorAvatar = actorUser?.discord_avatar || undefined;

        // Look up rank names for human-readable log messages
        const [oldRankData, newRankData] = await Promise.all([
          supabase.from('ranks').select('name').eq('id', oldRankId).single(),
          supabase.from('ranks').select('name').eq('id', newRankId).single(),
        ]);
        const oldRankName = oldRankData?.data?.name || `Rank ${oldRankId}`;
        const newRankName = newRankData?.data?.name || `Rank ${newRankId}`;

        const actionDesc = action === 'prestige' ? 'Prestige' :
          action === 'rank_to_max' ? 'Rank to Max' :
          action === 'rank_to_min' ? 'Rank to Min' :
          action === 'reset_prestige' ? 'Reset Prestige' :
          action === 'rank_up' ? 'Rank Up' : 'Rank Down';

        await createAdminLog({
          type: 'direct_rank_change',
          action: `Direct rank change on ${targetName}: ${actionDesc} (${oldRankName} â†’ ${newRankName}, prestige ${oldPrestigeLevel} â†’ ${newPrestigeLevel})`,
          actor_id: dbUser.id,
          actor_name: actorName,
          actor_avatar: actorAvatar,
          details: { target_user_id: userId, action, old_rank_id: oldRankId, new_rank_id: newRankId, old_prestige_level: oldPrestigeLevel, new_prestige_level: newPrestigeLevel },
        });

        await createUserActivity({
          user_id: userId,
          type: 'admin_rank_change',
          title: `Rank ${actionDesc}`,
          description: `Your rank was changed by ${actorName}: ${oldRankName} â†’ ${newRankName} (prestige ${oldPrestigeLevel} â†’ ${newPrestigeLevel}).`,
          actor_name: actorName,
          actor_avatar: actorAvatar,
        });

        await createNotification({
          user_id: userId,
          type: 'rank_changed',
          title: `Rank ${actionDesc}`,
          body: `Your rank was changed to ${newRankName} by ${actorName}.`,
          actor_name: actorName,
          actor_avatar: actorAvatar,
        });
      } catch (logErr) {
        console.error('Non-critical: activity logging for direct rank change failed:', logErr);
      }

      try {
        await kv.set(`rank_action:${userId}:${Date.now()}`, {
          action, performed_by_user_id: dbUser.id, target_user_id: userId,
          old_rank_id: oldRankId, new_rank_id: newRankId,
          old_prestige_level: oldPrestigeLevel, new_prestige_level: newPrestigeLevel,
          timestamp: new Date().toISOString()
        });
      } catch (_) { /* history logging is non-critical */ }

      return c.json({ user: updatedUser });
    } catch (error) {
      console.error('Update user rank error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Get user's own MVP requests
  app.get(`${PREFIX}/requests/mvp/my`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('id').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);

      const { data: requests, error: requestsError } = await supabase
        .from('rank_up_requests')
        .select(`*, users!rank_up_requests_user_id_fkey(id, discord_username, discord_avatar, email, rank_id, prestige_level),
          target_user:users!rank_up_requests_target_user_id_fkey(id, discord_username, discord_avatar, email, rank_id, prestige_level),
          reviewed_by_user:users!rank_up_requests_reviewed_by_fkey(id, discord_username, discord_avatar)`)
        .eq('user_id', dbUser.id).order('created_at', { ascending: false });
      if (requestsError) return c.json({ error: 'Failed to fetch MVP requests' }, 500);

      const requestsWithSignedUrls = await Promise.all((requests || []).map(async (request: any) => {
        if (request.screenshot_url && !request.screenshot_url.startsWith('http')) {
          const { data: urlData } = await supabase.storage.from('make-4789f4af-mvp-screenshots')
            .createSignedUrl(request.screenshot_url, 60 * 60 * 24);
          return { ...request, screenshot_url: urlData?.signedUrl || request.screenshot_url };
        }
        return request;
      }));

      return c.json({ requests: requestsWithSignedUrls });
    } catch (error) {
      console.error('Get MVP requests error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Get all MVP requests (Admin/Owner only)
  app.get(`${PREFIX}/admin/mvp-requests`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('role').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (!isOfficer(dbUser.role)) {
        return c.json({ error: 'Only owners and officers can access this endpoint' }, 403);
      }

      const { data: requests, error: requestsError } = await supabase
        .from('rank_up_requests')
        .select(`*, users!rank_up_requests_user_id_fkey(id, discord_username, discord_avatar, email, rank_id, prestige_level),
          target_user:users!rank_up_requests_target_user_id_fkey(id, discord_username, discord_avatar, email, rank_id, prestige_level),
          reviewed_by_user:users!rank_up_requests_reviewed_by_fkey(id, discord_username, discord_avatar)`)
        .order('created_at', { ascending: false });
      if (requestsError) return c.json({ error: 'Failed to fetch MVP requests' }, 500);

      const requestsWithSignedUrls = await Promise.all((requests || []).map(async (request: any) => {
        if (request.screenshot_url && !request.screenshot_url.startsWith('http')) {
          const { data: urlData } = await supabase.storage.from('make-4789f4af-mvp-screenshots')
            .createSignedUrl(request.screenshot_url, 60 * 60 * 24);
          return { ...request, screenshot_url: urlData?.signedUrl || request.screenshot_url };
        }
        return request;
      }));

      return c.json({ requests: requestsWithSignedUrls });
    } catch (error) {
      console.error('Get MVP requests error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Approve MVP request and rank up user (Admin/Owner only)
  app.post(`${PREFIX}/admin/mvp-requests/:requestId/approve`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('id, role, discord_username').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (!isOfficer(dbUser.role)) {
        return c.json({ error: 'Only owners and officers can approve requests' }, 403);
      }

      const requestId = c.req.param('requestId');
      const { data: request, error: fetchError } = await supabase
        .from('rank_up_requests')
        .select('user_id, target_user_id, action, status, current_rank_id, current_prestige_level, target_discord_id, target_discord_username, discord_message_id, discord_channel_id')
        .eq('id', requestId).single();
      if (fetchError || !request) return c.json({ error: 'Request not found' }, 404);
      if (request.status !== 'pending') return c.json({ error: 'Request has already been processed' }, 400);

      // Block if target user not registered
      if (!request.target_user_id) {
        if (request.discord_message_id && request.discord_channel_id && request.target_discord_id) {
          updateDiscordMVPMessageBlocked(request.discord_message_id, request.discord_channel_id,
            request.target_discord_id, request.target_discord_username || 'Unknown', dbUser.discord_username || 'Unknown');
        }
        return c.json({ error: 'Target user is not in The Corn Field guild.', requiresGuildJoin: true }, 400);
      }

      const userToRankUp = request.target_user_id;
      const action = request.action || 'rank_up';

      const { data: targetUser, error: targetError } = await supabase
        .from('users').select('rank_id, prestige_level, guild_id').eq('id', userToRankUp).single();
      if (targetError || !targetUser) return c.json({ error: 'User not found' }, 404);

      const maxRank = targetUser.prestige_level === 5 ? 11 : 10;
      let newRankId = targetUser.rank_id;
      let newPrestigeLevel = targetUser.prestige_level;

      if (action === 'rank_up') {
        if (targetUser.rank_id < maxRank) newRankId++;
        else return c.json({ error: 'User is already at max rank' }, 400);
      } else if (action === 'rank_down') {
        if (targetUser.rank_id > 1) newRankId--;
        else return c.json({ error: 'User is already at minimum rank' }, 400);
      } else if (action === 'prestige') {
        if (targetUser.prestige_level < 5) { newRankId = 1; newPrestigeLevel++; }
        else return c.json({ error: 'User is already at max prestige level' }, 400);
      }

      // Look up active season for Guild Wars stamping
      const { data: activeSeason } = await supabase
        .from('guild_wars_seasons')
        .select('id')
        .eq('status', 'active')
        .maybeSingle();

      // Stamp guild_id + season_id on the request for Guild Wars scoring
      const { error: updateRequestError } = await supabase
        .from('rank_up_requests').update({
          status: 'approved',
          reviewed_by: dbUser.id,
          reviewed_at: new Date().toISOString(),
          guild_id: targetUser.guild_id || null,
          season_id: activeSeason?.id || null,
        })
        .eq('id', requestId);
      if (updateRequestError) return c.json({ error: 'Failed to approve request' }, 500);

      const { error: updateUserError } = await supabase
        .from('users').update({ rank_id: newRankId, prestige_level: newPrestigeLevel, updated_at: new Date().toISOString() })
        .eq('id', userToRankUp);
      if (updateUserError) return c.json({ error: 'Failed to rank up user' }, 500);

      // Sync Discord roles (background/best-effort)
      // @ts-ignore: EdgeRuntime is available in Supabase
      EdgeRuntime.waitUntil(syncDiscordUserRoles(supabase, userToRankUp));

      try {
        await kv.set(`rank_action:${userToRankUp}:${Date.now()}`, {
          target_user_id: userToRankUp, performed_by_user_id: request.user_id, action,
          old_rank_id: targetUser.rank_id, new_rank_id: newRankId,
          old_prestige_level: targetUser.prestige_level, new_prestige_level: newPrestigeLevel,
          timestamp: new Date().toISOString()
        });
      } catch (_) { /* non-critical */ }

      updateDiscordMVPMessage(requestId, 'approved', dbUser.discord_username || 'Unknown');
      updateWebhookMVPMessage(requestId, 'approved', dbUser.discord_username || 'Unknown');

      // Notify the target user and log admin action (non-critical)
      try {
        // Look up human-readable names for log messages
        const { data: targetUserInfo } = await supabase
          .from('users').select('discord_username').eq('id', userToRankUp).single();
        const targetName = targetUserInfo?.discord_username || request.target_discord_username || 'Unknown';
        const [oldRankData, newRankData] = await Promise.all([
          supabase.from('ranks').select('name').eq('id', targetUser.rank_id).single(),
          supabase.from('ranks').select('name').eq('id', newRankId).single(),
        ]);
        const oldRankName = oldRankData?.data?.name || `Rank ${targetUser.rank_id}`;
        const newRankName = newRankData?.data?.name || `Rank ${newRankId}`;
        const actionLabel = action === 'rank_down' ? 'rank down' : action === 'prestige' ? 'prestige' : 'rank up';

        await createNotification({
          user_id: userToRankUp,
          type: 'mvp_reviewed',
          title: 'MVP Request Approved',
          body: `Your ${actionLabel} request was approved by ${dbUser.discord_username}. You are now ${newRankName}.`,
          related_id: requestId,
          actor_name: dbUser.discord_username,
        });
        await createAdminLog({
          type: 'mvp_approved',
          action: `Approved ${actionLabel} request for ${targetName} (${oldRankName} â†’ ${newRankName})`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
          details: { request_id: requestId, action, target_name: targetName, old_rank: targetUser.rank_id, new_rank: newRankId },
        });
        await createUserActivity({
          user_id: userToRankUp,
          type: 'admin_rank_change',
          title: `${action === 'rank_down' ? 'Rank Down' : action === 'prestige' ? 'Prestige' : 'Rank Up'}: Now ${newRankName}`,
          description: `Your ${actionLabel} request was approved by ${dbUser.discord_username}. You went from ${oldRankName} to ${newRankName}.`,
          related_id: requestId,
          actor_name: dbUser.discord_username,
          metadata: { action, old_rank: targetUser.rank_id, new_rank: newRankId, old_prestige: targetUser.prestige_level, new_prestige: newPrestigeLevel },
        });
      } catch (_) { /* notification/log is non-critical */ }

      return c.json({ success: true, new_rank_id: newRankId });
    } catch (error) {
      console.error('Approve MVP request error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Deny MVP request (Admin/Owner only)
  app.post(`${PREFIX}/admin/mvp-requests/:requestId/deny`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('id, role, discord_username').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);
      if (!isOfficer(dbUser.role)) {
        return c.json({ error: 'Only owners and officers can deny requests' }, 403);
      }

      const requestId = c.req.param('requestId');
      const { data: request, error: fetchError } = await supabase
        .from('rank_up_requests').select('status, user_id, target_user_id, action, target_discord_username').eq('id', requestId).single();
      if (fetchError || !request) return c.json({ error: 'Request not found' }, 404);
      if (request.status !== 'pending') return c.json({ error: 'Request has already been processed' }, 400);

      const { error: updateError } = await supabase
        .from('rank_up_requests').update({ status: 'denied', reviewed_by: dbUser.id, reviewed_at: new Date().toISOString() })
        .eq('id', requestId);
      if (updateError) return c.json({ error: 'Failed to deny request' }, 500);

      updateDiscordMVPMessage(requestId, 'denied', dbUser.discord_username || 'Unknown');
      updateWebhookMVPMessage(requestId, 'denied', dbUser.discord_username || 'Unknown');

      // Notify submitter and target, log admin action (non-critical)
      try {
        const notifyUserId = request.target_user_id || request.user_id;
        // Look up the target user's name for human-readable logs
        let targetName = request.target_discord_username || 'Unknown';
        if (notifyUserId) {
          const { data: targetUserInfo } = await supabase
            .from('users').select('discord_username').eq('id', notifyUserId).single();
          targetName = targetUserInfo?.discord_username || targetName;

          await createNotification({
            user_id: notifyUserId,
            type: 'mvp_reviewed',
            title: 'MVP Request Denied',
            body: `Your MVP ${request.action || 'rank up'} request was denied by ${dbUser.discord_username}.`,
            related_id: requestId,
            actor_name: dbUser.discord_username,
          });
          // Dual-log: target user sees it in their Activity tab too
          await createUserActivity({
            user_id: notifyUserId,
            type: 'admin_rank_change',
            title: 'MVP Request Denied',
            description: `Your ${request.action || 'rank up'} request was denied by ${dbUser.discord_username}.`,
            related_id: requestId,
            actor_name: dbUser.discord_username,
            metadata: { action: 'denied', request_id: requestId },
          });
        }
        const actionLabel = request.action === 'rank_down' ? 'rank down' : request.action === 'prestige' ? 'prestige' : 'rank up';
        await createAdminLog({
          type: 'mvp_denied',
          action: `Denied ${actionLabel} request from ${targetName}`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
          details: { request_id: requestId, target_name: targetName, action: request.action },
        });
      } catch (_) { /* non-critical */ }

      return c.json({ success: true });
    } catch (error) {
      console.error('Deny MVP request error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // Hard-delete (dismiss) an MVP request (Admin/Owner or request owner)
  app.delete(`${PREFIX}/admin/mvp-requests/:requestId`, async (c) => {
    try {
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (!accessToken) return c.json({ error: 'No access token provided' }, 401);

      const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
      if (authError || !authUser) return c.json({ error: 'Unauthorized' }, 401);

      const { data: dbUser, error: userError } = await supabase
        .from('users').select('id, role, discord_username').eq('supabase_id', authUser.id).single();
      if (userError || !dbUser) return c.json({ error: 'User not found' }, 404);

      const isAdmin = isOfficer(dbUser.role);
      const requestId = c.req.param('requestId');

      const { data: request, error: fetchError } = await supabase
        .from('rank_up_requests').select('screenshot_url, discord_message_id, discord_channel_id, user_id, target_user_id, action')
        .eq('id', requestId).single();
      if (fetchError || !request) return c.json({ error: 'Request not found' }, 404);
      if (!isAdmin && request.user_id !== dbUser.id) return c.json({ error: 'Only admins or the request owner can delete requests' }, 403);

      // Delete screenshot from storage
      if (request.screenshot_url && !request.screenshot_url.startsWith('http')) {
        await supabase.storage.from('make-4789f4af-mvp-screenshots').remove([request.screenshot_url]);
      }

      // Delete Discord messages (both bot and webhook)
      if (request.discord_message_id) {
        if (request.discord_channel_id) {
          const botToken = Deno.env.get('DISCORD_BOT_TOKEN');
          if (botToken) {
            try {
              await fetch(`https://discord.com/api/v10/channels/${request.discord_channel_id}/messages/${request.discord_message_id}`,
                { method: 'DELETE', headers: { 'Authorization': `Bot ${botToken}` } });
            } catch (_) { /* ignore */ }
          }
        }
        const webhookUrl = DISCORD_WEBHOOKS.MVP_SUBMISSION;
        if (webhookUrl) {
          try {
            await fetch(`${webhookUrl}/messages/${request.discord_message_id}`, { method: 'DELETE' });
          } catch (_) { /* ignore */ }
        }
      }

      // Delete request record
      const { error: deleteError } = await supabase.from('rank_up_requests').delete().eq('id', requestId);
      if (deleteError) return c.json({ error: 'Failed to delete request record' }, 500);

      // Log activity for the target user (non-critical â€” dismissed, not denied)
      try {
        const targetUserId = request.target_user_id || request.user_id;
        if (targetUserId && isAdmin) {
          const { data: targetUser } = await supabase
            .from('users').select('discord_username').eq('id', targetUserId).maybeSingle();
          await createUserActivity({
            user_id: targetUserId,
            type: 'mvp_dismissed',
            title: 'MVP Request Dismissed',
            description: `Your ${request.action || 'rank up'} request was dismissed by ${dbUser.discord_username || 'an officer'}. No rank changes were made.`,
            actor_name: dbUser.discord_username,
          });
          await createAdminLog({
            type: 'mvp_dismissed',
            action: `Dismissed MVP ${request.action || 'rank up'} request for ${targetUser?.discord_username || 'unknown user'}`,
            actor_id: dbUser.id,
            actor_name: dbUser.discord_username,
          });
        }
      } catch (_) { /* non-critical */ }

      return c.json({ success: true });
    } catch (error) {
      console.error('Delete MVP request error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

}

/**
 * Notification Routes â€” Unified notification system for The Corn Field
 *
 * KV key patterns:
 *   notification:{user_id}:{sortable_id}        â†’  Inbox notification (things sent TO user)
 *   user_activity:{user_id}:{sortable_id}       â†’  User activity entry (things user DID or done TO user)
 *   admin_log:{sortable_id}                     â†’  Admin activity log entry (officer panel)
 *   notification_config:{slug}                   â†’  Notification type config
 *
 * Notification statuses: unread | read | actioned | dismissed
 */

import { PREFIX } from './helpers.ts';
import * as kv from './kv_store.tsx';

// â”€â”€ Types â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export interface Notification {
  id: string;
  user_id: string;
  type: string;         // e.g. 'team_invite', 'mvp_reviewed', 'team_approved', 'giveaway_prize'
  title: string;
  body: string;
  status: 'unread' | 'read' | 'actioned' | 'dismissed';
  related_id?: string;  // e.g. team_id, request_id, giveaway_id
  action_url?: string;  // e.g. '#tournament-hub/abc123'
  actor_name?: string;  // who caused this notification
  actor_avatar?: string;
  metadata?: Record<string, any>;
  created_at: string;
  read_at?: string;
  actioned_at?: string;
}

export interface AdminLogEntry {
  id: string;
  type: string;         // e.g. 'user_joined', 'team_created', 'tournament_updated'
  actor_id?: string;
  actor_name?: string;
  actor_avatar?: string;
  action: string;       // human-readable: "created team Corn Dawgs"
  details?: Record<string, any>;
  created_at: string;
}

export interface NotificationTypeConfig {
  slug: string;
  label: string;
  icon: string;        // lucide icon name
  color: string;       // hex color for pill/badge
  description: string;
  enabled: boolean;
}

export interface UserActivity {
  id: string;
  user_id: string;
  type: string;           // activity type slug: 'team_joined', 'giveaway_entered', 'admin_rank_change', etc.
  title: string;          // human-readable: "Joined Team Corn Dawgs"
  description: string;    // longer context: "You accepted a team invite for Kernel Kup #10"
  related_id?: string;    // entity ID (team_id, tournament_id, etc.)
  related_url?: string;   // hash navigation: '#tournament-hub/abc123'
  actor_name?: string;    // for admin actions: "Tate"
  actor_avatar?: string;
  metadata?: Record<string, any>;  // extensible: original notification type, etc.
  frozen?: boolean;       // user-pinned: exempt from auto-pruning
  created_at: string;
}

// â”€â”€ Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

// Generate a sortable timestamp-based ID (reverse chronological â€” newest first in prefix queries)
function generateSortableId(): string {
  // Use inverted timestamp so getByPrefix returns newest first
  const maxTimestamp = 9999999999999;
  const invertedTs = (maxTimestamp - Date.now()).toString().padStart(13, '0');
  const rand = Math.random().toString(36).substring(2, 8);
  return `${invertedTs}_${rand}`;
}

// Build notification KV key
function notificationKey(userId: string, sortableId: string): string {
  return `notification:${userId}:${sortableId}`;
}

// Build admin log KV key
function adminLogKey(sortableId: string): string {
  return `admin_log:${sortableId}`;
}

// Build user activity KV key
function userActivityKey(userId: string, sortableId: string): string {
  return `user_activity:${userId}:${sortableId}`;
}

// â”€â”€ Public API: Create notifications (called from other route files) â”€â”€

/**
 * Create a notification for a user. Call this from any route handler.
 */
export async function createNotification(params: {
  user_id: string;
  type: string;
  title: string;
  body: string;
  related_id?: string;
  action_url?: string;
  actor_name?: string;
  actor_avatar?: string;
  metadata?: Record<string, any>;
}): Promise<Notification> {
  const sortableId = generateSortableId();
  const notification: Notification = {
    id: sortableId,
    user_id: params.user_id,
    type: params.type,
    title: params.title,
    body: params.body,
    status: 'unread',
    related_id: params.related_id,
    action_url: params.action_url,
    actor_name: params.actor_name,
    actor_avatar: params.actor_avatar,
    metadata: params.metadata,
    created_at: new Date().toISOString(),
  };

  const key = notificationKey(params.user_id, sortableId);
  await kv.set(key, notification);
  return notification;
}

/**
 * Create an admin activity log entry. Call from any route handler for significant actions.
 */
export async function createAdminLog(params: {
  type: string;
  action: string;
  actor_id?: string;
  actor_name?: string;
  actor_avatar?: string;
  details?: Record<string, any>;
}): Promise<AdminLogEntry> {
  const sortableId = generateSortableId();
  const entry: AdminLogEntry = {
    id: sortableId,
    type: params.type,
    action: params.action,
    actor_id: params.actor_id,
    actor_name: params.actor_name,
    actor_avatar: params.actor_avatar,
    details: params.details,
    created_at: new Date().toISOString(),
  };

  const key = adminLogKey(sortableId);
  await kv.set(key, entry);
  return entry;
}

/**
 * Create a user activity entry. Call from any route handler for user actions.
 * Auto-prunes old entries: removes non-frozen items older than 90 days,
 * then caps non-frozen items at 500 (oldest first).
 */
export async function createUserActivity(params: {
  user_id: string;
  type: string;
  title: string;
  description: string;
  related_id?: string;
  related_url?: string;
  actor_name?: string;
  actor_avatar?: string;
  metadata?: Record<string, any>;
  frozen?: boolean;
}): Promise<UserActivity> {
  const sortableId = generateSortableId();
  const activity: UserActivity = {
    id: sortableId,
    user_id: params.user_id,
    type: params.type,
    title: params.title,
    description: params.description,
    related_id: params.related_id,
    related_url: params.related_url,
    actor_name: params.actor_name,
    actor_avatar: params.actor_avatar,
    metadata: params.metadata,
    frozen: params.frozen || false,
    created_at: new Date().toISOString(),
  };

  const key = userActivityKey(params.user_id, sortableId);
  await kv.set(key, activity);

  // â”€â”€ Auto-prune (non-critical, fire-and-forget) â”€â”€
  // Rules: delete non-frozen items >90 days old, then cap non-frozen at 500
  try {
    const PRUNE_MAX = 500;
    const PRUNE_AGE_MS = 90 * 24 * 60 * 60 * 1000; // 90 days
    const now = Date.now();

    const allActivities: UserActivity[] = await kv.getByPrefix(`user_activity:${params.user_id}:`);

    // Separate frozen vs prunable (getByPrefix returns newest first due to inverted key)
    const prunable: UserActivity[] = [];
    const keysToDelete: string[] = [];

    for (const a of allActivities) {
      if (a.frozen) continue; // frozen items are never pruned
      const age = now - new Date(a.created_at).getTime();
      if (age > PRUNE_AGE_MS) {
        // Too old â€” mark for deletion
        keysToDelete.push(userActivityKey(params.user_id, a.id));
      } else {
        prunable.push(a);
      }
    }

    // Cap prunable at PRUNE_MAX (already sorted newest-first, so trim from end = oldest)
    if (prunable.length > PRUNE_MAX) {
      const excess = prunable.slice(PRUNE_MAX); // oldest non-frozen items beyond cap
      for (const a of excess) {
        keysToDelete.push(userActivityKey(params.user_id, a.id));
      }
    }

    if (keysToDelete.length > 0) {
      await kv.mdel(keysToDelete);
      console.log(`Pruned ${keysToDelete.length} activity entries for user ${params.user_id}`);
    }
  } catch (pruneErr) {
    // Prune failure should never block the write
    console.error('Non-critical: activity auto-prune failed:', pruneErr);
  }

  return activity;
}

// â”€â”€ Route Registration â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export function registerNotificationRoutes(
  app: any,
  supabase: any,
  _anonSupabase: any,
) {
  // Shared auth helper
  async function requireAuth(c: any) {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return { ok: false as const, response: c.json({ error: 'No auth token' }, 401) };
    const { data: { user }, error } = await supabase.auth.getUser(accessToken);
    if (error || !user?.id) return { ok: false as const, response: c.json({ error: 'Unauthorized' }, 401) };
    // Look up db user
    const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', user.id).single();
    if (!dbUser) return { ok: false as const, response: c.json({ error: 'User not found in database' }, 404) };
    return { ok: true as const, user, dbUser };
  }


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 1. GET MY NOTIFICATIONS (paginated)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/notifications`, async (c: any) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const userId = auth.dbUser.id;
      const status = c.req.query('status'); // optional: 'unread', 'read', 'actioned'
      const pending = c.req.query('pending'); // optional: 'true' â†’ only unread + read
      const type = c.req.query('type');     // optional: filter by notification type
      const limit = parseInt(c.req.query('limit') || '50');
      const offset = parseInt(c.req.query('offset') || '0');

      // Fetch all notifications for this user
      const all = await kv.getByPrefix(`notification:${userId}:`);

      // Sort newest first by created_at
      all.sort((a: any, b: any) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

      // Filter
      let filtered = all;
      if (pending === 'true') {
        // Only items the user needs to see in their inbox (not dismissed or actioned)
        filtered = filtered.filter((n: any) => n.status === 'unread' || n.status === 'read');
      } else if (status) {
        filtered = filtered.filter((n: any) => n.status === status);
      }
      if (type) {
        filtered = filtered.filter((n: any) => n.type === type);
      }

      const total = filtered.length;
      const page = filtered.slice(offset, offset + limit);
      const unreadCount = all.filter((n: any) => n.status === 'unread').length;

      // Count by type for pill badges
      const typeCounts: Record<string, number> = {};
      const unreadTypeCounts: Record<string, number> = {};
      for (const n of all) {
        typeCounts[n.type] = (typeCounts[n.type] || 0) + 1;
        if (n.status === 'unread') {
          unreadTypeCounts[n.type] = (unreadTypeCounts[n.type] || 0) + 1;
        }
      }

      return c.json({
        notifications: page,
        total,
        unread_count: unreadCount,
        type_counts: typeCounts,
        unread_type_counts: unreadTypeCounts,
        has_more: offset + limit < total,
      });
    } catch (error: any) {
      console.error('Fetch notifications error:', error);
      return c.json({ error: `Failed to fetch notifications: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 2. MARK NOTIFICATION(S) READ
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/notifications/read`, async (c: any) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const userId = auth.dbUser.id;
      const { ids, all: markAll } = await c.req.json();

      if (markAll) {
        // Mark all unread as read
        const allNotifications = await kv.getByPrefix(`notification:${userId}:`);
        const unread = allNotifications.filter((n: any) => n.status === 'unread');
        const keys: string[] = [];
        const values: any[] = [];
        for (const n of unread) {
          keys.push(notificationKey(userId, n.id));
          values.push({ ...n, status: 'read', read_at: new Date().toISOString() });
        }
        if (keys.length > 0) await kv.mset(keys, values);
        return c.json({ success: true, count: keys.length });
      }

      if (!ids || !Array.isArray(ids) || ids.length === 0) {
        return c.json({ error: 'Provide ids array or all: true' }, 400);
      }

      // Mark specific IDs as read
      const keys = ids.map((id: string) => notificationKey(userId, id));
      const values = await kv.mget(keys);
      const updateKeys: string[] = [];
      const updateValues: any[] = [];
      for (let i = 0; i < keys.length; i++) {
        if (values[i] && values[i].status === 'unread') {
          updateKeys.push(keys[i]);
          updateValues.push({ ...values[i], status: 'read', read_at: new Date().toISOString() });
        }
      }
      if (updateKeys.length > 0) await kv.mset(updateKeys, updateValues);

      return c.json({ success: true, count: updateKeys.length });
    } catch (error: any) {
      console.error('Mark read error:', error);
      return c.json({ error: `Failed to mark notifications read: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 3. DISMISS NOTIFICATION
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/notifications/:id/dismiss`, async (c: any) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const userId = auth.dbUser.id;
      const notifId = c.req.param('id');
      const key = notificationKey(userId, notifId);
      const existing = await kv.get(key);
      if (!existing) return c.json({ error: 'Notification not found' }, 404);

      await kv.set(key, { ...existing, status: 'dismissed' });

      // Create activity entry for the dismissed notification (non-critical)
      try {
        await createUserActivity({
          user_id: userId,
          type: 'notification_dismissed',
          title: `Dismissed: ${existing.title}`,
          description: existing.body || `Dismissed a ${existing.type} notification`,
          related_id: existing.related_id,
          related_url: existing.action_url,
          metadata: { original_type: existing.type, original_notification_id: notifId },
        });
      } catch (actErr) {
        console.error('Non-critical: failed to create activity for dismiss:', actErr);
      }

      return c.json({ success: true });
    } catch (error: any) {
      console.error('Dismiss notification error:', error);
      return c.json({ error: `Failed to dismiss notification: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 3b. MARK NOTIFICATION AS ACTIONED
  // Lightweight status flip â€” no duplicate activity created.
  // Used when the caller already handled the action (e.g. invite accept/decline)
  // and just needs the notification removed from the inbox.
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/notifications/:id/action`, async (c: any) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const userId = auth.dbUser.id;
      const notifId = c.req.param('id');
      const key = notificationKey(userId, notifId);
      const existing = await kv.get(key);

      if (!existing) {
        // Already gone or never existed â€” that's fine, the goal is "not in inbox"
        return c.json({ success: true, already_gone: true });
      }

      if (existing.status === 'actioned' || existing.status === 'dismissed') {
        return c.json({ success: true, already_actioned: true });
      }

      await kv.set(key, { ...existing, status: 'actioned', actioned_at: new Date().toISOString() });

      return c.json({ success: true });
    } catch (error: any) {
      console.error('Mark notification actioned error:', error);
      return c.json({ error: `Failed to mark notification actioned: ${error.message}` }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 4. UNREAD COUNT (lightweight poll endpoint)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/notifications/unread-count`, async (c: any) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const userId = auth.dbUser.id;
      const all = await kv.getByPrefix(`notification:${userId}:`);
      const unreadCount = all.filter((n: any) => n.status === 'unread').length;

      return c.json({ unread_count: unreadCount });
    } catch (error: any) {
      console.error('Unread count error:', error);
      return c.json({ error: `Failed to fetch unread count: ${error.message}` }, 500);
    }
