  // Fallback to OpenDota
  try {
    const od = await opendotaFetch(`/matches/${matchId}`);
    if (!od || !od.match_id) return null;

    // Normalize OpenDota shape â†’ Steam-compatible shape
    return {
      match_id: od.match_id,
