// TRANSFORM HELPERS â€” Steam data â†’ our normalized shapes
// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

/**
 * Transform Steam GetMatchDetails into our Match + PlayerStat shapes.
 * Keeps only the stats we already track: KDA, LH, denies, GPM, XPM,
 * hero_damage, tower_damage, hero_healing, net_worth, level.
 */
function transformMatchDetails(steam: any, teamLookup: Record<number, { name: string; tag: string; logo_url: string | null }>) {
  const radiantTeamId = steam.radiant_team_id || 0;
  const direTeamId = steam.dire_team_id || 0;

  const radiantTeam = teamLookup[radiantTeamId] || { name: `Team ${radiantTeamId}`, tag: 'RAD', logo_url: null };
  const direTeam = teamLookup[direTeamId] || { name: `Team ${direTeamId}`, tag: 'DIR', logo_url: null };

  // Compute team kill totals from player stats
  const players = steam.players || [];
  let radiantKills = 0;
  let direKills = 0;
  players.forEach((p: any) => {
    if (p.player_slot < 128) radiantKills += p.kills || 0;
    else direKills += p.kills || 0;
  });

  const winnerId = steam.radiant_win ? radiantTeamId : direTeamId;
  const winnerTeam = steam.radiant_win ? radiantTeam : direTeam;

  const match = {
    id: String(steam.match_id),
    match_id: steam.match_id,
    series_id: steam.match_seq_num || null,
    team1_id: String(radiantTeamId),
    team2_id: String(direTeamId),
    team1: { id: String(radiantTeamId), name: radiantTeam.name, tag: radiantTeam.tag, logo_url: radiantTeam.logo_url },
    team2: { id: String(direTeamId), name: direTeam.name, tag: direTeam.tag, logo_url: direTeam.logo_url },
    winner: { id: String(winnerId), name: winnerTeam.name, tag: winnerTeam.tag, logo_url: winnerTeam.logo_url },
    winner_team_id: String(winnerId),
    team1_score: radiantKills,
    team2_score: direKills,
    stage: 'group_stage',
    status: 'completed',
    scheduled_time: new Date(steam.start_time * 1000).toISOString(),
    duration: steam.duration || 0,
    dotabuff_url: `https://www.dotabuff.com/matches/${steam.match_id}`,
    youtube_url: null,
    twitch_vod_url: null,
    youtube_vod_url: null,
  };

  const playerStats = players.map((p: any) => {
    const isRadiant = p.player_slot < 128;
    const teamId = isRadiant ? radiantTeamId : direTeamId;
    const team = isRadiant ? radiantTeam : direTeam;

    return {
      id: `${steam.match_id}-${p.account_id || p.player_slot}`,
      match_id: String(steam.match_id),
      team_id: String(teamId),
      player_name: p.persona || `Player ${p.player_slot}`,
      steam_id: String(p.account_id || 0),
      account_id: p.account_id || 0,
      hero_id: p.hero_id || 0,
      hero_name: getHeroName(p.hero_id || 0),
      kills: p.kills || 0,
      deaths: p.deaths || 0,
      assists: p.assists || 0,
      last_hits: p.last_hits || 0,
      denies: p.denies || 0,
      gpm: p.gold_per_min || 0,
      xpm: p.xp_per_min || 0,
      hero_damage: p.hero_damage || 0,
      tower_damage: p.tower_damage || 0,
      hero_healing: p.hero_healing || 0,
      net_worth: p.net_worth || p.gold || 0,
      gold: p.gold || 0,
      level: p.level || 0,
      is_winner: isRadiant ? steam.radiant_win : !steam.radiant_win,
      player: {
        steam_id: String(p.account_id || 0),
        name: p.persona || `Player ${p.player_slot}`,
        avatar_url: null,
        dotabuff_url: p.account_id ? `https://www.dotabuff.com/players/${p.account_id}` : null,
        opendota_url: p.account_id ? `https://www.opendota.com/players/${p.account_id}` : null,
      },
      team: { id: String(teamId), name: team.name, tag: team.tag, logo_url: team.logo_url },
    };
  });

  return { match, playerStats };
}

/** Transform live game data into a clean shape for the frontend */
function transformLiveGame(game: any) {
  const scoreboard = game.scoreboard || {};
  const radiantSb = scoreboard.radiant || {};
  const direSb = scoreboard.dire || {};

  // â”€â”€ DEBUG: log raw structure during draft/early game to diagnose missing picks â”€â”€
  const duration = scoreboard.duration || 0;
  const hasScoreboard = Object.keys(scoreboard).length > 0;
  const radPicks = radiantSb.picks || [];
  const dirPicks = direSb.picks || [];
  const radBans = radiantSb.bans || [];
  const dirBans = direSb.bans || [];

  if (duration <= 5) {
    console.log(`[LIVE DEBUG] match_id=${game.match_id} | hasScoreboard=${hasScoreboard} | duration=${duration}`);
    console.log(`[LIVE DEBUG]   scoreboard keys: ${JSON.stringify(Object.keys(scoreboard))}`);
    console.log(`[LIVE DEBUG]   radiantSb keys: ${JSON.stringify(Object.keys(radiantSb))}`);
    console.log(`[LIVE DEBUG]   radiant picks: ${JSON.stringify(radPicks)} | bans: ${JSON.stringify(radBans)}`);
    console.log(`[LIVE DEBUG]   dire picks: ${JSON.stringify(dirPicks)} | bans: ${JSON.stringify(dirBans)}`);
    // Check if picks/bans are at game level instead of inside scoreboard
    if (game.radiant_picks || game.dire_picks || game.radiant_bans || game.dire_bans) {
      console.log(`[LIVE DEBUG]   *** FOUND GAME-LEVEL DRAFT DATA ***`);
      console.log(`[LIVE DEBUG]   game.radiant_picks: ${JSON.stringify(game.radiant_picks)}`);
      console.log(`[LIVE DEBUG]   game.dire_picks: ${JSON.stringify(game.dire_picks)}`);
      console.log(`[LIVE DEBUG]   game.radiant_bans: ${JSON.stringify(game.radiant_bans)}`);
      console.log(`[LIVE DEBUG]   game.dire_bans: ${JSON.stringify(game.dire_bans)}`);
    }
    // Log top-level game keys so we can see the full shape
    console.log(`[LIVE DEBUG]   game top-level keys: ${JSON.stringify(Object.keys(game))}`);
  }

  // Build player name lookup from game.players (top-level has names; scoreboard does NOT)
  // Steam puts real player names in game.players[].name, keyed by account_id
  // game.players[].team: 0 = radiant, 1 = dire (or 2/3/4 for other slots)
  const playerNameByAccount: Record<number, string> = {};
  const playerNameByHero: Record<number, string> = {};
  (game.players || []).forEach((p: any) => {
    if (p.account_id && p.name) playerNameByAccount[p.account_id] = p.name;
    if (p.hero_id && p.name) playerNameByHero[p.hero_id] = p.name;
  });

  // Extract picks and bans â€” check both scoreboard and game-level locations
  const radiantPicks = (radiantSb.picks || game.radiant_picks || []).map((p: any) => ({ hero_id: p.hero_id, hero_name: getHeroName(p.hero_id) }));
  const direPicks = (direSb.picks || game.dire_picks || []).map((p: any) => ({ hero_id: p.hero_id, hero_name: getHeroName(p.hero_id) }));
  const radiantBans = (radiantSb.bans || game.radiant_bans || []).map((b: any) => ({ hero_id: b.hero_id, hero_name: getHeroName(b.hero_id) }));
  const direBans = (direSb.bans || game.dire_bans || []).map((b: any) => ({ hero_id: b.hero_id, hero_name: getHeroName(b.hero_id) }));

  const totalPicks = radiantPicks.length + direPicks.length;
  const totalBans = radiantBans.length + direBans.length;
  const hasDraftData = totalPicks > 0 || totalBans > 0;

  // Infer match phase from data shape
  // - No scoreboard â†’ waiting (lobby exists but game hasn't loaded)
  // - Scoreboard exists, duration ~0, picks < 10 â†’ drafting
  // - Scoreboard exists, duration ~0, picks = 10 â†’ strategy (post-draft, pre-horn)  
  // - Scoreboard exists, duration > 0 â†’ playing
  let phase: 'waiting' | 'drafting' | 'strategy' | 'playing' = 'waiting';
  if (hasScoreboard) {
    if (duration > 5) {
      phase = 'playing';
    } else if (totalPicks >= 10) {
      phase = 'strategy';
    } else if (hasDraftData) {
      phase = 'drafting';
    } else {
      // Scoreboard exists but no picks yet â€” could be early draft or waiting
      phase = hasScoreboard && (radiantSb.score !== undefined) ? 'drafting' : 'waiting';
    }
  }

  const result = {
    match_id: game.match_id,
    lobby_id: game.lobby_id,
    game_number: game.game_number || 1,
    spectators: game.spectators || 0,
    stream_delay_s: game.stream_delay_s || 0,
    duration,
    phase,

    // Series info
    series_type: game.series_type || 0, // 0=none, 1=bo3, 2=bo5
    radiant_series_wins: game.radiant_series_wins || 0,
    dire_series_wins: game.dire_series_wins || 0,

    // Team info
    radiant_team: {
      id: game.radiant_team?.team_id || 0,
      name: game.radiant_team?.team_name || 'Radiant',
      tag: game.radiant_team?.team_tag || 'RAD',
      logo_url: game.radiant_team?.team_logo ? getSteamLogoUrl(game.radiant_team.team_logo) : null,
    },
    dire_team: {
      id: game.dire_team?.team_id || 0,
      name: game.dire_team?.team_name || 'Dire',
      tag: game.dire_team?.team_tag || 'DIR',
      logo_url: game.dire_team?.team_logo ? getSteamLogoUrl(game.dire_team.team_logo) : null,
    },

    // Team scores
    radiant_score: radiantSb.score || 0,
    dire_score: direSb.score || 0,

    // Tower & barracks state (bitmasks)
    radiant_tower_state: radiantSb.tower_state || 0,
    dire_tower_state: direSb.tower_state || 0,
    radiant_barracks_state: radiantSb.barracks_state || 0,
    dire_barracks_state: direSb.barracks_state || 0,

    // Draft data
    radiant_picks: radiantPicks,
    dire_picks: direPicks,
    radiant_bans: radiantBans,
    dire_bans: direBans,

    // Player data â€” keep to our tracked stats
    // Cross-reference with game.players for real names (scoreboard.players.name is usually empty)
    radiant_players: (radiantSb.players || []).map((p: any) => {
      const realName = (p.account_id && playerNameByAccount[p.account_id]) ||
                       (p.hero_id && playerNameByHero[p.hero_id]) ||
                       p.name || '';
      return {
        account_id: p.account_id || 0,
        name: realName,
        hero_id: p.hero_id || 0,
        hero_name: getHeroName(p.hero_id || 0),
        kills: p.kills || 0,
        deaths: p.deaths || 0,
        assists: p.assists || 0,
        last_hits: p.last_hits || 0,
        denies: p.denies || 0,
        gpm: p.gold_per_min || 0,
        xpm: p.xp_per_min || 0,
        net_worth: p.net_worth || p.gold || 0,
        level: p.level || 0,
        // Phase 2: rich live data â€” positions, items, ult/respawn status
        position_x: p.position_x ?? 0,
        position_y: p.position_y ?? 0,
        items: [p.item0 || 0, p.item1 || 0, p.item2 || 0, p.item3 || 0, p.item4 || 0, p.item5 || 0].map(
          (id: number) => ({ id, name: getItemName(id) })
        ),
        respawn_timer: p.respawn_timer || 0,
        ultimate_state: p.ultimate_state ?? 0, // 0=not learned, 1=cooldown, 2=no mana, 3=ready
        ultimate_cooldown: p.ultimate_cooldown || 0,
      };
    }),
    dire_players: (direSb.players || []).map((p: any) => {
      const realName = (p.account_id && playerNameByAccount[p.account_id]) ||
                       (p.hero_id && playerNameByHero[p.hero_id]) ||
                       p.name || '';
      return {
        account_id: p.account_id || 0,
        name: realName,
        hero_id: p.hero_id || 0,
        hero_name: getHeroName(p.hero_id || 0),
        kills: p.kills || 0,
        deaths: p.deaths || 0,
        assists: p.assists || 0,
        last_hits: p.last_hits || 0,
        denies: p.denies || 0,
        gpm: p.gold_per_min || 0,
        xpm: p.xp_per_min || 0,
        net_worth: p.net_worth || p.gold || 0,
        level: p.level || 0,
        // Phase 2: rich live data â€” positions, items, ult/respawn status
        position_x: p.position_x ?? 0,
        position_y: p.position_y ?? 0,
        items: [p.item0 || 0, p.item1 || 0, p.item2 || 0, p.item3 || 0, p.item4 || 0, p.item5 || 0].map(
          (id: number) => ({ id, name: getItemName(id) })
        ),
        respawn_timer: p.respawn_timer || 0,
        ultimate_state: p.ultimate_state ?? 0,
        ultimate_cooldown: p.ultimate_cooldown || 0,
      };
    }),
  };

  // Debug: log coordinate ranges so we can validate WORLD_MIN/MAX mapping
  const allPositions = [
    ...(result.radiant_players || []),
    ...(result.dire_players || []),
  ].filter((p: any) => p.position_x !== 0 || p.position_y !== 0);
  if (allPositions.length > 0) {
    const xs = allPositions.map((p: any) => p.position_x);
    const ys = allPositions.map((p: any) => p.position_y);
    console.log(`  [Minimap debug] Position ranges â€” X: [${Math.min(...xs)}, ${Math.max(...xs)}], Y: [${Math.min(...ys)}, ${Math.max(...ys)}] (${allPositions.length} heroes with positions)`);
  }

  return result;
}

// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
// ROUTE REGISTRATION
// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

export function registerPracticeTourneyRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ Inline auth helper â€” verifies token + officer role â”€â”€
  async function requireOfficerAuth(c: any): Promise<{ ok: true; authUser: any; dbUser: any } | { ok: false; response: any }> {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return { ok: false, response: c.json({ error: 'No access token provided' }, 401) };
    const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
    if (authError || !authUser) return { ok: false, response: c.json({ error: 'Unauthorized â€” invalid or expired token' }, 401) };
    const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', authUser.id).single();
    if (!dbUser) return { ok: false, response: c.json({ error: 'User not found in database' }, 404) };
    if (!isOfficer(dbUser.role)) return { ok: false, response: c.json({ error: 'Forbidden â€” only officers can manage practice tournaments' }, 403) };
    return { ok: true, authUser, dbUser };
  }

  // â”€â”€ POST /practice/create â€” Create practice tournament from league_id â”€â”€
  app.post(`${PREFIX}/practice/create`, async (c) => {
    try {
      // Auth: officer only
      const authResult = await requireOfficerAuth(c);
      if (!authResult.ok) return authResult.response;

      const { league_id } = await c.req.json();
      if (!league_id || typeof league_id !== 'number') {
        return c.json({ error: 'league_id (number) is required' }, 400);
      }

      // Check if already exists
      const existing = await kv.get(`practice:${league_id}:meta`);
      if (existing) {
        return c.json({ error: `Practice tournament for league ${league_id} already exists`, existing }, 409);
      }

      console.log(`Creating practice tournament for league ${league_id}...`);

      // Ensure hero cache is loaded before transforming match data
      await ensureHeroCache();

      // 1. Get league info
      const leagueInfo = await getLeagueInfo(league_id);
      const leagueName = leagueInfo?.name || `League ${league_id}`;

      // 2. Get match history
      const matchHistory = await getLeagueMatches(league_id);
      console.log(`Found ${matchHistory.length} matches for league ${league_id}`);

      // 3. Collect unique team IDs from match history
      const teamIds = new Set<number>();
      matchHistory.forEach((m: any) => {
        m.players?.forEach((p: any) => {
          // team_id is not always in match history, but radiant/dire team info might be
        });
      });

      // 4. Pull detailed data for first few completed matches to build team roster
      const teamLookup: Record<number, { name: string; tag: string; logo_url: string | null }> = {};
      const matchDetails: any[] = [];
      const allPlayerStats: any[] = [];

      // Pull details for up to 20 most recent matches
      const matchesToDetail = matchHistory.slice(0, 20);
      for (const m of matchesToDetail) {
        try {
          const details = await getMatchDetails(m.match_id);
          if (!details) continue;

          // Discover teams from match details
          if (details.radiant_team_id && !teamLookup[details.radiant_team_id]) {
            // Try team API (Steam â†’ OpenDota fallback), then use embedded match data
            try {
              const tInfo = await getTeamInfo(details.radiant_team_id);
              teamLookup[details.radiant_team_id] = {
                name: tInfo?.name || details.radiant_name || `Team ${details.radiant_team_id}`,
                tag: tInfo?.tag || details.radiant_tag || 'RAD',
                logo_url: tInfo?.logo_url || (tInfo?.logo ? getSteamLogoUrl(tInfo.logo) : null) || details.radiant_logo || null,
              };
            } catch {
              teamLookup[details.radiant_team_id] = {
                name: details.radiant_name || `Team ${details.radiant_team_id}`,
                tag: details.radiant_tag || 'RAD',
                logo_url: details.radiant_logo || null,
              };
            }
          }
          if (details.dire_team_id && !teamLookup[details.dire_team_id]) {
            try {
              const tInfo = await getTeamInfo(details.dire_team_id);
              teamLookup[details.dire_team_id] = {
                name: tInfo?.name || details.dire_name || `Team ${details.dire_team_id}`,
                tag: tInfo?.tag || details.dire_tag || 'DIR',
                logo_url: tInfo?.logo_url || (tInfo?.logo ? getSteamLogoUrl(tInfo.logo) : null) || details.dire_logo || null,
              };
            } catch {
              teamLookup[details.dire_team_id] = {
                name: details.dire_name || `Team ${details.dire_team_id}`,
                tag: details.dire_tag || 'DIR',
                logo_url: details.dire_logo || null,
              };
            }
          }

          const { match, playerStats } = transformMatchDetails(details, teamLookup);
          matchDetails.push(match);
          allPlayerStats.push(...playerStats);

          // Store individual match detail in KV
          await kv.set(`practice:${league_id}:match:${m.match_id}`, { match, playerStats });
        } catch (err) {
          console.error(`Failed to get details for match ${m.match_id}:`, err);
        }
      }

      // 5. Build team standings from match results
      const teamStandings: Record<string, { wins: number; losses: number; kills: number }> = {};
      matchDetails.forEach((m: any) => {
        const t1 = m.team1_id;
        const t2 = m.team2_id;
        if (!teamStandings[t1]) teamStandings[t1] = { wins: 0, losses: 0, kills: 0 };
        if (!teamStandings[t2]) teamStandings[t2] = { wins: 0, losses: 0, kills: 0 };

        if (m.winner_team_id === t1) {
          teamStandings[t1].wins++;
          teamStandings[t2].losses++;
        } else {
          teamStandings[t2].wins++;
          teamStandings[t1].losses++;
        }
        teamStandings[t1].kills += m.team1_score;
        teamStandings[t2].kills += m.team2_score;
      });

      // Build teams array matching our Team type
      const teams = Object.entries(teamLookup).map(([idStr, info]) => {
        const standing = teamStandings[idStr] || { wins: 0, losses: 0, kills: 0 };
        return {
          id: idStr,
          name: info.name,
          tag: info.tag,
          logo_url: info.logo_url,
          wins: standing.wins,
          losses: standing.losses,
          total_kills: standing.kills,
        };
      });

      // 6. Store everything in KV
      const meta = {
        league_id,
        name: leagueName,
        status: 'live',
        created_at: new Date().toISOString(),
        created_by: authResult.dbUser.discord_username,
        last_refreshed: new Date().toISOString(),
        total_matches: matchHistory.length,
        detailed_matches: matchDetails.length,
        team_count: teams.length,
      };

      await kv.set(`practice:${league_id}:meta`, meta);
      await kv.set(`practice:${league_id}:teams`, teams);
      await kv.set(`practice:${league_id}:matches`, matchDetails);

      console.log(`Practice tournament created: ${leagueName} (${league_id}) â€” ${matchDetails.length} matches, ${teams.length} teams`);

      return c.json({
        success: true,
        message: `Created practice tournament: ${leagueName}`,
        meta,
        teams: teams.length,
        matches: matchDetails.length,
      });
    } catch (err: any) {
      console.error('Practice tournament creation failed:', err);
      return c.json({ error: `Failed to create practice tournament: ${err.message}` }, 500);
    }
  });

  // â”€â”€ GET /practice/list â€” List all practice tournaments â”€â”€
  app.get(`${PREFIX}/practice/list`, async (c) => {
    try {
      const metas = await kv.getByPrefix('practice:');
      // Filter to only :meta keys
      const tournaments = metas
        .filter((m: any) => m.key?.endsWith(':meta'))
        .map((m: any) => ({ ...m, key: undefined }));

      return c.json({ tournaments });
    } catch (err: any) {
      console.error('Failed to list practice tournaments:', err);
      return c.json({ error: `Failed to list practice tournaments: ${err.message}` }, 500);
    }
  });

  // â”€â”€ GET /practice/:id â€” Get full practice tournament data â”€â”€
  app.get(`${PREFIX}/practice/:id`, async (c) => {
    try {
      const leagueId = c.req.param('id');

      const [meta, teams, matches] = await Promise.all([
        kv.get(`practice:${leagueId}:meta`),
        kv.get(`practice:${leagueId}:teams`),
        kv.get(`practice:${leagueId}:matches`),
      ]);

      if (!meta) {
        return c.json({ error: `Practice tournament ${leagueId} not found` }, 404);
      }

      return c.json({ meta, teams: teams || [], matches: matches || [] });
    } catch (err: any) {
      console.error(`Failed to get practice tournament ${c.req.param('id')}:`, err);
      return c.json({ error: `Failed to get practice tournament: ${err.message}` }, 500);
    }
  });

  // â”€â”€ GET /practice/:id/match/:matchId â€” Get detailed match data â”€â”€
  app.get(`${PREFIX}/practice/:id/match/:matchId`, async (c) => {
    try {
      const leagueId = c.req.param('id');
      const matchId = c.req.param('matchId');

      let data = await kv.get(`practice:${leagueId}:match:${matchId}`);

      // If not cached, try to pull from Steam and cache
      if (!data) {
        const teamLookup: Record<number, { name: string; tag: string; logo_url: string | null }> = {};
        // Rebuild team lookup from stored teams
        const teams = await kv.get(`practice:${leagueId}:teams`) || [];
        teams.forEach((t: any) => {
          teamLookup[Number(t.id)] = { name: t.name, tag: t.tag, logo_url: t.logo_url };
        });

        const details = await getMatchDetails(Number(matchId));
        if (!details) return c.json({ error: `Match ${matchId} not found on Steam` }, 404);

        // Discover any new teams
        if (details.radiant_team_id && !teamLookup[details.radiant_team_id]) {
          teamLookup[details.radiant_team_id] = { name: details.radiant_name || 'Radiant', tag: 'RAD', logo_url: null };
        }
        if (details.dire_team_id && !teamLookup[details.dire_team_id]) {
          teamLookup[details.dire_team_id] = { name: details.dire_name || 'Dire', tag: 'DIR', logo_url: null };
        }

        data = transformMatchDetails(details, teamLookup);
        await kv.set(`practice:${leagueId}:match:${matchId}`, data);
      }

      return c.json(data);
    } catch (err: any) {
      console.error(`Failed to get match ${c.req.param('matchId')}:`, err);
      return c.json({ error: `Failed to get match details: ${err.message}` }, 500);
    }
  });

  // â”€â”€ GET /practice/:id/live â€” Poll live games for this league â”€â”€
  app.get(`${PREFIX}/practice/:id/live`, async (c) => {
    try {
      const leagueId = Number(c.req.param('id'));

      const meta = await kv.get(`practice:${leagueId}:meta`);
      if (!meta) return c.json({ error: `Practice tournament ${leagueId} not found` }, 404);

      // Load stored teams for enrichment (Steam live data often lacks names/logos)
      const storedTeams: any[] = await kv.get(`practice:${leagueId}:teams`) || [];
      const teamById: Record<number, any> = {};
      storedTeams.forEach((t: any) => { teamById[Number(t.id)] = t; });

      // Ensure item name cache is populated (fetches once, then cached in memory)
      await ensureItemCache();
      // Ensure hero name cache is populated (fetches once, covers newly added heroes)
      await ensureHeroCache();

      const games = await getLiveLeagueGames(leagueId);
      const liveGames = games.map((game: any) => {
        const transformed = transformLiveGame(game);

        // Enrich team names/logos from stored data if Steam didn't provide them
        const radId = transformed.radiant_team.id;
        const dirId = transformed.dire_team.id;

        if (radId && teamById[radId]) {
          if (transformed.radiant_team.name === 'Radiant' || !transformed.radiant_team.name) {
            transformed.radiant_team.name = teamById[radId].name;
          }
          if (!transformed.radiant_team.tag || transformed.radiant_team.tag === 'RAD') {
            transformed.radiant_team.tag = teamById[radId].tag || transformed.radiant_team.tag;
          }
          if (!transformed.radiant_team.logo_url && teamById[radId].logo_url) {
            transformed.radiant_team.logo_url = teamById[radId].logo_url;
          }
        }

        if (dirId && teamById[dirId]) {
          if (transformed.dire_team.name === 'Dire' || !transformed.dire_team.name) {
            transformed.dire_team.name = teamById[dirId].name;
          }
          if (!transformed.dire_team.tag || transformed.dire_team.tag === 'DIR') {
            transformed.dire_team.tag = teamById[dirId].tag || transformed.dire_team.tag;
          }
          if (!transformed.dire_team.logo_url && teamById[dirId].logo_url) {
            transformed.dire_team.logo_url = teamById[dirId].logo_url;
          }
        }

        return transformed;
      });

      // Enrich player ranks from OpenDota (non-blocking, cached after first fetch)
      try {
        const allAccountIds = liveGames.flatMap((g: any) => [
          ...g.radiant_players.map((p: any) => p.account_id),
          ...g.dire_players.map((p: any) => p.account_id),
        ]).filter((id: number) => id > 0);

        if (allAccountIds.length > 0) {
          await fetchPlayerRanks(allAccountIds);

          // Attach rank_tier to each player
          for (const game of liveGames) {
            for (const p of game.radiant_players) {
              p.rank_tier = getCachedRank(p.account_id);
            }
            for (const p of game.dire_players) {
              p.rank_tier = getCachedRank(p.account_id);
            }
          }
        }
      } catch (rankErr) {
        console.log('Non-critical: rank enrichment failed:', rankErr);
      }

      // Cache latest live state
      if (liveGames.length > 0) {
        await kv.set(`practice:${leagueId}:live`, {
          games: liveGames,
          polled_at: new Date().toISOString(),
        });
      }

      return c.json({
        league_id: leagueId,
        league_name: meta.name,
        live_count: liveGames.length,
        games: liveGames,
        polled_at: new Date().toISOString(),
      });
    } catch (err: any) {
      console.error(`Failed to poll live games for league ${c.req.param('id')}:`, err);
      return c.json({ error: `Failed to poll live games: ${err.message}` }, 500);
    }
  });

  // â”€â”€ POST /practice/:id/refresh â€” Re-pull match data from Steam â”€â”€
  app.post(`${PREFIX}/practice/:id/refresh`, async (c) => {
    try {
      const authResult = await requireOfficerAuth(c);
      if (!authResult.ok) return authResult.response;

      const leagueId = Number(c.req.param('id'));
      const meta = await kv.get(`practice:${leagueId}:meta`);
      if (!meta) return c.json({ error: `Practice tournament ${leagueId} not found` }, 404);

      console.log(`Refreshing practice tournament ${leagueId}...`);

      // Re-pull match history
      const matchHistory = await getLeagueMatches(leagueId);

      // Get existing cached match IDs
      const existingMatches: any[] = await kv.get(`practice:${leagueId}:matches`) || [];
      const existingIds = new Set(existingMatches.map((m: any) => String(m.match_id || m.id)));

      // Find new matches
      const newMatchIds = matchHistory
        .filter((m: any) => !existingIds.has(String(m.match_id)))
        .slice(0, 20); // Limit new pulls

      // Build team lookup from existing teams
      const teamLookup: Record<number, { name: string; tag: string; logo_url: string | null }> = {};
      const existingTeams = await kv.get(`practice:${leagueId}:teams`) || [];
      existingTeams.forEach((t: any) => {
        teamLookup[Number(t.id)] = { name: t.name, tag: t.tag, logo_url: t.logo_url };
      });

      const newMatches: any[] = [];
      for (const m of newMatchIds) {
        try {
          const details = await getMatchDetails(m.match_id);
          if (!details) continue;

          // Discover new teams (same enrichment pattern as create)
          if (details.radiant_team_id && !teamLookup[details.radiant_team_id]) {
            try {
              const tInfo = await getTeamInfo(details.radiant_team_id);
              teamLookup[details.radiant_team_id] = {
                name: tInfo?.name || details.radiant_name || `Team ${details.radiant_team_id}`,
                tag: tInfo?.tag || details.radiant_tag || 'RAD',
                logo_url: tInfo?.logo_url || (tInfo?.logo ? getSteamLogoUrl(tInfo.logo) : null) || details.radiant_logo || null,
              };
            } catch {
              teamLookup[details.radiant_team_id] = {
                name: details.radiant_name || `Team ${details.radiant_team_id}`,
                tag: details.radiant_tag || 'RAD',
                logo_url: details.radiant_logo || null,
              };
            }
          }
          if (details.dire_team_id && !teamLookup[details.dire_team_id]) {
            try {
              const tInfo = await getTeamInfo(details.dire_team_id);
              teamLookup[details.dire_team_id] = {
                name: tInfo?.name || details.dire_name || `Team ${details.dire_team_id}`,
                tag: tInfo?.tag || details.dire_tag || 'DIR',
                logo_url: tInfo?.logo_url || (tInfo?.logo ? getSteamLogoUrl(tInfo.logo) : null) || details.dire_logo || null,
              };
            } catch {
              teamLookup[details.dire_team_id] = {
                name: details.dire_name || `Team ${details.dire_team_id}`,
                tag: details.dire_tag || 'DIR',
                logo_url: details.dire_logo || null,
              };
            }
          }

          const { match, playerStats } = transformMatchDetails(details, teamLookup);
          newMatches.push(match);
          await kv.set(`practice:${leagueId}:match:${m.match_id}`, { match, playerStats });
        } catch (err) {
          console.error(`Failed to refresh match ${m.match_id}:`, err);
        }
      }

      // Merge and re-store
      const allMatches = [...existingMatches, ...newMatches]
        .sort((a, b) => new Date(b.scheduled_time).getTime() - new Date(a.scheduled_time).getTime());

      // Rebuild team standings
      const teamStandings: Record<string, { wins: number; losses: number; kills: number }> = {};
      allMatches.forEach((m: any) => {
        const t1 = m.team1_id;
        const t2 = m.team2_id;
        if (!teamStandings[t1]) teamStandings[t1] = { wins: 0, losses: 0, kills: 0 };
        if (!teamStandings[t2]) teamStandings[t2] = { wins: 0, losses: 0, kills: 0 };
        if (m.winner_team_id === t1) { teamStandings[t1].wins++; teamStandings[t2].losses++; }
        else { teamStandings[t2].wins++; teamStandings[t1].losses++; }
        teamStandings[t1].kills += m.team1_score || 0;
        teamStandings[t2].kills += m.team2_score || 0;
      });

      const updatedTeams = Object.entries(teamLookup).map(([idStr, info]) => {
        const s = teamStandings[idStr] || { wins: 0, losses: 0, kills: 0 };
        return { id: idStr, name: info.name, tag: info.tag, logo_url: info.logo_url, wins: s.wins, losses: s.losses, total_kills: s.kills };
      });

      await kv.set(`practice:${leagueId}:matches`, allMatches);
      await kv.set(`practice:${leagueId}:teams`, updatedTeams);
      await kv.set(`practice:${leagueId}:meta`, {
        ...meta,
        last_refreshed: new Date().toISOString(),
        total_matches: allMatches.length,
        detailed_matches: allMatches.length,
        team_count: updatedTeams.length,
      });

      console.log(`Refreshed: +${newMatches.length} new matches, ${updatedTeams.length} teams`);

      return c.json({
        success: true,
        new_matches: newMatches.length,
        total_matches: allMatches.length,
        teams: updatedTeams.length,
      });
    } catch (err: any) {
      console.error(`Failed to refresh practice tournament:`, err);
      return c.json({ error: `Failed to refresh: ${err.message}` }, 500);
    }
  });

  // â”€â”€ DELETE /practice/:id â€” Nuke all KV entries for this league â”€
  app.delete(`${PREFIX}/practice/:id`, async (c) => {
    try {
      const authResult = await requireOfficerAuth(c);
      if (!authResult.ok) return authResult.response;

      const leagueId = c.req.param('id');
      const meta = await kv.get(`practice:${leagueId}:meta`);
      if (!meta) return c.json({ error: `Practice tournament ${leagueId} not found` }, 404);

      // Get all keys for this practice tournament
      const allEntries = await kv.getByPrefix(`practice:${leagueId}:`);
      const allKeys = allEntries.map((e: any) => e.key).filter(Boolean);

      if (allKeys.length > 0) {
        // mdel in batches of 50 to avoid oversized queries
        for (let i = 0; i < allKeys.length; i += 50) {
          await kv.mdel(allKeys.slice(i, i + 50));
        }
      }

      console.log(`Deleted practice tournament ${leagueId}: ${allKeys.length} KV entries removed`);

      return c.json({
        success: true,
        message: `Practice tournament "${meta.name}" deleted`,
        keys_removed: allKeys.length,
      });
    } catch (err: any) {
      console.error(`Failed to delete practice tournament:`, err);
      return c.json({ error: `Failed to delete: ${err.message}` }, 500);
    }
  });
}

/**
 * Printful API routes â€” fetches product catalog for the Secret Shop merch section.
 *
 * Public endpoint (no auth required) â€” this is storefront data.
 * Caches products in memory for 10 minutes to avoid hitting Printful rate limits.
 */

import { PREFIX } from "./helpers.ts";

const PRINTFUL_BASE = 'https://api.printful.com';

// â”€â”€ In-memory cache â”€â”€
const CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes
const CACHE_VERSION = 1;
let cachedProducts: SimplifiedProduct[] | null = null;
let cacheTimestamp = 0;
let cachedVersion = 0;
let cachedStoreId: number | null = null;

interface SimplifiedProduct {
  id: number;
  name: string;
  thumbnail_url: string;
  variants: {
    id: number;
    name: string;
    retail_price: string;
    preview_url: string | null;
  }[];
  retail_price_range: { min: string; max: string };
}

// â”€â”€ Products to hide from the storefront â”€â”€
// Add lowercase substrings here to temporarily exclude products (e.g. while remaking them).
// Remove entries once the new products are ready.
const HIDDEN_PRODUCT_KEYWORDS: string[] = [];

async function resolveStoreId(apiKey: string): Promise<number> {
  if (cachedStoreId) return cachedStoreId;

  const res = await fetch(`${PRINTFUL_BASE}/stores`, {
    headers: { 'Authorization': `Bearer ${apiKey}` },
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Printful /stores fetch failed (${res.status}): ${errText}`);
  }
  const data = await res.json();
  const stores = data.result || [];
  if (stores.length === 0) {
    throw new Error('No Printful stores found for this API key');
  }

  // Log all available stores for debugging
  console.log(`Printful stores found (${stores.length}):`);
  for (const s of stores) {
    console.log(`  - id: ${s.id}, name: "${s.name}", type: ${s.type || 'unknown'}, created: ${s.created}`);
  }

  // Prefer a real connected store over the default "Personal orders" store
  const realStore = stores.find((s: any) =>
    s.name && !s.name.toLowerCase().includes('personal order')
  );
  const selectedStore = realStore || stores[0];

  cachedStoreId = selectedStore.id;
  console.log(`Selected Printful store_id: ${cachedStoreId} ("${selectedStore.name}")${realStore ? '' : ' [WARNING: using fallback â€” no connected store found]'}`);
  return cachedStoreId!;
}

async function fetchPrintfulProducts(apiKey: string): Promise<SimplifiedProduct[]> {
  const storeId = await resolveStoreId(apiKey);

  // Step 1: Get all sync products
  const productsRes = await fetch(`${PRINTFUL_BASE}/store/products?store_id=${storeId}`, {
    headers: { 'Authorization': `Bearer ${apiKey}` },
  });
  if (!productsRes.ok) {
    const errText = await productsRes.text();
    throw new Error(`Printful products fetch failed (${productsRes.status}): ${errText}`);
  }
  const productsData = await productsRes.json();
  const products = productsData.result || [];

  console.log(`Printful store ${storeId}: ${products.length} sync product(s) found`);
  if (products.length === 0) return [];

  // Step 2: For each product, fetch full details (includes variants + preview images)
  const detailed: SimplifiedProduct[] = [];

  for (const p of products) {
    // Filter out hidden products
    const nameLower = (p.name || '').toLowerCase();
    if (HIDDEN_PRODUCT_KEYWORDS.some((kw) => nameLower.includes(kw))) continue;

    try {
      const detailRes = await fetch(`${PRINTFUL_BASE}/store/products/${p.id}?store_id=${storeId}`, {
        headers: { 'Authorization': `Bearer ${apiKey}` },
      });
      if (!detailRes.ok) {
        console.log(`Skipping product ${p.id} â€” detail fetch failed (${detailRes.status})`);
        continue;
      }
      const detailData = await detailRes.json();
      const syncProduct = detailData.result?.sync_product;
      const syncVariants = detailData.result?.sync_variants || [];

      const variants = syncVariants.map((v: any) => ({
        id: v.id,
        name: v.name,
        retail_price: v.retail_price || '0.00',
        preview_url: v.files?.find((f: any) => f.type === 'preview')?.preview_url || null,
      }));

      // Compute price range
      const prices = variants
        .map((v: any) => parseFloat(v.retail_price))
        .filter((p: number) => p > 0);
      const minPrice = prices.length > 0 ? Math.min(...prices).toFixed(2) : '0.00';
      const maxPrice = prices.length > 0 ? Math.max(...prices).toFixed(2) : '0.00';

      detailed.push({
        id: syncProduct?.id || p.id,
        name: syncProduct?.name || p.name,
        thumbnail_url: syncProduct?.thumbnail_url || p.thumbnail_url || '',
        variants,
        retail_price_range: { min: minPrice, max: maxPrice },
      });
    } catch (err) {
      console.log(`Skipping product ${p.id} â€” error: ${err}`);
    }
  }

  return detailed;
}

export function registerPrintfulRoutes(
  app: any,
  _supabase: any,
  _anonSupabase: any,
) {
  // GET /printful/products â€” public, cached
  app.get(`${PREFIX}/printful/products`, async (c: any) => {
    try {
      const apiKey = Deno.env.get('PRINTFUL_API_KEY');
      if (!apiKey) {
        return c.json({ error: 'PRINTFUL_API_KEY not configured on server' }, 500);
      }

      const now = Date.now();
      if (cachedProducts && cachedVersion === CACHE_VERSION && (now - cacheTimestamp) < CACHE_TTL_MS) {
        return c.json({ products: cachedProducts, cached: true });
      }

      const products = await fetchPrintfulProducts(apiKey);
      cachedProducts = products;
      cacheTimestamp = now;
      cachedVersion = CACHE_VERSION;

      return c.json({ products, cached: false });
    } catch (error: any) {
      console.log(`Printful products fetch error: ${error.message}`);
      return c.json({ error: `Failed to fetch Printful products: ${error.message}` }, 500);
    }
  });
}

import { Hono } from "npm:hono";
import { PREFIX, requireOwner, requireAuth } from "./helpers.ts";
import { createAdminLog, createNotification, createUserActivity } from "./routes-notifications.ts";

export function registerPrizeRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // 1. LIST PRIZES FOR A TOURNAMENT (Public)
  app.get(`${PREFIX}/kkup/tournaments/:id/prizes`, async (c) => {
    try {
      const tournamentId = c.req.param('id');
      const { data: prizes, error } = await supabase
        .from('kkup_prizes')
        .select('*')
        .eq('tournament_id', tournamentId)
        .order('sort_order', { ascending: true });

      if (error) {
        console.error('List prizes error:', error);
        return c.json({ error: `Failed to fetch prizes: ${error.message}` }, 500);
      }

      // Also fetch awards to show winners
      const { data: awards, error: awardError } = await supabase
        .from('prize_awards')
        .select(`
          id, prize_id, amount_cents, recipient_user_id, team_id,
          recipient:users!recipient_user_id(id, discord_username, discord_avatar),
          team:kkup_teams!team_id(id, team_name, team_tag, logo_url)
        `)
        .eq('tournament_id', tournamentId);

      if (awardError) {
        console.error('Fetch awards error:', awardError);
      }

      return c.json({ prizes: prizes || [], awards: awards || [] });
    } catch (error: any) {
      console.error('List prizes unexpected error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // 2. CREATE PRIZE (Owner only)
  app.post(`${PREFIX}/kkup/tournaments/:id/prizes`, async (c) => {
    try {
      const auth = await requireOwner(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');
      const body = await c.req.json();

      if (!body.title?.trim()) {
        return c.json({ error: 'Prize title is required' }, 400);
      }

      const { data: prize, error } = await supabase
        .from('kkup_prizes')
        .insert({
          tournament_id: tournamentId,
          title: body.title.trim(),
          description: body.description?.trim() || null,
          value_type: body.value_type || 'fixed',
          value: body.value ?? 0,
          sort_order: body.sort_order ?? 0
        })
        .select()
        .single();

      if (error) {
        console.error('Create prize error:', error);
        return c.json({ error: `Failed to create prize: ${error.message}` }, 500);
      }

      await createAdminLog({
        type: 'prize_created',
        action: `Created prize "${prize.title}" for tournament ${tournamentId}`,
        actor_id: auth.dbUser.id,
        actor_name: auth.dbUser.discord_username,
        details: { tournament_id: tournamentId, prize_id: prize.id, title: prize.title }
      });

      return c.json({ success: true, prize });
    } catch (error: any) {
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // 3. UPDATE PRIZE (Owner only)
  app.patch(`${PREFIX}/kkup/tournaments/:id/prizes/:prizeId`, async (c) => {
    try {
      const auth = await requireOwner(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const prizeId = c.req.param('prizeId');
      const body = await c.req.json();

      const updateData: any = {};
      const allowed = ['title', 'description', 'value_type', 'value', 'sort_order'];
      for (const field of allowed) {
        if (body[field] !== undefined) updateData[field] = body[field];
      }

      if (Object.keys(updateData).length === 0) {
        return c.json({ error: 'No fields to update' }, 400);
      }

      const { data: prize, error } = await supabase
        .from('kkup_prizes')
        .update(updateData)
        .eq('id', prizeId)
        .select()
        .single();

      if (error) {
        console.error('Update prize error:', error);
        return c.json({ error: `Failed to update prize: ${error.message}` }, 500);
      }

      return c.json({ success: true, prize });
    } catch (error: any) {
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // 4. DELETE PRIZE (Owner only)
  app.delete(`${PREFIX}/kkup/tournaments/:id/prizes/:prizeId`, async (c) => {
    try {
      const auth = await requireOwner(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const prizeId = c.req.param('prizeId');
      const { error } = await supabase
        .from('kkup_prizes')
        .delete()
        .eq('id', prizeId);

      if (error) {
        console.error('Delete prize error:', error);
        return c.json({ error: `Failed to delete prize: ${error.message}` }, 500);
      }

      return c.json({ success: true });
    } catch (error: any) {
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // 5. AWARD PRIZE (Owner only)
  app.post(`${PREFIX}/kkup/tournaments/:id/prizes/:prizeId/award`, async (c) => {
    try {
      const auth = await requireOwner(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');
      const prizeId = c.req.param('prizeId');
      const body = await c.req.json(); // { team_id, recipient_user_id, amount_cents, reason }

      const { data: prize } = await supabase.from('kkup_prizes').select('*').eq('id', prizeId).single();
      if (!prize) return c.json({ error: 'Prize NOT found' }, 404);

      // Create award record
      const insertData: any = {
        tournament_id: tournamentId,
        prize_id: prizeId,
        awarded_by_user_id: auth.dbUser.id,
        amount_cents: body.amount_cents || 0,
        reason: body.reason || prize.title,
        status: 'honorary', // Default as per plan for retroactive support
      };

      if (body.team_id) insertData.team_id = body.team_id;
      if (body.recipient_user_id) insertData.recipient_user_id = body.recipient_user_id;

      const { data: award, error } = await supabase
        .from('prize_awards')
        .insert(insertData)
        .select()
        .single();

      if (error) {
        console.error('Create award error:', error);
        return c.json({ error: `Failed to create award: ${error.message}` }, 500);
      }

      await createAdminLog({
        type: 'prize_awarded',
        action: `Awarded prize "${prize.title}" to ${body.team_id ? 'team ' + body.team_id : 'user ' + body.recipient_user_id}`,
        actor_id: auth.dbUser.id,
        actor_name: auth.dbUser.discord_username,
        details: { tournament_id: tournamentId, prize_id: prizeId, award_id: award.id }
      });

      return c.json({ success: true, award });
    } catch (error: any) {
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // 6. DELETE AWARD (Owner only)
  app.delete(`${PREFIX}/kkup/tournaments/:id/awards/:awardId`, async (c) => {
    try {
      const auth = await requireOwner(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;

      const awardId = c.req.param('awardId');
      const { error } = await supabase
        .from('prize_awards')
        .delete()
        .eq('id', awardId);

      if (error) {
        console.error('Delete award error:', error);
        return c.json({ error: `Failed to delete award: ${error.message}` }, 500);
      }

      return c.json({ success: true });
    } catch (error: any) {
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });
}

/**
 * Guild Wars â€” Season Routes
 * Season management + manual reset trigger for officers.
 *
 * 5 routes:
 *   GET    /seasons              â€” list all seasons
 *   GET    /seasons/active       â€” get the current active season
 *   POST   /seasons              â€” create a new season (officer only)
 *   POST   /seasons/:id/complete â€” mark season as completed + set winner (officer only)
 *   POST   /seasons/:id/reset    â€” trigger full rank + prestige reset (officer only)
 */
import type { Hono } from "npm:hono";
import { PREFIX, requireAuth } from "./helpers.ts";
import { isOfficer } from "./roles.ts";
import { createAdminLog, createUserActivity } from "./routes-notifications.ts";

export function registerSeasonRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ GET /seasons â€” List all seasons â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/seasons`, async (c) => {
    try {
      const { data: seasons, error } = await supabase
        .from('guild_wars_seasons')
        .select(`
          *,
          winning_guild:guild_wars_guilds!guild_wars_seasons_winning_guild_id_fkey (
            id, name, tag, color, logo_url
          )
        `)
        .order('year', { ascending: false });

      if (error) return c.json({ error: `Failed to fetch seasons: ${error.message}` }, 500);
      return c.json({ seasons: seasons || [] });
    } catch (error: any) {
      console.error('List seasons error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ GET /seasons/active â€” Current active season â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.get(`${PREFIX}/seasons/active`, async (c) => {
    try {
      const { data: season, error } = await supabase
        .from('guild_wars_seasons')
        .select('*')
        .eq('status', 'active')
        .maybeSingle();

      if (error) return c.json({ error: `Failed to fetch active season: ${error.message}` }, 500);
      if (!season) return c.json({ error: 'No active season found' }, 404);

      // Get guild leaderboard for this season
      const { data: guilds } = await supabase
        .from('guild_wars_guilds')
        .select('id, name, tag, color, logo_url, is_default');

      // Count approved MVPs per guild for this season
      const { data: mvpCounts } = await supabase
        .from('rank_up_requests')
        .select('guild_id')
        .eq('season_id', season.id)
        .eq('status', 'approved');

      const guildMvpMap: Record<string, number> = {};
      for (const r of (mvpCounts || [])) {
        if (r.guild_id) guildMvpMap[r.guild_id] = (guildMvpMap[r.guild_id] || 0) + 1;
      }

      // Count members per guild
      const { data: memberCounts } = await supabase
        .from('users')
        .select('guild_id')
        .not('guild_id', 'is', null);

      const guildMemberMap: Record<string, number> = {};
      for (const u of (memberCounts || [])) {
        guildMemberMap[u.guild_id] = (guildMemberMap[u.guild_id] || 0) + 1;
      }

      const leaderboard = (guilds || []).map((g: any) => ({
        ...g,
        mvp_count: guildMvpMap[g.id] || 0,
        member_count: guildMemberMap[g.id] || 0,
      })).sort((a: any, b: any) => b.mvp_count - a.mvp_count);

      return c.json({ season, leaderboard });
    } catch (error: any) {
      console.error('Get active season error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ POST /seasons â€” Create a new season (officer only) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/seasons`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      if (!isOfficer(dbUser.role)) {
        return c.json({ error: 'Only officers can create seasons' }, 403);
      }

      const { name, year, starts_at, ends_at } = await c.req.json();
      if (!name || !year) return c.json({ error: 'name and year are required' }, 400);

      // Check for duplicate year
      const { data: existing } = await supabase
        .from('guild_wars_seasons')
        .select('id')
        .eq('year', year)
        .maybeSingle();
      if (existing) return c.json({ error: `A season for year ${year} already exists` }, 409);

      const { data: season, error } = await supabase
        .from('guild_wars_seasons')
        .insert({
          name: name.trim(),
          year,
          starts_at: starts_at || `${year}-01-01T00:00:00Z`,
          ends_at: ends_at || `${year}-12-31T23:59:59Z`,
          status: 'upcoming',
        })
        .select()
        .single();

      if (error) return c.json({ error: `Failed to create season: ${error.message}` }, 500);

      try {
        await createAdminLog({
          type: 'season_created',
          action: `${dbUser.discord_username} created Guild Wars season "${name}" (${year})`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
          details: { season_id: season.id, year },
        });
      } catch (_) { /* non-critical */ }

      return c.json({ season });
    } catch (error: any) {
      console.error('Create season error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ POST /seasons/:id/complete â€” End a season + set winner â”€â”€â”€â”€â”€â”€â”€â”€
  app.post(`${PREFIX}/seasons/:id/complete`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      if (!isOfficer(dbUser.role)) {
        return c.json({ error: 'Only officers can complete seasons' }, 403);
      }

      const seasonId = c.req.param('id');
      const { winning_guild_id } = await c.req.json();

      const { data: season, error: fetchError } = await supabase
        .from('guild_wars_seasons')
        .select('*')
        .eq('id', seasonId)
        .single();

      if (fetchError || !season) return c.json({ error: 'Season not found' }, 404);
      if (season.status === 'completed') return c.json({ error: 'Season is already completed' }, 400);

      // If no winning guild specified, auto-detect from MVP counts
      let winnerGuildId = winning_guild_id;
      if (!winnerGuildId) {
        const { data: mvpCounts } = await supabase
          .from('rank_up_requests')
          .select('guild_id')
          .eq('season_id', seasonId)
          .eq('status', 'approved');

        const counts: Record<string, number> = {};
        for (const r of (mvpCounts || [])) {
          if (r.guild_id) counts[r.guild_id] = (counts[r.guild_id] || 0) + 1;
        }
        const sorted = Object.entries(counts).sort(([, a], [, b]) => (b as number) - (a as number));
        winnerGuildId = sorted[0]?.[0] || null;
      }

      const { data: updatedSeason, error: updateError } = await supabase
        .from('guild_wars_seasons')
        .update({ status: 'completed', winning_guild_id: winnerGuildId })
        .eq('id', seasonId)
        .select()
        .single();

      if (updateError) return c.json({ error: `Failed to complete season: ${updateError.message}` }, 500);

      // Get winner guild name for logging
      let winnerName = 'Unknown';
      if (winnerGuildId) {
        const { data: winnerGuild } = await supabase
          .from('guild_wars_guilds')
          .select('name')
          .eq('id', winnerGuildId)
          .single();
        winnerName = winnerGuild?.name || 'Unknown';
      }

      try {
        await createAdminLog({
          type: 'season_completed',
          action: `${dbUser.discord_username} completed Guild Wars season "${season.name}" â€” winner: ${winnerName}`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
          details: { season_id: seasonId, winner_guild_id: winnerGuildId, winner_name: winnerName },
        });
      } catch (_) { /* non-critical */ }

      return c.json({ season: updatedSeason, winner_name: winnerName });
    } catch (error: any) {
      console.error('Complete season error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

  // â”€â”€ POST /seasons/:id/reset â€” Full rank + prestige reset â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // This is the "start new year" action â€” resets ALL users to Earwig rank 1, prestige 0.
  // Historical data is preserved (membership records, rank_up_requests stay untouched).
  app.post(`${PREFIX}/seasons/:id/reset`, async (c) => {
    try {
      const auth = await requireAuth(c, supabase, anonSupabase);
      if (!auth.ok) return auth.response;
      const { dbUser } = auth;

      if (!isOfficer(dbUser.role)) {
        return c.json({ error: 'Only officers can trigger season resets' }, 403);
      }

      const seasonId = c.req.param('id');

      const { data: season, error: fetchError } = await supabase
        .from('guild_wars_seasons')
        .select('*')
        .eq('id', seasonId)
        .single();

      if (fetchError || !season) return c.json({ error: 'Season not found' }, 404);

      // Count affected users before reset
      const { count: affectedCount } = await supabase
        .from('users')
        .select('id', { count: 'exact', head: true })
        .neq('role', 'guest');

      // Reset all non-guest users to rank 1, prestige 0
      const { error: resetError } = await supabase
        .from('users')
        .update({ rank_id: 1, prestige_level: 0, updated_at: new Date().toISOString() })
        .neq('role', 'guest');

      if (resetError) return c.json({ error: `Failed to reset ranks: ${resetError.message}` }, 500);

      // If the season was upcoming, activate it
      if (season.status === 'upcoming') {
        // Deactivate any currently active season first
        await supabase
          .from('guild_wars_seasons')
          .update({ status: 'completed' })
          .eq('status', 'active');

        await supabase
          .from('guild_wars_seasons')
          .update({ status: 'active' })
          .eq('id', seasonId);
      }

      try {
        await createAdminLog({
          type: 'season_reset',
          action: `${dbUser.discord_username} triggered season reset for "${season.name}" â€” ${affectedCount || 0} users reset to Earwig rank 1, prestige 0`,
          actor_id: dbUser.id,
          actor_name: dbUser.discord_username,
          details: { season_id: seasonId, affected_users: affectedCount || 0 },
        });
      } catch (_) { /* non-critical */ }

      console.log(`Season reset triggered by ${dbUser.discord_username}: ${affectedCount || 0} users reset`);
      return c.json({ success: true, affected_users: affectedCount || 0 });
    } catch (error: any) {
      console.error('Season reset error:', error);
      return c.json({ error: 'Internal server error' }, 500);
    }
  });

}

/**
 * Seeding Routes â€” Officer-only
 *
 * Handles rank fetching from OpenDota and team seeding calculations
 * for use in the Bracket Builder before roster lock.
 *
 * Routes:
 *   GET  /kkup/tournaments/:id/seeding              â€” compute + return seeded team list
 *   POST /kkup/tournaments/:id/seeding/fetch-ranks  â€” fetch ranks for unranked players via OpenDota, save to DB
 *   POST /kkup/tournaments/:id/seeding/apply        â€” write computed seed numbers to kkup_teams.seeding
 */

import { Hono } from "npm:hono";
import { PREFIX } from "./helpers.ts";
import { isOfficer } from "./roles.ts";
import { fetchOpenDotaPlayerRank } from "./opendota-helpers.ts";

async function requireOfficer(c: any, supabase: any, anonSupabase: any) {
  const token = c.req.header('Authorization')?.split(' ')[1];
  if (!token) return { ok: false, response: c.json({ error: 'No access token' }, 401) };
  const { data: { user: authUser }, error } = await anonSupabase.auth.getUser(token);
  if (error || !authUser) return { ok: false, response: c.json({ error: 'Unauthorized' }, 401) };
  const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', authUser.id).single();
  if (!dbUser || !isOfficer(dbUser.role)) return { ok: false, response: c.json({ error: 'Officer access required' }, 403) };
  return { ok: true, dbUser };
}

/** Convert OpenDota rank_tier integer to numeric 1â€“36 scale for averaging */
function rankTierToNumeric(rankTier: number | null): number {
  if (!rankTier || rankTier === 0) return 0;
  if (rankTier >= 80) return 36; // Immortal
  const medalNum = Math.floor(rankTier / 10); // 1=Herald â€¦ 7=Divine
  const stars = rankTier % 10; // 1â€“5
  // Medal order: Herald(0) Guardian(1) Crusader(2) Archon(3) Legend(4) Ancient(5) Divine(6)
  const tierIndex = medalNum - 1;
  if (tierIndex < 0 || tierIndex > 6) return 0;
  return tierIndex * 5 + Math.max(1, Math.min(5, stars));
}

/** Convert OpenDota rank_tier integer to display string */
function rankTierToLabel(rankTier: number | null): string {
  if (!rankTier || rankTier === 0) return 'Unranked';
  if (rankTier >= 80) return 'Immortal';
  const medals = ['Herald', 'Guardian', 'Crusader', 'Archon', 'Legend', 'Ancient', 'Divine'];
  const medalNum = Math.floor(rankTier / 10) - 1;
  const stars = rankTier % 10;
  const medal = medals[medalNum];
  return medal ? `${medal} ${stars}` : 'Unranked';
}

/** Get a safe steam account_id â€” filters out synthetic TCF IDs (tcf_user_*) */
function getSteamAccountId(steamId: string | null): string | null {
  if (!steamId) return null;
  // Synthetic IDs start with 'tcf_user_' â€” these are not real Steam accounts
  if (steamId.startsWith('tcf_user_')) return null;
  // If somehow a 64-bit SteamID slipped in (> 4.3B), convert to 32-bit
  try {
    const n = BigInt(steamId);
    const STEAM_BASE = BigInt('76561197960265728');
    if (n > BigInt('10000000000')) {
      return String(n - STEAM_BASE);
    }
    return steamId;
  } catch {
    return null; // non-numeric â€” skip
  }
}

export function registerSeedingRoutes(app: Hono, supabase: any, anonSupabase: any) {

  /**
   * GET /kkup/tournaments/:id/seeding
   * Returns teams sorted by computed seed (best rank = seed 1).
   */
  app.get(`${PREFIX}/kkup/tournaments/:id/seeding`, async (c) => {
    const auth = await requireOfficer(c, supabase, anonSupabase);
    if (!auth.ok) return auth.response;

    const tournamentId = c.req.param('id');

    // Fetch approved teams with their rosters + person rank data
    const { data: teams, error: teamsErr } = await supabase
      .from('kkup_teams')
      .select(`
        id, team_name, team_tag, logo_url, seeding,
        kkup_team_rosters (
          person_id,
          kkup_persons ( id, display_name, steam_id, rank_tier )
        )
      `)
      .eq('tournament_id', tournamentId)
      .eq('approval_status', 'approved');

    if (teamsErr) {
      console.error('[Seeding] Error fetching teams:', teamsErr);
      return c.json({ error: 'Failed to fetch teams' }, 500);
    }

    if (!teams || teams.length === 0) {
      return c.json([]);
    }

    // Compute per-team average rank numeric (unranked = 0)
    const seeded = teams.map((team: any) => {
      const roster = team.kkup_team_rosters || [];
      const numericValues = roster.map((r: any) => rankTierToNumeric(r.kkup_persons?.rank_tier ?? null));
      const total = numericValues.reduce((s: number, v: number) => s + v, 0);
      const avg = numericValues.length > 0 ? total / numericValues.length : 0;

      return {
        team_id: team.id,
        team_name: team.team_name,
        team_tag: team.team_tag,
        logo_url: team.logo_url,
        avg_rank_numeric: avg,
        avg_rank_label: (() => {
          // Convert numeric back to label for display
          if (avg === 0) return 'Unranked';
          if (avg >= 36) return 'Immortal';
          const medals = ['Herald', 'Guardian', 'Crusader', 'Archon', 'Legend', 'Ancient', 'Divine', 'Immortal'];
          const tierIndex = Math.floor((Math.round(avg) - 1) / 5);
          const stars = ((Math.round(avg) - 1) % 5) + 1;
          return `${medals[tierIndex] || 'Unranked'} ${stars}`;
        })(),
        roster: roster.map((r: any) => ({
          person_id: r.kkup_persons?.id,
          display_name: r.kkup_persons?.display_name || 'Unknown',
          rank_tier: r.kkup_persons?.rank_tier ?? null,
          rank_label: rankTierToLabel(r.kkup_persons?.rank_tier ?? null),
        })),
      };
    });

    // Sort descending by avg numeric (highest rank = seed 1), then add seed numbers
    seeded.sort((a: any, b: any) => b.avg_rank_numeric - a.avg_rank_numeric);
    seeded.forEach((t: any, i: number) => { t.seed = i + 1; });

    return c.json(seeded);
  });


  /**
   * POST /kkup/tournaments/:id/seeding/fetch-ranks
   * Fetches Dota 2 rank_tier from OpenDota for roster members without one.
   * Saves results back to kkup_persons.rank_tier.
   */
  app.post(`${PREFIX}/kkup/tournaments/:id/seeding/fetch-ranks`, async (c) => {
    const auth = await requireOfficer(c, supabase, anonSupabase);
    if (!auth.ok) return auth.response;

    const tournamentId = c.req.param('id');

    // Get all persons on approved teams without a rank_tier
    const { data: rosters, error: rostersErr } = await supabase
      .from('kkup_teams')
      .select(`
        kkup_team_rosters (
          kkup_persons ( id, steam_id, rank_tier )
        )
      `)
      .eq('tournament_id', tournamentId)
      .eq('approval_status', 'approved');

    if (rostersErr || !rosters) {
      return c.json({ error: 'Failed to fetch rosters' }, 500);
    }

    // Flatten + filter to persons needing a lookup
    const personsMap = new Map<string, { id: string; steam_id: string }>();
    for (const team of rosters) {
      for (const r of (team.kkup_team_rosters || [])) {
        const p = r.kkup_persons;
        if (!p || p.rank_tier !== null) continue; // already has rank
        const accountId = getSteamAccountId(p.steam_id);
        if (!accountId) continue; // synthetic ID or invalid
        personsMap.set(p.id, { id: p.id, steam_id: accountId });
      }
    }

    const toFetch = Array.from(personsMap.values());
    console.log(`[Seeding] Need to fetch ranks for ${toFetch.length} persons`);

    let saved = 0;
    let skipped_private = 0;
    const already_had_rank = 0;

    // Batch: 5 concurrent, 300ms delay between batches
    const BATCH_SIZE = 5;
    for (let i = 0; i < toFetch.length; i += BATCH_SIZE) {
      const batch = toFetch.slice(i, i + BATCH_SIZE);
      const results = await Promise.all(
        batch.map(async (person) => {
          const rankTier = await fetchOpenDotaPlayerRank(person.steam_id);
          return { id: person.id, rank_tier: rankTier };
        })
      );

      for (const r of results) {
        if (r.rank_tier === null) {
          skipped_private++;
          continue;
        }
        const { error: updateErr } = await supabase
          .from('kkup_persons')
          .update({ rank_tier: r.rank_tier })
          .eq('id', r.id);
        if (!updateErr) saved++;
      }

      if (i + BATCH_SIZE < toFetch.length) {
        await new Promise(resolve => setTimeout(resolve, 300));
      }
    }

    console.log(`[Seeding] fetch-ranks done: saved=${saved} skipped_private=${skipped_private}`);
    return c.json({
      fetched: toFetch.length,
      saved,
      skipped_private,
      already_had_rank,
    });
  });


  /**
   * POST /kkup/tournaments/:id/seeding/apply
   * Writes the computed seed order to kkup_teams.seeding for each team.
   * Body: { seeds: [{ team_id: string, seed: number }] }
   */
  app.post(`${PREFIX}/kkup/tournaments/:id/seeding/apply`, async (c) => {
    const auth = await requireOfficer(c, supabase, anonSupabase);
    if (!auth.ok) return auth.response;

    const { seeds } = await c.req.json();
    if (!Array.isArray(seeds)) return c.json({ error: 'seeds array required' }, 400);

    let updated = 0;
    for (const { team_id, seed } of seeds) {
      const { error } = await supabase
        .from('kkup_teams')
        .update({ seeding: seed })
        .eq('id', team_id);
      if (!error) updated++;
    }

    return c.json({ updated });
  });
}

/**
 * Staff Application Routes â€” Tournament staff signup flow
 *
 * 6 routes:
 *   POST   /kkup/tournaments/:id/apply-staff     â€” Apply as staff (any authenticated user)
 *   DELETE /kkup/tournaments/:id/apply-staff     â€” Withdraw staff application
 *   GET    /kkup/tournaments/:id/staff           â€” List staff applications (public summary, full detail for owner)
 *   PATCH  /kkup/tournaments/:id/staff/:appId    â€” Approve/deny staff application (owner only)
 *   DELETE /kkup/tournaments/:id/staff/:appId    â€” Dismiss (hard delete) staff application (officer/owner)
 *   GET    /kkup/requests                        â€” List all KKup requests (aggregated)
 *
 * Storage: Uses real Postgres table `kkup_staff_applications`
 */
import type { Hono } from "npm:hono";
import { PREFIX, resolvePersonForUser, disbandCaptainTeam } from "./helpers.ts";
import { createNotification, createAdminLog, createUserActivity } from "./routes-notifications.ts";
import { isOfficer } from "./roles.ts";
import { DISCORD_WEBHOOKS } from "./discord-config.ts";
import { buildRegistrationEmbed, buildKkupActivityEmbed, sendWebhookEmbed } from "./discord-embeds.tsx";
import { resolveUserRank, getRankBadgeUrl } from "./rank-utils.ts";

export function registerStaffApplicationRoutes(app: Hono, supabase: any, anonSupabase: any) {

  // â”€â”€ Auth helpers â”€â”€
  async function requireAuth(c: any): Promise<{ ok: true; authUser: any; dbUser: any } | { ok: false; response: any }> {
    const accessToken = c.req.header('Authorization')?.split(' ')[1];
    if (!accessToken) return { ok: false, response: c.json({ error: 'No access token provided' }, 401) };
    const { data: { user: authUser }, error: authError } = await anonSupabase.auth.getUser(accessToken);
    if (authError || !authUser) return { ok: false, response: c.json({ error: 'Unauthorized â€” invalid or expired token' }, 401) };
    const { data: dbUser } = await supabase.from('users').select('*').eq('supabase_id', authUser.id).single();
    if (!dbUser) return { ok: false, response: c.json({ error: 'User not found in database' }, 404) };
    return { ok: true, authUser, dbUser };
  }

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 1. APPLY AS STAFF
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.post(`${PREFIX}/kkup/tournaments/:id/apply-staff`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');
      const body = await c.req.json();

      const { data: tournament, error: fetchError } = await supabase
        .from('kkup_tournaments').select('id, name, status, casters_needed, staff_needed')
        .eq('id', tournamentId).single();
      if (fetchError || !tournament) return c.json({ error: 'Tournament not found' }, 404);

      if (!['upcoming', 'registration_open', 'registration_closed'].includes(tournament.status)) {
        return c.json({ error: `Tournament "${tournament.name}" is not accepting staff applications (status: ${tournament.status}).` }, 400);
      }

      // Check for existing application
      const { data: existing } = await supabase
        .from('kkup_staff_applications')
        .select('id, status')
        .eq('tournament_id', tournamentId)
        .eq('user_id', auth.dbUser.id)
        .maybeSingle();

      if (existing && existing.status !== 'withdrawn') {
        return c.json({ error: 'You have already applied for staff. Check your application status or withdraw first.' }, 409);
      }

      const validRoles = ['caster', 'producer', 'helper', 'tournament_director', 'other'];
      const rolePreference = validRoles.includes(body.role_preference) ? body.role_preference : 'other';
      const plansToPlay = rolePreference === 'tournament_director' ? (body.plans_to_play === true) : false;

      // â”€â”€ Role exclusivity check â”€â”€
      // Staff roles (caster, producer, helper) are exclusive â€” can't also be a player/coach.
      // Tournament Director who plans to play is exempt.
      if (!(rolePreference === 'tournament_director' && plansToPlay)) {
        const { data: existingReg } = await supabase
          .from('kkup_registrations')
          .select('id, status, role')
          .eq('tournament_id', tournamentId)
          .eq('user_id', auth.dbUser.id)
          .neq('status', 'withdrawn')
          .maybeSingle();

        if (existingReg && existingReg.role === 'player') {
          return c.json({
            error: 'You\'re currently registered as a player. You must withdraw from the player role before applying as staff.',
            role_conflict: true,
            current_role: 'player',
          }, 409);
        }
        if (existingReg && existingReg.role === 'coach') {
          return c.json({
            error: 'You\'re currently registered as a coach. You must remove yourself from coaching before applying as staff.',
            role_conflict: true,
            current_role: 'coach',
          }, 409);
        }
      }

      // Resolve person_id from kkup_persons via user link (create if needed)
      const personResult = await resolvePersonForUser(supabase, auth.dbUser);
      if ('error' in personResult) {
        return c.json({ error: `Failed to resolve person identity: ${personResult.error}` }, 500);
      }
      const personId = personResult.person.id;

      // Upsert (handles re-applying after withdrawal)
      if (existing) {
        const { error: updateError } = await supabase
          .from('kkup_staff_applications')
          .update({
            role_preference: rolePreference,
            plans_to_play: plansToPlay,
            note: (body.message || '').trim().slice(0, 500),
            status: 'pending',
            reviewed_by: null,
            reviewed_at: null,
            updated_at: new Date().toISOString(),
          })
          .eq('id', existing.id);
        if (updateError) throw updateError;
      } else {
        const { error: insertError } = await supabase
          .from('kkup_staff_applications')
          .insert({
            tournament_id: tournamentId,
            person_id: personId,
            user_id: auth.dbUser.id,
            role_preference: rolePreference,
            plans_to_play: plansToPlay,
            note: (body.message || '').trim().slice(0, 500),
            status: 'pending',
          });
        if (insertError) throw insertError;
      }

      console.log(`Staff application: ${auth.dbUser.discord_username} applied as ${rolePreference}${plansToPlay ? ' (plans to play)' : ''} for "${tournament.name}"`);

      // Log activity
      try {
        await createUserActivity({
          user_id: auth.dbUser.id,
          type: 'staff_applied',
          title: `Applied as ${rolePreference === 'tournament_director' ? 'Tournament Director' : rolePreference}`,
          description: `You applied as ${rolePreference === 'tournament_director' ? 'Tournament Director' : rolePreference}${plansToPlay ? ' (plans to play)' : ''} for "${tournament.name}".`,
          related_id: tournamentId,
          related_url: `#tournament-hub/${tournamentId}`,
        });
      } catch (actErr) { console.error('Non-critical: activity log for staff application failed:', actErr); }

      const roleLabel = rolePreference === 'tournament_director' ? 'Tournament Director' : rolePreference;
      return c.json({
        success: true,
        message: `You've applied as ${roleLabel}${plansToPlay ? ' (playing)' : ''} for "${tournament.name}". An officer will review your application.`,
      });
    } catch (error: any) {
      console.error('Staff application error:', error);
      return c.json({ error: 'Internal server error during staff application: ' + error.message }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 2. WITHDRAW STAFF APPLICATION
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.delete(`${PREFIX}/kkup/tournaments/:id/apply-staff`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const tournamentId = c.req.param('id');

      const { data: existing, error: fetchErr } = await supabase
        .from('kkup_staff_applications')
        .select('id, status, role_preference, plans_to_play')
        .eq('tournament_id', tournamentId)
        .eq('user_id', auth.dbUser.id)
        .maybeSingle();

      if (fetchErr || !existing) return c.json({ error: 'No staff application found' }, 404);

      const wasApprovedTdWithPlay = existing.status === 'approved'
        && existing.role_preference === 'tournament_director'
        && existing.plans_to_play === true;

      const { error: updateErr } = await supabase
        .from('kkup_staff_applications')
        .delete()
        .eq('id', existing.id);
      if (updateErr) throw updateErr;

      // Clean up any legacy staff registration (from old flow that created registration on apply)
      try {
        const { data: staffReg } = await supabase
          .from('kkup_registrations')
          .select('id, role')
          .eq('tournament_id', tournamentId)
          .eq('user_id', auth.dbUser.id)
          .eq('role', 'staff')
          .neq('status', 'withdrawn')
          .maybeSingle();
        if (staffReg) {
          await supabase
            .from('kkup_registrations')
            .update({ status: 'withdrawn', withdrawn_at: new Date().toISOString() })
            .eq('id', staffReg.id);
          console.log(`Cleaned up legacy staff registration for ${auth.dbUser.discord_username} in tournament ${tournamentId}`);
        }
      } catch (regErr) {
        console.error('Non-critical: failed to clean up legacy staff registration:', regErr);
      }

      // Clean up auto-created player registration for approved TD with plans_to_play
      // When a TD who planned to play gets approved, a player registration is auto-created.
      // Stepping down should also remove that registration so they get a clean slate.
      // CRITICAL: If the TD is also a team captain, disband the team first.
      if (wasApprovedTdWithPlay) {
        try {
          const { data: playerReg } = await supabase
            .from('kkup_registrations')
            .select('id, role, status')
            .eq('tournament_id', tournamentId)
            .eq('user_id', auth.dbUser.id)
            .eq('role', 'player')
            .neq('status', 'withdrawn')
            .maybeSingle();
          if (playerReg) {
            const personResult = await resolvePersonForUser(supabase, auth.dbUser);
            if (!('error' in personResult)) {
              const { person } = personResult;

              // Check if this person is captain of a team â€” if so, disband it
              const { data: captainedTeam } = await supabase
                .from('kkup_teams')
                .select('id, team_name, team_tag, logo_url, coach_person_id, approval_status')
                .eq('tournament_id', tournamentId)
                .eq('captain_person_id', person.id)
                .neq('approval_status', 'withdrawn')
                .maybeSingle();

              if (captainedTeam) {
                // Get tournament name for notifications
                const { data: tournament } = await supabase
                  .from('kkup_tournaments')
                  .select('name')
                  .eq('id', tournamentId)
                  .single();

                const disbandResult = await disbandCaptainTeam(supabase, {
                  team: captainedTeam,
                  tournamentId,
                  tournamentName: tournament?.name || 'the tournament',
                  captainPerson: person,
                  authDbUserId: auth.dbUser.id,
                  createNotification,
                  createUserActivity,
                  createAdminLog,
                });
                console.log(`Team "${captainedTeam.team_name}" disbanded â€” TD captain ${person.display_name} stepped down from tournament ${tournamentId}`);

                // Discord webhook: team disbanded due to staff role change (non-critical)
                try {
                  const { embed } = buildKkupActivityEmbed({
                    type: 'team_withdrawn',
                    tournamentName: tournament?.name || 'Unknown Tournament',
                    tournamentId,
                    playerName: person.display_name,
                    playerAvatar: auth.dbUser.discord_avatar,
                    teamName: captainedTeam.team_name,
                    teamLogoUrl: captainedTeam.logo_url,
                    actorName: auth.dbUser.discord_username,
                    extraDetail: `Captain became staff â€” team disbanded. ${disbandResult.displacedPersonIds.length} player(s) returned to free agency.`,
                  });
                  await sendWebhookEmbed(DISCORD_WEBHOOKS.KKUP_REGISTRATIONS, embed);
                } catch (whErr) { console.error('Non-critical: team disband webhook (staff approval) failed:', whErr); }
              } else {
                // Not a captain â€” just clean up roster membership and invites
                const { data: tournTeams } = await supabase
                  .from('kkup_teams')
                  .select('id')
                  .eq('tournament_id', tournamentId)
                  .neq('approval_status', 'withdrawn');
                const teamIds = (tournTeams || []).map((t: any) => t.id);
                if (teamIds.length > 0) {
                  await supabase.from('kkup_team_rosters').delete().eq('person_id', person.id).in('team_id', teamIds);
                  await supabase.from('kkup_team_invites')
                    .update({ status: 'expired', updated_at: new Date().toISOString() })
                    .eq('invitee_person_id', person.id).eq('status', 'pending').in('team_id', teamIds);
                }
              }
            }
            await supabase
              .from('kkup_registrations')
              .update({ status: 'withdrawn', withdrawn_at: new Date().toISOString() })
              .eq('id', playerReg.id);
            console.log(`Cleaned up auto-created player registration for ${auth.dbUser.discord_username} (TD step-down) in tournament ${tournamentId}`);
          }
        } catch (regErr) {
          console.error('Non-critical: failed to clean up player registration on TD step-down:', regErr);
        }
      }

      try {
        await createUserActivity({
          user_id: auth.dbUser.id,
          type: 'staff_app_withdrawn',
          title: 'Withdrew Staff Application',
          description: `You withdrew your staff application for tournament ${tournamentId}.`,
          related_id: tournamentId,
          related_url: `#tournament-hub/${tournamentId}`,
        });
      } catch (actErr) { console.error('Non-critical: activity log for staff withdrawal failed:', actErr); }

      return c.json({ success: true, message: 'Staff application withdrawn.' });
    } catch (error: any) {
      console.error('Staff withdrawal error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 3. LIST STAFF APPLICATIONS
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/kkup/tournaments/:id/staff`, async (c) => {
    try {
      const tournamentId = c.req.param('id');

      let isOwnerOrOfficer = false;
      let currentUserId: string | null = null;
      const accessToken = c.req.header('Authorization')?.split(' ')[1];
      if (accessToken) {
        try {
          const { data, error: authErr } = await anonSupabase.auth.getUser(accessToken);
          const authUser = data?.user ?? null;
          if (!authErr && authUser) {
            const { data: dbUser } = await supabase.from('users').select('id, role').eq('supabase_id', authUser.id).single();
            if (dbUser) {
              isOwnerOrOfficer = isOfficer(dbUser.role);
              currentUserId = dbUser.id;
            }
          }
        } catch (authLookupErr) {
          console.warn('Non-critical: auth lookup failed in staff list endpoint:', authLookupErr);
        }
      }

      const { data: allApps, error: fetchErr } = await supabase
        .from('kkup_staff_applications')
        .select('*')
        .eq('tournament_id', tournamentId)
        .neq('status', 'withdrawn')
        .order('created_at', { ascending: true });

      if (fetchErr) throw fetchErr;
      const applications = allApps || [];

      // Enrich with user data (avatar, username)
      const userIds = applications.map((a: any) => a.user_id).filter(Boolean);
      const userMap = new Map<string, any>();
      if (userIds.length > 0) {
        const { data: users } = await supabase
          .from('users')
          .select('id, discord_username, discord_avatar, tcf_plus_active')
          .in('id', userIds);
        (users || []).forEach((u: any) => userMap.set(u.id, u));
      }

      const enrichedApps = applications.map((app: any) => {
        const u = userMap.get(app.user_id);
        return {
          ...app,
          discord_username: u?.discord_username || 'Unknown',
          discord_avatar: u?.discord_avatar || null,
          tcf_plus_active: u?.tcf_plus_active || false,
          // Compat: keep applied_at for frontend
          applied_at: app.created_at,
          message: app.note,
        };
      });

      const myApplication = currentUserId
        ? enrichedApps.find((a: any) => a.user_id === currentUserId) || null
        : null;

      const visibleApps = enrichedApps;

      const summary = {
        total: visibleApps.length,
        pending: visibleApps.filter((a: any) => a.status === 'pending').length,
        approved: visibleApps.filter((a: any) => a.status === 'approved').length,
        denied: visibleApps.filter((a: any) => a.status === 'denied').length,
        casters: visibleApps.filter((a: any) => a.status === 'approved' && a.role_preference === 'caster').length,
        producers: visibleApps.filter((a: any) => a.status === 'approved' && a.role_preference === 'producer').length,
        helpers: visibleApps.filter((a: any) => a.status === 'approved' && a.role_preference === 'helper').length,
        tournament_directors: visibleApps.filter((a: any) => a.status === 'approved' && a.role_preference === 'tournament_director').length,
      };

      return c.json({
        applications: isOwnerOrOfficer ? visibleApps : visibleApps.filter((a: any) => a.status === 'approved'),
        my_application: myApplication,
        summary,
      });
    } catch (error: any) {
      console.error('List staff applications error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 4. REVIEW STAFF APPLICATION (Officers + Owner)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.patch(`${PREFIX}/kkup/tournaments/:id/staff/:appId`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;
      if (!isOfficer(auth.dbUser.role)) {
        return c.json({ error: 'Only officers and the owner can review staff applications' }, 403);
      }

      const tournamentId = c.req.param('id');
      const appId = c.req.param('appId');
      const { status: newStatus } = await c.req.json();

      if (!['approved', 'denied'].includes(newStatus)) {
        return c.json({ error: 'Status must be "approved" or "denied"' }, 400);
      }

      // appId might be the user_id (legacy frontend) or the actual app id
      // Try both lookups
      let app: any = null;
      const { data: byId } = await supabase
        .from('kkup_staff_applications')
        .select('*')
        .eq('id', appId)
        .eq('tournament_id', tournamentId)
        .maybeSingle();
      if (byId) {
        app = byId;
      } else {
        // Fallback: treat appId as user_id
        const { data: byUserId } = await supabase
          .from('kkup_staff_applications')
          .select('*')
          .eq('user_id', appId)
          .eq('tournament_id', tournamentId)
          .maybeSingle();
        app = byUserId;
      }

      if (!app) return c.json({ error: 'Staff application not found' }, 404);

      // Fetch tournament name for logging and webhooks
      const { data: tournament } = await supabase
        .from('kkup_tournaments').select('name').eq('id', tournamentId).single();
      const tournamentName = tournament?.name || 'Unknown Tournament';

      const { error: updateErr } = await supabase
        .from('kkup_staff_applications')
        .update({
          status: newStatus,
          reviewed_by: auth.dbUser.id,
          reviewed_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq('id', app.id);
      if (updateErr) throw updateErr;

      // Get applicant's username for logging
      const { data: applicantUser } = await supabase
        .from('users')
        .select('discord_username, discord_id, discord_avatar, opendota_data')
        .eq('id', app.user_id)
        .maybeSingle();
      const applicantName = applicantUser?.discord_username || 'Unknown';

      // Notify the applicant and log admin action (non-critical)
      try {
        await createNotification({
          user_id: app.user_id,
          type: 'staff_app_result',
          title: `Staff Application ${newStatus === 'approved' ? 'Approved' : 'Denied'}`,
          body: newStatus === 'approved'
            ? `Your staff application as ${app.role_preference} has been approved!`
            : `Your staff application has been denied.`,
          related_id: `${tournamentId}_${app.user_id}`,
          action_url: `#tournament-hub/${tournamentId}`,
          actor_name: auth.dbUser.discord_username,
        });
        await createAdminLog({
          type: `staff_${newStatus}`,
          action: `${newStatus === 'approved' ? 'Approved' : 'Denied'} staff application from ${applicantName}`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          details: { tournament_id: tournamentId, applicant: applicantName, role: app.role_preference },
        });
        await createUserActivity({
          user_id: app.user_id,
          type: newStatus === 'approved' ? 'admin_staff_approved' : 'admin_staff_denied',
          title: `Staff Application ${newStatus === 'approved' ? 'Approved' : 'Denied'}`,
          description: newStatus === 'approved'
            ? `Your staff application as ${app.role_preference === 'tournament_director' ? 'Tournament Director' : app.role_preference} was approved by ${auth.dbUser.discord_username}.`
            : `Your staff application was denied by ${auth.dbUser.discord_username}.`,
          related_id: tournamentId,
          related_url: `#tournament-hub/${tournamentId}`,
          actor_name: auth.dbUser.discord_username,
        });
      } catch (_) { /* non-critical */ }

      // â”€â”€ Create/update registration on approval â”€â”€
      // Staff registration is only created when APPROVED, not on application.
      // TD with plans_to_play gets role='player', all others get role='staff'.
      if (newStatus === 'approved') {
        try {
          const targetRole = (app.role_preference === 'tournament_director' && app.plans_to_play) ? 'player' : 'staff';
          const targetStatus = targetRole === 'player' ? 'free_agent' : 'staff';

          const { data: existingReg } = await supabase
            .from('kkup_registrations')
            .select('id, status, role')
            .eq('tournament_id', tournamentId)
            .eq('user_id', app.user_id)
            .neq('status', 'withdrawn')
            .maybeSingle();

          if (existingReg) {
            // Upgrade existing registration if needed
            if (existingReg.role !== targetRole) {
              const { error: upgradeErr } = await supabase
                .from('kkup_registrations')
                .update({ role: targetRole, status: targetStatus })
                .eq('id', existingReg.id);
              if (upgradeErr) throw upgradeErr;
              console.log(`Upgraded ${applicantName} registration from ${existingReg.role} â†’ ${targetRole}/${targetStatus} for tournament ${tournamentId}`);
            }
          } else {
            // No registration exists â€” create one
            await supabase.from('kkup_registrations').insert({
              tournament_id: tournamentId,
              person_id: app.person_id,
              user_id: app.user_id,
              role: targetRole,
              status: targetStatus,
            });
            console.log(`Auto-registered ${applicantName} as ${targetRole} (staff approved) for tournament ${tournamentId}`);
          }
        } catch (regErr) {
          console.error('Non-critical: failed to create registration on staff approval:', regErr);
        }

        // Discord webhook: staff approval notification (non-critical)
        try {
          const { count: regCount } = await supabase
            .from('kkup_registrations').select('id', { count: 'exact', head: true })
            .eq('tournament_id', tournamentId).neq('status', 'withdrawn');
          const rank = applicantUser ? resolveUserRank(applicantUser) : null;
          const dotaRank = rank ? `${rank.medal}${rank.stars ? ` [${rank.stars}]` : ''}` : null;
          const rankBadgeUrl = rank ? getRankBadgeUrl(rank.medal, rank.stars) : null;
          const { embed } = buildRegistrationEmbed({
            discordId: applicantUser?.discord_id || null,
            discordUsername: applicantName,
            discordAvatar: applicantUser?.discord_avatar || null,
            role: 'staff',
            tournamentName,
            tournamentId,
            registrationNumber: regCount || 1,
            isEarlyAccess: false,
            isReRegistration: false,
            dotaRank, rankBadgeUrl,
            staffRole: app.role_preference,
            isStaffApproval: true,
          });
          await sendWebhookEmbed(DISCORD_WEBHOOKS.KKUP_REGISTRATIONS, embed);
        } catch (whErr) { console.error('Non-critical: staff approval webhook failed:', whErr); }
      }

      // â”€â”€ Clean up registration on denial â”€â”€
      if (newStatus === 'denied') {
        try {
          const { data: existingReg } = await supabase
            .from('kkup_registrations')
            .select('id, role')
            .eq('tournament_id', tournamentId)
            .eq('user_id', app.user_id)
            .eq('role', 'staff')
            .neq('status', 'withdrawn')
            .maybeSingle();

          if (existingReg) {
            await supabase
              .from('kkup_registrations')
              .update({ status: 'withdrawn', withdrawn_at: new Date().toISOString() })
              .eq('id', existingReg.id);
            console.log(`Withdrew staff registration for denied applicant ${applicantName} in tournament ${tournamentId}`);
          }
        } catch (regErr) {
          console.error('Non-critical: failed to clean up registration on staff denial:', regErr);
        }
      }

      console.log(`Staff application ${newStatus}: ${applicantName} for tournament ${tournamentId}`);
      return c.json({
        success: true,
        message: `Staff application ${newStatus} for ${applicantName}.`,
      });
    } catch (error: any) {
      console.error('Staff review error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 4b. DISMISS (DELETE) STAFF APPLICATION (officer/owner â€” hard delete)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.delete(`${PREFIX}/kkup/tournaments/:id/staff/:appId`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;
      if (!isOfficer(auth.dbUser.role)) {
        return c.json({ error: 'Only officers and the owner can dismiss staff applications' }, 403);
      }

      const tournamentId = c.req.param('id');
      const appId = c.req.param('appId');

      // Try by id, then by user_id
      let app: any = null;
      const { data: byId } = await supabase
        .from('kkup_staff_applications')
        .select('*')
        .eq('id', appId)
        .eq('tournament_id', tournamentId)
        .maybeSingle();
      if (byId) {
        app = byId;
      } else {
        const { data: byUserId } = await supabase
          .from('kkup_staff_applications')
          .select('*')
          .eq('user_id', appId)
          .eq('tournament_id', tournamentId)
          .maybeSingle();
        app = byUserId;
      }

      if (!app) return c.json({ error: 'Staff application not found' }, 404);

      const { data: applicantUser } = await supabase
        .from('users')
        .select('discord_username, steam_id')
        .eq('id', app.user_id)
        .maybeSingle();
      const applicantName = applicantUser?.discord_username || 'Unknown';

      const wasApproved = app.status === 'approved';
      const wasApprovedTdWithPlay = wasApproved
        && app.role_preference === 'tournament_director'
        && app.plans_to_play === true;

      const { error: delErr } = await supabase
        .from('kkup_staff_applications')
        .delete()
        .eq('id', app.id);
      if (delErr) throw delErr;

      // â”€â”€ Clean up associated registration â”€â”€
      // When an approved staff member is removed, their auto-created registration should also be cleaned up.
      if (wasApproved) {
        try {
          // For non-TD staff: role='staff'. For TD with plans_to_play: role='player'.
          const targetRole = wasApprovedTdWithPlay ? 'player' : 'staff';
          const { data: staffReg } = await supabase
            .from('kkup_registrations')
            .select('id, role, status')
            .eq('tournament_id', tournamentId)
            .eq('user_id', app.user_id)
            .eq('role', targetRole)
            .neq('status', 'withdrawn')
            .maybeSingle();

          if (staffReg) {
            // If the player was on a team, clean up team roster too
            if (wasApprovedTdWithPlay && applicantUser?.steam_id) {
              const { data: person } = await supabase
                .from('kkup_persons')
                .select('id')
                .eq('steam_id', applicantUser.steam_id)
                .maybeSingle();
              if (person) {
                const { data: tournTeams } = await supabase
                  .from('kkup_teams')
                  .select('id')
                  .eq('tournament_id', tournamentId)
                  .neq('approval_status', 'withdrawn');
                const teamIds = (tournTeams || []).map((t: any) => t.id);
                if (teamIds.length > 0) {
                  await supabase.from('kkup_team_rosters').delete().eq('person_id', person.id).in('team_id', teamIds);
                  await supabase.from('kkup_team_invites')
                    .update({ status: 'expired', updated_at: new Date().toISOString() })
                    .eq('invitee_person_id', person.id).eq('status', 'pending').in('team_id', teamIds);
                }
              }
            }

            await supabase
              .from('kkup_registrations')
              .update({ status: 'withdrawn', withdrawn_at: new Date().toISOString() })
              .eq('id', staffReg.id);
            console.log(`Cleaned up ${targetRole} registration for ${applicantName} (staff dismissed) in tournament ${tournamentId}`);
          }
        } catch (regErr) {
          console.error('Non-critical: failed to clean up registration on staff dismiss:', regErr);
        }
      }

      console.log(`Staff application dismissed: ${applicantName} for tournament ${tournamentId} by ${auth.dbUser.discord_username}`);

      try {
        await createAdminLog({
          type: 'staff_dismissed',
          action: `Removed ${applicantName} from staff`,
          actor_id: auth.dbUser.id,
          actor_name: auth.dbUser.discord_username,
          details: { tournament_id: tournamentId, applicant: applicantName, role: app.role_preference },
        });
        await createUserActivity({
          user_id: app.user_id,
          type: 'staff_app_dismissed',
          title: wasApproved ? 'Removed from Staff' : 'Staff Application Dismissed',
          description: wasApproved
            ? `You were removed from staff by ${auth.dbUser.discord_username || 'an officer'}.`
            : `Your staff application was dismissed by ${auth.dbUser.discord_username || 'an officer'}.`,
          related_id: tournamentId,
          related_url: `#tournament-hub/${tournamentId}`,
          actor_name: auth.dbUser.discord_username,
        });
        // Notify the removed user
        await createNotification({
          user_id: app.user_id,
          type: wasApproved ? 'staff_removed' : 'staff_app_dismissed',
          title: wasApproved ? 'Removed from Staff' : 'Staff Application Dismissed',
          body: wasApproved
            ? `You were removed from staff for this tournament by ${auth.dbUser.discord_username || 'an officer'}.`
            : `Your staff application was dismissed by ${auth.dbUser.discord_username || 'an officer'}.`,
          related_id: tournamentId,
          action_url: `#tournament-hub/${tournamentId}`,
          actor_name: auth.dbUser.discord_username,
        });
      } catch (_) { /* non-critical */ }

      return c.json({
        success: true,
        message: `Staff application from ${applicantName} dismissed.`,
      });
    } catch (error: any) {
      console.error('Staff dismiss error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // 5. LIST ALL KKUP REQUESTS (aggregated â€” for admin requests page)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/kkup/requests`, async (c) => {
    try {
      const auth = await requireAuth(c);
      if (!auth.ok) return auth.response;

      const isOwnerRole = auth.dbUser.role === 'owner';
      const isOfficerRole = isOfficer(auth.dbUser.role);

      const { data: tournaments } = await supabase
        .from('kkup_tournaments').select('id, name, status').order('created_at', { ascending: false });

      const allRequests: any[] = [];
      const myRequests: any[] = [];

      for (const t of (tournaments || [])) {
        if (isOfficerRole) {
          const { data: pendingTeams } = await supabase
            .from('kkup_teams')
            .select('id, team_name, team_tag, logo_url, approval_status, created_at, captain:kkup_persons!captain_person_id(id, display_name, avatar_url)')
            .eq('tournament_id', t.id).eq('approval_status', 'pending_approval');
          for (const team of (pendingTeams || [])) {
            allRequests.push({
              id: `team_${team.id}`, raw_id: team.id, request_type: 'kkup_team_approval',
              tournament_id: t.id, tournament_name: t.name, status: 'pending',
              created_at: team.created_at, data: team,
            });
          }
        }

        // Staff applications from real table (exclude withdrawn)
        const { data: staffApps } = await supabase
          .from('kkup_staff_applications')
          .select('*')
          .eq('tournament_id', t.id)
          .neq('status', 'withdrawn');

        // Enrich with user data
        const staffUserIds = (staffApps || []).map((a: any) => a.user_id).filter(Boolean);
        const staffUserMap = new Map<string, any>();
        if (staffUserIds.length > 0) {
          const { data: users } = await supabase
            .from('users')
            .select('id, discord_username, discord_avatar, tcf_plus_active')
            .in('id', staffUserIds);
          (users || []).forEach((u: any) => staffUserMap.set(u.id, u));
        }

        for (const sApp of (staffApps || [])) {
          const u = staffUserMap.get(sApp.user_id);
          const enriched = {
            ...sApp,
            discord_username: u?.discord_username || 'Unknown',
            discord_avatar: u?.discord_avatar || null,
            tcf_plus_active: u?.tcf_plus_active || false,
            applied_at: sApp.created_at,
            message: sApp.note,
          };

          if (isOfficerRole) {
            allRequests.push({
              id: `staff_${sApp.id}`, raw_id: sApp.id, request_type: 'kkup_staff_application',
              tournament_id: t.id, tournament_name: t.name, status: sApp.status,
              created_at: sApp.created_at, data: enriched,
            });
          }
          if (sApp.user_id === auth.dbUser.id) {
            myRequests.push({
              id: `mystaff_${sApp.id}`, request_type: 'kkup_my_staff',
              tournament_id: t.id, tournament_name: t.name, status: sApp.status,
              created_at: sApp.created_at, data: enriched,
            });
          }
        }
      }

      allRequests.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
      myRequests.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

      return c.json({
        requests: allRequests, my_requests: myRequests,
        summary: { total: allRequests.length, pending: allRequests.filter(r => r.status === 'pending').length, my_total: myRequests.length },
      });
    } catch (error: any) {
      console.error('List KKup requests error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });
}

