  } catch (err) {
    console.error('Non-critical: failed to update donation tracking for user:', err);
  }

  // â”€â”€ Activity log + admin log â”€â”€
  const noteDisplay = meta.note ? ` (Note: ${meta.note})` : '';

  try {
    await createUserActivity({
      user_id: userId,
