      const playerId = c.req.param('player_id');

      // Look up names before deleting
      const [{ data: player }, { data: team }] = await Promise.all([
        supabase.from('kkup_persons').select('display_name').eq('id', playerId).maybeSingle(),
        supabase.from('kkup_teams').select('team_name').eq('id', teamId).maybeSingle(),
      ]);

      const { error: deleteError } = await supabase
        .from('kkup_team_rosters').delete().eq('team_id', teamId).eq('person_id', playerId);
      if (deleteError) return c.json({ error: 'Failed to remove player from team: ' + deleteError.message }, 500);

      try { await createAdminLog({ type: 'kkup_roster_removed', action: `Removed ${player?.display_name || 'player'} from ${team?.team_name || 'team'}`, actor_name: 'Owner' }); } catch (_) {}

      return c.json({ success: true, message: 'Player removed from team' });
    } catch (error: any) {
      console.error('Remove player from team error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

  // Get team roster with top 3 heroes (public)
  app.get(`${PREFIX}/tournament/:kkup_id/team/:team_id/roster`, async (c) => {
    try {
      const teamId = c.req.param('team_id');

      const { data: roster, error } = await supabase
        .from('kkup_team_rosters').select(`*, player:kkup_persons(*)`).eq('team_id', teamId);
      if (error) return c.json({ error: 'Failed to fetch roster' }, 500);

      const rosterWithHeroes = await Promise.all((roster || []).map(async (entry: any) => {
        const playerId = entry.player.id;
        const { data: playerStats } = await supabase
          .from('kkup_player_match_stats').select('hero_id, hero, is_winner')
          .eq('person_id', playerId).eq('team_id', teamId);

        const heroCount = new Map<number, { name: string; count: number; wins: number }>();
        (playerStats || []).forEach((stat: any) => {
          if (!heroCount.has(stat.hero_id)) heroCount.set(stat.hero_id, { name: stat.hero, count: 0, wins: 0 });
          const hero = heroCount.get(stat.hero_id)!;
          hero.count++;
          if (stat.is_winner) hero.wins++;
        });

        const topHeroes = Array.from(heroCount.values())
          .sort((a, b) => b.count - a.count).slice(0, 3)
          .map(h => ({ name: h.name, count: h.count, wins: h.wins, winRate: h.count > 0 ? ((h.wins / h.count) * 100).toFixed(0) : "0" }));

        return { ...entry, topHeroes };
      }));

      return c.json({ roster: rosterWithHeroes });
    } catch (error: any) {
      console.error('Get roster error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });

}

/**
 * Tournament Lifecycle Routes â€” Phase 2+3: Live Tournament Creation & Registration
 *
 * 9 routes:
 *   POST   /kkup/tournaments/create              â€” Create a new tournament (owner only)
 *   PATCH  /kkup/tournaments/:id/config          â€” Update tournament config (owner only)
 *   PATCH  /kkup/tournaments/:id/status          â€” Change tournament status (owner only)
 *   DELETE /kkup/tournaments/:id                 â€” Delete a tournament and all related data (owner only)
 *   GET    /kkup/tournaments/:id/my-registration â€” Get current user's registration status
 *   POST   /kkup/tournaments/:id/register        â€” Register for tournament with chosen role
 *   PATCH  /kkup/tournaments/:id/register/role   â€” Change role after registration
 *   DELETE /kkup/tournaments/:id/register        â€” Player withdraws registration
 *   GET    /kkup/tournaments/:id/registrations   â€” List registrations (free agents + on-team)
 *
 * Tables used: kkup_tournaments, kkup_persons, kkup_registrations, users,
 *              kkup_teams, kkup_team_rosters, kkup_team_invites, kkup_coach_assignments,
 *              kkup_matches, kkup_player_match_stats
 *
 * Auth:
 *   - Owner-only routes use requireOwner() (same pattern as routes-tournament-crud.ts)
 *   - Registration routes use requireAuth() â€” any authenticated user
 */
import { PREFIX, requireAuth as sharedRequireAuth, requireOwner as sharedRequireOwner, resolvePersonForUser as sharedResolvePersonForUser, clearCoachAssignment, disbandCaptainTeam } from "./helpers.ts";
import { createAdminLog, createNotification, createUserActivity } from "./routes-notifications.ts";
import { checkKernelKupEligibility, resolveUserRank, getRankBadgeUrl } from "./rank-utils.ts";
import { getMaxPlayerRank, getMinPlayerRank } from "./routes-config.ts";
import { DISCORD_WEBHOOKS } from "./discord-config.ts";
import { buildRegistrationEmbed, buildKkupAnnouncementEmbed, buildChampionsEmbed, buildPopdKernelEmbed, buildKkupActivityEmbed, sendWebhookEmbed } from "./discord-embeds.tsx";
