            }

            const allRegs = regs || [];
            const allStaff = staffApps || [];
            const totalRegistrants = (regCount || 0) + (staffCount || 0);

            // Count unique teams
            let teamsCount = 0;
            const { count: tCount } = await supabase
              .from('kkup_teams')
              .select('id', { count: 'exact', head: true })
              .eq('tournament_id', t.id);
            teamsCount = tCount || 0;

            // Collect user IDs from both registrations and staff apps for Discord avatars
            const regUserIds = allRegs.map((r: any) => r.user_id).filter(Boolean);
            const staffUserIds = allStaff.map((s: any) => s.user_id).filter(Boolean);
            const allUserIds = [...new Set([...regUserIds, ...staffUserIds])];
            const userAvatarMap = new Map<string, { discord_avatar: string | null; discord_username: string; tcf_plus_active: boolean }>();
            if (allUserIds.length > 0) {
              const { data: users } = await supabase
                .from('users')
                .select('id, discord_avatar, discord_username, tcf_plus_active')
                .in('id', allUserIds.slice(0, 40)); // Limit DB query
              (users || []).forEach((u: any) => userAvatarMap.set(u.id, u));
            }

            // Merge registrations + staff apps, sort by most recent, deduplicate
            const mergedEntries = [
              ...allRegs.map((r: any) => ({
                user_id: r.user_id,
                person: r.person,
                timestamp: r.registered_at,
              })),
              ...allStaff.map((s: any) => ({
                user_id: s.user_id,
                person: s.person,
                timestamp: s.created_at,
              })),
            ].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

            // Deduplicate by user_id (a staff member might also be a player registrant)
            const seen = new Set<string>();
            const deduped = mergedEntries.filter((entry) => {
              if (!entry.user_id || seen.has(entry.user_id)) return false;
              seen.add(entry.user_id);
              return true;
            });

            // Build preview list (15 most recent) â€” prefer Discord avatar, fall back to kkup_persons
            const playerPreviews = deduped.slice(0, 15).map((entry) => {
              const linkedUser = userAvatarMap.get(entry.user_id);
              return {
                avatar: linkedUser?.discord_avatar || entry.person?.avatar_url || null,
                name: linkedUser?.discord_username || entry.person?.display_name || 'Player',
                tcf_plus_active: linkedUser?.tcf_plus_active || false,
              };
            });

            // Fetch winner team info if tournament is completed
            let winner = null;
            if (t.winning_team_id) {
              const { data: winnerTeam } = await supabase
                .from('kkup_teams')
                .select('team_name, team_tag, logo_url')
                .eq('id', t.winning_team_id)
                .single();
              if (winnerTeam) {
                winner = winnerTeam;
              }
            }

            return {
              ...t,
              registration_count: deduped.length,
              teams_count: teamsCount,
              player_previews: playerPreviews,
              winner,
            };
          } catch (enrichErr: any) {
            console.error(`Enrichment error for tournament ${t.id}:`, enrichErr);
            return { ...t, registration_count: 0, player_previews: [], teams_count: 0 };
          }
        })
      );

      return c.json({ tournaments: enrichedTournaments });
    } catch (error: any) {
      console.error('List kkup_tournaments error:', error);
      return c.json({ error: 'Internal server error listing tournaments: ' + error.message }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // GET SINGLE TOURNAMENT (Public)
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

  app.get(`${PREFIX}/kkup/tournaments/:id`, async (c) => {
    try {
      const tournamentId = c.req.param('id');

      // Fetch tournament
      const { data: tournament, error } = await supabase
        .from('kkup_tournaments')
        .select('*')
        .eq('id', tournamentId)
        .single();

      if (error || !tournament) {
        return c.json({ error: 'Tournament not found' }, 404);
      }

      // Enrich with winner data if completed
      let winner = null;
      if (tournament.winning_team_id) {
        const { data: winnerTeam } = await supabase
          .from('kkup_teams')
          .select('team_name, team_tag, logo_url')
          .eq('id', tournament.winning_team_id)
          .single();
        if (winnerTeam) {
          winner = winnerTeam;
        }
      }

      // Enrich with popd kernels if available
      let popd_kernels = [];
      const pkIds = [tournament.popd_kernel_1_person_id, tournament.popd_kernel_2_person_id].filter(Boolean);
      if (pkIds.length > 0) {
        const { data: pkPersons } = await supabase
          .from('kkup_persons')
          .select('id, display_name, avatar_url, steam_id')
          .in('id', pkIds);
          
        if (pkPersons && pkPersons.length > 0) {
          const steamIds = pkPersons.map(p => p.steam_id).filter(Boolean);
          let usersBySteam = new Map();
          if (steamIds.length > 0) {
            const { data: users } = await supabase
              .from('users')
              .select('id, discord_username, discord_avatar, tcf_plus_active, steam_id')
              .in('steam_id', steamIds);
            users?.forEach(u => usersBySteam.set(u.steam_id, u));
          }
          
          popd_kernels = pkPersons.map(p => {
             const u = p.steam_id ? usersBySteam.get(p.steam_id) : null;
             return {
               id: u ? u.id : p.id,
               discord_username: u ? u.discord_username : p.display_name,
               discord_avatar: u ? u.discord_avatar : p.avatar_url,
               tcf_plus_active: u ? u.tcf_plus_active : false
             };
          });
        }
      }

      // Get counts based on tournament status
      const isCompleted = ['completed', 'archived'].includes(tournament.status);
      
      let registrationCount = 0;
      let teamsCount = 0;
      
      if (isCompleted) {
        // For completed tournaments, count from rosters (player_count column if it exists, otherwise calculate)
        if (tournament.player_count) {
          registrationCount = tournament.player_count;
        } else {
          // Count unique players from team rosters
          const { data: rosters } = await supabase
            .from('kkup_team_rosters')
            .select('person_id, team:kkup_teams!team_id(tournament_id)')
            .eq('team.tournament_id', tournamentId);
          
          const uniquePlayers = new Set(
            (rosters || [])
              .filter((r: any) => r.team?.tournament_id === tournamentId)
              .map((r: any) => r.person_id)
          );
          registrationCount = uniquePlayers.size;
        }
        
        // Use team_count column if available
        teamsCount = tournament.team_count || 0;
        if (!teamsCount) {
          const { count } = await supabase
            .from('kkup_teams')
            .select('id', { count: 'exact', head: true })
            .eq('tournament_id', tournamentId);
          teamsCount = count || 0;
        }
      } else {
        // For active/pre-tournament phases, count from kkup_team_rosters (most accurate
        // for roster_lock and reg_closed where players are on teams but may not have
        // a matching kkup_registrations row).
        const { data: activeTeams } = await supabase
          .from('kkup_teams')
          .select('id')
          .eq('tournament_id', tournamentId)
          .neq('approval_status', 'withdrawn');

        const activeTeamIds = (activeTeams || []).map((t: any) => t.id);

        if (activeTeamIds.length > 0) {
          const { data: rosterRows } = await supabase
            .from('kkup_team_rosters')
            .select('person_id')
            .in('team_id', activeTeamIds);
          registrationCount = (rosterRows || []).length;
        }

        // Fallback: if no rosters yet (reg_open / upcoming), count player-role registrations
        if (registrationCount === 0) {
          const { count: regCount } = await supabase
            .from('kkup_registrations')
            .select('id', { count: 'exact', head: true })
            .eq('tournament_id', tournamentId)
            .eq('role', 'player')
            .neq('status', 'withdrawn');
          registrationCount = regCount || 0;
        }

        const { count: teamCount } = await supabase
          .from('kkup_teams')
          .select('id', { count: 'exact', head: true })
          .eq('tournament_id', tournamentId);
        teamsCount = teamCount || 0;
      }

      // Fetch prizes and awards
      const { data: prizes } = await supabase
        .from('kkup_prizes')
        .select('*')
        .eq('tournament_id', tournamentId)
        .order('sort_order', { ascending: true });

      const { data: awards } = await supabase
        .from('prize_awards')
        .select(`
          id, prize_id, amount_cents, recipient_user_id, team_id,
          recipient:users!recipient_user_id(id, discord_username, discord_avatar, tcf_plus_active),
          team:kkup_teams!team_id(id, team_name, team_tag, logo_url)
        `)
        .eq('tournament_id', tournamentId);

      return c.json({
        tournament: {
          ...tournament,
          winner,
          popd_kernels,
          registration_count: registrationCount,
          player_count: registrationCount, // Same value, different field name
          teams_count: teamsCount,
          team_count: teamsCount, // Same value, different field name
          prizes: prizes || [],
          awards: awards || [],
        },
      });
    } catch (error: any) {
      console.error('Get single tournament error:', error);
      return c.json({ error: 'Internal server error: ' + error.message }, 500);
    }
  });


  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // NEXT UPCOMING TOURNAMENT (public â€” used by donation flow)
