      }

      const playerEntries = allRosterPersons.map((r: any) => {
        const team = teams.find((t: any) => t.id === r.team_id);
        const lu = r.person?.steam_id ? (userMap[r.person.steam_id] || null) : null;
        const urls = deriveProfileUrls(r.person?.steam_id);
        return {
