      // Fetch player stats for all matches
      const matchIds = matches.map((m: any) => m.id);
      const { data: playerStats } = await supabase
        .from('kkup_player_match_stats')
        .select(`
          id,
          match_id,
          person_id,
          team_id,
          hero,
          kills,
          deaths,
          assists,
          gpm,
          xpm,
          last_hits,
