    // OpenDota league teams endpoint
    const teamsUrl = `https://api.opendota.com/api/leagues/${leagueId}/teams`;
    const teamsResponse = await fetch(teamsUrl);
    const teamsData = await teamsResponse.json();

    return {
      success: true,
      league: leagueData,
