      notes: 'OpenDota may have more detailed data than Steam API'
    };
  } catch (error) {
    return {
      success: false,
      error: String(error)
    };
  }
}

/**
 * Compare Steam vs OpenDota for a specific match
 */
export async function compareSteamVsOpenDota(matchId: number) {
  const results: any = {
    matchId,
    timestamp: new Date().toISOString(),
    steam: {
      success: false,
      data: null,
      error: null
    },
    opendota: {
      success: false,
      data: null,
      error: null
    },
    comparison: {
      dataAvailability: {},
      recommendations: []
    }
  };

  // 1. Try Steam API - GetMatchDetails
  console.log('ðŸ” Fetching from Steam API...');
  try {
    const steamUrl = `${STEAM_API_BASE}/IDOTA2Match_${DOTA2_APP_ID}/GetMatchDetails/v1/?key=${STEAM_API_KEY}&match_id=${matchId}`;
    const steamResponse = await fetch(steamUrl);
    const steamData = await steamResponse.json();
    
    results.steam.success = steamResponse.ok && steamData.result;
    results.steam.data = steamData;
    
    if (results.steam.success) {
      console.log('âœ… Steam API returned match data');
    } else {
      results.steam.error = 'No match data in response';
      console.log('âŒ Steam API did not return match data');
    }
  } catch (error) {
    results.steam.error = String(error);
    console.error('âŒ Steam API error:', error);
  }

  // 2. Try OpenDota API - Match details
  console.log('ðŸ” Fetching from OpenDota API...');
  try {
    const openDotaUrl = `https://api.opendota.com/api/matches/${matchId}`;
    const openDotaResponse = await fetch(openDotaUrl);
    const openDotaData = await openDotaResponse.json();
    
    results.opendota.success = openDotaResponse.ok && !openDotaData.error;
    results.opendota.data = openDotaData;
    
    if (results.opendota.success) {
      console.log('âœ… OpenDota API returned match data');
    } else {
      results.opendota.error = openDotaData.error || 'No match data in response';
      console.log('âŒ OpenDota API did not return match data');
    }
  } catch (error) {
    results.opendota.error = String(error);
    console.error('âŒ OpenDota API error:', error);
  }

  // 3. Compare what data each API provides
  results.comparison.dataAvailability = {
    steam: {
      basicMatchInfo: !!results.steam.data?.result?.match_id,
      players: !!results.steam.data?.result?.players,
      heroes: !!results.steam.data?.result?.players?.[0]?.hero_id,
      items: !!results.steam.data?.result?.players?.[0]?.item_0,
      kills: !!results.steam.data?.result?.players?.[0]?.kills,
      winner: results.steam.data?.result?.radiant_win !== undefined,
      duration: !!results.steam.data?.result?.duration,
      leagueId: !!results.steam.data?.result?.leagueid
    },
    opendota: {
      basicMatchInfo: !!results.opendota.data?.match_id,
      players: !!results.opendota.data?.players,
      heroes: !!results.opendota.data?.players?.[0]?.hero_id,
      items: !!results.opendota.data?.players?.[0]?.item_0,
      kills: !!results.opendota.data?.players?.[0]?.kills,
      winner: results.opendota.data?.radiant_win !== undefined,
      duration: !!results.opendota.data?.duration,
      leagueId: !!results.opendota.data?.leagueid,
      // OpenDota extras
      detailedStats: !!results.opendota.data?.players?.[0]?.gold_per_min,
      itemTimings: !!results.opendota.data?.players?.[0]?.purchase_log,
      objectives: !!results.opendota.data?.objectives,
      teamfights: !!results.opendota.data?.teamfights,
      parsedData: !!results.opendota.data?.version,
      playerNames: !!results.opendota.data?.players?.[0]?.personaname
    }
  };

  // 4. Generate recommendations
  if (results.steam.success && results.opendota.success) {
    results.comparison.recommendations.push('âœ… Both APIs work! Use Steam for verification, OpenDota for detailed stats');
    results.comparison.recommendations.push('ðŸŽ¯ Steam: League ID, Team IDs, Basic match info');
    results.comparison.recommendations.push('ðŸ“Š OpenDota: Player stats, GPM/XPM, item builds, timelines');
  } else if (results.steam.success && !results.opendota.success) {
    results.comparison.recommendations.push('âš ï¸ Only Steam API works - may be limited data');
    results.comparison.recommendations.push('ðŸ’¡ Consider using Steam GetMatchHistory for league data');
  } else if (!results.steam.success && results.opendota.success) {
    results.comparison.recommendations.push('âœ… OpenDota works but Steam failed');
    results.comparison.recommendations.push('ðŸ’¡ Use OpenDota for all data - has league_id and team info');
  } else {
    results.comparison.recommendations.push('âŒ Neither API returned data for this match');
    results.comparison.recommendations.push('ðŸ’¡ Match may be too old or not in public databases');
  }

  return results;
}

/**
 * Steam ID Helper Functions
 * 
 * Steam has multiple ID formats for the same account:
 * - Account ID (Steam32): 51579950 (8-10 digits) â† OpenDota/Dota 2 match data
 * - Steam64: 76561198011845678 (17 digits) â† Steam profile lookups
 * - Vanity URL: "permasnooze" â† Custom profile URL
 * 
 * We canonically store Account ID (Steam32) in the database.
 */

const STEAM_ID_OFFSET = 76561197960265728;
const STEAM_API_BASE = 'https://api.steampowered.com';

/**
 * Convert Steam64 to Account ID (Steam32)
 */
export function steam64ToSteam32(steam64: string | number): number {
  const steam64Num = typeof steam64 === 'string' ? parseInt(steam64) : steam64;
  return steam64Num - STEAM_ID_OFFSET;
}

/**
 * Convert Account ID (Steam32) to Steam64
 */
export function steam32ToSteam64(accountId: string | number): string {
  const accountIdNum = typeof accountId === 'string' ? parseInt(accountId) : accountId;
  return String(accountIdNum + STEAM_ID_OFFSET);
}

/**
 * Resolve a Steam vanity URL (custom profile name) to Steam64
 * Example: "permasnooze" â†’ "76561198011845678"
 * 
 * Requires STEAM_WEB_API_KEY environment variable
 */
export async function resolveVanityUrl(vanityUrl: string): Promise<string | null> {
  try {
    const apiKey = Deno.env.get('STEAM_WEB_API_KEY');
    if (!apiKey) {
      console.error('STEAM_WEB_API_KEY not set - cannot resolve vanity URL');
      return null;
    }

    const url = `${STEAM_API_BASE}/ISteamUser/ResolveVanityURL/v0001/?key=${apiKey}&vanityurl=${vanityUrl}`;
    const response = await fetch(url);
    const data = await response.json();

    if (data.response?.success === 1) {
      return data.response.steamid; // Returns Steam64
    }

    console.warn(`Failed to resolve vanity URL "${vanityUrl}":`, data.response?.message || 'Unknown error');
    return null;
  } catch (error) {
    console.error(`Error resolving vanity URL "${vanityUrl}":`, error);
    return null;
  }
}

/**
 * Normalize ANY Steam ID format to Account ID (Steam32)
 * 
 * Accepts:
 * - Account ID: "51579950" or 51579950
 * - Steam64: "76561198011845678"
 * - Vanity URL: "permasnooze"
 * 
 * Returns: Account ID as number, or null if invalid/unresolvable
 */
export async function normalizeToAccountId(input: string | number): Promise<number | null> {
  if (!input) return null;

  const inputStr = String(input).trim();

  // Handle numeric Account ID (8-10 digits) - already correct format
  if (/^\d{8,10}$/.test(inputStr)) {
    return parseInt(inputStr);
  }

  // Handle Steam64 (17 digits)
  if (/^\d{17}$/.test(inputStr)) {
    return steam64ToSteam32(inputStr);
  }

  // Handle vanity URL (alphanumeric + underscores/hyphens)
  // Must be at least 3 chars (Steam requirement)
  if (/^[a-zA-Z0-9_-]{3,}$/.test(inputStr)) {
    const steam64 = await resolveVanityUrl(inputStr);
    if (steam64) {
      return steam64ToSteam32(steam64);
    }
  }

  console.warn(`Could not normalize Steam ID input: "${inputStr}"`);
  return null;
}

/**
 * Get Dotabuff URL from Account ID
 */
export function getDotabuffUrl(accountId: string | number): string {
  return `https://www.dotabuff.com/players/${accountId}`;
}

/**
 * Get OpenDota URL from Account ID
 */
export function getOpendotaUrl(accountId: string | number): string {
  return `https://www.opendota.com/players/${accountId}`;
}

/**
 * Get Steam profile URL from Account ID (converts to Steam64)
 */
export function getSteamProfileUrl(accountId: string | number): string {
  const steam64 = steam32ToSteam64(accountId);
  return `https://steamcommunity.com/profiles/${steam64}`;
}
